window.PHARM_DATA = {"chapters":[{"title":"第一章 绪言","questions":[{"type":"A","stem":"药效学是研究","options":{"A":"药物的临床疗效","B":"提高药物疗效的途径","C":"如何改善药物质量","D":"机体如何对药物进行处理","E":"在药物影响下机体细胞功能如何发生变化"},"answer":["E"],"rationale":"药效学研究药物对机体的作用及其机制，即药物影响下机体细胞功能发生的变化，故为E。","expl":{"A":"临床疗效是药物治疗疾病的效果，属疗效评价，非药效学的研究对象。","B":"提高药物疗效的途径属药物治疗学范畴，不是药效学的定义。","C":"改善药物质量属药物分析或制剂范畴，与药效学无关。","D":"机体如何处理药物是药动学的研究内容，非药效学。","E":"正确，药效学研究药物对机体的作用，即机体细胞功能在药物影响下的变化。"},"id":"ph01_q01","chapter":"第一章 绪言","chapterIdx":0,"num":1},{"type":"A","stem":"药动学是研究","options":{"A":"机体如何对药物进行处理","B":"药物如何影响机体","C":"药物在体内的时间变化","D":"合理用药的治疗方案","E":"药物效应动力学"},"answer":["A"],"rationale":"药动学研究机体对药物的处置过程，即药物在体内的吸收、分布、代谢和排泄，故为A。","expl":{"A":"正确，药动学研究机体对药物的吸收、分布、代谢和排泄等处理过程。","B":"药物如何影响机体是药效学的内容，非药动学。","C":"药物在体内的时间变化只是药动学的一部分，表述不完整。","D":"合理用药的治疗方案属临床药理学与治疗学，非药动学定义。","E":"药物效应动力学即药效学，与药动学是两个不同学科，此选项错误。"},"id":"ph01_q02","chapter":"第一章 绪言","chapterIdx":0,"num":2},{"type":"A","stem":"新药进行临床试验必须提供","options":{"A":"系统药理研究数据","B":"新药作用谱","C":"临床前研究资料","D":"LD50","E":"急慢性毒理研究数据"},"answer":["C"],"rationale":"新药开展临床试验前须完成临床前研究并提供资料，经批准后方可进行，故为C。","expl":{"A":"系统药理研究数据属临床前研究的一部分，不足以代表全部必备资料。","B":"新药作用谱仅是药效学内容之一，不能单独作为临床试验依据。","C":"正确，临床试验须以充分的临床前研究资料（药效、药动、毒理）为依据。","D":"LD50只是急性毒性指标之一，不能单独代表临床前资料。","E":"急慢性毒理研究数据仅属毒理学部分，非临床试验所需的全部资料。"},"id":"ph01_q03","chapter":"第一章 绪言","chapterIdx":0,"num":3},{"type":"A","stem":"关于化学治疗的叙述，正确的是","options":{"A":"指用化学药物抑制或杀灭体内病原体及肿瘤细胞以治疗疾病的方法","B":"仅指用化学药物治疗恶性肿瘤的方法","C":"由药理学总论提出，专指抗菌药物的临床给药方案","D":"指用药物抑制机体免疫反应以治疗自身免疫病的方法","E":"与化学治疗学是同一概念，二者可以互换使用"},"answer":["A"],"rationale":"化学治疗是用化学药物抑制或杀灭体内病原体（细菌、真菌、病毒、寄生虫等）及肿瘤细胞，以治疗感染性疾病和肿瘤的方法，故答案为 A。","expl":{"A":"正确，涵盖抗病原体与抗肿瘤两方面，是化疗药的总称来源。","B":"错误，化学治疗还包括感染性疾病的治疗，不限于恶性肿瘤。","C":"错误，该概念由Ehrlich提出，其“魔弹”设想开创了选择性杀灭病原体的研究方向。","D":"错误，抑制免疫反应属免疫抑制治疗，与化学治疗概念不同。","E":"错误，化学治疗是治疗方法，化学治疗学是研究药物-病原体-机体三者关系的学科。"},"id":"ph01_q04","chapter":"第一章 绪言","chapterIdx":0,"num":4}]},{"title":"第二章 药物效应动力学","questions":[{"type":"A","stem":"药物作用的基本表现是是机体器官组织","options":{"A":"功能升高或兴奋","B":"功能降低或抑制","C":"兴奋和/或抑制","D":"产生新的功能","E":"A 和 D"},"answer":["C"],"rationale":"药物作用的基本表现是使机体功能兴奋或抑制，或两者兼有，故为C。","expl":{"A":"功能升高或兴奋只是兴奋作用，未包括抑制作用，不全面。","B":"功能降低或抑制仅指抑制作用，遗漏了兴奋作用。","C":"正确，药物对机体的基本作用表现为兴奋和（或）抑制。","D":"药物不能使机体产生新的功能，只能调节原有功能，此说法错误。","E":"A与D均不全面或不正确，故不是答案。"},"id":"ph02_q01","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":1},{"type":"A","stem":"药物的副反应是与治疗效应同时发生的不良反应，此时的药物剂量是","options":{"A":"大于治疗量","B":"小于治疗量","C":"治疗剂量","D":"极量","E":"以上都不对"},"answer":["C"],"rationale":"副反应是药物在治疗剂量下出现的与治疗目的无关的作用，故为C。","expl":{"A":"大于治疗量属中毒量，引起的是毒性反应而非副反应。","B":"小于治疗量常无效，一般不引起副反应。","C":"正确，副反应发生在治疗剂量，是与治疗效应同时出现的不良反应。","D":"极量是最大治疗量，超出常致毒性反应，副反应概念不限于此。","E":"以上均不对，不符合副反应的定义。"},"id":"ph02_q02","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":2},{"type":"A","stem":"半数有效量是指","options":{"A":"临床有效量","B":"LD50","C":"引起 50%阳性反应的剂量","D":"效应强度","E":"以上都不是"},"answer":["C"],"rationale":"半数有效量（ED50）指引起50%阳性反应（半数有效）的剂量，故为C。","expl":{"A":"临床有效量是临床用药剂量，并非ED50的严格定义。","B":"LD50是半数致死量，属毒性指标，非有效量。","C":"正确，ED50即引起50%阳性反应（半数有效）的剂量。","D":"效应强度指药物作用强度，与半数有效量含义不同。","E":"以上都不是，因C为正确答案。"},"id":"ph02_q03","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":3},{"type":"A","stem":"药物半数致死量（LD50）是指","options":{"A":"致死量的一半","B":"中毒量的一半","C":"杀死半数病原微生物的剂量","D":"杀死半数寄生虫的剂量","E":"引起半数动物死亡的剂量"},"answer":["E"],"rationale":"LD50指能使半数实验动物死亡的剂量，用于评价药物急性毒性，故为E。","expl":{"A":"致死量的一半是字面误读，LD50不是简单除以2。","B":"中毒量的一半同样属误读，LD50是统计半数死亡的剂量。","C":"杀死半数病原微生物的剂量属抗菌药物评价概念，非LD50。","D":"杀死半数寄生虫的剂量是杀虫药评价指标，非LD50定义。","E":"正确，LD50是引起半数动物死亡的剂量。"},"id":"ph02_q04","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":4},{"type":"A","stem":"药物的极量是指","options":{"A":"一次量","B":"一日量","C":"疗程总量","D":"单位时间内注入量","E":"以上都不对"},"answer":["E"],"rationale":"极量是药典规定的最大治疗量（最大有效量），非一次量、一日量等，故以上都不对。","expl":{"A":"极量不是一次量，一次量指单次给药剂量。","B":"极量不是一日量，一日量指每日总剂量。","C":"疗程总量是整个疗程的累计剂量，与极量无关。","D":"单位时间内注入量是给药速度，与极量无关。","E":"正确，极量是最大治疗量，以上各项均不符合其定义。"},"id":"ph02_q05","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":5},{"type":"A","stem":"药物的治疗指数是","options":{"A":"ED50/LD50","B":"LD50/ED50","C":"LD5/ED95","D":"ED99/LD1","E":"ED95/LD5"},"answer":["B"],"rationale":"治疗指数为LD50与ED50的比值（TI=LD50/ED50），比值越大越安全，故为B。","expl":{"A":"ED50/LD50是治疗指数的倒数，不是治疗指数。","B":"正确，治疗指数TI=LD50/ED50。","C":"LD5/ED95是与安全范围相关的比值，非治疗指数。","D":"ED99/LD1无此标准定义。","E":"ED95/LD5不是治疗指数。"},"id":"ph02_q06","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":6},{"type":"A","stem":"药物与受体结合后，可激动受体，也可阻断受体，取决于","options":{"A":"药物是否具有亲和力","B":"药物是否具有内在活性","C":"药物的酸碱度","D":"药物的脂溶性","E":"药物的极性大小"},"answer":["B"],"rationale":"药物与受体结合后能否激动受体取决于其是否具有内在活性，故为B。","expl":{"A":"亲和力决定能否结合，但不决定是激动还是阻断。","B":"正确，有内在活性则激动受体，无内在活性则阻断受体。","C":"酸碱度影响药物解离与吸收，与激动或阻断无关。","D":"脂溶性影响药物跨膜，与激动或阻断无关。","E":"极性大小与跨膜有关，不影响内在活性。"},"id":"ph02_q07","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":7},{"type":"A","stem":"竞争性拮抗剂的特点是","options":{"A":"无亲和力，无内在活性","B":"有亲和力，无内在活性","C":"有亲和力，有内在活性","D":"无亲和力，有内在活性","E":"以上均不是"},"answer":["B"],"rationale":"竞争性拮抗剂有亲和力能与受体结合，但无内在活性，故不产生效应，为B。","expl":{"A":"无亲和力则不能与受体结合，不符合竞争性拮抗剂。","B":"正确，竞争性拮抗剂有亲和力而无内在活性。","C":"有亲和力且有内在活性的是激动药。","D":"无亲和力有内在活性在药理上不成立。","E":"以上均不是，因B正确。"},"id":"ph02_q08","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":8},{"type":"A","stem":"药物作用的双重性是指","options":{"A":"治疗作用和副作用","B":"对因治疗和对症治疗","C":"治疗作用和毒性作用","D":"治疗作用和不良反应","E":"局部作用和吸收作用"},"answer":["D"],"rationale":"药物作用双重性指药物既有治疗作用，又有不良反应，故为D。","expl":{"A":"治疗作用和副作用只是双重性的一部分，不完整。","B":"对因治疗和对症治疗同属治疗作用，非双重性。","C":"治疗作用和毒性作用未涵盖全部不良反应。","D":"正确，药物作用双重性即治疗作用与不良反应并存。","E":"局部作用和吸收作用属作用部位分类，与双重性无关。"},"id":"ph02_q09","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":9},{"type":"A","stem":"属于后遗效应的是","options":{"A":"青霉素过敏性休克","B":"地高辛引起的心律性失常","C":"呋塞米所致的心律失常","D":"保泰松所致的肝肾损害","E":"巴比妥类药催眠后所致的次晨宿醉现象"},"answer":["E"],"rationale":"后遗效应指停药后血药浓度已降至阈浓度以下仍残存的药理效应，巴比妥次晨宿醉属之。","expl":{"A":"青霉素过敏性休克属变态反应，非后遗效应。","B":"地高辛引起心律失常属毒性反应。","C":"呋塞米所致心律失常属毒性反应（电解质紊乱）。","D":"保泰松所致肝肾损害属毒性反应或药源性疾病。","E":"正确，巴比妥类催眠后次晨宿醉为典型后遗效应。"},"id":"ph02_q10","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":10},{"type":"A","stem":"量效曲线可以为用药提供下列哪种参考？","options":{"A":"药物的安全范围","B":"药物的疗效大小","C":"药物的毒性性质","D":"药物的体内过程","E":"药物的给药方案"},"answer":["E"],"rationale":"量效曲线可确定有效剂量与最大效应等，为制定给药方案提供依据，故为E。","expl":{"A":"安全范围需结合量效与毒效曲线，单独量效曲线不足。","B":"疗效大小（效能）只是量效曲线信息之一，非最全面选项。","C":"毒性性质需毒性试验与毒效曲线，非量效曲线所能提供。","D":"体内过程是药动学内容，量效曲线不反映。","E":"正确，量效曲线可指导剂量选择，为制定给药方案提供参考。"},"id":"ph02_q11","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":11},{"type":"A","stem":"药物的内在活性（效应力）是指","options":{"A":"药物穿透生物膜的能力","B":"药物对受体的亲合能力","C":"药物水溶性大小","D":"受体激动时的反应强度","E":"药物脂溶性大小"},"answer":["D"],"rationale":"内在活性（效应力）指药物激动受体后产生效应的能力，即受体激动时的反应强度，故为D。","expl":{"A":"穿透生物膜能力与脂溶性、跨膜有关，非内在活性。","B":"对受体的亲和能力是亲和力，非内在活性。","C":"水溶性大小影响溶解与吸收，与内在活性无关。","D":"正确，内在活性是药物激动受体引起反应的能力（反应强度）。","E":"脂溶性大小与跨膜有关，非内在活性。"},"id":"ph02_q12","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":12},{"type":"A","stem":"安全范围是指","options":{"A":"有效剂量的范围","B":"最小中毒量与治疗量间的距离","C":"最小治疗量至最小致死量间的距离","D":"ED95 与 LD5 间的距离","E":"最小治疗量与最小中毒量间的距离"},"answer":["E"],"rationale":"安全范围指最小治疗量与最小中毒量之间的距离，距离越大越安全，故为E。","expl":{"A":"有效剂量范围是有效量区间，非安全范围。","B":"最小中毒量与治疗量间距离表述含糊，非标准定义。","C":"最小治疗量至最小致死量间距过大，非安全范围定义。","D":"ED95与LD5间距是实验安全范围表示（安全系数），非本题标准定义。","E":"正确，安全范围是最小治疗量与最小中毒量之间的距离。"},"id":"ph02_q13","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":13},{"type":"A","stem":"副作用是在下述哪种剂量时产生的不良反应？","options":{"A":"中毒量","B":"治疗量","C":"无效量","D":"极量","E":"致死量"},"answer":["B"],"rationale":"副作用是治疗量下出现的与治疗目的无关的反应，故为B。","expl":{"A":"中毒量产生的是毒性反应，非副作用。","B":"正确，副作用在治疗剂量下产生。","C":"无效量不产生药理效应，也无副作用。","D":"极量虽在治疗范围内，但副作用概念仍指治疗量。","E":"致死量引起死亡，非副作用。"},"id":"ph02_q14","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":14},{"type":"A","stem":"可用于表示药物安全性的参数","options":{"A":"阈剂量","B":"效能","C":"效价强度","D":"治疗指数","E":"LD50"},"answer":["D"],"rationale":"治疗指数（LD50/ED50）是评价药物安全性的重要参数，故为D。","expl":{"A":"阈剂量是刚产生效应的剂量，与安全性无直接关系。","B":"效能反映最大效应，不直接表示安全性。","C":"效价强度反映剂量大小关系，非安全性指标。","D":"正确，治疗指数越大，药物越安全。","E":"LD50单独只能说明毒性，需与ED50结合才表示安全性。"},"id":"ph02_q15","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":15},{"type":"A","stem":"药原性疾病是","options":{"A":"严重的不良反应","B":"停药反应","C":"变态反应","D":"较难恢复的不良反应","E":"特异质反应"},"answer":["D"],"rationale":"药源性疾病是药物引起的较难恢复的机体损害（疾病），故为D。","expl":{"A":"严重不良反应未必都构成药源性疾病，概念不完全等同。","B":"停药反应是突然停药引起的，非药源性疾病。","C":"变态反应只是药源性疾病的一种类型。","D":"正确，药源性疾病指药物引起的较难恢复的损害（疾病）。","E":"特异质反应是遗传异常所致，非药源性疾病总称。"},"id":"ph02_q16","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":16},{"type":"A","stem":"药物的最大效能反映药物的","options":{"A":"内在活性","B":"效应强度","C":"亲和力","D":"量效关系","E":"时效关系"},"answer":["A"],"rationale":"药物的最大效能（效能）取决于其内在活性，内在活性高则最大效应大，故为A。","expl":{"A":"正确，效能反映药物的内在活性，内在活性越大最大效应越大。","B":"效应强度即效能本身，题目问其反映的本质，应为内在活性。","C":"亲和力影响效价强度，不决定最大效能。","D":"量效关系是描述效应的关系曲线，非效能反映的对象。","E":"时效关系描述效应随时间变化，与最大效能无直接关系。"},"id":"ph02_q17","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":17},{"type":"A","stem":"肾上腺素受体属于","options":{"A":"G 蛋白偶联受体","B":"含离子通道的受体","C":"具有酪氨酸激酶活性的受体","D":"细胞内受体","E":"以上均不是"},"answer":["A"],"rationale":"肾上腺素受体（α、β受体）属于G蛋白偶联受体（GPCR），故为A。","expl":{"A":"正确，α、β肾上腺素受体均为G蛋白偶联受体。","B":"含离子通道的受体如N胆碱受体（配体门控离子通道），非肾上腺素受体。","C":"具酪氨酸激酶活性的受体如胰岛素受体，非肾上腺素受体。","D":"细胞内受体如甾体激素受体，肾上腺素受体位于细胞膜上。","E":"以上均不是，因A正确。"},"id":"ph02_q18","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":18},{"type":"A","stem":"拮抗参数 pA2 的定义是","options":{"A":"使激动剂的效应增加 1 倍时竞争性拮抗剂浓度的负对数","B":"使激动剂的剂量增加 1 倍时竞争性拮抗剂浓度的负对数","C":"使激动剂的效应增加 1 倍时激动剂浓度的负对数","D":"使激动剂的效应不变时竞争性拮抗剂浓度的负对数","E":"使激动剂的效应增加 1 倍时非竞争性拮抗剂浓度的负对数"},"answer":["B"],"rationale":"pA2是使激动药剂量加倍仍维持原效应时竞争性拮抗药浓度的负对数，故为B。","expl":{"A":"pA2定义涉及激动药剂量加倍而非效应加倍，A错误。","B":"正确，pA2为使激动药剂量增加1倍而效应不变时拮抗药浓度的负对数。","C":"pA2是拮抗药浓度而非激动药浓度的负对数。","D":"效应不变是前提之一，但定义还要求激动药剂量加倍。","E":"pA2针对竞争性拮抗药，而非非竞争性拮抗药。"},"id":"ph02_q19","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":19},{"type":"A","stem":"药理效应是","options":{"A":"药物的初始作用","B":"药物作用的结果","C":"药物的特异性","D":"药物的选择性","E":"药物的临床疗效"},"answer":["B"],"rationale":"药理效应是药物作用的结果（机体功能变化的表现），故为B。","expl":{"A":"初始作用是药物作用的起始环节，非效应本身。","B":"正确，药理效应是药物作用引起的机体反应（结果）。","C":"特异性指药物对特定靶点的选择性作用，非效应。","D":"选择性是药物作用的范围特性，非效应。","E":"临床疗效是效应中对治疗有利的部分，非全部药理效应。"},"id":"ph02_q20","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":20},{"type":"A","stem":"储备受体是","options":{"A":"药物未结合的受体","B":"药物不结合的受体","C":"与药物结合过的受体","D":"药物难结合的受体","E":"与药物解离了的受体"},"answer":["A"],"rationale":"储备受体（spare receptor）指产生最大效应时仍未被药物占据（未结合）的受体，故为A。","expl":{"A":"正确，储备受体是药物未结合（未被占据）的受体。","B":"药物不结合的受体表述绝对，储备受体是可被结合但未结合的受体。","C":"与药物结合过的受体已被占据，非储备受体。","D":"药物难结合的受体概念不准确，储备受体是可结合受体。","E":"与药物解离了的受体已释放，非储备受体的定义。"},"id":"ph02_q21","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":21},{"type":"A","stem":"pD2 是","options":{"A":"解离常数的负对数","B":"拮抗常数的负对数","C":"解离常数","D":"拮抗常数","E":"平衡常数"},"answer":["A"],"rationale":"pD2是药物-受体复合物解离常数的负对数，反映亲和力，故为A。","expl":{"A":"正确，pD2=-logKD，即解离常数的负对数。","B":"拮抗常数（KB）的负对数为pA2，非pD2。","C":"pD2是负对数，不是解离常数本身。","D":"拮抗常数是KB，与pD2无关。","E":"平衡常数表述笼统，非pD2的准确定义。"},"id":"ph02_q22","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":22},{"type":"A","stem":"关于受体二态模型学说的叙述，下列哪项是错误的？","options":{"A":"拮抗药对 R 及 R*的亲和力不等","B":"受体蛋白有可以互变的构型状态。即静息态（R）和活动态（R*）","C":"静息时平衡趋势向于 R","D":"激动药只与 R*有较大亲和力","E":"部分激动药与 R 及 R*都能结合，但对 R*的亲和力大于对 R 的亲和力"},"answer":["D"],"rationale":"激动药对R*亲和力较大，但并非“只与”R*结合，也可与静息态R结合，故D叙述错误。","expl":{"A":"正确，拮抗药对R及R*亲和力不等（对R亲和力较大）。","B":"正确，受体蛋白有静息态R和活动态R*两种可互变构型。","C":"正确，静息时受体平衡偏向R态。","D":"错误，激动药并非只与R*结合，对R也有一定亲和力，只是对R*亲和力较大。","E":"正确，部分激动药对R及R*均能结合，对R*亲和力大于R。"},"id":"ph02_q23","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":23},{"type":"A","stem":"质反应的累加曲线是","options":{"A":"对称 S 型曲线","B":"长尾 S 型曲线","C":"直线","D":"双曲线","E":"正态分布曲线"},"answer":["A"],"rationale":"质反应累加量效曲线呈对称的S型曲线，故为A。","expl":{"A":"正确，质反应累加量效曲线为对称S型曲线。","B":"长尾S型是量反应（纵坐标效应、横坐标剂量）曲线。","C":"直线不是质反应累加曲线的形态。","D":"双曲线不符合量效曲线特征。","E":"正态分布曲线是质反应频数分布，非累加量效曲线。"},"id":"ph02_q24","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":24},{"type":"A","stem":"从下列 pD2 值中可知，与受体亲和力最小的是","options":{"A":"1","B":"2","C":"4","D":"5","E":"6"},"answer":["A"],"rationale":"pD2越大亲和力越大，故pD2=1时亲和力最小，为A。","expl":{"A":"正确，pD2值最小（1），故亲和力最小。","B":"pD2=2大于1，亲和力较大。","C":"pD2=4，亲和力更大。","D":"pD2=5，亲和力更大。","E":"pD2=6，亲和力最大。"},"id":"ph02_q25","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":25},{"type":"A","stem":"从下列 pA2 值可知拮抗作用最强的是","options":{"A":"0.1","B":"0.5","C":"1.0","D":"1.5","E":"1.6"},"answer":["E"],"rationale":"pA2越大表示拮抗药作用越强，故pA2=1.6者拮抗最强，为E。","expl":{"A":"0.1最小，拮抗作用最弱。","B":"0.5较小，拮抗作用弱。","C":"1.0居中，拮抗作用较弱。","D":"1.5较大，但小于1.6。","E":"正确，pA2值最大（1.6），拮抗作用最强。"},"id":"ph02_q26","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":26},{"type":"A","stem":"某降压药停药后血压剧烈回升，此种现象称为","options":{"A":"变态反应","B":"停药反应","C":"后遗效应","D":"特异质反应","E":"毒性反应"},"answer":["B"],"rationale":"停药后血压剧烈回升是长期用药突然停药引起的反跳，属停药反应，故为B。","expl":{"A":"变态反应与免疫有关，非停药所致。","B":"正确，突然停药致血压反跳属停药反应（反跳现象）。","C":"后遗效应是血药浓度降至阈下后残存的效应，非反跳。","D":"特异质反应与遗传异常有关，非停药反应。","E":"毒性反应是剂量过大所致，非停药引起。"},"id":"ph02_q27","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":27},{"type":"A","stem":"下列关于激动药的描述，错误的是","options":{"A":"有内在活性","B":"与受体有亲和力","C":"量效曲线呈 S 型","D":"pA2 值越大作用越强","E":"与受体迅速解离"},"answer":["D"],"rationale":"pA2是拮抗药的拮抗参数，不是评价激动药作用的指标，故D错误。","expl":{"A":"正确，激动药具有内在活性。","B":"正确，激动药与受体有亲和力。","C":"正确，激动药量效曲线呈S型。","D":"错误，pA2是竞争性拮抗药的作用强度参数，与激动药作用强弱无关。","E":"正确，激动药与受体结合后可迅速解离（可逆）。"},"id":"ph02_q28","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":28},{"type":"A","stem":"下列关于受体的叙述，正确的是","options":{"A":"受体是首先与药物结合并起反应的细胞成分","B":"受体都是细胞膜上的蛋白质","C":"受体是遗传基因生成的，其分布密度是固定不变的","D":"受体与配基或激动药结合后都引起兴奋性效应","E":"药物都是通过激动或抑制相应受体而发挥作用的"},"answer":["A"],"rationale":"受体是首先与药物结合并引起反应的细胞成分（靶点），故A正确。","expl":{"A":"正确，受体是药物首先结合并触发效应的细胞成分。","B":"受体不全在细胞膜上，还有细胞内受体（如甾体激素受体）。","C":"受体密度可受调节（上调或下调），非固定不变。","D":"激动受体可产生兴奋也可产生抑制效应，非都兴奋。","E":"药物并非都通过受体作用，有些直接作用于酶、离子通道等。"},"id":"ph02_q29","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":29},{"type":"B","stem":"高敏性是指","options":{"A":"药物引起的反应与个体体质有关，与用药剂量无关","B":"等量药物引起和一般病人相似但强度更高的药理效应或毒性","C":"用药一段时间后，病人对药物产生精神上依赖，中断用药，出现主观不适","D":"长期用药，需逐渐增加剂量，才可保持药效不减","E":"长期用药，产生生理上依赖，停药后出现戒断症状"},"answer":["B"],"rationale":"高敏性指等量药物引起比一般人更强的药理效应或毒性，故为B。","expl":{"A":"与体质有关且与剂量无关的是过敏或特异质反应，非高敏性。","B":"正确，高敏性是个体对等量药物反应增强。","C":"精神依赖、中断不适是习惯性，非高敏性。","D":"逐渐增量保持药效是耐受性，非高敏性。","E":"生理依赖、停药戒断是成瘾性，非高敏性。"},"id":"ph02_q30","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":30},{"type":"B","stem":"过敏反应是指","options":{"A":"药物引起的反应与个体体质有关，与用药剂量无关","B":"等量药物引起和一般病人相似但强度更高的药理效应或毒性","C":"用药一段时间后，病人对药物产生精神上依赖，中断用药，出现主观不适","D":"长期用药，需逐渐增加剂量，才可保持药效不减","E":"长期用药，产生生理上依赖，停药后出现戒断症状"},"answer":["A"],"rationale":"过敏反应（变态反应）与个体体质（免疫）有关，与剂量关系不大，故为A。","expl":{"A":"正确，过敏反应与体质有关，剂量关系不大（极微量即可发生）。","B":"等量药物反应增强是高敏性，非过敏反应。","C":"精神依赖、主观不适是习惯性，非过敏反应。","D":"逐渐增量是耐受性，非过敏反应。","E":"生理依赖、戒断症状是成瘾性，非过敏反应。"},"id":"ph02_q31","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":31},{"type":"B","stem":"习惯性是指","options":{"A":"药物引起的反应与个体体质有关，与用药剂量无关","B":"等量药物引起和一般病人相似但强度更高的药理效应或毒性","C":"用药一段时间后，病人对药物产生精神上依赖，中断用药，出现主观不适","D":"长期用药，需逐渐增加剂量，才可保持药效不减","E":"长期用药，产生生理上依赖，停药后出现戒断症状"},"answer":["C"],"rationale":"习惯性指用药一段时间后产生精神依赖，中断用药出现主观不适，故为C。","expl":{"A":"与体质有关且与剂量无关的是过敏反应。","B":"等量药物反应增强是高敏性。","C":"正确，习惯性表现为精神依赖，停药后有主观不适。","D":"逐渐增量是耐受性，非习惯性。","E":"生理依赖、戒断症状是成瘾性，非习惯性。"},"id":"ph02_q32","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":32},{"type":"B","stem":"耐受性是指","options":{"A":"药物引起的反应与个体体质有关，与用药剂量无关","B":"等量药物引起和一般病人相似但强度更高的药理效应或毒性","C":"用药一段时间后，病人对药物产生精神上依赖，中断用药，出现主观不适","D":"长期用药，需逐渐增加剂量，才可保持药效不减","E":"长期用药，产生生理上依赖，停药后出现戒断症状"},"answer":["D"],"rationale":"耐受性指长期用药后需逐渐增加剂量才能维持原有效果，故为D。","expl":{"A":"与体质有关且与剂量无关的是过敏反应。","B":"等量药物反应增强是高敏性。","C":"精神依赖是习惯性，非耐受性。","D":"正确，耐受性表现为需逐渐增量才能保持药效不减。","E":"生理依赖、戒断症状是成瘾性，非耐受性。"},"id":"ph02_q33","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":33},{"type":"B","stem":"成瘾性是指","options":{"A":"药物引起的反应与个体体质有关，与用药剂量无关","B":"等量药物引起和一般病人相似但强度更高的药理效应或毒性","C":"用药一段时间后，病人对药物产生精神上依赖，中断用药，出现主观不适","D":"长期用药，需逐渐增加剂量，才可保持药效不减","E":"长期用药，产生生理上依赖，停药后出现戒断症状"},"answer":["E"],"rationale":"成瘾性指长期用药产生生理依赖，停药后出现戒断症状，故为E。","expl":{"A":"与体质有关且与剂量无关的是过敏反应。","B":"等量药物反应增强是高敏性。","C":"精神依赖是习惯性，非成瘾性。","D":"逐渐增量是耐受性，非成瘾性。","E":"正确，成瘾性为生理依赖，停药出现戒断症状。"},"id":"ph02_q34","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":34},{"type":"B","stem":"起后继信息传导系统作用","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["B"],"rationale":"第二信使（如cAMP、IP3）在受体激活后传递、放大信息，起后继信息传导作用，故为B。","expl":{"A":"受体是识别并结合配体、启动信号的部位，非后继传导系统。","B":"正确，第二信使承担受体后的信息传导作用。","C":"激动药是激活受体的配体，非传导系统。","D":"结合体仅结合配体，无传导功能。","E":"拮抗药阻断受体，不传导信号。"},"id":"ph02_q35","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":35},{"type":"B","stem":"能与配体结合触发效应","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["A"],"rationale":"受体能与配体（如激素、递质）特异性结合并触发效应，故为A。","expl":{"A":"正确，受体与配体结合后触发细胞效应。","B":"第二信使不直接结合配体，而是传导信号。","C":"激动药是与受体结合的配体，非与配体结合者。","D":"结合体虽与配体结合但不触发效应。","E":"拮抗药与受体结合不触发效应。"},"id":"ph02_q36","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":36},{"type":"B","stem":"能与受体结合触发效应","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["C"],"rationale":"激动药能与受体结合并激动受体，触发效应，故为C。","expl":{"A":"受体是与配体结合触发效应，题干为“与受体结合”。","B":"第二信使不直接与受体结合触发效应。","C":"正确，激动药与受体结合后触发效应。","D":"结合体与配体结合但不触发效应。","E":"拮抗药与受体结合但不触发效应。"},"id":"ph02_q37","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":37},{"type":"B","stem":"能与配体结合不能触发效应","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["D"],"rationale":"结合体（如配体结合蛋白）能与配体结合，但不具备触发效应的能力，故为D。","expl":{"A":"受体与配体结合可触发效应，非不能触发。","B":"第二信使传导信号，不直接结合配体。","C":"激动药与受体结合触发效应。","D":"正确，结合体仅与配体结合，不能触发效应。","E":"拮抗药是与受体结合不触发效应，非与配体结合。"},"id":"ph02_q38","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":38},{"type":"B","stem":"起放大分化和整合作用","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["B"],"rationale":"第二信使系统可对信号进行放大、分化和整合，故为B。","expl":{"A":"受体主要识别信号，不负责放大整合。","B":"正确，第二信使起放大、分化和整合信息的作用。","C":"激动药激活受体，非信号整合系统。","D":"结合体仅结合配体，无整合功能。","E":"拮抗药阻断受体，无放大整合作用。"},"id":"ph02_q39","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":39},{"type":"B","stem":"能与受体结合不触发效应","options":{"A":"受体","B":"第二信使","C":"激动药","D":"结合体","E":"拮抗药"},"answer":["E"],"rationale":"拮抗药能与受体结合（占据受体），但无内在活性，不触发效应，故为E。","expl":{"A":"受体与配体结合可触发效应。","B":"第二信使传导信号，非结合受体。","C":"激动药与受体结合触发效应。","D":"结合体是与配体结合，非与受体结合。","E":"正确，拮抗药与受体结合但不触发效应。"},"id":"ph02_q40","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":40},{"type":"B","stem":"对称 S 型的量效曲线应为","options":{"A":"纵坐标为效应，横坐标为剂量","B":"纵坐标为剂量，横坐标为效应","C":"纵坐标为效应，横坐标为对数剂量","D":"纵坐标为对数剂量，横坐标为效应","E":"纵坐标为对数剂量，横坐标为对数效应"},"answer":["C"],"rationale":"以效应为纵坐标、对数剂量为横坐标作图，量效曲线呈对称S型，故为C。","expl":{"A":"纵坐标为效应、横坐标为剂量时得长尾S型，非对称S型。","B":"纵、横坐标颠倒，不符合。","C":"正确，纵坐标为效应、横坐标为对数剂量时曲线为对称S型。","D":"纵、横坐标颠倒，不符合。","E":"纵坐标为对数剂量非标准作图方式。"},"id":"ph02_q41","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":41},{"type":"B","stem":"长尾 S 型的量效曲线应为","options":{"A":"纵坐标为效应，横坐标为剂量","B":"纵坐标为剂量，横坐标为效应","C":"纵坐标为效应，横坐标为对数剂量","D":"纵坐标为对数剂量，横坐标为效应","E":"纵坐标为对数剂量，横坐标为对数效应"},"answer":["A"],"rationale":"以效应为纵坐标、剂量（非对数）为横坐标时，量效曲线呈长尾S型，故为A。","expl":{"A":"正确，纵坐标为效应、横坐标为剂量时呈长尾S型。","B":"纵、横坐标颠倒，不符合。","C":"横坐标为对数剂量时是对称S型，非长尾S型。","D":"纵、横坐标颠倒，不符合。","E":"纵坐标为对数剂量非标准作图方式。"},"id":"ph02_q42","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":42},{"type":"B","stem":"属毒性反应的是","options":{"A":"患者服治疗量的伯氨喹所致的溶血反应","B":"强心甙所致的心律失常","C":"四环素和氯霉素所致的二重感染","D":"阿托品在治疗量解除胃肠痉挛时所致的口干、心悸","E":"巴比妥类药物所致的次晨宿醉现象"},"answer":["B"],"rationale":"强心苷（强心甙）中毒引起的心律失常属剂量过大所致的毒性反应，故为B。","expl":{"A":"伯氨喹溶血属特异质反应（G6PD缺乏），非毒性反应。","B":"正确，强心苷所致心律失常是其毒性反应。","C":"四环素、氯霉素二重感染属继发反应，非毒性反应。","D":"阿托品口干、心悸属副作用，非毒性反应。","E":"巴比妥次晨宿醉属后遗效应，非毒性反应。"},"id":"ph02_q43","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":43},{"type":"B","stem":"属后遗效应的是","options":{"A":"患者服治疗量的伯氨喹所致的溶血反应","B":"强心甙所致的心律失常","C":"四环素和氯霉素所致的二重感染","D":"阿托品在治疗量解除胃肠痉挛时所致的口干、心悸","E":"巴比妥类药物所致的次晨宿醉现象"},"answer":["E"],"rationale":"巴比妥类催眠后次晨宿醉是血药浓度已降至阈下仍残存的效应，属后遗效应，故为E。","expl":{"A":"伯氨喹溶血属特异质反应。","B":"强心苷心律失常属毒性反应。","C":"二重感染属继发反应。","D":"阿托品口干、心悸属副作用。","E":"正确，巴比妥次晨宿醉为后遗效应。"},"id":"ph02_q44","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":44},{"type":"B","stem":"属继发反应的是","options":{"A":"患者服治疗量的伯氨喹所致的溶血反应","B":"强心甙所致的心律失常","C":"四环素和氯霉素所致的二重感染","D":"阿托品在治疗量解除胃肠痉挛时所致的口干、心悸","E":"巴比妥类药物所致的次晨宿醉现象"},"answer":["C"],"rationale":"四环素、氯霉素致菌群失调引起二重感染是药物作用后的继发后果，属继发反应，故为C。","expl":{"A":"伯氨喹溶血属特异质反应。","B":"强心苷心律失常属毒性反应。","C":"正确，广谱抗生素引起二重感染属继发反应。","D":"阿托品口干、心悸属副作用。","E":"巴比妥次晨宿醉属后遗效应。"},"id":"ph02_q45","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":45},{"type":"B","stem":"属特异质反应的是","options":{"A":"患者服治疗量的伯氨喹所致的溶血反应","B":"强心甙所致的心律失常","C":"四环素和氯霉素所致的二重感染","D":"阿托品在治疗量解除胃肠痉挛时所致的口干、心悸","E":"巴比妥类药物所致的次晨宿醉现象"},"answer":["A"],"rationale":"伯氨喹在治疗量引起溶血是G6PD缺乏的遗传异常所致，属特异质反应，故为A。","expl":{"A":"正确，治疗量伯氨喹致溶血（G6PD缺乏）属特异质反应。","B":"强心苷心律失常属毒性反应。","C":"二重感染属继发反应。","D":"阿托品口干、心悸属副作用。","E":"巴比妥次晨宿醉属后遗效应。"},"id":"ph02_q46","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":46},{"type":"B","stem":"属副作用的是","options":{"A":"患者服治疗量的伯氨喹所致的溶血反应","B":"强心甙所致的心律失常","C":"四环素和氯霉素所致的二重感染","D":"阿托品在治疗量解除胃肠痉挛时所致的口干、心悸","E":"巴比妥类药物所致的次晨宿醉现象"},"answer":["D"],"rationale":"阿托品治疗量解除胃肠痉挛时的口干、心悸是与治疗目的无关的反应，属副作用，故为D。","expl":{"A":"伯氨喹溶血属特异质反应。","B":"强心苷心律失常属毒性反应。","C":"二重感染属继发反应。","D":"正确，阿托品治疗量致口干、心悸属副作用。","E":"巴比妥次晨宿醉属后遗效应。"},"id":"ph02_q47","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":47},{"type":"C","stem":"受体激动剂的特点中应包括","options":{"A":"对受体有较强的亲和力","B":"对受体有较强的内在活性","C":"两者都有","D":"两者都无"},"answer":["C"],"rationale":"受体激动剂既有较强亲和力，又有较强内在活性，故两者都有。","expl":{"A":"激动剂确需亲和力，但仅选亲和力不完整。","B":"激动剂确需内在活性，但仅选内在活性不完整。","C":"正确，激动剂兼具较强亲和力和较强内在活性。","D":"两者都无不符合激动剂特征。"},"id":"ph02_q48","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":48},{"type":"C","stem":"部分激动剂的特点中应包括","options":{"A":"对受体有较强的亲和力","B":"对受体有较强的内在活性","C":"两者都有","D":"两者都无"},"answer":["A"],"rationale":"部分激动剂对受体有较强亲和力，但内在活性较弱，故为A。","expl":{"A":"正确，部分激动剂亲和力较强，但内在活性弱。","B":"部分激动剂内在活性弱，非较强内在活性。","C":"两者都有不符合部分激动剂（内在活性弱）。","D":"两者都无不符合，因其有亲和力。"},"id":"ph02_q49","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":49},{"type":"C","stem":"受体阻断剂的特点中可包括","options":{"A":"对受体有较强的亲和力","B":"对受体有较强的内在活性","C":"两者都有","D":"两者都无"},"answer":["A"],"rationale":"受体阻断剂（拮抗药）对受体有较强亲和力，但无内在活性，故为A。","expl":{"A":"正确，阻断剂有较强亲和力但无内在活性。","B":"阻断剂无内在活性，故B不符合。","C":"两者都有不符合阻断剂。","D":"两者都无不符合，因其有亲和力。"},"id":"ph02_q50","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":50},{"type":"C","stem":"表示拮抗药的作用强度用","options":{"A":"pA2","B":"pD2","C":"两者均是","D":"两者均无"},"answer":["A"],"rationale":"pA2是表示竞争性拮抗药作用强度的参数，故为A。","expl":{"A":"正确，pA2表示拮抗药作用强度。","B":"pD2表示激动药与受体亲和力，非拮抗强度。","C":"两者均是错误，pD2不表示拮抗强度。","D":"两者均无错误，pA2正是拮抗强度参数。"},"id":"ph02_q51","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":51},{"type":"C","stem":"表示药物与受体的亲和力用","options":{"A":"pA2","B":"pD2","C":"两者均是","D":"两者均无"},"answer":["B"],"rationale":"pD2（-logKD）表示药物与受体的亲和力，故为B。","expl":{"A":"pA2表示拮抗药作用强度，非亲和力。","B":"正确，pD2表示药物与受体的亲和力。","C":"两者均是错误，pA2不表示亲和力。","D":"两者均无错误，pD2正是亲和力参数。"},"id":"ph02_q52","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":52},{"type":"C","stem":"表示受体动力学的参数用","options":{"A":"pA2","B":"pD2","C":"两者均是","D":"两者均无"},"answer":["C"],"rationale":"pA2和pD2均为受体动力学（受体-药物相互作用）参数，故两者均是。","expl":{"A":"pA2是拮抗参数，属受体动力学参数，但仅选A不完整。","B":"pD2是亲和力参数，属受体动力学参数，但仅选B不完整。","C":"正确，pA2和pD2均为受体动力学参数。","D":"两者均无错误。"},"id":"ph02_q53","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":53},{"type":"C","stem":"表示药物与受体结合的内在活性用","options":{"A":"pA2","B":"pD2","C":"两者均是","D":"两者均无"},"answer":["D"],"rationale":"内在活性用α（效应力）或最大效应表示，pA2和pD2均不表示内在活性，故两者均无。","expl":{"A":"pA2表示拮抗强度，不表示内在活性。","B":"pD2表示亲和力，不表示内在活性。","C":"两者均是错误。","D":"正确，pA2和pD2均不表示内在活性。"},"id":"ph02_q54","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":54},{"type":"X","stem":"有关量效关系的描述，正确的是","options":{"A":"在一定范围内，药理效应强度与血浆药物浓度呈正相关","B":"量反应的量效关系皆呈常态分布曲线","C":"质反应的量效关系皆呈常态分布曲线","D":"LD50 与 ED50 均是量反应中出现的剂量","E":"量效曲线可以反映药物效能和效价强度"},"answer":["A","E"],"rationale":"一定范围内效应强度与血药浓度正相关，量效曲线可反映效能和效价强度，故为AE。","expl":{"A":"正确，一定范围内药理效应强度与血药浓度呈正相关。","B":"量反应量效曲线为长尾S型或双曲线，非正态分布。","C":"质反应频数分布呈正态分布，其累加量效曲线为S型，非正态分布。","D":"LD50与ED50是质反应的参数，非量反应。","E":"正确，量效曲线可反映药物效能和效价强度。"},"id":"ph02_q55","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":55},{"type":"X","stem":"质反应的特点有","options":{"A":"频数分布曲线为正态分布曲线","B":"无法计算出 ED50","C":"用全或无、阳性或阴性表示","D":"可用死亡与生存、惊厥与不惊厥表示","E":"累加量效曲线为 S 型量效曲线"},"answer":["A","C","D","E"],"rationale":"质反应以全或无表示，频数分布呈正态，累加曲线为S型，并可计算ED50，故为ACDE。","expl":{"A":"正确，质反应频数分布曲线为正态分布。","B":"质反应可计算ED50（半数有效量），此说法错误。","C":"正确，质反应以全或无、阳性或阴性表示。","D":"正确，可用死亡与生存、惊厥与不惊厥等表示。","E":"正确，质反应累加量效曲线为S型。"},"id":"ph02_q56","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":56},{"type":"X","stem":"药物作用包括","options":{"A":"引起机体功能或形态改变","B":"引起机体体液成分改变","C":"抑制或杀灭入侵的病原微生物或寄生虫","D":"改变机体的反应性","E":"补充体内营养物质或激素的不足"},"answer":["A","B","C","D","E"],"rationale":"药物作用包括改变机体功能形态、体液成分、抑制病原微生物、改变反应性及补充物质等，全对。","expl":{"A":"正确，药物可改变机体功能或形态。","B":"正确，药物可改变机体体液成分。","C":"正确，药物可抑制或杀灭病原微生物、寄生虫。","D":"正确，药物可改变机体反应性。","E":"正确，药物可补充体内营养物质或激素的不足。"},"id":"ph02_q57","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":57},{"type":"X","stem":"药物与受体结合的特性有","options":{"A":"高度特异性","B":"高度亲和力","C":"可逆性","D":"饱和性","E":"高度效应力"},"answer":["A","B","C","D"],"rationale":"药物与受体结合具特异性、亲和力、可逆性和饱和性，效应力（内在活性）非结合特性，故为ABCD。","expl":{"A":"正确，药物与受体结合具高度特异性。","B":"正确，具高度亲和力。","C":"正确，结合可逆。","D":"正确，结合具饱和性。","E":"效应力是激动受体产生效应的能力，非结合特性。"},"id":"ph02_q58","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":58},{"type":"X","stem":"下列正确的描述是","options":{"A":"药物可通过受体发挥效应","B":"药物激动受体即表现为兴奋效应","C":"安慰剂不会产生治疗作用","D":"药物化学结构相似，则作用相似","E":"药效与被占领的受体数目成正比"},"answer":["A","E"],"rationale":"药物可通过受体发挥效应，且按占领学说药效与被占领受体数目成正比，故为AE。","expl":{"A":"正确，药物可通过受体发挥效应。","B":"激动受体可为兴奋也可为抑制，非皆表现为兴奋。","C":"安慰剂可产生安慰剂效应（如镇痛），非无治疗作用。","D":"化学结构相似作用未必相似，拮抗药与激动药结构相近而作用相反。","E":"正确，按占领学说药效与被占领受体数目成正比。"},"id":"ph02_q59","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":59},{"type":"X","stem":"下列有关亲和力的描述，正确的是","options":{"A":"亲和力是药物与受体结合的能力","B":"亲和力是药物与受体结合后引起效应的能力","C":"亲和力越大，则药物效价越强","D":"亲和力越大，则药物效能越强","E":"亲和力越大，则药物作用维持时间越长"},"answer":["A","C"],"rationale":"亲和力是药物与受体结合的能力，亲和力越大效价越强，故为AC。","expl":{"A":"正确，亲和力是药物与受体结合的能力。","B":"结合后引起效应的能力是内在活性，非亲和力。","C":"正确，亲和力越大，药物效价强度越大。","D":"效能由内在活性决定，非亲和力。","E":"作用维持时间与药动学有关，非亲和力。"},"id":"ph02_q60","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":60},{"type":"X","stem":"药效动力学的内容包括","options":{"A":"药物的作用与临床疗效","B":"给药方法和用量","C":"药物的剂量与量效关系","D":"药物的作用机制","E":"药物的不良反应和禁忌症"},"answer":["A","C","D","E"],"rationale":"药效学研究作用、剂量与量效关系、作用机制及不良反应等，给药方法用量属药动学或治疗学，故为ACDE。","expl":{"A":"正确，药效学包括药物作用与临床疗效。","B":"给药方法和用量属药动学或临床用药范畴，非药效学主要内容。","C":"正确，药效学包括剂量与量效关系。","D":"正确，药效学包括药物作用机制。","E":"正确，药效学包括不良反应和禁忌症。"},"id":"ph02_q61","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":61},{"type":"X","stem":"竞争性拮抗剂的特点有","options":{"A":"本身可产生效应","B":"降低激动剂的效价","C":"降低激动剂的效能","D":"可使激动剂的量效曲线平行右移","E":"可使激动剂的量效曲线平行左移"},"answer":["B","D"],"rationale":"竞争性拮抗剂无内在活性，降低激动药效价，使其量效曲线平行右移，故为BD。","expl":{"A":"竞争性拮抗剂本身无内在活性，不产生效应。","B":"正确，竞争性拮抗剂降低激动药的效价强度。","C":"加大激动药剂量可恢复最大效应，不降低效能。","D":"正确，使激动药量效曲线平行右移。","E":"量效曲线是右移而非左移。"},"id":"ph02_q62","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":62},{"type":"X","stem":"可作为用药安全性的指标有","options":{"A":"TD50/ED50","B":"极量","C":"ED95~TD5 之间的距离","D":"TC50/EC50","E":"常用剂量范围"},"answer":["A","C","D"],"rationale":"TD50/ED50（治疗指数）、ED95~TD5距离（安全范围）和TC50/EC50均为安全性指标，故为ACD。","expl":{"A":"正确，TD50/ED50即治疗指数，是安全性指标。","B":"极量是最大治疗量，非评价安全性的比值或范围指标。","C":"正确，ED95~TD5之间距离为安全范围。","D":"正确，TC50/EC50为化疗药物的治疗指数。","E":"常用剂量范围不是安全性评价指标。"},"id":"ph02_q63","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":63},{"type":"A","stem":"长期应用普萘洛尔后突然停药出现血压反跳、心绞痛加重，其受体机制是","options":{"A":"受体向上调节","B":"受体向下调节","C":"受体脱敏","D":"受体数量无明显改变","E":"G蛋白表达增加"},"answer":["A"],"rationale":"长期阻断β受体可使受体数目增多、敏感性增高即向上调节，突然停药后内源性儿茶酚胺作用相对增强，出现反跳现象，故答案为 A。","expl":{"A":"正确，长期使用拮抗药引起受体数目上调，停药后递质效应被放大，出现反跳。","B":"错误，向下调节见于受体长期受激动药作用，受体数目减少、反应减弱。","C":"错误，受体脱敏是受体对激动药反应性降低，与本例的反跳现象方向相反。","D":"错误，反跳恰恰说明受体数目和敏感性已经发生了改变。","E":"错误，反跳主要由受体数目上调引起，与G蛋白表达增加无直接因果关系。"},"id":"ph02_q64","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":64},{"type":"A","stem":"甲、乙两药的治疗指数相同，但甲药量效曲线斜率较陡，评价两药安全性更可靠的参数是","options":{"A":"效价强度","B":"最大效能","C":"半数有效量","D":"亲和力","E":"安全范围"},"answer":["E"],"rationale":"治疗指数相同的药物因量效曲线斜率不同，有效量曲线与致死量曲线的重叠程度不同，安全范围即ED5与LD5之间的距离能更可靠地反映安全性，故答案为 E。","expl":{"A":"错误，效价强度反映药物达到一定效应所需剂量的大小，与用药安全性无关。","B":"错误，最大效能反映药物能产生的最大效应，不能说明安全窗的宽窄。","C":"错误，半数有效量只描述50%个体有效时的剂量，单独使用无法评价安全性。","D":"错误，亲和力是药物与受体结合能力的指标，与治疗安全范围无关。","E":"正确，曲线斜率大者ED5与LD5间距较宽，安全范围较大，故用它评价更可靠。"},"id":"ph02_q65","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":65}]},{"title":"第三章 药物代谢动力学","questions":[{"type":"A","stem":"某弱酸药物 pka=3.4,在血浆中解离百分率约","options":{"A":"10%","B":"90%","C":"99%","D":"99.9%","E":"99.99%"},"answer":["E"],"rationale":"血浆pH约7.4，比弱酸pKa3.4高约4个单位，弱酸在碱性环境几乎全部解离，解离度约99.99%。","expl":{"A":"10%，错误，血浆偏碱性，弱酸解离远高于此值。","B":"90%，偏小，未达弱酸在血浆中的实际解离度。","C":"99%，仍偏小，实际接近全部解离。","D":"99.9%，仍略偏小。","E":"正确，pH与pKa相差4个单位，解离约99.99%。"},"id":"ph03_q01","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":1},{"type":"A","stem":"阿司匹林的 pKa 是 3.5,它在 pH 为 7.5 肠液中可吸收约","options":{"A":"1%","B":"0. 1%","C":"0.01%","D":"10%","E":"99%"},"answer":["C"],"rationale":"阿司匹林为弱酸，在pH7.5肠液中几乎全部解离，非解离（可吸收）型仅约0.01%。","expl":{"A":"1%，偏大。","B":"0.1%，偏大。","C":"正确，非解离型约1/(1+10^4)≈0.01%。","D":"10%，错误，肠液碱性使弱酸解离多、吸收少。","E":"99%，错误，这是解离型比例而非可吸收型。"},"id":"ph03_q02","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":2},{"type":"A","stem":"某弱碱性药在 pH5 时，非解离部分为 90.9%，该药 pKa 的接近数值","options":{"A":"2","B":"3","C":"4","D":"5","E":"6"},"answer":["E"],"rationale":"按弱碱性药 pKa=pH+lg(解离/非解离) 计算：若解离部分为90.9%，则 pKa=5+lg(90.9/9.1)=5+1=6。（原题写“非解离部分为90.9%”应为“解离部分”之笔误。）","expl":{"A":"错误，pKa≈2 时在 pH5 几乎全解离，与题设不符。","B":"错误，pKa≈3 时解离程度更大，与题设不符。","C":"错误，pKa≈4 对应“非解离90.9%”，但原答案按“解离90.9%”取值。","D":"错误，pKa≈5 时解离与未解离各约50%。","E":"正确，解离90.9%时 pKa=pH+lg(解离/非解离)=5+1=6。"},"id":"ph03_q03","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":3},{"type":"A","stem":"下列情况可称为首关消除：","options":{"A":"苯巴比妥钠肌注后被肝药酶代谢，使血中浓度降低","B":"硝酸甘油舌下给药，自口腔粘膜吸收，经肝代谢后药效降低","C":"青霉素口服后被胃酸破坏，使吸收入血的药量减少","D":"普萘洛尔口服，经肝代谢，使进入体循环的药量减少"},"answer":["D"],"rationale":"首关消除指口服药物经肠壁和肝脏代谢后进入体循环的药量减少，普萘洛尔口服有明显首关消除。","expl":{"A":"苯巴比妥钠肌注不经门静脉，属一般代谢而非首关消除。","B":"硝酸甘油舌下给药不经首关，经肝代谢是吸收后的代谢。","C":"青霉素口服被胃酸破坏属胃肠道破坏，非首关消除。","D":"正确，口服经肝代谢使进入体循环药量减少，符合首关消除。"},"id":"ph03_q04","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":4},{"type":"A","stem":"弱酸性药物从胃肠道吸收的主要部位是：","options":{"A":"胃粘膜","B":"小肠","C":"横结肠","D":"乙状结肠","E":"十二指肠"},"answer":["B"],"rationale":"弱酸性药物虽在胃中多呈非解离型易吸收，但小肠吸收面积大、血流丰富，是主要吸收部位。","expl":{"A":"胃粘膜，虽利于弱酸吸收但面积小，非主要部位。","B":"正确，小肠面积大、血流丰富，是主要吸收部位。","C":"横结肠，非主要吸收部位。","D":"乙状结肠，非主要吸收部位。","E":"十二指肠仅是小肠一部分，整体主要部位为小肠。"},"id":"ph03_q05","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":5},{"type":"A","stem":"临床上可用丙磺舒以增加青霉素的疗效,原因是","options":{"A":"在杀菌作用上有协同作用","B":"二者竞争肾小管的分泌通道","C":"对细菌代谢有双重阻断作用","D":"延缓抗药性产生","E":"以上都不对"},"answer":["B"],"rationale":"丙磺舒与青霉素竞争肾小管有机酸分泌通道，减慢青霉素排泄，提高血药浓度而增强疗效。","expl":{"A":"杀菌协同，错误，机制并非协同杀菌。","B":"正确，二者竞争肾小管分泌通道，延缓青霉素排泄。","C":"双重阻断，错误，与细菌代谢双重阻断无关。","D":"延缓抗药性，非其主要机制。","E":"以上都不对，错误。"},"id":"ph03_q06","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":6},{"type":"A","stem":"药物的 t1/2 是指","options":{"A":"药物的血药浓度下降一半所需时间","B":"药物的稳态血药浓度下降一半所需时间","C":"与药物的血浆浓度下降一半相关，单位为小时","D":"与药物的血浆浓度下降一半相关，单位为克","E":"药物的血浆蛋白结合率下降一半所需剂量"},"answer":["A"],"rationale":"t1/2指血浆药物浓度下降一半所需的时间。","expl":{"A":"正确，半衰期即血药浓度下降一半所需时间。","B":"错误，半衰期针对血药浓度下降，不限稳态浓度。","C":"错误，半衰期单位不固定为小时，可为分钟、天等。","D":"错误，半衰期为时间量，单位“克”明显错误。","E":"错误，半衰期与血浆蛋白结合率无关。"},"id":"ph03_q07","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":7},{"type":"A","stem":"某催眠药的 t1/2 为 1 小时，给予 100mg 剂量后，病人在体内药物只剩 12.5mg 时便清醒过来，该病人睡了","options":{"A":"2h","B":"3h","C":"4h","D":"5h","E":"0.5h"},"answer":["B"],"rationale":"100mg经3个半衰期依次降为50、25、12.5mg，每个t1/2为1小时，共3小时。","expl":{"A":"2h，此时体内剩25mg，尚未清醒。","B":"正确，100mg经3个半衰期降至12.5mg，历时3h。","C":"4h，此时剩6.25mg，时间偏长。","D":"5h，偏长。","E":"0.5h，体内尚余约70mg，错误。"},"id":"ph03_q08","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":8},{"type":"A","stem":"药物的作用强度，主要取决于","options":{"A":"药物在血液中的浓度","B":"在靶器官的浓度大小","C":"药物排泄的速率大小","D":"药物与血浆蛋白结合率之高低","E":"以上都对"},"answer":["B"],"rationale":"药物作用强度主要取决于作用部位（靶器官、靶组织）的药物浓度。","expl":{"A":"血药浓度仅间接相关，非直接决定因素。","B":"正确，靶器官浓度直接决定作用强度。","C":"排泄速率影响持续时间，非作用强度。","D":"蛋白结合率影响游离浓度，非直接决定强度。","E":"以上都对，错误。"},"id":"ph03_q09","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":9},{"type":"A","stem":"一次静注给药后约经过几个血浆 t1/2 可自机体排出达 95%以上","options":{"A":"3 个","B":"4 个","C":"5 个","D":"6 个","E":"7 个"},"answer":["C"],"rationale":"经5个半衰期药物消除约97%（>95%），接近完全消除。","expl":{"A":"3个，消除约87.5%，不足95%。","B":"4个，消除约93.75%，略不足95%。","C":"正确，5个半衰期消除约96.9%，大于95%。","D":"6个，消除更多但非最少所需。","E":"7个，偏多。"},"id":"ph03_q10","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":10},{"type":"A","stem":"弱酸性药物与抗酸药物同服时，比单用该弱酸性药物","options":{"A":"在胃中解离增多，自胃吸收增多","B":"在胃中解离减少，自胃吸收增多","C":"在胃中解离减少，自胃吸收减少","D":"在胃中解离增多，自胃吸收减少","E":"无变化"},"answer":["D"],"rationale":"抗酸药升高胃内pH，使弱酸性药物解离增多、非解离型减少，故吸收减少。","expl":{"A":"解离增多则吸收应减少，此说矛盾。","B":"解离方向与吸收方向均反。","C":"解离减少的说法错误。","D":"正确，pH升高使弱酸解离增多，非解离型减少，吸收减少。","E":"无变化，错误。"},"id":"ph03_q11","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":11},{"type":"A","stem":"甲药与血浆蛋白的结合率为 95%，乙药的血浆蛋白结合率为 85%，甲药单用时血浆 t1/2为 4h，如甲药与乙药合用，则甲药血浆 t1/2 为","options":{"A":"小于 4h","B":"不变","C":"大于 4h","D":"大于 8h","E":"大于10h"},"answer":["B"],"rationale":"t1/2由消除速率常数与表观分布容积决定，蛋白结合率高低不直接决定半衰期，竞争置换不使t1/2改变。","expl":{"A":"小于4h，错误。","B":"正确，蛋白结合率差异不改变消除半衰期。","C":"大于4h，错误。","D":"大于8h，错误。","E":"大于10h，错误。"},"id":"ph03_q12","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":12},{"type":"A","stem":"常用剂量恒量恒速给药最后形成的血药浓度为","options":{"A":"有效血浓度","B":"稳态血浓度","C":"峰浓度","D":"阈浓度","E":"中毒浓度"},"answer":["B"],"rationale":"恒量恒速给药，经4~5个半衰期血药浓度达稳态（坪浓度）。","expl":{"A":"有效血浓度，是浓度范围而非最终浓度。","B":"正确，恒量恒速给药最终形成稳态血浓度。","C":"峰浓度，是单次给药后的最高浓度。","D":"阈浓度，是起效的最低浓度。","E":"中毒浓度，是过量所致。"},"id":"ph03_q13","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":13},{"type":"A","stem":"药物产生作用的快慢取决于","options":{"A":"药物的吸收速度","B":"药物的排泄速度","C":"药物的转运方式","D":"药物的光学异构体","E":"药物的代谢速度"},"answer":["A"],"rationale":"药物起效快慢主要取决于吸收速度，吸收越快，血药浓度上升越快、起效越快。","expl":{"A":"正确，吸收速度决定起效快慢。","B":"排泄速度影响持续时间，非起效快慢。","C":"转运方式影响吸收分布，非直接决定起效。","D":"光学异构体影响活性，非起效快慢。","E":"代谢速度影响持续时间，非起效快慢。"},"id":"ph03_q14","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":14},{"type":"A","stem":"苯巴比妥中毒时应用碳酸氢钠的目的是","options":{"A":"加速药物从尿液的排泄","B":"加速药物从尿液的代谢灭活","C":"加速药物由脑组织向血浆的转移","D":"A 和 C","E":"A 和 B"},"answer":["D"],"rationale":"苯巴比妥为弱酸性药，碳酸氢钠碱化尿液使药物解离增加、肾小管重吸收减少而加速排泄；同时碱化血液促使药物由脑组织向血浆转移，故二者兼有。","expl":{"A":"正确，碱化尿液减少弱酸性药在肾小管的重吸收，加速其从尿液排泄。","B":"错误，碳酸氢钠影响的是排泄而非加速药物代谢灭活。","C":"正确，碱化血液使药物在血中解离增多、不易透过血脑屏障，促使药物由脑组织向血浆转移。","D":"正确，碱化尿液加速排泄与碱化血液促药物向血浆转移，二者兼有。","E":"错误，B项不正确，故“A和B”不能作为完整答案。"},"id":"ph03_q15","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":15},{"type":"A","stem":"某药在体内可被肝药酶转化，与酶抑制剂合用时比单独应用的效应","options":{"A":"增强","B":"减弱","C":"不变","D":"无效","E":"相反"},"answer":["A"],"rationale":"酶抑制剂抑制肝药酶，减慢药物代谢灭活，使药效增强。","expl":{"A":"正确，酶抑制使代谢减慢，药效增强。","B":"减弱，错误，方向相反。","C":"不变，错误。","D":"无效，错误。","E":"相反，错误。"},"id":"ph03_q16","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":16},{"type":"A","stem":"每个 t1/2 恒量给药一次，约经过几个血浆 t1/2 可达稳态血浓度","options":{"A":"1 个","B":"3 个","C":"5 个","D":"7 个","E":"9 个"},"answer":["C"],"rationale":"恒量恒速给药，约经4~5个半衰期可达稳态血浓度。","expl":{"A":"1个，远不足。","B":"3个，达87.5%，尚未达稳态。","C":"正确，约5个半衰期达稳态血浓度。","D":"7个，偏多。","E":"9个，偏多。"},"id":"ph03_q17","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":17},{"type":"A","stem":"某药 t1/2 为 8h ，一天给药三次，达到稳态血浓度的时间是","options":{"A":"16h","B":"30h","C":"24h","D":"40h","E":"50h"},"answer":["D"],"rationale":"t1/2为8h，达稳态约需5个半衰期，即40h。","expl":{"A":"16h，仅2个半衰期。","B":"30h，约3.75个半衰期，不足。","C":"24h，仅3个半衰期。","D":"正确，5×8=40h。","E":"50h，偏多。"},"id":"ph03_q18","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":18},{"type":"A","stem":"药物的时量曲线下面积反映","options":{"A":"在一定时间内药物的分布情况","B":"药物的血浆 t1/2 长短","C":"在一定时间内药物消除的量","D":"在一定时间内药物吸收入血的相对量","E":"药物达到稳态浓度时所需要的时间"},"answer":["D"],"rationale":"时量曲线下面积（AUC）反映药物吸收入血的相对量，可用于计算生物利用度。","expl":{"A":"分布情况，错误。","B":"t1/2长短，错误，t1/2由消除速率决定。","C":"消除的量，错误，AUC反映体内药量的时间积分。","D":"正确，AUC反映药物吸收入血的相对量。","E":"达稳态时间，错误。"},"id":"ph03_q19","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":19},{"type":"A","stem":"静脉注射某药 0.5mg，达到稳态时测定其血浆药物浓度为 0.7ηg/ml，其表观分布容积约为","options":{"A":"0.5L","B":"7L","C":"50L","D":"70L","E":"700L"},"answer":["E"],"rationale":"Vd=剂量/血药浓度，0.5mg=5×10⁵ng，除以0.7ng/ml约为714L，接近700L。","expl":{"A":"0.5L，远小于实际值。","B":"7L，偏小。","C":"50L，偏小。","D":"70L，偏小。","E":"正确，约714L≈700L。"},"id":"ph03_q20","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":20},{"type":"A","stem":"对于肾功能低下者，用药时主要考虑","options":{"A":"药物自肾脏的转运","B":"药物在肝脏的转化","C":"胃肠对药物的吸收","D":"药物与血浆蛋白的结合率","E":"个体差异"},"answer":["A"],"rationale":"肾功能低下者药物经肾排泄减慢，用药需重点考虑药物自肾脏的转运（排泄）。","expl":{"A":"正确，肾功能低下主要影响药物经肾转运排泄。","B":"肝脏转化，非肾功能低下者的首要考虑。","C":"胃肠吸收，影响较小。","D":"蛋白结合率，非主要考虑。","E":"个体差异，不具针对性。"},"id":"ph03_q21","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":21},{"type":"A","stem":"二室模型的药物分布于","options":{"A":"血液与体液","B":"血液与尿液","C":"心脏与肝脏","D":"中央室与周边室","E":"肺脏与肾脏"},"answer":["D"],"rationale":"二室模型将机体分为中央室（血液及血流丰富组织）与周边室。","expl":{"A":"血液与体液，非二室模型划分。","B":"血液与尿液，错误。","C":"心脏与肝脏，错误。","D":"正确，分为中央室与周边室。","E":"肺脏与肾脏，错误。"},"id":"ph03_q22","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":22},{"type":"A","stem":"血浆 t1/2 是指哪种情况下降一半的时间","options":{"A":"血浆稳态浓度","B":"有效血浓度","C":"血浆浓度","D":"血浆蛋白结合率","E":"阈浓度"},"answer":["C"],"rationale":"血浆t1/2指血浆药物浓度下降一半所需的时间。","expl":{"A":"血浆稳态浓度，错误。","B":"有效血浓度，错误。","C":"正确，指血浆浓度下降一半的时间。","D":"血浆蛋白结合率，错误。","E":"阈浓度，错误。"},"id":"ph03_q23","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":23},{"type":"A","stem":"关于坪值，错误的描述是","options":{"A":"血药浓度相对地稳定在一定水平称坪值，平均血药浓度称坪浓度","B":"通常用药间隔时间约为一个血浆半衰期时,需经 4~5 个 t1/2 才能达到坪值","C":"坪浓度的高低与每日总量成正比，在每日总量相等时，用药次数不改变坪浓度","D":"坪浓度的高限（峰）和低限（谷）的差距与每次用药量成正比","E":"首次用突击剂量，不能使血药浓度迅速达到坪浓度"},"answer":["E"],"rationale":"首次突击剂量（负荷剂量）正是为迅速达到坪浓度而设，故E描述错误。","expl":{"A":"正确，坪值指血药浓度相对稳定水平。","B":"正确，约经4~5个t1/2达坪值。","C":"正确，坪浓度与每日总量成正比。","D":"正确，峰谷差距与每次用药量成正比。","E":"错误，突击剂量可使血药浓度迅速达坪浓度。"},"id":"ph03_q24","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":24},{"type":"A","stem":"药物的零级动力学消除是指","options":{"A":"药物完全消除至零","B":"单位时间内消除恒量的药物","C":"药物的吸收量与消除量达到平衡","D":"药物的消除速率常数为零","E":"单位时间内消除恒定比例的药物"},"answer":["B"],"rationale":"零级动力学消除指单位时间内消除恒定数量的药物，与浓度无关。","expl":{"A":"完全消除至零，属字面误解。","B":"正确，单位时间内消除恒量药物。","C":"吸收与消除平衡，错误。","D":"消除速率常数为零，错误。","E":"恒定比例消除，这是一级动力学。"},"id":"ph03_q25","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":25},{"type":"A","stem":"按一级动力学消除的药物，其血浆 t1/2 等于","options":{"A":"0.301/kE.","B":"2.303/kE.","C":"ke/0.693","D":"0.693/kE.","E":"ke/2.303"},"answer":["D"],"rationale":"一级动力学消除的药物t1/2=0.693/ke（ke为消除速率常数）。","expl":{"A":"0.301/ke，系数错误。","B":"2.303/ke，系数错误。","C":"ke/0.693，分子分母颠倒。","D":"正确，t1/2=0.693/ke。","E":"ke/2.303，错误。"},"id":"ph03_q26","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":26},{"type":"A","stem":"离子障指的是","options":{"A":"离子型药物可自由穿过，而非离子型药物则不能穿过","B":"非离子型药物不可自由穿过，离子型的也不能穿过","C":"非离子型药物可自由穿过，离子型的也能穿过","D":"非离子型药物可自由穿过，而离子型的则不能穿过","E":"以上都不是"},"answer":["D"],"rationale":"离子障指生物膜只允许非离子型（脂溶性）药物自由通过，离子型药物难以穿过。","expl":{"A":"相反，离子型不能自由穿过。","B":"错误，非离子型可自由穿过。","C":"错误，离子型不能穿过。","D":"正确，非离子型可自由穿过而离子型不能。","E":"以上都不是，错误。"},"id":"ph03_q27","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":27},{"type":"A","stem":"pka 是","options":{"A":"药物 90%解离时的 pH 值","B":"药物不解离时的 pH 值","C":"50%药物解离时的 pH 值","D":"药物全部长解离时的 pH 值","E":"酸性药物解离常数值的负对数"},"answer":["E"],"rationale":"pKa是解离常数Ka的负对数，即pKa=-lgKa。","expl":{"A":"90%解离时的pH，错误。","B":"不解离时的pH，错误，pKa时仍有50%解离。","C":"是pKa的性质而非定义，定义应为负对数。","D":"错误，pKa时药物50%解离而非全部解离。","E":"正确，pKa是解离常数值的负对数。"},"id":"ph03_q28","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":28},{"type":"A","stem":"某病人应用双香豆素治疗血栓栓塞性疾病，后因失眠加用苯巴比妥，结果病人的凝血酶原时间比未加苯巴比妥时缩短，这是因为","options":{"A":"苯巴比妥对抗双香豆素的作用","B":"苯巴比妥诱导肝药酶使双香豆素代谢加速","C":"苯巴比妥抑制凝血酶","D":"病人对双香豆素产生了耐药性","E":"苯巴比妥抗血小板聚集"},"answer":["B"],"rationale":"苯巴比妥为肝药酶诱导剂，加速双香豆素代谢，抗凝作用减弱，凝血酶原时间缩短。","expl":{"A":"直接对抗，错误，机制是酶诱导加速代谢。","B":"正确，苯巴比妥诱导肝药酶使双香豆素代谢加速。","C":"抑制凝血酶，错误。","D":"耐药性，错误。","E":"抗血小板聚集，错误。"},"id":"ph03_q29","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":29},{"type":"A","stem":"药物进入循环后首先","options":{"A":"作用于靶器官","B":"在肝脏代谢","C":"由肾脏排泄","D":"储存在脂肪","E":"与血浆蛋白结合"},"answer":["E"],"rationale":"药物进入体循环后首先与血浆蛋白可逆结合，形成结合型与游离型动态平衡。","expl":{"A":"作用于靶器官，需先分布，非首先。","B":"肝脏代谢，非首先。","C":"肾脏排泄，非首先。","D":"储存在脂肪，非首先。","E":"正确，首先与血浆蛋白结合。"},"id":"ph03_q30","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":30},{"type":"A","stem":"药物的生物转化和排泄速度决定其","options":{"A":"副作用的多少","B":"最大效应的高低","C":"作用持续时间的长短","D":"起效的快慢","E":"后遗效应的大小"},"answer":["C"],"rationale":"生物转化和排泄决定药物消除，从而决定药物作用持续时间的长短。","expl":{"A":"副作用的多少，错误。","B":"最大效应，取决于剂量与受体。","C":"正确，代谢和排泄决定作用持续时间。","D":"起效快慢，取决于吸收速度。","E":"后遗效应大小，非直接决定。"},"id":"ph03_q31","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":31},{"type":"A","stem":"时量曲线的峰值浓度表明","options":{"A":"药物吸收速度与消除速度相等","B":"药物吸收过程已完成","C":"药物在体内分布已达到平衡","D":"药物消除过程才开始","E":"药物的疗效最好"},"answer":["A"],"rationale":"时量曲线达峰时吸收速度与消除速度相等，此后消除占优势。","expl":{"A":"正确，峰浓度时吸收与消除速度相等。","B":"吸收已完成，错误，达峰时吸收仍在进行。","C":"分布已平衡，错误，非此含义。","D":"消除才开始，错误。","E":"疗效最好，错误。"},"id":"ph03_q32","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":32},{"type":"A","stem":"药物的排泄途径不包括","options":{"A":"汗腺","B":"肾脏","C":"胆汁","D":"肺","E":"肝脏"},"answer":["E"],"rationale":"肝脏是代谢器官而非排泄途径，药物主要经肾、胆汁、肺、汗腺等排泄。","expl":{"A":"汗腺，属排泄途径（汗液）。","B":"肾脏，是主要排泄途径。","C":"胆汁，属排泄途径。","D":"肺，属排泄途径（呼气）。","E":"正确，肝脏是代谢器官，不属于排泄途径。"},"id":"ph03_q33","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":33},{"type":"A","stem":"关于肝药酶的描述，错误的是","options":{"A":"属 P-450 酶系统","B":"其活性有限","C":"易发生竞争性抑制","D":"个体差异大","E":"只代谢 20 余种药物"},"answer":["E"],"rationale":"肝药酶（CYP450）底物广泛，可代谢数百种药物，远不止20余种。","expl":{"A":"正确，属P-450酶系统。","B":"正确，其活性有限。","C":"正确，易发生竞争性抑制。","D":"正确，个体差异大。","E":"错误，肝药酶可代谢众多药物，远不止20余种。"},"id":"ph03_q34","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":34},{"type":"A","stem":"已知某药按一级动力学消除，上午 9 时测得血药浓度为 100μg/ml，晚 6 时测得的血药浓度为12.5μg/ml，则此药的 t1/2 为","options":{"A":"4h","B":"2h","C":"6h","D":"3h","E":"9h"},"answer":["D"],"rationale":"9时到18时共9小时，浓度100→50→25→12.5μg/ml，经3个半衰期，故t1/2=3h。","expl":{"A":"4h，错误。","B":"2h，错误。","C":"6h，错误。","D":"正确，9小时经3个半衰期，t1/2=3h。","E":"9h，错误。"},"id":"ph03_q35","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":35},{"type":"A","stem":"某药的时量关系为：该药的消除规律是","options":{"A":"一级动力学消除","B":"一级转为零级动力学消除","C":"零级动力学消除","D":"零级转为一级动力学消除","E":"无恒定半衰期"},"answer":["A"],"rationale":"一级动力学消除时血药浓度按恒定比例下降，半衰期恒定，是多数药物治疗量下的消除规律。","expl":{"A":"正确，一级动力学按恒定比例消除、t1/2恒定。","B":"错误。","C":"错误，零级动力学为恒量消除。","D":"错误。","E":"错误，一级动力学有恒定半衰期。"},"id":"ph03_q36","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":36},{"type":"B","stem":"单位时间内药物消除的百分速率","options":{"A":"消除速率常数","B":"清除率","C":"半衰期","D":"一级动力学消除","E":"零级动力学消除"},"answer":["A"],"rationale":"消除速率常数ke表示单位时间内药物消除的百分速率（一级动力学中）。","expl":{"A":"正确，消除速率常数即单位时间消除的百分速率。","B":"清除率，是单位时间清除的血浆体积。","C":"半衰期，是浓度下降一半的时间。","D":"一级动力学消除，是消除类型。","E":"零级动力学消除，是消除类型。"},"id":"ph03_q37","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":37},{"type":"B","stem":"单位时间内能将多少体积血中的某药全部消除净","options":{"A":"消除速率常数","B":"清除率","C":"半衰期","D":"一级动力学消除","E":"零级动力学消除"},"answer":["B"],"rationale":"清除率定义为单位时间内能将多少体积血中药物全部清除净。","expl":{"A":"消除速率常数，是百分速率。","B":"正确，清除率指单位时间清除的血浆体积。","C":"半衰期，是时间概念。","D":"一级动力学消除，是类型。","E":"零级动力学消除，是类型。"},"id":"ph03_q38","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":38},{"type":"B","stem":"作为药物制剂质量指标","options":{"A":"生物利用度","B":"血浆蛋白结合率","C":"消除速率常数","D":"剂量","E":"吸收速度"},"answer":["A"],"rationale":"生物利用度反映药物进入体循环的速度和程度，是评价制剂质量的重要指标。","expl":{"A":"正确，生物利用度是制剂质量指标。","B":"血浆蛋白结合率，非制剂质量指标。","C":"消除速率常数，是药动学参数而非制剂指标。","D":"剂量，非制剂质量指标。","E":"吸收速度，仅属生物利用度的一部分。"},"id":"ph03_q39","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":39},{"type":"B","stem":"影响表观分布容积大小","options":{"A":"生物利用度","B":"血浆蛋白结合率","C":"消除速率常数","D":"剂量","E":"吸收速度"},"answer":["B"],"rationale":"血浆蛋白结合率影响药物在血浆与组织间的分布，从而影响表观分布容积。","expl":{"A":"生物利用度，影响吸收而非Vd。","B":"正确，蛋白结合率高者Vd较小。","C":"消除速率常数，影响t1/2。","D":"剂量，不改变Vd。","E":"吸收速度，非Vd的决定因素。"},"id":"ph03_q40","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":40},{"type":"B","stem":"决定半衰期长短","options":{"A":"生物利用度","B":"血浆蛋白结合率","C":"消除速率常数","D":"剂量","E":"吸收速度"},"answer":["C"],"rationale":"半衰期t1/2=0.693/ke，由消除速率常数决定。","expl":{"A":"生物利用度，影响吸收量。","B":"血浆蛋白结合率，影响Vd。","C":"正确，消除速率常数决定半衰期长短。","D":"剂量，不决定t1/2。","E":"吸收速度，影响起效快慢。"},"id":"ph03_q41","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":41},{"type":"B","stem":"决定起效快慢","options":{"A":"生物利用度","B":"血浆蛋白结合率","C":"消除速率常数","D":"剂量","E":"吸收速度"},"answer":["E"],"rationale":"起效快慢取决于药物吸收速度，吸收越快血药浓度上升越快。","expl":{"A":"生物利用度，影响吸收量。","B":"血浆蛋白结合率，影响分布。","C":"消除速率常数，影响消除。","D":"剂量，影响作用强度。","E":"正确，吸收速度决定起效快慢。"},"id":"ph03_q42","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":42},{"type":"B","stem":"决定作用强弱","options":{"A":"生物利用度","B":"血浆蛋白结合率","C":"消除速率常数","D":"剂量","E":"吸收速度"},"answer":["D"],"rationale":"在有效范围内作用强弱主要取决于剂量，剂量越大作用越强。","expl":{"A":"生物利用度，影响吸收量。","B":"血浆蛋白结合率，影响分布。","C":"消除速率常数，影响消除。","D":"正确，剂量决定作用强弱。","E":"吸收速度，影响起效快慢。"},"id":"ph03_q43","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":43},{"type":"B","stem":"给药间隔大","options":{"A":"血药浓度波动小","B":"血药浓度波动大","C":"血药浓度不波动","D":"血药浓度高","E":"血药浓度低"},"answer":["B"],"rationale":"给药间隔越大，血药浓度在峰谷之间波动越大。","expl":{"A":"波动小，错误，与间隔大成反。","B":"正确，给药间隔大则血药浓度波动大。","C":"不波动，错误。","D":"高，非直接结果。","E":"低，非直接结果。"},"id":"ph03_q44","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":44},{"type":"B","stem":"给药间隔小","options":{"A":"血药浓度波动小","B":"血药浓度波动大","C":"血药浓度不波动","D":"血药浓度高","E":"血药浓度低"},"answer":["A"],"rationale":"给药间隔越小，血药浓度波动越小。","expl":{"A":"正确，给药间隔小则血药浓度波动小。","B":"波动大，错误。","C":"不波动，错误。","D":"高，非直接结果。","E":"低，非直接结果。"},"id":"ph03_q45","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":45},{"type":"B","stem":"静脉滴注","options":{"A":"血药浓度波动小","B":"血药浓度波动大","C":"血药浓度不波动","D":"血药浓度高","E":"血药浓度低"},"answer":["C"],"rationale":"恒速静脉滴注时血药浓度平稳上升至稳态后保持恒定，不出现波动。","expl":{"A":"波动小，不准确，应为不波动。","B":"波动大，错误。","C":"正确，静滴达稳态后血药浓度不波动。","D":"高，非直接结果。","E":"低，非直接结果。"},"id":"ph03_q46","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":46},{"type":"B","stem":"给药剂量小","options":{"A":"血药浓度波动小","B":"血药浓度波动大","C":"血药浓度不波动","D":"血药浓度高","E":"血药浓度低"},"answer":["E"],"rationale":"给药剂量小，血药浓度相应较低。","expl":{"A":"波动小，非剂量所决定。","B":"波动大，错误。","C":"不波动，错误。","D":"高，与剂量小相反。","E":"正确，剂量小则血药浓度低。"},"id":"ph03_q47","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":47},{"type":"B","stem":"给药剂量大","options":{"A":"血药浓度波动小","B":"血药浓度波动大","C":"血药浓度不波动","D":"血药浓度高","E":"血药浓度低"},"answer":["D"],"rationale":"给药剂量大，血药浓度相应较高。","expl":{"A":"波动小，非剂量所决定。","B":"波动大，错误。","C":"不波动，错误。","D":"正确，剂量大则血药浓度高。","E":"低，与剂量大相反。"},"id":"ph03_q48","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":48},{"type":"C","stem":"影响 t1/2","options":{"A":"表观分布容积","B":"血浆清除率","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"t1/2=0.693×Vd/CL，同时受表观分布容积和血浆清除率影响。","expl":{"A":"表观分布容积，影响t1/2但不完整。","B":"血浆清除率，影响t1/2但不完整。","C":"正确，两者均影响t1/2。","D":"错误。"},"id":"ph03_q49","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":49},{"type":"C","stem":"受肝肾功能影响","options":{"A":"表观分布容积","B":"血浆清除率","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"血浆清除率主要由肝（代谢）和肾（排泄）功能决定，而表观分布容积主要受蛋白结合与组织分布影响。","expl":{"A":"表观分布容积，受肝肾功能影响较小。","B":"正确，血浆清除率受肝肾功能影响。","C":"错误。","D":"错误。"},"id":"ph03_q50","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":50},{"type":"C","stem":"受血浆蛋白结合影响","options":{"A":"表观分布容积","B":"血浆清除率","C":"两者均是","D":"两者均否"},"answer":["A"],"rationale":"血浆蛋白结合率影响药物分布，结合率高则游离少、表观分布容积小。","expl":{"A":"正确，表观分布容积受血浆蛋白结合影响。","B":"血浆清除率，主要受肝肾功能影响。","C":"错误。","D":"错误。"},"id":"ph03_q51","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":51},{"type":"C","stem":"影响消除速率常数","options":{"A":"表观分布容积","B":"血浆清除率","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"ke=CL/Vd，消除速率常数同时受血浆清除率和表观分布容积影响。","expl":{"A":"表观分布容积，影响ke但不完整。","B":"血浆清除率，影响ke但不完整。","C":"正确，两者均影响消除速率常数。","D":"错误。"},"id":"ph03_q52","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":52},{"type":"C","stem":"药物主动转运的竞争性抑制可影响","options":{"A":"药物的药理学活性","B":"药效的持续时间","C":"两者均影响","D":"两者均不影响"},"answer":["B"],"rationale":"主动转运的竞争性抑制（如丙磺舒与青霉素）减慢排泄，延长药效持续时间，但不改变药物内在活性。","expl":{"A":"药理学活性，不改变药物内在活性。","B":"正确，竞争抑制减慢排泄，延长药效持续时间。","C":"错误。","D":"错误。"},"id":"ph03_q53","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":53},{"type":"C","stem":"药物与血浆蛋白结合的竞争性可影响","options":{"A":"药物的药理学活性","B":"药效的持续时间","C":"两者均影响","D":"两者均不影响"},"answer":["C"],"rationale":"血浆蛋白结合的竞争置换使游离药物增多，既增强药理活性又加速消除而缩短持续时间。","expl":{"A":"药理学活性，受影响但不完整。","B":"药效持续时间，受影响但不完整。","C":"正确，两者均受影响。","D":"错误。"},"id":"ph03_q54","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":54},{"type":"C","stem":"药物的肝肠循环可影响","options":{"A":"药物的药理学活性","B":"药效的持续时间","C":"两者均影响","D":"两者均不影响"},"answer":["B"],"rationale":"肝肠循环使药物经胆汁排泄后又重吸收，延长药效持续时间，但不改变药物内在活性。","expl":{"A":"药理学活性，不改变内在活性。","B":"正确，肝肠循环延长药效持续时间。","C":"错误。","D":"错误。"},"id":"ph03_q55","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":55},{"type":"C","stem":"药物的生物转化可影响","options":{"A":"药物的药理学活性","B":"药效的持续时间","C":"两者均影响","D":"两者均不影响"},"answer":["C"],"rationale":"生物转化既可活化或灭活药物（影响活性），又决定消除速度（影响持续时间）。","expl":{"A":"药理学活性，受影响但不完整。","B":"药效持续时间，受影响但不完整。","C":"正确，两者均受影响。","D":"错误。"},"id":"ph03_q56","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":56},{"type":"X","stem":"药物与血浆蛋白结合","options":{"A":"有利于药物进一步吸收","B":"有利于药物从肾脏排泄","C":"加快药物发生作用","D":"两种蛋白结合率高的药物易发生竞争置换现象","E":"血浆蛋白量低者易发生药物中毒"},"answer":["A","D","E"],"rationale":"药物与血浆蛋白结合为可逆结合，结合型可作贮库利于进一步吸收，结合率高者易竞争置换，血浆蛋白低者游离药物增多易中毒。","expl":{"A":"正确，结合减少游离药物，利于药物继续吸收。","B":"错误，结合型不被肾小球滤过，不利于排泄。","C":"错误，结合型暂时失活，减慢起效。","D":"正确，蛋白结合率高的药物易发生竞争置换。","E":"正确，血浆蛋白低时游离药物增多易中毒。"},"id":"ph03_q57","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":57},{"type":"X","stem":"关于一级动力学的描述，正确的是","options":{"A":"消除速率与当时药浓一次方成正比","B":"定量消除","C":"c-t 为直线","D":"t1/2 恒定","E":"大多数药物在治疗量时均为一级动力学"},"answer":["A","D","E"],"rationale":"一级动力学消除速率与血药浓度一次方成正比，t1/2恒定，多数药物治疗量下符合此规律。","expl":{"A":"正确，消除速率与当时药浓一次方成正比。","B":"错误，定量消除是零级动力学的特点。","C":"错误，c-t在半对数坐标上才是直线。","D":"正确，t1/2恒定。","E":"正确，多数药物治疗量下为一级动力学。"},"id":"ph03_q58","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":58},{"type":"X","stem":"表观分布容积的意义有","options":{"A":"反映药物吸收的量","B":"反映药物分布的广窄程度","C":"反映药物排泄的过程","D":"反映药物消除的速度","E":"估算欲达到有效药浓应投药量"},"answer":["B","E"],"rationale":"表观分布容积反映药物分布的广窄程度，并可据此估算达到有效浓度所需剂量。","expl":{"A":"错误，Vd不反映药物吸收的量。","B":"正确，Vd反映药物分布的广窄程度。","C":"错误，Vd不反映排泄过程。","D":"错误，Vd不反映消除速度。","E":"正确，可用于估算达到有效药浓的投药量。"},"id":"ph03_q59","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":59},{"type":"X","stem":"属于药动学参数的有","options":{"A":"一级动力学","B":"半衰期","C":"表观分布容积","D":"二室模型","E":"生物利用度"},"answer":["B","C","E"],"rationale":"半衰期、表观分布容积、生物利用度均属药动学参数，而一级动力学和二室模型属模型类型。","expl":{"A":"错误，一级动力学是消除类型而非参数。","B":"正确，半衰期是药动学参数。","C":"正确，表观分布容积是药动学参数。","D":"错误，二室模型是模型而非参数。","E":"正确，生物利用度是药动学参数。"},"id":"ph03_q60","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":60},{"type":"X","stem":"经生物转化后的药物","options":{"A":"可具有活性","B":"有利于肾小管重吸收","C":"脂溶性增加","D":"失去药理活性","E":"极性升高"},"answer":["A","D","E"],"rationale":"药物经生物转化后可活化（前药）或灭活，一般极性升高、水溶性增加、脂溶性降低，不利于重吸收。","expl":{"A":"正确，前药经转化后可具有活性。","B":"错误，极性升高不利于肾小管重吸收。","C":"错误，脂溶性通常降低而非增加。","D":"正确，多数药物经转化后失去药理活性。","E":"正确，转化后极性升高。"},"id":"ph03_q61","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":61},{"type":"X","stem":"药物消除 t1/2 的影响因素有","options":{"A":"首关消除","B":"血浆蛋白结合率","C":"表观分布容积","D":"血浆清除率","E":"曲线下面积"},"answer":["C","D"],"rationale":"t1/2=0.693×Vd/CL，故其影响因素为表观分布容积和血浆清除率。","expl":{"A":"错误，首关消除影响吸收量。","B":"错误，蛋白结合率不直接决定t1/2。","C":"正确，表观分布容积影响t1/2。","D":"正确，血浆清除率影响t1/2。","E":"错误，曲线下面积不决定t1/2。"},"id":"ph03_q62","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":62},{"type":"X","stem":"药物与血浆蛋白结合的特点是","options":{"A":"暂时失去药理活性","B":"具可逆性","C":"特异性低","D":"结合点有限","E":"两药间可产生竞争性置换作用"},"answer":["A","B","C","D","E"],"rationale":"药物与血浆蛋白结合具有可逆性、饱和性、特异性低、暂时失活，且两药间可竞争性置换。","expl":{"A":"正确，结合型暂时失去药理活性。","B":"正确，结合具可逆性。","C":"正确，结合特异性低。","D":"正确，结合点有限（饱和性）。","E":"正确，两药间可产生竞争性置换。"},"id":"ph03_q63","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":63},{"type":"A","stem":"药物经肝生物转化后，多数情况下发生的变化是","options":{"A":"脂溶性增加，更易透过生物膜","B":"分子量增大，主要经胆汁排泄","C":"与血浆蛋白结合率必然升高","D":"药理活性必然增强","E":"水溶性增加，有利于经肾排泄"},"answer":["E"],"rationale":"多数药物经氧化、还原、水解及结合反应后脂溶性降低、水溶性增加，活性减弱或消失，有利于随尿排出，故答案为 E。","expl":{"A":"错误，生物转化后药物脂溶性通常降低而不是升高，故不易再向组织细胞内转运。","B":"错误，分子量增大并非生物转化的普遍规律，主要经胆汁排泄只是少数药物的特点。","C":"错误，转化后血浆蛋白结合率可升高也可降低，并非必然升高。","D":"错误，只有前药经转化后活性才增强，多数药物转化后活性减弱或消失。","E":"正确，生物转化使药物极性增大、水溶性增加，经肾排泄增多，是药物消除的重要环节。"},"id":"ph03_q64","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":64},{"type":"A","stem":"硝酸甘油口服给药生物利用度很低，其主要原因是","options":{"A":"胃酸破坏","B":"吸收不完全","C":"血浆蛋白结合率过高","D":"首过效应显著","E":"肾排泄过快"},"answer":["D"],"rationale":"硝酸甘油口服后经门静脉入肝，被肝内高活性的有机硝酸酯还原酶大量代谢灭活，首过效应显著，故口服生物利用度仅约8%，答案为 D。","expl":{"A":"错误，硝酸甘油在胃酸中较稳定，胃酸破坏不是生物利用度低的主要原因。","B":"错误，硝酸甘油脂溶性高，胃肠道吸收良好，限速因素不是吸收。","C":"错误，其血浆蛋白结合率并不高，不能解释如此低的生物利用度。","D":"正确，口服后经肝代谢灭活明显，首过效应是生物利用度低的主要原因，故临床多舌下含服。","E":"错误，肾排泄不是硝酸甘油的主要消除途径，也不是生物利用度低的原因。"},"id":"ph03_q65","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":65},{"type":"A","stem":"某药静脉注射后AUC为120 μg·h/L，口服等剂量后AUC为36 μg·h/L，其绝对生物利用度约为","options":{"A":"3%","B":"30%","C":"33%","D":"70%","E":"120%"},"answer":["B"],"rationale":"绝对生物利用度F等于口服AUC除以静脉AUC再乘以100%，即36/120×100%等于30%，故答案为 B。","expl":{"A":"错误，3%是把比值再缩小100倍所得，与计算公式不符。","B":"正确，36÷120×100%等于30%，即该药口服后仅30%进入体循环。","C":"错误，33%是把120与36之差同120相比的近似值，误解了生物利用度的定义。","D":"错误，70%是经首过效应损失的药量比例，不是生物利用度。","E":"错误，绝对生物利用度以静脉给药为100%参比，不可能超过100%。"},"id":"ph03_q66","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":66},{"type":"A","stem":"某药表观分布容积约为400 L，最可能提示","options":{"A":"药物主要分布在血浆","B":"药物全部以原形经肾排出","C":"药物在组织分布广泛，血药浓度较低","D":"药物半衰期必然很短","E":"药物不能透过血脑屏障"},"answer":["C"],"rationale":"表观分布容积是体内药量与血药浓度的比值，远大于体液总容量说明药物大量被组织摄取，血药浓度低，故答案为 C。","expl":{"A":"错误，主要分布在血浆的药物其表观分布容积接近血浆容量，约为3～5 L。","B":"错误，表观分布容积大小与消除途径无必然联系，不能推断以原形排出。","C":"正确，Vd远大于总体液量提示药物与组织蛋白结合多、组织分布广。","D":"错误，半衰期由表观分布容积与清除率共同决定，Vd大者半衰期可以很长。","E":"错误，能否透过血脑屏障取决于分子性质，不能由表观分布容积推断。"},"id":"ph03_q67","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":67},{"type":"A","stem":"某药表观分布容积为25 L，清除率为0.5 L/h，其血浆半衰期约为","options":{"A":"5 h","B":"12.5 h","C":"25 h","D":"35 h","E":"70 h"},"answer":["D"],"rationale":"按一级动力学，t1/2等于0.693乘以表观分布容积再除以清除率，即0.693×25÷0.5约等于34.7 h，故答案为 D。","expl":{"A":"错误，5 h是把清除率直接当作消除速率常数计算所得，公式使用有误。","B":"错误，12.5 h等于25除以2，混淆了表观分布容积与半衰期的关系。","C":"错误，25 h直接取了表观分布容积的数值，未引入0.693和清除率。","D":"正确，0.693×25÷0.5约等于34.7 h，接近35 h。","E":"错误，70 h是忽略0.693、直接用50÷0.5所得，计算有误。"},"id":"ph03_q68","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":68},{"type":"A","stem":"恒速静脉滴注给药时，为使血药浓度迅速达到稳态水平，可采取的措施是","options":{"A":"先给予负荷剂量","B":"增大滴注速度","C":"延长滴注时间","D":"改为分次肌内注射","E":"合用肝药酶诱导剂"},"answer":["A"],"rationale":"恒速滴注时达到稳态约需5个半衰期，与滴注速度无关；先给负荷剂量可使血药浓度立即达到稳态水平，故答案为 A。","expl":{"A":"正确，负荷剂量等于稳态浓度乘以表观分布容积，可迅速补足体内药量，缩短达坪时间。","B":"错误，提高滴注速度只改变稳态浓度的高低，不缩短达到稳态所需的时间。","C":"错误，延长滴注时间只会使达坪更晚，与迅速达稳态的目的相反。","D":"错误，改变给药途径不能缩短按半衰期决定的达坪过程，还增加血药浓度波动。","E":"错误，酶诱导剂加速药物代谢，反而降低稳态浓度，不能加快达坪。"},"id":"ph03_q69","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":69},{"type":"A","stem":"下列药物中属于肝药酶诱导剂的是","options":{"A":"西咪替丁","B":"酮康唑","C":"氯霉素","D":"红霉素","E":"利福平"},"answer":["E"],"rationale":"利福平是典型的肝药酶诱导剂，可加速华法林、口服避孕药等药物的代谢而使其疗效降低，故答案为 E。","expl":{"A":"错误，西咪替丁抑制肝药酶，可使华法林、苯妥英钠等药物血药浓度升高。","B":"错误，酮康唑是强效肝药酶抑制剂，属于CYP3A4抑制药。","C":"错误，氯霉素抑制肝药酶，可延缓甲苯磺丁脲等药物的代谢。","D":"错误，红霉素抑制肝药酶，与特非那定等合用可致严重心脏毒性。","E":"正确，利福平诱导CYP450和葡萄糖醛酸转移酶，是常见的酶诱导药。"},"id":"ph03_q70","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":70},{"type":"A","stem":"下列药物中属于肝药酶抑制剂的是","options":{"A":"苯巴比妥","B":"苯妥英钠","C":"酮康唑","D":"卡马西平","E":"利福平"},"answer":["C"],"rationale":"酮康唑为强效肝药酶抑制剂，可使经CYP3A4代谢的药物血药浓度升高而发生毒性反应，故答案为 C。","expl":{"A":"错误，苯巴比妥是经典肝药酶诱导剂，可加速多种药物代谢。","B":"错误，苯妥英钠长期应用表现为酶诱导作用，可加速洋地黄毒苷等代谢。","C":"正确，酮康唑抑制肝药酶，与特非那定、西沙必利合用可致尖端扭转型室速。","D":"错误，卡马西平是自身诱导型肝药酶诱导剂，可加速自身及合用药物代谢。","E":"错误，利福平是强效酶诱导剂，不属于酶抑制剂。"},"id":"ph03_q71","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":71},{"type":"X","stem":"关于首过效应，下列叙述正确的有","options":{"A":"口服药物经胃肠道吸收后先经门静脉入肝，部分被代谢灭活","B":"首过效应明显的药物口服生物利用度较低","C":"舌下含服经口腔黏膜吸收直接入体循环，可避免首过效应","D":"直肠给药可完全避免首过效应","E":"静脉注射给药不存在首过效应"},"answer":["A","B","C","E"],"rationale":"首过效应指口服药物首次通过肝脏被代谢灭活使进入体循环药量减少，凡绕过肝脏的给药途径均无首过效应；直肠上段吸收的药物仍经门静脉入肝，不能完全避免，故D错误。","expl":{"A":"正确，口服药物经肠壁和门静脉入肝，部分在首次通过肝脏时即被灭活。","B":"正确，首过效应越明显，进入体循环的原形药越少，口服生物利用度越低。","C":"正确，口腔黏膜下静脉直接汇入上腔静脉，舌下给药可避开肝脏首过效应。","D":"错误，只有直肠下段吸收的药物大部分绕过肝脏，直肠上段吸收者仍经门静脉入肝。","E":"正确，静脉注射药物直接进入体循环，不经肝脏首过代谢。"},"id":"ph03_q72","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":72},{"type":"X","stem":"关于表观分布容积与清除率，下列叙述正确的有","options":{"A":"表观分布容积是体内药量与血浆药物浓度之间的比例常数","B":"表观分布容积小的药物主要分布在血浆","C":"清除率是单位时间内被机体清除药物的血浆体积","D":"清除率等于消除速率除以血浆药物浓度","E":"表观分布容积越大，药物半衰期一定越长"},"answer":["A","B","C","D"],"rationale":"表观分布容积是计算所得的比值而非真实体液容积，Vd小提示药物主要留在血浆；清除率表示单位时间内被完全清除药物的血浆体积，数值上等于消除速率除以血药浓度，故A、B、C、D正确。","expl":{"A":"正确，Vd等于体内药量除以血浆药物浓度，是描述分布特征的比例常数。","B":"正确，Vd接近血浆容量时说明药物主要分布于血浆，组织摄取少。","C":"正确，清除率反映机体消除药物的能力，单位为体积除以时间。","D":"正确，CL等于消除速率除以血药浓度，这是清除率的基本定义式。","E":"错误，半衰期同时取决于表观分布容积和清除率，Vd大而清除率也大者半衰期可很短。"},"id":"ph03_q73","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":73}]},{"title":"第四章 影响药物作用的因素","questions":[{"type":"A","stem":"患者长期服用口服避孕药后失效,可能是因为","options":{"A":"同时服用肝药酶诱导剂","B":"同时服用肝药酶抑制剂","C":"产生耐受性","D":"产生耐药性","E":"首关消除改变"},"answer":["A"],"rationale":"肝药酶诱导剂可加速口服避孕药代谢，使血药浓度下降而致避孕失败。","expl":{"A":"正确，肝药酶诱导剂加快避孕药代谢，降低其血药浓度而失效。","B":"肝药酶抑制剂减慢代谢、增强药效，不会导致避孕失败。","C":"耐受性指机体反应性降低，与避孕药被加速代谢的机制不符。","D":"耐药性针对病原体或肿瘤细胞，不适用于口服避孕药。","E":"首关消除改变并非长期服药后失效的常见原因。"},"id":"ph04_q01","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":1},{"type":"A","stem":"安慰剂是一种","options":{"A":"可以增加疗效的药物","B":"阳性对照药","C":"口服制剂","D":"使病人在精神上得到鼓励和安慰的药物","E":"不具有药理活性的剂型"},"answer":["E"],"rationale":"安慰剂是不含药理活性成分的制剂，主要通过心理作用产生效果。","expl":{"A":"安慰剂本身无药理活性，不能增加药物的实际疗效。","B":"安慰剂多作阴性对照药，而非阳性对照药。","C":"安慰剂不限于口服，剂型多样。","D":"使病人精神上得到安慰是其作用表现，并非安慰剂的定义。","E":"正确，安慰剂是不含活性成分、无药理活性的剂型。"},"id":"ph04_q02","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":2},{"type":"A","stem":"药物滥用是指","options":{"A":"医生用药不当","B":"未掌握药物适应症","C":"大量长期使用某种药物","D":"无病情根据的长期自我用药","E":"采用不恰当的剂量"},"answer":["D"],"rationale":"药物滥用指无医疗指征、非治疗目的的长期自行用药。","expl":{"A":"医生用药不当属于不合理处方，非药物滥用。","B":"未掌握适应证是处方错误，不属药物滥用。","C":"大量长期用药不一定是滥用，关键在于有无病情根据。","D":"正确，无病情根据的长期自我用药即药物滥用。","E":"采用不恰当剂量属用药差错，并非滥用。"},"id":"ph04_q03","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":3},{"type":"A","stem":"药物的配伍禁忌是指","options":{"A":"吸收后和血浆蛋白结合","B":"体外配伍过程中发生的物理和化学变化","C":"肝药酶活性的抑制","D":"两种药物在体内产生拮抗作用","E":"以上都不是"},"answer":["B"],"rationale":"配伍禁忌指药物在体外混合时发生的物理化学变化。","expl":{"A":"与血浆蛋白结合属体内分布过程，是药动学相互作用。","B":"正确，配伍禁忌是体外配伍时发生的物理化学变化。","C":"肝药酶抑制属体内代谢性相互作用。","D":"两药在体内拮抗属药效学相互作用。","E":"以上都不是，错误。"},"id":"ph04_q04","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":4},{"type":"A","stem":"长期应用某药后需要增加剂量才能奏效，这种现象称为","options":{"A":"耐药性","B":"耐受性","C":"成瘾性","D":"习惯性","E":"适应性"},"answer":["B"],"rationale":"机体对药物敏感性降低、需加大剂量才能奏效，称为耐受性。","expl":{"A":"耐药性指病原体或肿瘤细胞对药物敏感性降低。","B":"正确，长期用药后机体反应性降低、需增量即耐受性。","C":"成瘾性指停药后出现戒断症状的精神与躯体依赖。","D":"习惯性仅为精神依赖，无严重生理功能紊乱。","E":"适应性不是描述药物反应的专用术语。"},"id":"ph04_q05","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":5},{"type":"A","stem":"利用药物协同作用的目的是","options":{"A":"增加药物在肝脏的代谢","B":"增加药物在受体水平的拮抗","C":"增加药物的吸收","D":"增加药物的排泄","E":"增加药物的疗效"},"answer":["E"],"rationale":"药物协同作用使合用后效应增强，其目的即为提高疗效。","expl":{"A":"增加肝代谢会降低血药浓度，非协同目的。","B":"受体水平拮抗属拮抗作用，非协同。","C":"增加吸收不是协同作用的核心目的。","D":"增加排泄会降低药效，非协同目的。","E":"正确，利用协同作用旨在增强药物疗效。"},"id":"ph04_q06","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":6},{"type":"A","stem":"遗传异常主要表现在","options":{"A":"对药物肾脏排泄的异常","B":"对药物体内转化的异常","C":"对药物体内分布的异常","D":"对药物胃肠吸收的异常","E":"对药物引起的效应异常"},"answer":["E"],"rationale":"遗传异常最终表现为机体对药物效应的异常改变。","expl":{"A":"肾排泄异常仅为遗传影响的局部表现，不全面。","B":"体内转化异常只是遗传影响的一个方面。","C":"分布异常也只是遗传影响的局部表现。","D":"胃肠吸收异常仅为遗传影响的局部表现。","E":"正确，遗传异常主要表现为对药物引起的效应异常。"},"id":"ph04_q07","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":7},{"type":"A","stem":"影响药动学相互作用的方式不包括","options":{"A":"肝脏生物转化","B":"吸收","C":"血浆蛋白结合","D":"排泄","E":"生理性拮抗"},"answer":["E"],"rationale":"生理性拮抗属药效学相互作用，不属于药动学相互作用。","expl":{"A":"肝脏生物转化属药动学的代谢环节。","B":"吸收属药动学环节。","C":"血浆蛋白结合属药动学的分布环节。","D":"排泄属药动学环节。","E":"正确，生理性拮抗属药效学范畴，不属药动学相互作用。"},"id":"ph04_q08","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":8},{"type":"B","stem":"短时间内反复应用数次药效递减直至消失","options":{"A":"耐受性","B":"耐药性","C":"成瘾性","D":"习惯性","E":"快速耐受性"},"answer":["E"],"rationale":"短时间内反复用药后药效迅速递减乃至消失，即快速耐受性。","expl":{"A":"耐受性多需较长期用药后才出现。","B":"耐药性针对病原体或肿瘤细胞。","C":"成瘾性表现为停药后出现戒断症状。","D":"习惯性仅为精神依赖。","E":"正确，短时反复用药药效迅速递减为快速耐受性。"},"id":"ph04_q09","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":9},{"type":"B","stem":"病原体及肿瘤细胞对化学治疗药物的敏感性降低","options":{"A":"耐受性","B":"耐药性","C":"成瘾性","D":"习惯性","E":"快速耐受性"},"answer":["B"],"rationale":"病原体及肿瘤细胞对化疗药物敏感性降低称为耐药性。","expl":{"A":"耐受性是机体对药物的反应性降低。","B":"正确，病原体及肿瘤细胞敏感性降低即耐药性。","C":"成瘾性为停药后出现戒断症状。","D":"习惯性仅为精神依赖。","E":"快速耐受性指短时用药药效迅速递减。"},"id":"ph04_q10","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":10},{"type":"B","stem":"长期用药后突然停药发生严重的生理功能紊乱","options":{"A":"耐受性","B":"耐药性","C":"成瘾性","D":"习惯性","E":"快速耐受性"},"answer":["C"],"rationale":"长期用药后突然停药出现严重生理功能紊乱，是成瘾性的表现。","expl":{"A":"耐受性指需增加剂量才能奏效。","B":"耐药性针对病原体或肿瘤细胞。","C":"正确，停药后严重生理功能紊乱是成瘾性的戒断反应。","D":"习惯性仅精神依赖，无严重生理紊乱。","E":"快速耐受性指短时反复用药药效递减。"},"id":"ph04_q11","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":11},{"type":"C","stem":"维拉帕米","options":{"A":"肝药酶抑制","B":"遗传异常影响效应","C":"两者均有","D":"两者均无"},"answer":["D"],"rationale":"维拉帕米为钙通道阻滞药，既非典型肝药酶抑制剂，也无遗传异常影响效应。","expl":{"A":"肝药酶抑制并非维拉帕米的特点。","B":"遗传异常影响效应并非维拉帕米的特点。","C":"两者均有，错误。","D":"正确，维拉帕米两者均无。"},"id":"ph04_q12","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":12},{"type":"C","stem":"伯氨喹","options":{"A":"肝药酶抑制","B":"遗传异常影响效应","C":"两者均有","D":"两者均无"},"answer":["B"],"rationale":"伯氨喹在G6PD缺乏者中可诱发溶血，属遗传异常影响效应。","expl":{"A":"肝药酶抑制不是伯氨喹的主要作用。","B":"正确，G6PD缺乏者用伯氨喹易致溶血，属遗传异常影响效应。","C":"两者均有，错误。","D":"两者均无，错误。"},"id":"ph04_q13","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":13},{"type":"C","stem":"异烟肼","options":{"A":"肝药酶抑制","B":"遗传异常影响效应","C":"两者均有","D":"两者均无"},"answer":["C"],"rationale":"异烟肼既抑制肝药酶，又存在乙酰化快慢型的遗传多态性。","expl":{"A":"肝药酶抑制是异烟肼的特点之一。","B":"遗传异常影响效应（乙酰化快慢型）亦为其特点。","C":"正确，异烟肼两者均有。","D":"两者均无，错误。"},"id":"ph04_q14","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":14},{"type":"C","stem":"西米替丁","options":{"A":"肝药酶抑制","B":"遗传异常影响效应","C":"两者均有","D":"两者均无"},"answer":["A"],"rationale":"西咪替丁是典型的肝药酶抑制剂。","expl":{"A":"正确，西咪替丁抑制肝药酶，减慢药物代谢。","B":"遗传异常影响效应并非西咪替丁的特点。","C":"两者均有，错误。","D":"两者均无，错误。"},"id":"ph04_q15","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":15},{"type":"X","stem":"联合应用两种以上药物的目的在于","options":{"A":"减少单味药用量","B":"减少不良反应","C":"增强疗效","D":"延缓耐药性发生","E":"改变遗传异常表现的快及慢代谢型"},"answer":["A","B","C"],"rationale":"联合用药可增强疗效、减少不良反应并减少单味药用量。","expl":{"A":"正确，联合用药可减少单味药用量。","B":"正确，合理联合可减少不良反应。","C":"正确，联合用药可增强疗效。","D":"延缓耐药性主要用于抗感染药物，非一般联合用药的普遍目的。","E":"改变遗传快慢代谢型不是联合用药的目的。"},"id":"ph04_q16","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":16},{"type":"X","stem":"连续用药后，机体对药物的反应发生改变，包括","options":{"A":"耐药性","B":"耐受性","C":"依赖性","D":"药物慢代谢型","E":"快速耐受"},"answer":["B","C","E"],"rationale":"连续用药后机体反应改变包括耐受性、依赖性和快速耐受性。","expl":{"A":"耐药性针对病原体或肿瘤细胞，非机体对药物的反应改变。","B":"正确，耐受性是连续用药后机体反应性降低。","C":"正确，依赖性是连续用药后机体产生的状态。","D":"药物慢代谢型属遗传多态性，非连续用药所致。","E":"正确，快速耐受是短时反复用药的反应改变。"},"id":"ph04_q17","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":17},{"type":"X","stem":"舌下给药的特点是","options":{"A":"可避免肝肠循环","B":"可避免胃酸破坏","C":"吸收极慢","D":"可避免首过效应","E":"吸收较迅速"},"answer":["B","C","D","E"],"rationale":"舌下给药不经消化道和门静脉，可避免胃酸破坏与首过效应，吸收较口服迅速。","expl":{"A":"肝肠循环指药物经胆汁排入肠后再被吸收，与舌下给药途径无直接关系。","B":"正确，舌下给药不经胃，可避免胃酸破坏。","C":"正确，舌下给药经口腔黏膜吸收，吸收量有限、速度慢于静脉给药。","D":"正确，舌下给药不经门静脉和肝脏，可避免首过效应。","E":"正确，舌下给药较口服吸收迅速，起效快。"},"id":"ph04_q18","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":18},{"type":"X","stem":"联合用药可发生的作用包括","options":{"A":"拮抗作用","B":"配伍禁忌","C":"协同作用","D":"个体差异","E":"药剂当量"},"answer":["A","B","C"],"rationale":"联合用药可产生协同作用、拮抗作用及配伍禁忌。","expl":{"A":"正确，联合用药可发生拮抗作用。","B":"正确，联合用药体外配伍可发生配伍禁忌。","C":"正确，联合用药可发生协同作用。","D":"个体差异是机体自身特点，非联合用药产生的作用。","E":"药剂当量属制剂学概念，非联合用药产生的作用。"},"id":"ph04_q19","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":19},{"type":"X","stem":"影响药代动力学的因素有","options":{"A":"胃肠吸收","B":"血浆蛋白结合","C":"干扰神经递质的转运","D":"肾脏排泄","E":"肝脏生物转化"},"answer":["A","B","D","E"],"rationale":"影响药动学的因素包括吸收、分布（蛋白结合）、代谢和排泄。","expl":{"A":"正确，胃肠吸收影响药物的吸收过程。","B":"正确，血浆蛋白结合影响药物分布。","C":"干扰神经递质转运属药效学作用，非药动学因素。","D":"正确，肾脏排泄影响药物消除。","E":"正确，肝脏生物转化影响药物代谢。"},"id":"ph04_q20","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":20},{"type":"X","stem":"关于药物相互作用与用药监护，下列叙述正确的有","options":{"A":"华法林与阿司匹林合用增加出血风险","B":"氨基糖苷类与呋塞米合用可加重耳毒性","C":"四环素类与含钙、铁、镁的药物同服可减少吸收","D":"他汀类与红霉素合用增加横纹肌溶解风险","E":"洋地黄中毒时可用葡萄糖酸钙静脉注射解救"},"answer":["A","B","C","D"],"rationale":"华法林与阿司匹林合用因抗凝与抗血小板作用叠加而增加出血，氨基糖苷类与呋塞米耳毒性相加，四环素与多价金属离子络合影响吸收，红霉素抑制CYP3A4使他汀血药浓度升高，故E错误。","expl":{"A":"正确，抗凝作用与血小板抑制叠加，并竞争血浆蛋白，出血风险明显增加。","B":"正确，两者均损害耳蜗，合用耳毒性相加，应避免联用。","C":"正确，四环素与钙、铁、镁离子形成难溶络合物，吸收明显减少。","D":"正确，红霉素抑制CYP3A4使他汀浓度升高，可致肌痛和横纹肌溶解。","E":"错误，钙剂可加重强心苷对心脏的毒性，中毒时应禁用钙剂。"},"id":"ph04_q21","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":21}]},{"title":"第五章 传出神经系统药理学概论","questions":[{"type":"A","stem":"下列哪种效应不是通过激动 M 受体实现的","options":{"A":"心率减慢","B":"胃肠道平滑肌收缩","C":"胃肠道括约肌收缩","D":"膀胱括约肌舒张","E":"瞳孔括约肌收缩"},"answer":["C"],"rationale":"激动M受体使胃肠道括约肌舒张而非收缩，故C不是M受体效应。","expl":{"A":"心率减慢是激动心脏M受体的效应。","B":"胃肠道平滑肌收缩是M受体激动效应。","C":"正确，M受体激动使胃肠道括约肌舒张，而非收缩。","D":"膀胱括约肌舒张是M受体激动效应。","E":"瞳孔括约肌收缩是M受体激动效应。"},"id":"ph05_q01","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":1},{"type":"A","stem":"胆碱能神经不包括","options":{"A":"交感、副交感神经节前纤维","B":"交感神经节后纤维的大部分","C":"副交感神经节后纤维","D":"运动神经","E":"支配汗腺的分泌神经"},"answer":["B"],"rationale":"交感神经节后纤维大部分为肾上腺素能纤维，不属胆碱能神经。","expl":{"A":"交感、副交感节前纤维均为胆碱能纤维。","B":"正确，交感节后纤维大部分属肾上腺素能，不属胆碱能神经。","C":"副交感节后纤维为胆碱能纤维。","D":"运动神经为胆碱能神经。","E":"支配汗腺的分泌神经为交感节后胆碱能纤维。"},"id":"ph05_q02","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":2},{"type":"A","stem":"骨骼肌血管平滑肌上有","options":{"A":"α 受体、β 受体、无 M 受体","B":"α 受体、M 受体、无 β 受体","C":"α 受体、β 受体及M 受体","D":"α 受体、无 β 受体及 M 受体","E":"M 受体、无 α 受体及 β 受体"},"answer":["C"],"rationale":"骨骼肌血管平滑肌同时分布有α、β和M受体。","expl":{"A":"骨骼肌血管有M受体，并非无M受体。","B":"骨骼肌血管有β受体，并非无β受体。","C":"正确，骨骼肌血管平滑肌上同时有α、β及M受体。","D":"骨骼肌血管有β和M受体，并非无β及M受体。","E":"骨骼肌血管亦有α、β受体，并非仅M受体。"},"id":"ph05_q03","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":3},{"type":"A","stem":"乙酰胆碱作用消失主要依赖于","options":{"A":"摄取 1","B":"摄取 2","C":"胆碱乙酰转移酶的作用","D":"胆碱酯酶水解","E":"以上都不对"},"answer":["D"],"rationale":"乙酰胆碱释放后主要被胆碱酯酶水解而失活。","expl":{"A":"摄取1是去甲肾上腺素的消除方式，非ACh。","B":"摄取2也是去甲肾上腺素的消除方式，非ACh。","C":"胆碱乙酰转移酶催化ACh合成，非分解。","D":"正确，ACh作用消失主要依赖胆碱酯酶水解。","E":"以上都不对，错误。"},"id":"ph05_q04","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":4},{"type":"A","stem":"能选择性的与毒蕈碱结合的胆碱受体称为","options":{"A":"M 受体","B":"N 受体","C":"α 受体","D":"β 受体","E":"DA 受体"},"answer":["A"],"rationale":"能选择性被毒蕈碱激动并与之结合的胆碱受体称M受体。","expl":{"A":"正确，与毒蕈碱选择性结合的胆碱受体为M受体。","B":"N受体与烟碱选择性结合。","C":"α受体属肾上腺素受体，非胆碱受体。","D":"β受体属肾上腺素受体。","E":"DA受体是多巴胺受体。"},"id":"ph05_q05","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":5},{"type":"A","stem":"下列哪种效应是通过激动 M-R 实现的？","options":{"A":"膀胱括约肌收缩","B":"骨骼肌收缩","C":"虹膜辐射肌收缩","D":"汗腺分泌","E":"睫状肌舒张"},"answer":["D"],"rationale":"汗腺分泌受M受体激动支配，故属M受体效应。","expl":{"A":"膀胱括约肌在M激动时是舒张，非收缩。","B":"骨骼肌收缩经N2受体，非M受体。","C":"虹膜辐射肌收缩是α受体效应（扩瞳）。","D":"正确，汗腺分泌由交感节后胆碱能纤维经M受体介导。","E":"睫状肌在M激动时收缩，非舒张。"},"id":"ph05_q06","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":6},{"type":"A","stem":"ACh 作用的消失，主要","options":{"A":"被突触前膜再摄取","B":"是扩散入血液中被肝肾破坏","C":"被神经未梢的胆碱乙酰化酶水解","D":"被神经突触部位的胆碱酯酶水解","E":"在突触间隙被 MAO 所破坏"},"answer":["D"],"rationale":"ACh释放后主要被突触部位的胆碱酯酶水解失活。","expl":{"A":"被突触前膜再摄取是NA的消除方式，非ACh。","B":"扩散入血被肝肾破坏并非ACh失活的主要方式。","C":"胆碱乙酰化酶催化合成，非水解。","D":"正确，ACh主要被突触部位的胆碱酯酶水解。","E":"MAO主要破坏单胺类递质，非ACh。"},"id":"ph05_q07","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":7},{"type":"A","stem":"M 样作用是指","options":{"A":"烟碱样作用","B":"心脏兴奋、血管扩张、平滑肌松驰","C":"骨骼肌收缩","D":"血管收缩、扩瞳","E":"心脏抑制、腺体分泌增加、胃肠平滑肌收缩"},"answer":["E"],"rationale":"M样作用指心脏抑制、腺体分泌增加、胃肠平滑肌收缩等表现。","expl":{"A":"烟碱样作用由N受体介导，非M样作用。","B":"心脏兴奋、血管扩张、平滑肌松弛非M样作用组合。","C":"骨骼肌收缩为N样作用。","D":"血管收缩、扩瞳是α受体效应。","E":"正确，心脏抑制、腺体分泌增加、胃肠平滑肌收缩为M样作用。"},"id":"ph05_q08","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":8},{"type":"A","stem":"在囊泡内合成 NA 的前身物质是","options":{"A":"酪氨酸","B":"多巴","C":"多巴胺","D":"肾上腺素","E":"5-羟色胺"},"answer":["C"],"rationale":"囊泡内的多巴胺经多巴胺β-羟化酶转化为去甲肾上腺素，故前身是多巴胺。","expl":{"A":"酪氨酸是多巴的前体，在胞质中转化。","B":"多巴在胞质中经脱羧生成多巴胺。","C":"正确，囊泡内合成NA的直接前身物质是多巴胺。","D":"肾上腺素由NA甲基化而来，非NA前身。","E":"5-羟色胺与NA合成无关。"},"id":"ph05_q09","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":9},{"type":"A","stem":"下列哪种表现不属于 β-R 兴奋效应","options":{"A":"支气管舒张","B":"血管扩张","C":"心脏兴奋","D":"瞳孔扩大","E":"肾素分泌"},"answer":["D"],"rationale":"瞳孔扩大由α受体介导（辐射肌收缩），不属β受体兴奋效应。","expl":{"A":"支气管舒张是β2受体兴奋效应。","B":"骨骼肌、冠脉血管扩张是β2受体效应。","C":"心脏兴奋是β1受体效应。","D":"正确，瞳孔扩大为α受体效应，非β受体兴奋表现。","E":"肾素分泌由β1受体介导。"},"id":"ph05_q10","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":10},{"type":"A","stem":"某受体被激动后，引起支气管平滑肌松驰，此受体为：","options":{"A":"α-R","B":"β1-R","C":"β2-R","D":"M-R","E":"N1-R"},"answer":["C"],"rationale":"支气管平滑肌松弛由β2受体激动介导。","expl":{"A":"α受体激动使血管收缩等，不引起支气管舒张。","B":"β1受体主要兴奋心脏，非支气管。","C":"正确，激动β2受体使支气管平滑肌松弛。","D":"M受体激动使支气管收缩。","E":"N1受体位于自主神经节，非支气管平滑肌。"},"id":"ph05_q11","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":11},{"type":"A","stem":"去甲肾上腺素减慢心率的机制是","options":{"A":"直接负性频率作用","B":"抑制窦房结","C":"阻断窦房结的 β 1-R","D":"外周阻力升高致间接刺激压力感受器","E":"激动心脏 M-R"},"answer":["D"],"rationale":"NA收缩血管使外周阻力升高、血压上升，反射性兴奋压力感受器减慢心率。","expl":{"A":"NA对心脏为直接正性频率作用，非负性。","B":"NA不直接抑制窦房结。","C":"NA不阻断窦房结β1受体。","D":"正确，外周阻力升高刺激压力感受器，反射性减慢心率。","E":"NA不激动心脏M受体。"},"id":"ph05_q12","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":12},{"type":"A","stem":"多巴胺 β-羟化酶主要存在于","options":{"A":"去甲肾上腺素能神经末梢膨体内","B":"去甲肾上腺素能神经末梢囊泡内","C":"去甲肾上腺素能神经突触间隙","D":"胆碱能神经突触间隙","E":"胆碱能神经突触前膜"},"answer":["B"],"rationale":"多巴胺β-羟化酶存在于去甲肾上腺素能神经末梢的囊泡内。","expl":{"A":"该酶位于囊泡内，并非末梢膨体胞质。","B":"正确，多巴胺β-羟化酶存在于囊泡内。","C":"突触间隙不含该酶。","D":"胆碱能神经不含多巴胺β-羟化酶。","E":"胆碱能神经突触前膜不含该酶。"},"id":"ph05_q13","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":13},{"type":"A","stem":"α-R 分布占优势的效应器是","options":{"A":"皮肤、粘膜、内脏血管","B":"冠状动脉血管","C":"肾血管","D":"脑血管","E":"肌肉血管"},"answer":["A"],"rationale":"皮肤、黏膜、内脏血管以α受体占优势，激动时收缩。","expl":{"A":"正确，皮肤、黏膜、内脏血管α受体占优势。","B":"冠脉以β2受体占优势，非α。","C":"肾血管α受体亦较多，但皮肤黏膜内脏血管更典型。","D":"脑血管受体复杂，α不占绝对优势。","E":"肌肉血管以β2受体占优势。"},"id":"ph05_q14","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":14},{"type":"A","stem":"关于 N2-R 结构和偶联的叙述，正确的是","options":{"A":"属 G-蛋白偶联受体","B":"由 3 个亚单位组成","C":"肽链的 N-端在细胞膜外，C-端在细胞内","D":"为 7 次跨膜的肽链","E":"属配体、门控通道型受体"},"answer":["E"],"rationale":"N2受体属配体门控离子通道型受体，非G蛋白偶联。","expl":{"A":"N2受体非G蛋白偶联受体。","B":"N2受体由5个亚单位组成，非3个。","C":"N受体亚单位N端、C端均在细胞外，此说法错误。","D":"7次跨膜是G蛋白偶联受体特点，N2受体亚单位仅4次跨膜。","E":"正确，N2受体属配体门控通道型受体。"},"id":"ph05_q15","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":15},{"type":"B","stem":"睫状肌的优势受体是","options":{"A":"α-R","B":"β 1-R","C":"β2-R","D":"M-R","E":"N-R"},"answer":["D"],"rationale":"睫状肌主要受M受体支配，激动时收缩。","expl":{"A":"α受体不支配睫状肌。","B":"β1受体不支配睫状肌。","C":"β2受体不支配睫状肌。","D":"正确，睫状肌的优势受体是M受体。","E":"N受体不在睫状肌。"},"id":"ph05_q16","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":16},{"type":"B","stem":"肾血管的优势受体是","options":{"A":"α-R","B":"β 1-R","C":"β2-R","D":"M-R","E":"N-R"},"answer":["A"],"rationale":"肾血管以α受体占优势。","expl":{"A":"正确，肾血管的优势受体是α受体。","B":"β1受体主要分布于心脏。","C":"β2受体主要分布于支气管和骨骼肌血管。","D":"M受体不分布于肾血管。","E":"N受体位于神经节和骨骼肌。"},"id":"ph05_q17","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":17},{"type":"B","stem":"骨骼肌血管的优势受体是","options":{"A":"α-R","B":"β 1-R","C":"β2-R","D":"M-R","E":"N-R"},"answer":["C"],"rationale":"骨骼肌血管以β2受体占优势，激动时舒张。","expl":{"A":"骨骼肌血管α受体较少，非优势。","B":"β1受体主要在心脏。","C":"正确，骨骼肌血管的优势受体是β2受体。","D":"骨骼肌血管有M受体但非优势。","E":"N受体不在骨骼肌血管。"},"id":"ph05_q18","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":18},{"type":"B","stem":"抑制突触前膜 NA 释放的受体是","options":{"A":"D1","B":"D2","C":"α 1","D":"α2","E":"N1"},"answer":["D"],"rationale":"突触前膜α2受体兴奋可抑制NA释放，起负反馈作用。","expl":{"A":"D1受体与NA释放无直接关系。","B":"D2受体与NA释放无直接关系。","C":"α1受体主要介导血管收缩等效应。","D":"正确，激动突触前膜α2受体可抑制NA释放。","E":"N1受体位于神经节。"},"id":"ph05_q19","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":19},{"type":"B","stem":"促进肾上腺髓质释放 NA 、AD 的受体是","options":{"A":"D1","B":"D2","C":"α 1","D":"α2","E":"N1"},"answer":["E"],"rationale":"肾上腺髓质受交感节前胆碱能纤维支配，其N1受体激动促进分泌。","expl":{"A":"D1受体不参与肾上腺髓质分泌。","B":"D2受体不参与肾上腺髓质分泌。","C":"α1受体不促进肾上腺髓质释放。","D":"α2受体不促进肾上腺髓质释放。","E":"正确，激动N1受体促进肾上腺髓质释放NA、AD。"},"id":"ph05_q20","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":20},{"type":"B","stem":"与锥体外运动有关的受体是","options":{"A":"D1","B":"D2","C":"α 1","D":"α2","E":"N1"},"answer":["B"],"rationale":"黑质-纹状体通路的多巴胺D2受体与锥体外系运动功能有关。","expl":{"A":"D1受体与锥体外系运动关系相对较小。","B":"正确，D2受体与锥体外系运动功能密切相关。","C":"α1受体与锥体外系运动无关。","D":"α2受体与锥体外系运动无关。","E":"N1受体与锥体外系运动无关。"},"id":"ph05_q21","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":21},{"type":"C","stem":"M-R 激动时","options":{"A":"胃肠蠕动加强","B":"心脏收缩加快","C":"两者都是","D":"两者都不是"},"answer":["A"],"rationale":"M受体激动使胃肠蠕动加强，但使心脏收缩减慢减弱。","expl":{"A":"正确，M受体激动使胃肠蠕动加强。","B":"M受体激动使心脏收缩减慢减弱，非加快。","C":"两者都是，错误。","D":"两者都不是，错误。"},"id":"ph05_q22","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":22},{"type":"C","stem":"N1-R 激动时","options":{"A":"胃肠蠕动加强","B":"心脏收缩加快","C":"两者都是","D":"两者都不是"},"answer":["C"],"rationale":"N1受体激动兴奋自主神经节，使胃肠蠕动加强且心脏收缩加快。","expl":{"A":"胃肠蠕动加强是N1激动效应之一。","B":"心脏收缩加快也是N1激动效应之一。","C":"正确，N1激动使胃肠蠕动加强且心脏收缩加快。","D":"两者都不是，错误。"},"id":"ph05_q23","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":23},{"type":"C","stem":"α-R 激动时","options":{"A":"胃肠蠕动加强","B":"心脏收缩加快","C":"两者都是","D":"两者都不是"},"answer":["D"],"rationale":"α受体激动主要收缩血管，不直接加强胃肠蠕动和心脏收缩。","expl":{"A":"α激动不加强胃肠蠕动。","B":"α激动不加快心脏收缩。","C":"两者都是，错误。","D":"正确，α受体激动两者都不是。"},"id":"ph05_q24","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":24},{"type":"X","stem":"去甲肾上腺素消除的方式是","options":{"A":"单胺氧化酶破坏","B":"环加氧酶氧 化","C":"儿茶酚氧位甲基转移酶破坏","D":"经突触前膜摄取","E":"磷酸二酯酶代谢"},"answer":["A","C","D"],"rationale":"NA主要经突触前膜摄取及MAO、COMT破坏而消除。","expl":{"A":"正确，MAO可氧化破坏NA。","B":"环加氧酶参与前列腺素合成，不代谢NA。","C":"正确，COMT可破坏NA。","D":"正确，NA经突触前膜摄取是主要消除方式。","E":"磷酸二酯酶分解cAMP，不代谢NA。"},"id":"ph05_q25","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":25},{"type":"X","stem":"M 受体兴奋时的效应是","options":{"A":"腺体分泌增加","B":"胃肠平滑肌收缩","C":"瞳孔缩小","D":"A-V 传导加快","E":"心率减慢"},"answer":["A","B","C","E"],"rationale":"M受体兴奋表现为腺体分泌、胃肠收缩、缩瞳和心率减慢。","expl":{"A":"正确，M受体兴奋使腺体分泌增加。","B":"正确，M受体兴奋使胃肠平滑肌收缩。","C":"正确，M受体兴奋使瞳孔括约肌收缩、瞳孔缩小。","D":"M受体兴奋使房室传导减慢，非加快。","E":"正确，M受体兴奋使心率减慢。"},"id":"ph05_q26","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":26},{"type":"X","stem":"关于去甲肾上腺素的描述，哪些是正确的","options":{"A":"主要兴奋a 受体","B":"是肾上腺素能神经释放的递质","C":"升压时易出现双向反应","D":"在整体情况下出现心率减慢","E":"引起冠状动脉收缩"},"answer":["A","B","D"],"rationale":"NA主要兴奋α受体、是肾上腺素能递质，整体升压时反射性心率减慢。","expl":{"A":"正确，NA主要兴奋α受体。","B":"正确，NA是肾上腺素能神经释放的递质。","C":"双向反应（先升后降）是肾上腺素的特点，NA无。","D":"正确，NA升压后经压力感受器反射性减慢心率。","E":"NA整体使冠脉血流量增加，不引起冠脉收缩。"},"id":"ph05_q27","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":27},{"type":"X","stem":"N 受体激动时可引起","options":{"A":"自主神经节兴奋","B":"肾上腺髓质分泌","C":"骨骼肌收缩","D":"汗腺分泌减少","E":"递质释放减少"},"answer":["A","B","C"],"rationale":"N受体激动可兴奋自主神经节、促进肾上腺髓质分泌并收缩骨骼肌。","expl":{"A":"正确，N1受体激动使自主神经节兴奋。","B":"正确，N1受体激动促进肾上腺髓质分泌。","C":"正确，N2受体激动使骨骼肌收缩。","D":"N受体激动使汗腺分泌增加，非减少。","E":"N受体激动促进递质释放，非减少。"},"id":"ph05_q28","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":28},{"type":"X","stem":"β 受体激动是可产生下列那些效应","options":{"A":"心率加快","B":"血管收缩","C":"支气管平滑肌松弛","D":"糖原分解","E":"瞳孔缩小"},"answer":["A","C","D"],"rationale":"β受体激动使心率加快、支气管松弛、糖原分解。","expl":{"A":"正确，β1受体激动使心率加快。","B":"β2受体激动使血管舒张，非收缩。","C":"正确，β2受体激动使支气管平滑肌松弛。","D":"正确，β受体激动促进糖原分解。","E":"瞳孔缩小是M受体效应，非β受体。"},"id":"ph05_q29","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":29},{"type":"X","stem":"激动 β 受体，同时阻滞 α 受体可导致下列哪些效应","options":{"A":"子宫松弛","B":"支气管扩张","C":"血管扩张","D":"瞳孔散大","E":"以上均无"},"answer":["A","B","C"],"rationale":"激动β受体并阻滞α受体可致子宫松弛、支气管扩张、血管扩张。","expl":{"A":"正确，β2激动使子宫平滑肌松弛。","B":"正确，β2激动使支气管扩张。","C":"正确，β2激动使血管扩张，α阻滞也削弱血管收缩。","D":"阻滞α受体使辐射肌松弛而缩瞳，非散瞳。","E":"以上均无，错误。"},"id":"ph05_q30","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":30},{"type":"A","stem":"骨骼肌运动终板膜上的胆碱受体主要是","options":{"A":"M受体","B":"N1受体","C":"N2受体","D":"α1受体","E":"β2受体"},"answer":["C"],"rationale":"骨骼肌运动终板膜上分布的是N2受体，属配体门控离子通道型受体，激动后引起终板电位和肌肉收缩，故答案为 C。","expl":{"A":"错误，M受体主要分布于副交感神经支配的效应器细胞及汗腺，不在运动终板。","B":"错误，N1受体位于自主神经节和肾上腺髓质，介导节后神经元兴奋。","C":"正确，N2受体位于骨骼肌运动终板，被筒箭毒碱阻断后骨骼肌松弛。","D":"错误，α1受体是肾上腺素受体，分布于血管平滑肌等效应器。","E":"错误，β2受体分布于支气管和血管平滑肌，与骨骼肌收缩无直接关系。"},"id":"ph05_q31","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":31},{"type":"A","stem":"支配汗腺的交感神经末梢释放的递质是","options":{"A":"乙酰胆碱","B":"去甲肾上腺素","C":"肾上腺素","D":"多巴胺","E":"5-羟色胺"},"answer":["A"],"rationale":"支配汗腺的交感神经节后纤维属胆碱能纤维，释放乙酰胆碱作用于M受体引起汗腺分泌，故答案为 A。","expl":{"A":"正确，汗腺虽由交感神经支配，但其节后纤维为胆碱能纤维，递质是乙酰胆碱。","B":"错误，多数交感节后纤维释放去甲肾上腺素，但支配汗腺者例外。","C":"错误，肾上腺素主要由肾上腺髓质分泌入血，不是汗腺神经末梢递质。","D":"错误，多巴胺是中枢及肾、肠系膜血管部分神经的递质，与汗腺分泌无关。","E":"错误，5-羟色胺主要是中枢递质和肠嗜铬细胞分泌物质，不支配汗腺。"},"id":"ph05_q32","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":32}]},{"title":"第六章 胆碱受体激动药","questions":[{"type":"A","stem":"毛果芸香碱对眼睛的作用是","options":{"A":"瞳孔缩小，升高眼内压，调节痉挛","B":"瞳孔缩小，降低眼内压，调节痉挛","C":"瞳孔扩大，升高眼内压，调节麻痹","D":"瞳孔扩大，降低眼内压，调节麻痹","E":"瞳孔缩小，降低眼内压，调节麻痹"},"answer":["B"],"rationale":"毛果芸香碱使瞳孔缩小、眼内压降低并致调节痉挛。","expl":{"A":"毛果芸香碱降低眼内压，非升高。","B":"正确，毛果芸香碱缩瞳、降眼压、调节痉挛。","C":"瞳孔扩大是阿托品类效应。","D":"瞳孔扩大、调节麻痹是阿托品类效应。","E":"毛果芸香碱致调节痉挛，非麻痹。"},"id":"ph06_q01","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":1},{"type":"A","stem":"毛果芸香碱的缩瞳机制是","options":{"A":"阻断虹膜 a 受体，开大肌松弛","B":"阻断虹膜 M 胆碱受体，括约肌松弛","C":"激动虹膜 a 受体，开大肌收缩","D":"激动虹膜 M 胆碱受体，括约肌收缩","E":"抑制胆碱酯酶，使乙酰胆碱增多"},"answer":["D"],"rationale":"毛果芸香碱激动虹膜瞳孔括约肌M受体使其收缩而缩瞳。","expl":{"A":"阻断α受体、开大肌松弛非毛果芸香碱机制。","B":"阻断M受体使括约肌松弛会引起扩瞳，非缩瞳。","C":"激动α受体使开大肌收缩引起扩瞳。","D":"正确，激动虹膜M受体使括约肌收缩而缩瞳。","E":"抑制胆碱酯酶是毒扁豆碱机制，非毛果芸香碱。"},"id":"ph06_q02","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":2},{"type":"A","stem":"下列关于卡巴胆碱作用错误的是","options":{"A":"激动 M 胆碱受体","B":"激动 N 胆碱受体","C":"用于术后腹气胀与尿潴留","D":"作用广泛，副作用大","E":"禁用于青光眼"},"answer":["C"],"rationale":"卡巴胆碱主要用于青光眼，用于术后腹气胀与尿潴留的是氨甲酰甲胆碱。","expl":{"A":"卡巴胆碱激动M胆碱受体，正确。","B":"卡巴胆碱也激动N胆碱受体，正确。","C":"正确，用于术后腹气胀与尿潴留是氨甲酰甲胆碱的用途。","D":"卡巴胆碱作用广泛、副作用大，正确。","E":"卡巴胆碱主要局部用于青光眼，并非禁用。"},"id":"ph06_q03","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":3},{"type":"A","stem":"氨甲酰胆碱临床主要用于","options":{"A":"青光眼","B":"术后腹气胀和尿潴留","C":"眼底检查","D":"解救有机磷农药中毒","E":"治疗室上性心动过速"},"answer":["A"],"rationale":"氨甲酰胆碱（卡巴胆碱）临床主要局部用于青光眼。","expl":{"A":"正确，氨甲酰胆碱主要局部点眼用于青光眼。","B":"用于术后腹气胀和尿潴留的是氨甲酰甲胆碱。","C":"眼底检查需散瞳，用阿托品等，非氨甲酰胆碱。","D":"解救有机磷中毒用阿托品和解磷定，非氨甲酰胆碱。","E":"治疗室上性心动过速用维拉帕米等，非氨甲酰胆碱。"},"id":"ph06_q04","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":4},{"type":"A","stem":"对于 ACh，下列叙述错误的是","options":{"A":"激动 M 、N-R","B":"无临床实用价值","C":"作用广泛","D":"化学性质稳定","E":"化学性质不稳定"},"answer":["D"],"rationale":"ACh化学性质不稳定，易被胆碱酯酶水解。","expl":{"A":"ACh可激动M、N受体，正确。","B":"ACh无临床实用价值，正确。","C":"ACh作用广泛，正确。","D":"正确，ACh化学性质不稳定，此题说法错误。","E":"ACh化学性质不稳定，正确。"},"id":"ph06_q05","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":5},{"type":"A","stem":"与毒扁豆碱相比，毛果芸香碱不具备哪种特点？","options":{"A":"遇光不稳定","B":"维持时间短","C":"刺激性小","D":"作用较弱","E":"水溶液稳定"},"answer":["A"],"rationale":"毛果芸香碱水溶液稳定，遇光不稳定是毒扁豆碱的特点。","expl":{"A":"正确，遇光不稳定是毒扁豆碱的特点，毛果芸香碱不具备。","B":"毛果芸香碱维持时间较短，具备。","C":"毛果芸香碱刺激性小，具备。","D":"毛果芸香碱作用较弱，具备。","E":"毛果芸香碱水溶液稳定，具备。"},"id":"ph06_q06","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":6},{"type":"A","stem":"切除支配虹膜的神经（即去神经眼）后再滴入毛果芸香碱，则应","options":{"A":"扩瞳","B":"缩瞳","C":"先扩瞳后缩瞳","D":"先缩瞳后扩瞳","E":"无影响"},"answer":["B"],"rationale":"毛果芸香碱直接激动M受体，去神经后仍可缩瞳。","expl":{"A":"扩瞳需激动α受体或阻断M受体，毛果芸香碱不引起。","B":"正确，去神经眼滴毛果芸香碱仍直接激动M受体而缩瞳。","C":"先扩瞳后缩瞳与毛果芸香碱作用不符。","D":"先缩瞳后扩瞳与毛果芸香碱作用不符。","E":"无影响错误，毛果芸香碱仍有缩瞳作用。"},"id":"ph06_q07","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":7},{"type":"A","stem":"小剂量 ACh 或 M-R 激动药无下列哪种作用","options":{"A":"缩瞳、降低眼内压","B":"腺体分泌增加","C":"胃肠、膀胱平滑肌兴奋","D":"骨骼肌收缩","E":"心脏抑制、血管扩张、血压下降"},"answer":["D"],"rationale":"骨骼肌收缩需激动N2受体，小剂量M激动药不引起。","expl":{"A":"缩瞳、降眼压是M激动效应。","B":"腺体分泌增加是M激动效应。","C":"胃肠、膀胱平滑肌兴奋是M激动效应。","D":"正确，骨骼肌收缩需N2受体，M激动药不引起。","E":"心脏抑制、血管扩张、血压下降是M激动效应。"},"id":"ph06_q08","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":8},{"type":"A","stem":"与毛果芸香碱相比，毒扁豆碱用于治疗青光眼的优点是","options":{"A":"作用强而久","B":"水溶液稳定","C":"毒副作用小","D":"不引起调节痉挛","E":"不会吸收中毒"},"answer":["A"],"rationale":"毒扁豆碱通过抑制胆碱酯酶间接发挥作用，作用强而持久。","expl":{"A":"正确，毒扁豆碱治青光眼作用强而久。","B":"毒扁豆碱水溶液不稳定，非优点。","C":"毒扁豆碱毒副作用较大。","D":"毒扁豆碱也引起调节痉挛。","E":"毒扁豆碱可吸收中毒。"},"id":"ph06_q09","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":9},{"type":"A","stem":"可直接激动 M 、N-R 的药物是","options":{"A":"氨甲酰甲胆碱","B":"氨甲酰胆碱","C":"毛果芸香碱","D":"毒扁豆碱","E":"加兰他敏"},"answer":["B"],"rationale":"氨甲酰胆碱可直接激动M和N受体。","expl":{"A":"氨甲酰甲胆碱主要激动M受体。","B":"正确，氨甲酰胆碱直接激动M、N受体。","C":"毛果芸香碱主要激动M受体。","D":"毒扁豆碱为胆碱酯酶抑制剂，非直接激动。","E":"加兰他敏为胆碱酯酶抑制剂。"},"id":"ph06_q10","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":10},{"type":"B","stem":"ACh 的作用是","options":{"A":"激动 M-R 及 N-R","B":"激动 M-R","C":"小剂量激动 N-R，大剂量阻断 N-R","D":"阻断 M-R 和 N-R","E":"阻断 M-R"},"answer":["A"],"rationale":"ACh可激动M和N受体。","expl":{"A":"正确，ACh激动M受体及N受体。","B":"仅激动M受体非ACh的完整作用。","C":"小剂量激动N、大剂量阻断N是烟碱的作用特点。","D":"阻断M和N受体是阿托品类的作用。","E":"仅阻断M受体非ACh作用。"},"id":"ph06_q11","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":11},{"type":"B","stem":"毛果芸香碱的作用是","options":{"A":"激动 M-R 及 N-R","B":"激动 M-R","C":"小剂量激动 N-R，大剂量阻断 N-R","D":"阻断 M-R 和 N-R","E":"阻断 M-R"},"answer":["B"],"rationale":"毛果芸香碱选择性激动M受体。","expl":{"A":"毛果芸香碱不激动N受体。","B":"正确，毛果芸香碱主要激动M受体。","C":"小剂量激动N、大剂量阻断N是烟碱特点。","D":"毛果芸香碱不阻断M、N受体。","E":"毛果芸香碱是激动M受体，非阻断。"},"id":"ph06_q12","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":12},{"type":"B","stem":"氨甲酰胆碱的作用是","options":{"A":"激动 M-R 及 N-R","B":"激动 M-R","C":"小剂量激动 N-R，大剂量阻断 N-R","D":"阻断 M-R 和 N-R","E":"阻断 M-R"},"answer":["A"],"rationale":"氨甲酰胆碱可激动M和N受体。","expl":{"A":"正确，氨甲酰胆碱激动M及N受体。","B":"仅激动M受体不完整。","C":"小剂量激动N、大剂量阻断N是烟碱特点。","D":"氨甲酰胆碱不阻断受体。","E":"氨甲酰胆碱是激动剂，非阻断。"},"id":"ph06_q13","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":13},{"type":"B","stem":"氨甲酰甲胆碱","options":{"A":"用于青光眼和虹膜炎","B":"用于术后腹气胀和尿潴留","C":"解救有机磷农药中毒","D":"无临床实用价值，但有毒理意义","E":"被胆碱酯酶水解，作科研工具药"},"answer":["B"],"rationale":"氨甲酰甲胆碱用于术后腹气胀和尿潴留。","expl":{"A":"用于青光眼和虹膜炎的是毛果芸香碱。","B":"正确，氨甲酰甲胆碱用于术后腹气胀和尿潴留。","C":"解救有机磷中毒用阿托品等。","D":"无临床价值、有毒理意义的是烟碱。","E":"被胆碱酯酶水解、作工具药的是ACh。"},"id":"ph06_q14","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":14},{"type":"B","stem":"烟碱","options":{"A":"用于青光眼和虹膜炎","B":"用于术后腹气胀和尿潴留","C":"解救有机磷农药中毒","D":"无临床实用价值，但有毒理意义","E":"被胆碱酯酶水解，作科研工具药"},"answer":["D"],"rationale":"烟碱无临床实用价值，但有毒理意义。","expl":{"A":"用于青光眼和虹膜炎的是毛果芸香碱。","B":"用于术后腹气胀尿潴留的是氨甲酰甲胆碱。","C":"解救有机磷中毒用阿托品。","D":"正确，烟碱无临床实用价值，但有毒理意义。","E":"被胆碱酯酶水解、作工具药的是ACh。"},"id":"ph06_q15","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":15},{"type":"C","stem":"治疗青光眼","options":{"A":"毛果芸香碱","B":"毒扁豆碱","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"毛果芸香碱和毒扁豆碱均可缩瞳降眼压，用于青光眼。","expl":{"A":"毛果芸香碱用于青光眼。","B":"毒扁豆碱也用于青光眼。","C":"正确，两者均用于治疗青光眼。","D":"两者均否，错误。"},"id":"ph06_q16","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":16},{"type":"C","stem":"水溶液不稳定，需避光保存","options":{"A":"毛果芸香碱","B":"毒扁豆碱","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"毒扁豆碱水溶液不稳定、遇光易氧化变色，需避光保存。","expl":{"A":"毛果芸香碱水溶液稳定。","B":"正确，毒扁豆碱水溶液不稳定，需避光保存。","C":"两者均是，错误。","D":"两者均否，错误。"},"id":"ph06_q17","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":17},{"type":"X","stem":"毛果芸香碱对眼的作用","options":{"A":"瞳孔缩小","B":"降低眼内压","C":"睫状肌松弛","D":"治虹膜炎","E":"对汗腺不敏感"},"answer":["A","B","C"],"rationale":"毛果芸香碱激动M受体，使瞳孔缩小、眼内压降低，并引起调节痉挛。","expl":{"A":"正确，毛果芸香碱激动瞳孔括约肌M受体而缩瞳。","B":"正确，缩瞳使前房角开放，房水回流，眼内压降低。","C":"正确，毛果芸香碱使睫状肌收缩、悬韧带松弛，引起调节痉挛。","D":"毛果芸香碱与扩瞳药交替用于虹膜炎以防粘连，并非直接治疗虹膜炎。","E":"毛果芸香碱促进汗腺和唾液腺分泌，对汗腺敏感而非不敏感。"},"id":"ph06_q18","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":18},{"type":"X","stem":"有关毒蕈碱的论述正确的有","options":{"A":"食用丝盖伞菌属和杯伞菌属蕈类后 30-60 分钟出现中毒","B":"中毒表现为流涎，流泪，恶心，呕吐，头痛，视觉障碍，腹部绞痛，腹泻","C":"中毒表现为心动过速，血压升高，易脑出血","D":"中毒表现为气管痉挛，呼吸困难，重者休克","E":"可用阿托品 每隔 30 分钟肌注 1-2mg"},"answer":["B","E"],"rationale":"毒蕈碱中毒表现为M样症状，可用阿托品解救。","expl":{"A":"中毒多在食后30分钟至数小时出现，30-60分钟并非固定界限。","B":"正确，流涎、流泪、恶心、呕吐、腹痛、腹泻等为典型M样表现。","C":"毒蕈碱中毒表现为心动过缓、血压下降，非心动过速、血压升高。","D":"毒蕈碱中毒可致支气管痉挛、呼吸困难，但休克非其典型表现。","E":"正确，阿托品为M受体阻断药，可解救毒蕈碱中毒，需重复肌注。"},"id":"ph06_q19","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":19},{"type":"A","stem":"治疗虹膜炎时，毛果芸香碱与阿托品交替滴眼的主要目的是","options":{"A":"增强缩瞳作用","B":"防止虹膜与晶状体粘连","C":"降低眼压","D":"减轻疼痛","E":"延长局麻药作用"},"answer":["B"],"rationale":"阿托品使瞳孔散大、虹膜退向周边，毛果芸香碱使瞳孔缩小，二者交替应用可防止虹膜与晶状体粘连，故答案为 B。","expl":{"A":"错误，阿托品散瞳与缩瞳作用相反，交替用药并非为了增强缩瞳。","B":"正确，散瞳与缩瞳交替可使虹膜活动，防止渗出物造成虹膜晶状体粘连。","C":"错误，降低眼压主要是毛果芸香碱治疗青光眼的目的，与虹膜炎用药目的不同。","D":"错误，两药交替并非以镇痛为主要目的，炎症疼痛需其他处理。","E":"错误，延长局麻药作用靠配伍肾上腺素，与本题用药目的无关。"},"id":"ph06_q20","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":20}]},{"title":"第七章 抗胆碱酯酶药","questions":[{"type":"A","stem":"新斯的明对下列效应器兴奋作用最强的是","options":{"A":"心血管","B":"腺体","C":"眼","D":"骨骼肌","E":"支气管平滑肌"},"answer":["D"],"rationale":"新斯的明除抑制胆碱酯酶外，还能直接兴奋骨骼肌运动终板上的N2受体，故对骨骼肌兴奋作用最强。","expl":{"A":"心血管：新斯的明对心血管作用较弱，不是其兴奋作用最强的效应器。","B":"腺体：新斯的明对腺体分泌促进作用弱，远不及骨骼肌。","C":"眼：新斯的明不易透过角膜，对眼的作用很弱。","D":"骨骼肌：正确，新斯的明直接兴奋N2受体并抑制胆碱酯酶，对骨骼肌作用最强。","E":"支气管平滑肌：新斯的明对支气管平滑肌作用较弱，并非最强。"},"id":"ph07_q01","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":1},{"type":"A","stem":"毒扁豆碱用于去神经的眼，产生的效应是","options":{"A":"瞳孔散大","B":"瞳孔缩小","C":"瞳孔无变化","D":"眼压升高","E":"调节麻痹"},"answer":["C"],"rationale":"毒扁豆碱为易逆性抗胆碱酯酶药，靠抑制AChE使乙酰胆碱蓄积起效；去神经眼无乙酰胆碱释放，故瞳孔无变化。","expl":{"A":"瞳孔散大：毒扁豆碱不散瞳，去神经眼无乙酰胆碱来源，不会散大。","B":"瞳孔缩小：去神经眼无乙酰胆碱释放，毒扁豆碱的间接作用无法缩瞳。","C":"瞳孔无变化：正确，毒扁豆碱依赖内源性乙酰胆碱，去神经眼故无效应。","D":"眼压升高：毒扁豆碱不升高眼压，去神经眼亦无此效应。","E":"调节麻痹：调节麻痹为阿托品类作用，毒扁豆碱致调节痉挛而非麻痹。"},"id":"ph07_q02","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":2},{"type":"A","stem":"新斯的明在临床上的主要用途是","options":{"A":"阵发性室上性心动过速","B":"阿托品中毒","C":"青光眼","D":"重症肌无力","E":"机械性肠梗阻"},"answer":["D"],"rationale":"新斯的明对骨骼肌选择性高，可兴奋N2受体增强肌力，是治疗重症肌无力的常用药物。","expl":{"A":"阵发性室上性心动过速：新斯的明虽可减慢心率，但非其主要用途。","B":"阿托品中毒：阿托品中毒多用毒扁豆碱解救，非新斯的明主要用途。","C":"青光眼：新斯的明不易入眼，青光眼用毒扁豆碱或毛果芸香碱。","D":"重症肌无力：正确，新斯的明增强骨骼肌收缩力，为重症肌无力常用药。","E":"机械性肠梗阻：机械性肠梗阻为禁忌，新斯的明促进蠕动可致肠穿孔。"},"id":"ph07_q03","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":3},{"type":"A","stem":"有机磷酸酯类中毒症状中，不属 M 样症状的是","options":{"A":"瞳孔缩小","B":"流涎流泪流汗","C":"腹痛腹泻","D":"肌颤","E":"小便失禁"},"answer":["D"],"rationale":"肌颤由运动神经末梢N2受体过度兴奋引起，属N样症状；其余选项均为M样症状。","expl":{"A":"瞳孔缩小：属M样症状，由缩瞳肌M受体兴奋引起。","B":"流涎流泪流汗：属M样症状，由腺体M受体兴奋所致。","C":"腹痛腹泻：属M样症状，由胃肠平滑肌M受体兴奋所致。","D":"肌颤：正确，肌颤为N样（N2受体）症状，不属M样。","E":"小便失禁：属M样症状，由膀胱逼尿肌M受体兴奋所致。"},"id":"ph07_q04","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":4},{"type":"A","stem":"碘解磷啶解救有机磷酸酯类（农药）中毒是因为","options":{"A":"能使失去活性的胆碱酯酶复活","B":"能直接对抗乙酰胆碱的作用","C":"有阻断 M 胆碱受体的作用","D":"有阻断 N 胆碱受体的作用","E":"能对抗有机磷酸酯分子中磷的毒性"},"answer":["A"],"rationale":"碘解磷定能与磷酰化胆碱酯酶结合，使被抑制的胆碱酯酶复活，恢复水解乙酰胆碱的能力。","expl":{"A":"能使失去活性的胆碱酯酶复活：正确，碘解磷定夺取与酶结合的磷酸基使其复活。","B":"能直接对抗乙酰胆碱的作用：碘解磷定不直接对抗乙酰胆碱，对抗M样作用靠阿托品。","C":"有阻断M胆碱受体的作用：碘解磷定无阻断M受体作用。","D":"有阻断N胆碱受体的作用：碘解磷定不阻断N受体。","E":"能对抗有机磷酸酯分子中磷的毒性：并非对抗磷本身毒性，而是复活被磷酰化的酶。"},"id":"ph07_q05","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":5},{"type":"A","stem":"抢救有机磷酸酯类中度以上中毒，最好应当使用","options":{"A":"阿托品","B":"解磷定","C":"解磷定和筒箭毒碱","D":"解磷定和阿托品","E":"阿托品和筒箭毒碱"},"answer":["D"],"rationale":"阿托品解除M样症状，解磷定复活胆碱酯酶并缓解N样（肌颤）症状，二者合用互补。","expl":{"A":"阿托品：单用阿托品不能复活胆碱酯酶，不能解除肌颤。","B":"解磷定：单用解磷定不能迅速对抗M样症状。","C":"解磷定和筒箭毒碱：筒箭毒碱阻断N2受体会加重呼吸肌麻痹，不可用。","D":"解磷定和阿托品：正确，二者合用兼顾M样与N样症状，疗效最佳。","E":"阿托品和筒箭毒碱：筒箭毒碱为肌松药，会加重中毒的呼吸抑制，禁用。"},"id":"ph07_q06","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":6},{"type":"A","stem":"属于胆碱酯酶复活药的药物是","options":{"A":"新斯的明","B":"氯磷定","C":"阿托品","D":"安贝氯铵","E":"毒扁豆碱"},"answer":["B"],"rationale":"氯磷定为常用胆碱酯酶复活药，可复活被有机磷磷酰化的胆碱酯酶。","expl":{"A":"新斯的明：为易逆性抗胆碱酯酶药，非复活药。","B":"氯磷定：正确，氯磷定属胆碱酯酶复活药。","C":"阿托品：为M受体阻断药，不复活胆碱酯酶。","D":"安贝氯铵：为易逆性抗胆碱酯酶药，非复活药。","E":"毒扁豆碱：为易逆性抗胆碱酯酶药，非复活药。"},"id":"ph07_q07","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":7},{"type":"B","stem":"易逆性抗胆碱酯酶药","options":{"A":"碘解磷定","B":"有机磷酸酯类","C":"毒扁豆碱","D":"氨甲酰胆碱","E":"乙酰胆碱"},"answer":["C"],"rationale":"毒扁豆碱与胆碱酯酶可逆结合、作用可自行恢复，属易逆性抗胆碱酯酶药。","expl":{"A":"碘解磷定：为胆碱酯酶复活药，非抗胆碱酯酶药。","B":"有机磷酸酯类：为难逆性抗胆碱酯酶药。","C":"毒扁豆碱：正确，毒扁豆碱属易逆性抗胆碱酯酶药。","D":"氨甲酰胆碱：为M、N受体激动药（拟胆碱药），非抗胆碱酯酶药。","E":"乙酰胆碱：为神经递质，非抗胆碱酯酶药。"},"id":"ph07_q08","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":8},{"type":"B","stem":"难逆性抗胆碱酯酶药","options":{"A":"碘解磷定","B":"有机磷酸酯类","C":"毒扁豆碱","D":"氨甲酰胆碱","E":"乙酰胆碱"},"answer":["B"],"rationale":"有机磷酸酯类与胆碱酯酶形成稳定的磷酰化酶、不易解离，属难逆性抑制。","expl":{"A":"碘解磷定：为胆碱酯酶复活药。","B":"有机磷酸酯类：正确，有机磷酸酯类为难逆性抗胆碱酯酶药。","C":"毒扁豆碱：为易逆性抗胆碱酯酶药。","D":"氨甲酰胆碱：为拟胆碱药，非抗胆碱酯酶药。","E":"乙酰胆碱：为神经递质，非抗胆碱酯酶药。"},"id":"ph07_q09","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":9},{"type":"B","stem":"胆碱酯酶复活药","options":{"A":"碘解磷定","B":"有机磷酸酯类","C":"毒扁豆碱","D":"氨甲酰胆碱","E":"乙酰胆碱"},"answer":["A"],"rationale":"碘解磷定为经典的胆碱酯酶复活药，可使磷酰化胆碱酯酶恢复活性。","expl":{"A":"碘解磷定：正确，碘解磷定属胆碱酯酶复活药。","B":"有机磷酸酯类：为难逆性抗胆碱酯酶药（毒物）。","C":"毒扁豆碱：为易逆性抗胆碱酯酶药。","D":"氨甲酰胆碱：为拟胆碱药。","E":"乙酰胆碱：为神经递质。"},"id":"ph07_q10","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":10},{"type":"B","stem":"加兰他敏用于","options":{"A":"有机磷酸酯中毒","B":"青光眼","C":"缓慢型心律失常","D":"脊髓前角灰白质炎","E":"胃肠平滑肌痉挛"},"answer":["D"],"rationale":"加兰他敏为易逆性抗胆碱酯酶药，可兴奋骨骼肌，用于脊髓灰质炎后遗症改善肌力。","expl":{"A":"有机磷酸酯中毒：加兰他敏抑酶会加重中毒，禁用。","B":"青光眼：青光眼用毒扁豆碱、毛果芸香碱等，非加兰他敏。","C":"缓慢型心律失常：非加兰他敏适应证。","D":"脊髓前角灰白质炎：正确，加兰他敏兴奋骨骼肌，用于该病后遗症。","E":"胃肠平滑肌痉挛：加兰他敏兴奋平滑肌，会加重痉挛，禁用。"},"id":"ph07_q11","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":11},{"type":"B","stem":"派姆用于","options":{"A":"有机磷酸酯中毒","B":"青光眼","C":"缓慢型心律失常","D":"脊髓前角灰白质炎","E":"胃肠平滑肌痉挛"},"answer":["A"],"rationale":"派姆（PAM）即碘解磷定，为胆碱酯酶复活药，专用于有机磷酸酯类中毒。","expl":{"A":"有机磷酸酯中毒：正确，PAM复活胆碱酯酶，用于有机磷酸酯中毒。","B":"青光眼：PAM不用于青光眼。","C":"缓慢型心律失常：PAM不用于心律失常。","D":"脊髓前角灰白质炎：该病用加兰他敏，非PAM。","E":"胃肠平滑肌痉挛：PAM无解痉作用。"},"id":"ph07_q12","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":12},{"type":"B","stem":"依色林用于","options":{"A":"有机磷酸酯中毒","B":"青光眼","C":"缓慢型心律失常","D":"脊髓前角灰白质炎","E":"胃肠平滑肌痉挛"},"answer":["B"],"rationale":"依色林（毒扁豆碱）抑制虹膜胆碱酯酶使乙酰胆碱蓄积，缩瞳降低眼压，用于青光眼。","expl":{"A":"有机磷酸酯中毒：依色林抑酶，加重中毒，禁用。","B":"青光眼：正确，依色林缩瞳降低眼压，用于青光眼。","C":"缓慢型心律失常：非依色林适应证。","D":"脊髓前角灰白质炎：该病用加兰他敏，非依色林。","E":"胃肠平滑肌痉挛：依色林兴奋平滑肌，加重痉挛，禁用。"},"id":"ph07_q13","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":13},{"type":"C","stem":"胆碱酯酶复活药","options":{"A":"阿托品","B":"解磷定","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"解磷定是胆碱酯酶复活药；阿托品为M受体阻断药，不能复活胆碱酯酶。","expl":{"A":"阿托品：为M受体阻断药，不复活胆碱酯酶。","B":"解磷定：正确，解磷定复活磷酰化胆碱酯酶。","C":"两者均是：阿托品无复活胆碱酯酶作用。","D":"两者均否：解磷定确能复活胆碱酯酶。"},"id":"ph07_q14","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":14},{"type":"C","stem":"解救有机磷酸酯类中毒","options":{"A":"阿托品","B":"解磷定","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"阿托品解除M样症状，解磷定复活胆碱酯酶并缓解肌颤，二者均为有机磷中毒解救药。","expl":{"A":"阿托品：可解除M样症状，是解毒药之一。","B":"解磷定：可复活胆碱酯酶，是解毒药之一。","C":"两者均是：正确，阿托品与解磷定均用于有机磷中毒解救。","D":"两者均否：二者均为有机磷中毒解救药。"},"id":"ph07_q15","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":15},{"type":"X","stem":"下列抗胆碱酯酶的药物是","options":{"A":"毒扁豆碱","B":"琥珀胆碱","C":"安贝氯铵","D":"丙胺太林","E":"后马托品"},"answer":["A","C"],"rationale":"毒扁豆碱、安贝氯铵均为易逆性抗胆碱酯酶药；其余为胆碱受体阻断药或去极化肌松药。","expl":{"A":"毒扁豆碱：正确，毒扁豆碱为易逆性抗胆碱酯酶药。","B":"琥珀胆碱：为去极化型N2受体阻断药（肌松药），非抗胆碱酯酶药。","C":"安贝氯铵：正确，安贝氯铵为易逆性抗胆碱酯酶药。","D":"丙胺太林：为M受体阻断药，非抗胆碱酯酶药。","E":"后马托品：为M受体阻断药，非抗胆碱酯酶药。"},"id":"ph07_q16","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":16},{"type":"X","stem":"用于治疗重症肌无力可选用的药物","options":{"A":"新斯的明","B":"筒箭毒碱","C":"安贝氯铵","D":"依酚氯铵","E":"吡啶斯的明"},"answer":["A","C","E"],"rationale":"新斯的明、安贝氯铵、吡啶斯的明均为易逆性抗胆碱酯酶药，可增强骨骼肌收缩力，用于重症肌无力。","expl":{"A":"新斯的明：正确，新斯的明对骨骼肌选择性高，治重症肌无力。","B":"筒箭毒碱：阻断N2受体使肌无力，禁用。","C":"安贝氯铵：正确，安贝氯铵抗胆碱酯酶，用于重症肌无力。","D":"依酚氯铵：作用短暂，主要用于诊断，不作常规治疗。","E":"吡啶斯的明：正确，吡啶斯的明（吡斯的明）用于重症肌无力。"},"id":"ph07_q17","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":17},{"type":"X","stem":"氯磷定的特点","options":{"A":"水溶性高","B":"溶液较稳定","C":"可肌内注射或静脉给药","D":"经肾排泄较慢","E":"副作用较碘解磷定小"},"answer":["A","B","C","E"],"rationale":"氯磷定水溶性高、溶液稳定，可肌注或静注，副作用较碘解磷定小，且经肾排泄较快。","expl":{"A":"水溶性高：正确，氯磷定水溶性高。","B":"溶液较稳定：正确，氯磷定溶液较碘解磷定稳定。","C":"可肌内注射或静脉给药：正确，氯磷定肌注、静注均可。","D":"经肾排泄较慢：错误，氯磷定经肾排泄较快。","E":"副作用较碘解磷定小：正确，氯磷定副作用较碘解磷定小。"},"id":"ph07_q18","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":18},{"type":"X","stem":"新斯的明可治疗","options":{"A":"重症肌无力","B":"术后肠胀气","C":"青光眼","D":"有机磷中毒","E":"阵发性室上性心动过速"},"answer":["A","B","E"],"rationale":"新斯的明兴奋骨骼肌治重症肌无力，兴奋胃肠平滑肌治术后肠胀气，兴奋迷走神经治室上性心动过速。","expl":{"A":"重症肌无力：正确，新斯的明增强骨骼肌力。","B":"术后肠胀气：正确，新斯的明促进肠蠕动，治术后腹气胀。","C":"青光眼：错误，新斯的明不易入眼，不用于青光眼。","D":"有机磷中毒：错误，新斯的明抑酶会加重有机磷中毒。","E":"阵发性室上性心动过速：正确，新斯的明兴奋迷走神经减慢心率。"},"id":"ph07_q19","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":19},{"type":"X","stem":"胆碱酯酶能与 ACh 结合的活性中心包括","options":{"A":"乙酰基","B":"带负电荷的阴离子部位","C":"带正电荷的阳离子部位","D":"酯解部位","E":"氨基部位"},"answer":["B","D"],"rationale":"胆碱酯酶的活性中心由带负电荷的阴离子部位与酯解部位组成，分别结合乙酰胆碱的阳离子头和酯键。","expl":{"A":"乙酰基：是乙酰胆碱的结构部分，不是酶活性中心部位。","B":"带负电荷的阴离子部位：正确，阴离子部位吸引乙酰胆碱的季铵阳离子头。","C":"带正电荷的阳离子部位：错误，活性中心为阴离子部位，非阳离子。","D":"酯解部位：正确，酯解部位水解乙酰胆碱的酯键。","E":"氨基部位：错误，活性中心不含“氨基部位”。"},"id":"ph07_q20","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":20},{"type":"A","stem":"下列药物中，新斯的明禁用于","options":{"A":"重症肌无力","B":"手术后腹气胀","C":"尿潴留","D":"支气管哮喘","E":"阵发性室上性心动过速"},"answer":["D"],"rationale":"新斯的明抑制胆碱酯酶使乙酰胆碱蓄积，可收缩支气管平滑肌并促进腺体分泌，故支气管哮喘患者禁用，答案为 D。","expl":{"A":"错误，重症肌无力正是新斯的明的首选适应证，可明显改善肌无力。","B":"错误，手术后腹气胀是其常用适应证，可促进肠蠕动恢复。","C":"错误，尿潴留可用新斯的明促进膀胱逼尿肌收缩而排尿。","D":"正确，乙酰胆碱蓄积会诱发支气管痉挛，故支气管哮喘患者禁用。","E":"错误，新斯的明可减慢心率，可用于阵发性室上性心动过速。"},"id":"ph07_q21","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":21},{"type":"A","stem":"有机磷酸酯类中毒出现骨骼肌纤维震颤，其机制是","options":{"A":"激动M受体","B":"激动N2受体","C":"激动α1受体","D":"兴奋中枢胆碱能神经","E":"直接抑制骨骼肌兴奋收缩偶联"},"answer":["B"],"rationale":"有机磷酸酯类抑制胆碱酯酶使乙酰胆碱在神经肌肉接头堆积，激动运动终板N2受体引起肌束颤动，属N样症状，故答案为 B。","expl":{"A":"错误，激动M受体产生的是瞳孔缩小、流涎、多汗、腹痛腹泻等M样症状。","B":"正确，乙酰胆碱蓄积激动N2受体，引起肌束颤动甚至肌无力、呼吸肌麻痹。","C":"错误，α1受体是肾上腺素受体，与胆碱能神经兴奋的肌颤无关。","D":"错误，中枢胆碱能神经过度兴奋表现为烦躁、惊厥，不是骨骼肌纤维震颤。","E":"错误，该机制不会导致肌束颤动，且有机磷中毒并非直接抑制兴奋收缩偶联。"},"id":"ph07_q22","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":22},{"type":"A","stem":"有机磷酸酯类中毒时间过久、胆碱酯酶已经老化时，碘解磷定的作用是","options":{"A":"仍可完全复活胆碱酯酶","B":"作用明显增强","C":"需加倍剂量才有效","D":"可预防胆碱酯酶老化","E":"基本无效"},"answer":["E"],"rationale":"磷酰化胆碱酯酶随时间延长发生脱烷基反应而老化，老化酶不能再被复活药水解，此时碘解磷定基本无效，故答案为 E。","expl":{"A":"错误，老化后的磷酰化胆碱酯酶结构稳定，复活药无法使其恢复活性。","B":"错误，中毒时间越久酶老化越多，复活药作用反而越差。","C":"错误，加倍剂量也不能水解已老化的磷酰化酶，只会增加不良反应。","D":"错误，复活药只能夺取尚未老化的磷酰基，不能阻止老化过程本身。","E":"正确，酶老化后碘解磷定失去作用，故有机磷中毒必须尽早用药。"},"id":"ph07_q23","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":23},{"type":"X","stem":"关于有机磷酸酯类中毒的解救，下列叙述正确的有","options":{"A":"阿托品可迅速解除M样症状","B":"阿托品不能解除骨骼肌震颤","C":"胆碱酯酶复活药可使已老化的胆碱酯酶复活","D":"应尽早、足量、反复应用阿托品","E":"胆碱酯酶复活药与阿托品合用可提高疗效"},"answer":["A","B","D","E"],"rationale":"阿托品阻断M受体迅速缓解M样症状，但对N2受体介导的肌束颤动无效；胆碱酯酶复活药对已老化的酶无效，故应尽早与阿托品合用并反复给药，故C错误。","expl":{"A":"正确，阿托品竞争性阻断M受体，迅速缓解瞳孔缩小、流涎、腹痛等M样症状。","B":"正确，肌束颤动由N2受体激动引起，阿托品不能阻断N2受体。","C":"错误，磷酰化胆碱酯酶老化后不能再被复活药水解，故复活药对老化酶无效。","D":"正确，阿托品作用短暂，须早期、足量、反复给药直至阿托品化。","E":"正确，两药合用可同时解除M样症状并恢复酶活性，疗效明显提高。"},"id":"ph07_q24","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":24}]},{"title":"第八章 胆碱受体阻断药","questions":[{"type":"A","stem":"治疗胆绞痛宜选用","options":{"A":"阿托品","B":"阿托品+哌替啶","C":"哌替啶","D":"阿司匹林","E":"溴丙胺太林"},"answer":["B"],"rationale":"胆绞痛由胆道平滑肌及括约肌痉挛引起，应合用阿托品类解痉药与哌替啶镇痛。","expl":{"A":"阿托品：单用阿托品镇痛有限，重度胆绞痛需联合镇痛药。","B":"阿托品+哌替啶：正确，阿托品解痉、哌替啶镇痛，合用治胆绞痛。","C":"哌替啶：单用哌替啶可致胆道括约肌痉挛，不利于胆绞痛。","D":"阿司匹林：阿司匹林对内脏绞痛无效。","E":"溴丙胺太林：可解痉但镇痛弱，重度胆绞痛需合用哌替啶。"},"id":"ph08_q01","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":1},{"type":"A","stem":"针对下列药物，麻醉前用药的最佳选择是","options":{"A":"毛果芸香碱","B":"氨甲酰胆碱","C":"东莨菪碱","D":"后马托品","E":"阿托品"},"answer":["C"],"rationale":"东莨菪碱抑制腺体分泌且具中枢镇静作用，是麻醉前给药的最佳选择；后马托品仅用于眼科散瞳。","expl":{"A":"毛果芸香碱：拟胆碱药，缩瞳促分泌，不能用于麻醉前给药。","B":"氨甲酰胆碱：拟胆碱药，兴奋平滑肌、促分泌，禁用于麻醉前给药。","C":"东莨菪碱：正确，东莨菪碱抑腺体分泌并镇静，宜作麻醉前给药。","D":"后马托品：仅用于眼科散瞳检查，不作麻醉前给药。","E":"阿托品：亦可用于麻醉前给药，但无镇静作用，非最佳。"},"id":"ph08_q02","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":2},{"type":"A","stem":"阿托品抢救有机磷酯类中毒时能","options":{"A":"复活AchE","B":"促进Ach的排泄","C":"阻断M受体，解除M样作用","D":"阻断M受体和N2受体","E":"与有机磷结合成无毒产物而解毒"},"answer":["C"],"rationale":"阿托品通过阻断M受体解除有机磷中毒的M样症状（流涎、缩瞳、支气管痉挛等）；复活胆碱酯酶的是解磷定（氯解磷定），并非阿托品。","expl":{"A":"错误，复活胆碱酯酶的是解磷定（氯解磷定），阿托品无此作用。","B":"错误，阿托品不促进乙酰胆碱的排泄。","C":"正确，阿托品阻断M受体，解除有机磷中毒的M样症状。","D":"错误，治疗量阿托品主要阻断M受体，对N2受体无明显阻断作用。","E":"错误，与有机磷结合成无毒产物是肟类复活药（解磷定）的作用，阿托品不与有机磷结合。"},"id":"ph08_q03","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":3},{"type":"A","stem":"感染性休克用阿托品治疗时，哪种情况不能用","options":{"A":"血容量已补足","B":"酸中毒已纠正","C":"心率60次/分钟以下","D":"体温39℃以上","E":"房室传导阻滞"},"answer":["D"],"rationale":"感染性休克用阿托品时，体温过高（39℃以上）时禁用；补足血容量是应用前提而非禁忌。","expl":{"A":"血容量已补足：错误，补足血容量是使用阿托品的前提，并非禁忌。","B":"酸中毒已纠正：纠正酸中毒是治疗所需，非禁忌。","C":"心率60次/分钟以下：心率过慢时阿托品可增快心率，非禁忌。","D":"体温39℃以上：正确，体温过高时阿托品抑制散热，属禁忌。","E":"房室传导阻滞：阿托品可改善房室传导，非禁忌。"},"id":"ph08_q04","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":4},{"type":"A","stem":"治疗量阿托品一般不出现","options":{"A":"口干、乏汗","B":"皮肤潮红","C":"心率加快","D":"畏光，视力模糊","E":"烦躁不安，呼吸加快"},"answer":["E"],"rationale":"烦躁不安、呼吸加快属阿托品中毒表现，治疗量一般不出现；口干、心率加快治疗量即可出现。","expl":{"A":"口干、乏汗：治疗量阿托品即可引起口干、乏汗。","B":"皮肤潮红：较大剂量才引起皮肤潮红，治疗量一般不明显。","C":"心率加快：治疗量阿托品即可使心率轻度加快。","D":"畏光，视力模糊：治疗量散瞳可致畏光、视近物模糊。","E":"烦躁不安，呼吸加快：正确，此为中毒剂量表现，治疗量一般不出现。"},"id":"ph08_q05","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":5},{"type":"A","stem":"阿托品禁用于","options":{"A":"虹膜睫状体炎","B":"验光配镜","C":"胆绞痛","D":"青光眼","E":"感染性休克"},"answer":["D"],"rationale":"阿托品散瞳可升高眼压，故青光眼禁用；胆绞痛是阿托品的适应证而非禁忌。","expl":{"A":"虹膜睫状体炎：阿托品散瞳防止粘连，为适应证。","B":"验光配镜：儿童验光可用阿托品散瞳。","C":"胆绞痛：胆绞痛可用阿托品解痉，非禁忌。","D":"青光眼：正确，阿托品散瞳升高眼压，青光眼禁用。","E":"感染性休克：阿托品可用于感染性休克，非禁忌。"},"id":"ph08_q06","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":6},{"type":"A","stem":"常用于抗感染性休克的药是","options":{"A":"山莨菪碱","B":"溴丙胺太林","C":"贝那替秦","D":"哌仑西平","E":"东莨菪碱"},"answer":["A"],"rationale":"山莨菪碱改善微循环作用强、副作用小，常用于抗感染性休克；哌仑西平为治溃疡药。","expl":{"A":"山莨菪碱：正确，山莨菪碱改善微循环，常用于感染性休克。","B":"溴丙胺太林：用于胃肠痉挛、溃疡，不作抗休克。","C":"贝那替秦：用于伴焦虑的溃疡病，不作抗休克。","D":"哌仑西平：为M1受体阻断药，用于消化性溃疡，非抗休克药。","E":"东莨菪碱：亦可用于抗休克，但山莨菪碱更为常用。"},"id":"ph08_q07","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":7},{"type":"A","stem":"具有安定作用，适用于兼有焦虑症溃疡病人的是","options":{"A":"山莨菪碱","B":"溴丙胺太林","C":"贝那替秦","D":"哌仑西平","E":"东莨菪碱"},"answer":["C"],"rationale":"贝那替秦（胃复康）为叔胺类，兼具解痉抑酸与中枢安定作用，适用于伴焦虑症的溃疡病。","expl":{"A":"山莨菪碱：不易透过血脑屏障，无中枢安定作用。","B":"溴丙胺太林：为季铵类，口服难吸收，无中枢安定作用。","C":"贝那替秦：正确，贝那替秦有中枢安定作用，宜用于焦虑症溃疡。","D":"哌仑西平：为M1阻断药抑酸，无中枢安定作用。","E":"东莨菪碱：有中枢作用但非用于溃疡病。"},"id":"ph08_q08","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":8},{"type":"A","stem":"阿托品对眼的作用是","options":{"A":"扩瞳，视近物清楚","B":"扩瞳，调节痉挛","C":"扩瞳，降低眼内压","D":"扩瞳，调节麻痹","E":"缩瞳，调节麻痹"},"answer":["D"],"rationale":"阿托品阻断虹膜括约肌和睫状肌M受体，使瞳孔散大、调节麻痹。","expl":{"A":"扩瞳，视近物清楚：调节麻痹时视近物模糊，非清楚。","B":"扩瞳，调节痉挛：阿托品致调节麻痹，非痉挛。","C":"扩瞳，降低眼内压：阿托品散瞳使房水回流受阻，眼压升高。","D":"扩瞳，调节麻痹：正确，阿托品散瞳并使睫状肌麻痹。","E":"缩瞳，调节麻痹：阿托品散瞳，非缩瞳。"},"id":"ph08_q09","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":9},{"type":"A","stem":"阿托品最适于治疗的休克是","options":{"A":"失血性休克","B":"过敏性休克","C":"神经原性休克","D":"感染性休克","E":"心源性休克"},"answer":["D"],"rationale":"阿托品大剂量能解除小血管痉挛、改善微循环，最适于感染性休克。","expl":{"A":"失血性休克：以补充血容量为主，不宜用阿托品。","B":"过敏性休克：首选肾上腺素，非阿托品。","C":"神经原性休克：非阿托品最适适应证。","D":"感染性休克：正确，阿托品解除微血管痉挛，最适于感染性休克。","E":"心源性休克：非阿托品适应证。"},"id":"ph08_q10","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":10},{"type":"A","stem":"治疗量的阿托品可产生","options":{"A":"血压升高","B":"眼内压降低","C":"胃肠道平滑肌松驰","D":"镇静","E":"腺体分泌增加"},"answer":["C"],"rationale":"治疗量阿托品阻断胃肠M受体，松弛胃肠平滑肌，并抑制腺体分泌。","expl":{"A":"血压升高：治疗量阿托品对血压无明显影响。","B":"眼内压降低：阿托品散瞳使眼内压升高，非降低。","C":"胃肠道平滑肌松驰：正确，治疗量阿托品松弛胃肠平滑肌。","D":"镇静：治疗量阿托品无镇静，大剂量才兴奋中枢。","E":"腺体分泌增加：阿托品抑制腺体分泌，非增加。"},"id":"ph08_q11","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":11},{"type":"A","stem":"阿托品对有机磷酸酯类中毒症状无效的是","options":{"A":"流涎","B":"瞳孔缩小","C":"大小便失禁","D":"肌震颤","E":"腹痛"},"answer":["D"],"rationale":"肌震颤由运动终板N2受体过度兴奋所致，阿托品不阻断N2受体，故无效。","expl":{"A":"流涎：为M样症状，阿托品可解除。","B":"瞳孔缩小：为M样症状，阿托品可解除。","C":"大小便失禁：为M样症状，阿托品可解除。","D":"肌震颤：正确，肌震颤为N样症状，阿托品无效。","E":"腹痛：为M样症状，阿托品可解除。"},"id":"ph08_q12","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":12},{"type":"A","stem":"对于山莨菪碱的描述，错误的是","options":{"A":"可用于震颤麻痹症","B":"可用于感染性休克","C":"可用于内脏平滑肌绞痛","D":"副作用与阿托品相似","E":"其人工合成品为654-2"},"answer":["A"],"rationale":"山莨菪碱脂溶性低、难透过血脑屏障，无中枢抗震颤麻痹作用，故A项描述错误。","expl":{"A":"可用于震颤麻痹症：错误（答案），山莨菪碱难入脑，不能治震颤麻痹。","B":"可用于感染性休克：山莨菪碱改善微循环，可用于感染性休克，表述正确。","C":"可用于内脏平滑肌绞痛：山莨菪碱可解痉，用于内脏绞痛，表述正确。","D":"副作用与阿托品相似：山莨菪碱副作用与阿托品相似但较轻，表述正确。","E":"其人工合成品为654-2：山莨菪碱人工合成品为654-2，表述正确。"},"id":"ph08_q13","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":13},{"type":"A","stem":"与阿托品相比，后马托品对眼的作用特点是","options":{"A":"作用强","B":"扩瞳持久","C":"调节麻痹充分","D":"调节麻痹作用高峰出现较慢","E":"调节麻痹作用维持时间短"},"answer":["E"],"rationale":"后马托品扩瞳与调节麻痹作用较阿托品出现快、维持时间短，适于一般检查。","expl":{"A":"作用强：后马托品作用较阿托品弱。","B":"扩瞳持久：后马托品扩瞳维持时间短。","C":"调节麻痹充分：后马托品调节麻痹不如阿托品充分。","D":"调节麻痹作用高峰出现较慢：后马托品作用出现较快。","E":"调节麻痹作用维持时间短：正确，后马托品作用短暂，为检查用。"},"id":"ph08_q14","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":14},{"type":"A","stem":"对于胃康复，描述正确的是","options":{"A":"属季铵类","B":"具解痉及抑制胃酸分泌作用","C":"口服难吸收","D":"无中枢作用","E":"不适宜于兼有焦虑症的溃疡病病人"},"answer":["B"],"rationale":"胃复康（贝那替秦）为叔胺类，有解痉和抑制胃酸分泌作用，且口服易吸收、有中枢作用。","expl":{"A":"属季铵类：错误，胃复康为叔胺类。","B":"具解痉及抑制胃酸分泌作用：正确，胃复康兼有解痉与抑酸作用。","C":"口服难吸收：错误，胃复康为叔胺类，口服易吸收。","D":"无中枢作用：错误，胃复康有中枢安定作用。","E":"不适宜于兼有焦虑症的溃疡病病人：错误，胃复康正适于焦虑症溃疡病人。"},"id":"ph08_q15","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":15},{"type":"A","stem":"有关东莨菪碱的叙述，错误的是","options":{"A":"可抑制中枢","B":"具抗震颤麻痹作用","C":"对心血管作用较弱","D":"增加唾液分泌","E":"抗晕动病"},"answer":["D"],"rationale":"东莨菪碱抑制腺体分泌、减少唾液，故D项“增加唾液分泌”表述错误。","expl":{"A":"可抑制中枢：东莨菪碱有中枢抑制作用，表述正确。","B":"具抗震颤麻痹作用：东莨菪碱有抗震颤麻痹作用，表述正确。","C":"对心血管作用较弱：东莨菪碱对心血管作用较弱，表述正确。","D":"增加唾液分泌：错误（答案），东莨菪碱抑制腺体分泌，减少唾液。","E":"抗晕动病：东莨菪碱可防晕止吐，表述正确。"},"id":"ph08_q16","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":16},{"type":"A","stem":"对下列哪个部位平滑肌痉挛，阿托品的作用最好？","options":{"A":"支气管","B":"胃肠道","C":"胆道","D":"输尿管","E":"子宫"},"answer":["B"],"rationale":"阿托品对胃肠道平滑肌解痉作用最强，对胆道、输尿管、支气管等作用较弱。","expl":{"A":"支气管：阿托品对支气管解痉作用弱。","B":"胃肠道：正确，阿托品对胃肠平滑肌解痉作用最显著。","C":"胆道：对胆道作用较弱，胆绞痛常需合用哌替啶。","D":"输尿管：对输尿管作用弱。","E":"子宫：对子宫平滑肌作用很弱。"},"id":"ph08_q17","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":17},{"type":"A","stem":"各器官对阿托品阻断作用的敏感性不同，最先敏感者是","options":{"A":"心脏","B":"中枢","C":"腺体","D":"眼睛","E":"胃肠平滑肌"},"answer":["C"],"rationale":"腺体对阿托品最敏感，小剂量即可抑制分泌；眼、胃肠、心脏等敏感性依次较低。","expl":{"A":"心脏：心脏对阿托品敏感性低于腺体。","B":"中枢：治疗量对中枢影响小，敏感性低。","C":"腺体：正确，腺体对阿托品最敏感。","D":"眼睛：眼对阿托品敏感性低于腺体。","E":"胃肠平滑肌：胃肠平滑肌敏感性低于腺体。"},"id":"ph08_q18","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":18},{"type":"B","stem":"治疗感染性休克","options":{"A":"东莨菪碱","B":"山莨菪碱","C":"托吡卡胺","D":"丙胺太林","E":"依色林"},"answer":["B"],"rationale":"山莨菪碱改善微循环作用强、副作用小，为抗感染性休克常用药。","expl":{"A":"东莨菪碱：亦用于抗休克，但山莨菪碱更常用。","B":"山莨菪碱：正确，山莨菪碱改善微循环，治感染性休克。","C":"托吡卡胺：为散瞳药，用于眼底检查。","D":"丙胺太林：用于胃肠痉挛、溃疡。","E":"依色林：为拟胆碱药，不用于抗休克。"},"id":"ph08_q19","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":19},{"type":"B","stem":"用于麻醉前给药","options":{"A":"东莨菪碱","B":"山莨菪碱","C":"托吡卡胺","D":"丙胺太林","E":"依色林"},"answer":["A"],"rationale":"东莨菪碱抑制腺体分泌并有中枢镇静，常用于麻醉前给药。","expl":{"A":"东莨菪碱：正确，东莨菪碱抑分泌兼镇静，用于麻醉前给药。","B":"山莨菪碱：主要用于抗感染性休克、内脏绞痛。","C":"托吡卡胺：用于眼底检查散瞳。","D":"丙胺太林：用于溃疡、胃肠痉挛。","E":"依色林：拟胆碱药，不用于麻醉前给药。"},"id":"ph08_q20","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":20},{"type":"B","stem":"治疗青光眼","options":{"A":"东莨菪碱","B":"山莨菪碱","C":"托吡卡胺","D":"丙胺太林","E":"依色林"},"answer":["E"],"rationale":"依色林（毒扁豆碱）抑酶缩瞳、降低眼压，用于青光眼。","expl":{"A":"东莨菪碱：散瞳升高眼压，禁用于青光眼。","B":"山莨菪碱：散瞳升眼压，禁用于青光眼。","C":"托吡卡胺：散瞳药，禁用于青光眼。","D":"丙胺太林：非青光眼用药。","E":"依色林：正确，依色林缩瞳降眼压，用于青光眼。"},"id":"ph08_q21","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":21},{"type":"B","stem":"用于伴胃酸过多的溃疡病","options":{"A":"东莨菪碱","B":"山莨菪碱","C":"托吡卡胺","D":"丙胺太林","E":"依色林"},"answer":["D"],"rationale":"丙胺太林（普鲁本辛）为季铵类M阻断药，解痉并抑制胃酸分泌，用于溃疡病。","expl":{"A":"东莨菪碱：中枢作用强，不作溃疡病常规用药。","B":"山莨菪碱：主要用于抗休克、内脏绞痛。","C":"托吡卡胺：散瞳药，用于眼底检查。","D":"丙胺太林：正确，丙胺太林解痉抑酸，用于溃疡病。","E":"依色林：拟胆碱药，促进分泌，不用于溃疡病。"},"id":"ph08_q22","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":22},{"type":"B","stem":"用于眼底检查","options":{"A":"东莨菪碱","B":"山莨菪碱","C":"托吡卡胺","D":"丙胺太林","E":"依色林"},"answer":["C"],"rationale":"托吡卡胺散瞳作用快而短，是眼底检查常用散瞳药。","expl":{"A":"东莨菪碱：作用时间长，不作眼底检查首选。","B":"山莨菪碱：散瞳弱，不作眼底检查。","C":"托吡卡胺：正确，托吡卡胺散瞳快而短暂，用于眼底检查。","D":"丙胺太林：无散瞳用途。","E":"依色林：缩瞳药，不用于眼底检查散瞳。"},"id":"ph08_q23","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":23},{"type":"C","stem":"扩瞳","options":{"A":"毛果芸香碱","B":"阿托品","C":"两者均可","D":"两者均不可"},"answer":["B"],"rationale":"阿托品阻断虹膜括约肌M受体而扩瞳；毛果芸香碱激动M受体则缩瞳。","expl":{"A":"毛果芸香碱：缩瞳，非扩瞳。","B":"阿托品：正确，阿托品散瞳。","C":"两者均可：毛果芸香碱不扩瞳。","D":"两者均不可：阿托品可扩瞳。"},"id":"ph08_q24","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":24},{"type":"C","stem":"缩瞳","options":{"A":"毛果芸香碱","B":"阿托品","C":"两者均可","D":"两者均不可"},"answer":["A"],"rationale":"毛果芸香碱激动虹膜括约肌M受体而缩瞳；阿托品阻断M受体则散瞳。","expl":{"A":"毛果芸香碱：正确，毛果芸香碱缩瞳。","B":"阿托品：散瞳，不缩瞳。","C":"两者均可：阿托品不缩瞳。","D":"两者均不可：毛果芸香碱可缩瞳。"},"id":"ph08_q25","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":25},{"type":"C","stem":"影响视物","options":{"A":"毛果芸香碱","B":"阿托品","C":"两者均可","D":"两者均不可"},"answer":["C"],"rationale":"毛果芸香碱致调节痉挛、视远物模糊，阿托品致调节麻痹、视近物模糊，二者均影响视物。","expl":{"A":"毛果芸香碱：可致视远物模糊。","B":"阿托品：可致视近物模糊。","C":"两者均可：正确，二者均影响视物。","D":"两者均不可：二者均影响视物。"},"id":"ph08_q26","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":26},{"type":"C","stem":"调节麻痹","options":{"A":"毛果芸香碱","B":"阿托品","C":"两者均可","D":"两者均不可"},"answer":["B"],"rationale":"阿托品阻断睫状肌M受体致调节麻痹；毛果芸香碱则引起调节痉挛。","expl":{"A":"毛果芸香碱：致调节痉挛，非麻痹。","B":"阿托品：正确，阿托品致调节麻痹。","C":"两者均可：毛果芸香碱不致调节麻痹。","D":"两者均不可：阿托品可致调节麻痹。"},"id":"ph08_q27","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":27},{"type":"C","stem":"调节痉挛","options":{"A":"毛果芸香碱","B":"阿托品","C":"两者均可","D":"两者均不可"},"answer":["A"],"rationale":"毛果芸香碱激动睫状肌M受体致调节痉挛；阿托品则引起调节麻痹。","expl":{"A":"毛果芸香碱：正确，毛果芸香碱致调节痉挛。","B":"阿托品：致调节麻痹，非痉挛。","C":"两者均可：阿托品不致调节痉挛。","D":"两者均不可：毛果芸香碱可致调节痉挛。"},"id":"ph08_q28","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":28},{"type":"X","stem":"与阿托品相比，东莨菪碱有如下特点","options":{"A":"抑制中枢","B":"扩瞳、调节麻痹作用较弱","C":"抑制腺体分泌作用较强","D":"对心、血管系统作用较强","E":"抑制前庭神经内耳功能"},"answer":["A","C","E"],"rationale":"东莨菪碱抑制中枢、抑制腺体分泌强、抗晕动，但对心血管作用弱、扩瞳调节麻痹作用较强。","expl":{"A":"抑制中枢：正确，东莨菪碱有中枢抑制作用。","B":"扩瞳、调节麻痹作用较弱：错误，东莨菪碱扩瞳、调节麻痹作用较强。","C":"抑制腺体分泌作用较强：正确，东莨菪碱抑制腺体分泌比阿托品强。","D":"对心、血管系统作用较强：错误，东莨菪碱对心血管作用较弱。","E":"抑制前庭神经内耳功能：正确，东莨菪碱抑制前庭功能而抗晕动。"},"id":"ph08_q29","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":29},{"type":"X","stem":"阿托品滴眼后可产生下列效应","options":{"A":"扩瞳","B":"调节痉挛","C":"眼内压升高","D":"调节麻痹","E":"视近物清楚"},"answer":["A","C","D"],"rationale":"阿托品滴眼后扩瞳、调节麻痹，并使房水回流受阻、眼内压升高，视近物模糊。","expl":{"A":"扩瞳：正确，阿托品阻断虹膜括约肌M受体而扩瞳。","B":"调节痉挛：错误，阿托品致调节麻痹，非痉挛。","C":"眼内压升高：正确，扩瞳使房水回流受阻，眼压升高。","D":"调节麻痹：正确，阿托品麻痹睫状肌。","E":"视近物清楚：错误，调节麻痹时视近物模糊。"},"id":"ph08_q30","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":30},{"type":"X","stem":"患有青光眼的病人禁用的药物有","options":{"A":"东莨菪碱","B":"阿托品","C":"山莨菪碱","D":"后马托品","E":"托吡卡胺"},"answer":["A","B","C","D","E"],"rationale":"所列均为M受体阻断药，可散瞳升高眼压，青光眼均禁用。","expl":{"A":"东莨菪碱：正确，东莨菪碱散瞳升眼压，青光眼禁用。","B":"阿托品：正确，阿托品散瞳升眼压，青光眼禁用。","C":"山莨菪碱：正确，山莨菪碱散瞳升眼压，青光眼禁用。","D":"后马托品：正确，后马托品散瞳升眼压，青光眼禁用。","E":"托吡卡胺：正确，托吡卡胺散瞳升眼压，青光眼禁用。"},"id":"ph08_q31","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":31},{"type":"X","stem":"阿托品能解除有机磷酸酯类中毒时的哪些症状？","options":{"A":"M 样作用","B":"神经节兴奋症状","C":"肌颤","D":"部分中枢症状","E":"AChE 抑制症状"},"answer":["A","B","D"],"rationale":"阿托品阻断M受体解除M样症状和部分中枢症状，大剂量可阻断N1受体缓解神经节兴奋，但不能解除肌颤。","expl":{"A":"M样作用：正确，阿托品阻断M受体，解除M样症状。","B":"神经节兴奋症状：正确，大剂量阿托品阻断N1受体，缓解神经节兴奋。","C":"肌颤：错误，肌颤由N2受体介导，阿托品不能解除。","D":"部分中枢症状：正确，阿托品可缓解部分中枢症状。","E":"AChE抑制症状：错误，AChE抑制是中毒原因，阿托品不能恢复酶活性。"},"id":"ph08_q32","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":32},{"type":"X","stem":"与阿托品相比，山莨菪碱的特点有","options":{"A":"易穿透血脑屏障","B":"抑制分泌和扩瞳作用弱","C":"解痉作用相似或略弱","D":"改善微循环作用较强","E":"毒性较大"},"answer":["B","C","D"],"rationale":"山莨菪碱不易透过血脑屏障，抑制分泌和扩瞳弱，解痉相似或略弱，改善微循环强，毒性小。","expl":{"A":"易穿透血脑屏障：错误，山莨菪碱难透过血脑屏障，中枢作用弱。","B":"抑制分泌和扩瞳作用弱：正确，山莨菪碱抑制分泌、扩瞳较阿托品弱。","C":"解痉作用相似或略弱：正确，山莨菪碱解痉作用与阿托品相似或略弱。","D":"改善微循环作用较强：正确，山莨菪碱改善微循环作用较强。","E":"毒性较大：错误，山莨菪碱毒性较阿托品小。"},"id":"ph08_q33","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":33},{"type":"A","stem":"治疗量阿托品对心率的影响是","options":{"A":"明显减慢","B":"无影响","C":"明显加快","D":"轻度减慢，较大剂量则加快","E":"先加快后减慢"},"answer":["D"],"rationale":"治疗量阿托品阻断突触前膜M1受体使乙酰胆碱释放增多，可使部分病人心率轻度减慢；较大剂量阻断窦房结M2受体，解除迷走神经抑制而使心率加快，故答案为 D。","expl":{"A":"错误，明显减慢并不符合治疗量阿托品的实际表现，其减慢程度较轻。","B":"错误，阿托品对心率确有影响，只是随剂量不同表现不同。","C":"错误，明显加快见于较大剂量，治疗量一般不出现明显心动过速。","D":"正确，治疗量可轻度减慢心率，较大剂量阻断M2受体后心率明显加快。","E":"错误，阿托品对心率的作用不表现为先快后慢的顺序。"},"id":"ph08_q34","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":34},{"type":"A","stem":"筒箭毒碱过量引起呼吸肌麻痹时，可选的解救药是","options":{"A":"阿托品","B":"新斯的明","C":"碘解磷定","D":"肾上腺素","E":"尼可刹米"},"answer":["B"],"rationale":"筒箭毒碱为非去极化型N2受体阻断药，新斯的明抑制胆碱酯酶提高接头处乙酰胆碱浓度，可竞争性拮抗其肌松作用，故答案为 B。","expl":{"A":"错误，阿托品阻断M受体，对N2受体介导的神经肌肉阻滞没有拮抗作用。","B":"正确，新斯的明增加乙酰胆碱浓度，可竞争性逆转非去极化肌松药的阻滞。","C":"错误，碘解磷定用于有机磷中毒复活胆碱酯酶，对肌松药过量无效。","D":"错误，肾上腺素不能解除神经肌肉接头的竞争性阻滞，无解救价值。","E":"错误，尼可刹米是呼吸兴奋药，只能短暂兴奋呼吸中枢，不能解除阻滞。"},"id":"ph08_q35","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":35},{"type":"A","stem":"琥珀胆碱最典型的不良反应是","options":{"A":"术后肌痛","B":"锥体外系反应","C":"耳毒性","D":"骨髓抑制","E":"牙龈增生"},"answer":["A"],"rationale":"琥珀胆碱为去极化型肌松药，用药后肌束成束收缩可致术后肌痛，多见于青年和短小手术后，故答案为 A。","expl":{"A":"正确，药物引起肌纤维成束收缩造成肌纤维损伤，术后出现肩背、腹部肌痛。","B":"错误，锥体外系反应见于吩噻嗪类抗精神病药，与琥珀胆碱无关。","C":"错误，耳毒性是氨基糖苷类抗生素的典型不良反应。","D":"错误，骨髓抑制多见于抗肿瘤药和氯霉素，不是琥珀胆碱的不良反应。","E":"错误，牙龈增生见于苯妥英钠和硝苯地平长期应用。"},"id":"ph08_q36","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":36}]},{"title":"第九章 肾上腺素受体激动药","questions":[{"type":"A","stem":"去甲肾上腺素治疗上消化道出血时的给药方法是","options":{"A":"静脉滴注","B":"皮下注射","C":"肌肉注射","D":"口服稀释液","E":"以上都不是"},"answer":["D"],"rationale":"去甲肾上腺素口服后收缩胃肠黏膜血管，达局部止血目的。","expl":{"A":"错误，静脉滴注用于抗休克升高血压，非上消化道出血的局部给药法。","B":"错误，皮下注射会引起注射部位血管强烈收缩而缺血坏死。","C":"错误，肌内注射同样引起局部缺血坏死，不宜使用。","D":"正确，口服稀释液使局部黏膜血管收缩而止血。","E":"错误，D为正确的给药方法。"},"id":"ph09_q01","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":1},{"type":"A","stem":"具有明显舒张肾血管，增加肾血流的药物是","options":{"A":"肾上腺素","B":"异丙肾上腺素","C":"麻黄碱","D":"多巴胺","E":"去甲肾上腺素"},"answer":["D"],"rationale":"多巴胺激动肾血管D1受体，扩张肾血管、增加肾血流量。","expl":{"A":"错误，肾上腺素以激动α受体收缩肾血管为主。","B":"错误，异丙肾上腺素主要扩张骨骼肌血管，对肾血管作用弱。","C":"错误，麻黄碱主要通过促递质释放升压，不直接舒张肾血管。","D":"正确，多巴胺激动肾D1受体，舒张肾血管、增加肾血流量。","E":"错误，去甲肾上腺素强烈收缩肾血管，减少肾血流。"},"id":"ph09_q02","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":2},{"type":"A","stem":"防治硬膜外麻醉引起的低血压宜先用","options":{"A":"肾上腺素","B":"去甲肾上腺素","C":"麻黄碱","D":"多巴胺","E":"异丙肾上腺素"},"answer":["C"],"rationale":"麻黄碱升压作用温和持久、可肌注给药，是防治硬膜外麻醉所致低血压的常用药。","expl":{"A":"错误，肾上腺素作用强而短暂，易致心律失常，不宜用于此。","B":"错误，去甲肾上腺素强烈收缩血管且需静滴，不适用。","C":"正确，麻黄碱升压温和持久，可皮下或肌注，适用于麻醉后低血压。","D":"错误，多巴胺主要增加肾血流，升压作用有限。","E":"错误，异丙肾上腺素扩张血管、增快心率，不用于升压。"},"id":"ph09_q03","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":3},{"type":"A","stem":"非儿茶酚胺类的药物是","options":{"A":"多巴胺","B":"异丙肾上腺素","C":"肾上腺素","D":"麻黄碱","E":"去甲肾上腺素"},"answer":["D"],"rationale":"麻黄碱化学结构无儿茶酚（邻苯二酚）核，属于非儿茶酚胺类药物。","expl":{"A":"错误，多巴胺属儿茶酚胺类。","B":"错误，异丙肾上腺素属儿茶酚胺类。","C":"错误，肾上腺素属儿茶酚胺类。","D":"正确，麻黄碱不含儿茶酚核，为非儿茶酚胺类，故可口服。","E":"错误，去甲肾上腺素属儿茶酚胺类。"},"id":"ph09_q04","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":4},{"type":"A","stem":"去甲肾上腺素与肾上腺素的下列哪项作用不同","options":{"A":"正性肌力作用","B":"兴奋 β 受体","C":"兴奋 α 受体","D":"对心率的影响","E":"被MAO 和COMT 灭活"},"answer":["D"],"rationale":"去甲肾上腺素整体因升压反射使心率减慢，肾上腺素兴奋心脏β1受体使心率加快，二者对心率影响不同。","expl":{"A":"错误，二者均有正性肌力作用。","B":"错误，二者均可兴奋β受体（主要为β1）。","C":"错误，二者均可兴奋α受体。","D":"正确，去甲肾上腺素反射性减慢心率，肾上腺素使心率加快。","E":"错误，二者均可被MAO和COMT灭活。"},"id":"ph09_q05","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":5},{"type":"A","stem":"去甲肾上腺素扩张冠状血管主要是由于","options":{"A":"激动 β2 受体","B":"激动 M 胆碱受体","C":"使心肌代谢产物增加","D":"激动 α2 受体","E":"以上都不是"},"answer":["C"],"rationale":"去甲肾上腺素收缩血管升高血压，使心肌代谢产物（如腺苷）增多，继发扩张冠脉。","expl":{"A":"错误，去甲肾上腺素对β2受体作用很弱。","B":"错误，去甲肾上腺素不激动M胆碱受体。","C":"正确，心肌代谢产物增加引起冠脉继发性扩张。","D":"错误，激动α2受体主要抑制递质释放，非直接扩冠脉。","E":"错误，C为正确答案。"},"id":"ph09_q06","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":6},{"type":"A","stem":"治疗房室传导阻滞的药物是","options":{"A":"肾上腺素","B":"去甲肾上腺素","C":"异丙肾上腺素","D":"阿拉明","E":"普萘洛尔"},"answer":["C"],"rationale":"异丙肾上腺素激动心脏β1受体，加快房室传导，用于治疗房室传导阻滞。","expl":{"A":"错误，肾上腺素虽兴奋心脏但易致心律失常，非房室阻滞首选。","B":"错误，去甲肾上腺素反射性减慢心率，不宜用于房室传导阻滞。","C":"正确，异丙肾上腺素兴奋β1受体，加速房室传导，用于房室传导阻滞。","D":"错误，阿拉明（间羟胺）为升压药，不改善房室传导。","E":"错误，普萘洛尔阻断β受体，反会加重房室传导阻滞。"},"id":"ph09_q07","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":7},{"type":"A","stem":"肾上腺素对血管作用的叙述，错误的是","options":{"A":"皮肤、粘膜血管收缩强","B":"微弱收缩脑和肺血管","C":"肾血管扩张","D":"骨骼肌血管扩张","E":"舒张冠状血管"},"answer":["C"],"rationale":"肾上腺素激动α受体使肾血管收缩，故“肾血管扩张”的说法错误。","expl":{"A":"错误，皮肤、黏膜血管在α受体作用下强烈收缩，该项叙述正确。","B":"错误，肾上腺素对脑、肺血管仅微弱收缩，该项叙述正确。","C":"正确，肾上腺素使肾血管收缩而非扩张，此项表述错误。","D":"错误，骨骼肌血管以β2受体为主，肾上腺素使之扩张，该项叙述正确。","E":"错误，肾上腺素经心肌代谢产物增多可舒张冠脉，该项叙述正确。"},"id":"ph09_q08","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":8},{"type":"A","stem":"异丙肾上腺素不具有肾上腺素的哪项作用","options":{"A":"松弛支气管平滑肌","B":"兴奋 β2 受体","C":"抑制组胺等过敏介质释放","D":"促进 CAMP 的产生","E":"收缩支气管粘膜血管"},"answer":["E"],"rationale":"异丙肾上腺素无α受体激动作用，不能收缩支气管黏膜血管，故此项为其所不具有。","expl":{"A":"错误，异丙肾上腺素激动β2受体可松弛支气管平滑肌，与肾上腺素相同。","B":"错误，二者均可兴奋β2受体。","C":"错误，二者均能抑制组胺等过敏介质释放。","D":"错误，二者激动β受体均促进cAMP产生。","E":"正确，异丙肾上腺素不激动α受体，不能收缩支气管黏膜血管。"},"id":"ph09_q09","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":9},{"type":"A","stem":"大剂量肾上腺素静注，血压的变化是","options":{"A":"收缩压和舒张压均缓慢、持久升高","B":"收缩压上升，舒张压不变或稍下降","C":"收缩压上升，舒张压上升，脉压变小","D":"收缩压上升，舒张压上升不明显，脉压增大","E":"收缩压上升，舒张压下降，脉压增大"},"answer":["C"],"rationale":"大剂量时α受体兴奋占优势，外周阻力显著升高，收缩压和舒张压均上升，脉压变小。","expl":{"A":"错误，肾上腺素作用快而短暂，并非缓慢持久。","B":"错误，大剂量时α受体占优势，舒张压也上升。","C":"正确，收缩压与舒张压均升高，且舒张压升高明显使脉压变小。","D":"错误，大剂量时舒张压升高明显，脉压变小而非增大。","E":"错误，大剂量时舒张压上升而非下降。"},"id":"ph09_q10","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":10},{"type":"A","stem":"小剂量去甲肾上腺素静脉滴注，血压变化是","options":{"A":"收缩压和舒张压均缓慢、持久升高","B":"收缩压上升，舒张压不变或稍下降","C":"收缩压上升，舒张压上升，脉压变小","D":"收缩压上升，舒张压上升不明显，脉压增大","E":"收缩压上升，舒张压下降，脉压增大"},"answer":["D"],"rationale":"小剂量去甲肾上腺素主要兴奋心脏β1受体，收缩压升高为主，舒张压升高不明显，脉压增大。","expl":{"A":"错误，小剂量去甲肾上腺素并非以升高舒张压为主。","B":"错误，去甲肾上腺素反射性减慢心率，并非心率增快。","C":"错误，小剂量时舒张压升高不明显。","D":"正确，收缩压升高、舒张压升高不明显，脉压增大。","E":"错误，去甲肾上腺素使收缩压上升而非下降。"},"id":"ph09_q11","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":11},{"type":"A","stem":"去甲肾上腺素静滴时间过长引起的最严重的不良反应是","options":{"A":"血压过高","B":"静滴部位出血坏死","C":"心率紊乱","D":"急性肾功能衰竭","E":"突然停药引起血压下降"},"answer":["D"],"rationale":"去甲肾上腺素强烈收缩肾血管，久滴可致肾缺血甚至急性肾衰竭，为最严重的不良反应。","expl":{"A":"错误，血压过高可通过调整剂量控制，不如肾衰竭严重。","B":"错误，静滴部位坏死由药液外漏引起，非久滴最严重者。","C":"错误，去甲肾上腺素较少引起严重心律失常。","D":"正确，强收缩肾血管致肾缺血、急性肾功能衰竭，最为严重。","E":"错误，突然停药血压下降不属久滴最严重的不良反应。"},"id":"ph09_q12","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":12},{"type":"A","stem":"反复使用麻黄碱产生快速耐受性的原因是","options":{"A":"诱导肝药酶，使其代谢加快","B":"受体敏感性下降","C":"去甲肾上腺素能神经末梢递质排空","D":"其代谢产物拮抗了麻黄碱的作用","E":"麻黄碱被 MAO 和 COMT 破坏"},"answer":["C"],"rationale":"麻黄碱通过促进去甲肾上腺素能神经末梢释放递质而起作用，反复用药递质耗竭产生快速耐受。","expl":{"A":"错误，快速耐受主要不是肝药酶诱导代谢加快所致。","B":"错误，受体敏感性下降非快速耐受的主要原因。","C":"正确，递质排空导致快速耐受。","D":"错误，其代谢产物并不拮抗麻黄碱的作用。","E":"错误，麻黄碱为非儿茶酚胺类，不易被MAO、COMT破坏。"},"id":"ph09_q13","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":13},{"type":"A","stem":"麻黄碱的特点是","options":{"A":"不易产生快速耐受性","B":"性质不稳定，口服无效","C":"性质稳定，口服有效","D":"具中枢抑制作用","E":"作用快、强"},"answer":["C"],"rationale":"麻黄碱为非儿茶酚胺类，化学性质稳定，口服有效，作用持久。","expl":{"A":"错误，麻黄碱易产生快速耐受性。","B":"错误，麻黄碱性质稳定，口服有效。","C":"正确，性质稳定、可口服，作用温和持久。","D":"错误，麻黄碱具有中枢兴奋作用而非抑制。","E":"错误，麻黄碱作用较肾上腺素弱而持久，并非快、强。"},"id":"ph09_q14","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":14},{"type":"A","stem":"既可直接激动 α 、β-R，又可促进去甲肾上腺素能神经末梢释放递质的药物是","options":{"A":"麻黄碱","B":"去甲肾上腺素","C":"肾上腺素","D":"异丙肾上腺素","E":"苯肾上腺素"},"answer":["A"],"rationale":"麻黄碱既能直接激动α、β受体，又能促进去甲肾上腺素能神经末梢释放递质。","expl":{"A":"正确，麻黄碱兼有直接激动受体和促进递质释放双重机制。","B":"错误，去甲肾上腺素为直接激动剂，不促进自身递质释放。","C":"错误，肾上腺素为直接激动剂，无促进递质释放作用。","D":"错误，异丙肾上腺素为直接β激动剂，不促进递质释放。","E":"错误，苯肾上腺素（去氧肾上腺素）为直接α1激动剂。"},"id":"ph09_q15","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":15},{"type":"A","stem":"去甲肾上腺素静脉滴注时间过长或剂量过大的主要危险是","options":{"A":"抑制心脏","B":"急性肾功能衰竭","C":"局部组织缺血坏死","D":"心律失常","E":"血压升高"},"answer":["B"],"rationale":"去甲肾上腺素静滴时间过长或剂量过大强烈收缩肾血管，可致急性肾衰竭，为主要危险。","expl":{"A":"错误，去甲肾上腺素不直接抑制心脏。","B":"正确，肾血管强烈收缩致肾缺血、急性肾功能衰竭。","C":"错误，局部组织缺血坏死主要由药液外漏引起。","D":"错误，心律失常并非其主要危险。","E":"错误，血压升高是治疗目的，控制适当并非主要危险。"},"id":"ph09_q16","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":16},{"type":"A","stem":"去氧肾上腺素对眼的作用是","options":{"A":"激动瞳孔开大肌上的 α-R","B":"阻断瞳孔括约肌上的 M-R","C":"明显升高眼内压","D":"可产生调节麻痹","E":"可产生调节痉挛"},"answer":["A"],"rationale":"去氧肾上腺素激动瞳孔开大肌α1受体，使之收缩而散瞳。","expl":{"A":"正确，激动瞳孔开大肌α受体产生散瞳，且不麻痹睫状肌。","B":"错误，去氧肾上腺素不阻断M受体。","C":"错误，去氧肾上腺素散瞳不伴明显升高眼压。","D":"错误，去氧肾上腺素不麻痹睫状肌，不产生调节麻痹。","E":"错误，去氧肾上腺素不产生调节痉挛。"},"id":"ph09_q17","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":17},{"type":"A","stem":"异丙肾上腺素没有下述哪种作用？","options":{"A":"松驰支气管平滑肌","B":"激动 β2-R","C":"收缩支气管粘膜血管","D":"促使 ATP 转变为 CAMP","E":"抑制组胺等过敏性物质的释放"},"answer":["C"],"rationale":"异丙肾上腺素为纯β受体激动剂，无α受体作用，故不能收缩支气管黏膜血管。","expl":{"A":"错误，异丙肾上腺素能松弛支气管平滑肌。","B":"错误，异丙肾上腺素可激动β2受体。","C":"正确，异丙肾上腺素不激动α受体，不能收缩支气管黏膜血管。","D":"错误，异丙肾上腺素可促进ATP转变为cAMP。","E":"错误，异丙肾上腺素可抑制组胺等过敏性物质释放。"},"id":"ph09_q18","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":18},{"type":"A","stem":"异丙肾上腺素治疗哮喘的常见不良反应是","options":{"A":"腹泻","B":"中枢兴奋","C":"直立性低血压","D":"心动过速","E":"脑血管意外"},"answer":["D"],"rationale":"异丙肾上腺素激动心脏β1受体，可引起心动过速，为其治疗哮喘的常见不良反应。","expl":{"A":"错误，异丙肾上腺素不引起腹泻。","B":"错误，异丙肾上腺素无显著中枢兴奋作用。","C":"错误，异丙肾上腺素不引起直立性低血压。","D":"正确，激动β1受体致心动过速、心悸，为常见不良反应。","E":"错误，异丙肾上腺素不引起脑血管意外。"},"id":"ph09_q19","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":19},{"type":"A","stem":"现有一新药，给人静脉注射后可产生轻度心动过速，但平均动脉血压无变化，还可减少汗腺分泌和扩瞳，不具有中枢效应，该药应属于","options":{"A":"α-R 阻断药","B":"β-R 激动药","C":"神经节 N 受体激动药","D":"神经节 N 受体阻断药","E":"以上均不是"},"answer":["E"],"rationale":"该药轻度增快心率、抑制汗腺分泌、扩瞳且无中枢作用，符合M胆碱受体阻断药（如阿托品）特点，不属于所列各类。","expl":{"A":"错误，α受体阻断药扩张血管降压，不抑制汗腺、不扩瞳。","B":"错误，β受体激动药增快心率但不抑制汗腺分泌、不扩瞳。","C":"错误，神经节N受体激动药不呈此特征。","D":"错误，神经节N受体阻断药致低血压及腺体抑制，但机制不符。","E":"正确，该药为M受体阻断药，不属于A~D任一类。"},"id":"ph09_q20","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":20},{"type":"A","stem":"静滴剂量过大，易致肾功能衰竭的药物是","options":{"A":"肾上腺素","B":"异丙肾上腺素","C":"去甲肾上腺素","D":"多巴胺","E":"麻黄碱"},"answer":["C"],"rationale":"去甲肾上腺素强烈收缩肾血管，静滴剂量过大易致肾缺血、急性肾功能衰竭。","expl":{"A":"错误，肾上腺素收缩肾血管作用相对较弱，不以此为主要危险。","B":"错误，异丙肾上腺素扩张血管，不收缩肾血管。","C":"正确，去甲肾上腺素强烈收缩肾血管，大剂量易致急性肾衰竭。","D":"错误，多巴胺舒张肾血管，不引起肾衰竭。","E":"错误，麻黄碱对肾血管影响小，不易致肾衰竭。"},"id":"ph09_q21","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":21},{"type":"A","stem":"肾上腺素与局麻药合用于局麻的目的是","options":{"A":"使局部血管收缩而止血","B":"预防过敏性休克的发生","C":"防止低血压的发生","D":"使局麻时间延长，减少吸收中毒","E":"使局部血管扩张，使局麻药吸收加快"},"answer":["D"],"rationale":"肾上腺素收缩局部血管，延缓局麻药吸收，可延长麻醉时间并减少吸收中毒。","expl":{"A":"错误，合用目的主要是延缓吸收而非直接止血。","B":"错误，肾上腺素不能预防局麻药引起的过敏性休克。","C":"错误，防止低血压并非合用的主要目的。","D":"正确，收缩局部血管使局麻时间延长、减少吸收中毒。","E":"错误，肾上腺素使局部血管收缩而非扩张。"},"id":"ph09_q22","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":22},{"type":"A","stem":"房室结功能衰竭伴心脏骤停的心跳复苏药最佳是","options":{"A":"氯化钙","B":"利多卡因","C":"去甲肾上腺素","D":"异丙肾上腺素","E":"苯上肾腺素"},"answer":["D"],"rationale":"异丙肾上腺素激动β1受体，加快房室传导、增快心率，适用于房室结功能衰竭伴心脏骤停的复苏。","expl":{"A":"错误，氯化钙用于低钙等，非房室阻滞复苏首选。","B":"错误，利多卡因为抗心律失常药，不用于心跳复苏。","C":"错误，去甲肾上腺素升压强但减慢心率，不适用。","D":"正确，异丙肾上腺素兴奋β1受体，加快传导与心率，宜用于复苏。","E":"错误，苯肾上腺素为升压药，不改善传导。"},"id":"ph09_q23","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":23},{"type":"A","stem":"去甲肾上腺素不同于肾上腺素之处是","options":{"A":"为儿茶酚胺类药物","B":"能激动 α-R","C":"能增加心肌耗氧量","D":"升高血压","E":"在整体情况下心率会减慢"},"answer":["E"],"rationale":"去甲肾上腺素升压作用强，反射性使心率减慢；肾上腺素整体使心率加快，此为二者重要区别。","expl":{"A":"错误，二者均属儿茶酚胺类。","B":"错误，二者均能激动α受体。","C":"错误，二者均可增加心肌耗氧量。","D":"错误，二者均可升高血压。","E":"正确，去甲肾上腺素整体反射性减慢心率，不同于肾上腺素。"},"id":"ph09_q24","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":24},{"type":"A","stem":"属 α 1-R 激动药的药物是","options":{"A":"去甲肾上腺素","B":"肾上腺素","C":"甲氧明","D":"间羟胺","E":"麻黄碱"},"answer":["C"],"rationale":"甲氧明选择性激动α1受体，为典型的α1受体激动药。","expl":{"A":"错误，去甲肾上腺素为α、β受体激动药，非选择性α1激动药。","B":"错误，肾上腺素为α、β受体激动药。","C":"正确，甲氧明选择性激动α1受体。","D":"错误，间羟胺主要促递质释放，兼直接激动α受体。","E":"错误，麻黄碱为α、β受体兼间接激动药。"},"id":"ph09_q25","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":25},{"type":"A","stem":"控制支气管哮喘急性发作宜选用","options":{"A":"麻黄碱","B":"异丙肾上腺素","C":"多巴胺","D":"间羟胺","E":"去甲肾上腺素"},"answer":["B"],"rationale":"异丙肾上腺素激动β2受体快速松弛支气管平滑肌，宜用于支气管哮喘急性发作。","expl":{"A":"错误，麻黄碱作用缓慢持久，用于轻症和预防。","B":"正确，异丙肾上腺素起效快，宜控制哮喘急性发作。","C":"错误，多巴胺主要影响心血管和肾，不用于哮喘。","D":"错误，间羟胺为升压药，不用于哮喘。","E":"错误，去甲肾上腺素收缩血管，不用于哮喘。"},"id":"ph09_q26","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":26},{"type":"A","stem":"肾上腺素禁用于","options":{"A":"支气管哮喘急性发作","B":"甲亢","C":"过敏性休克","D":"心脏骤停","E":"局部止血"},"answer":["B"],"rationale":"肾上腺素增快心率、升高代谢，可诱发甲亢危象及心律失常，故甲亢患者禁用。","expl":{"A":"错误，支气管哮喘急性发作是肾上腺素的适应证。","B":"正确，甲亢患者对儿茶酚胺敏感，肾上腺素可诱发危象，属禁忌。","C":"错误，过敏性休克是肾上腺素首选适应证。","D":"错误，心脏骤停可用肾上腺素复苏。","E":"错误，局部止血为肾上腺素的应用之一。"},"id":"ph09_q27","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":27},{"type":"A","stem":"主要用于支气管哮喘轻症治疗的药物是","options":{"A":"麻黄碱","B":"肾上腺素","C":"异丙肾上腺素","D":"阿托品","E":"去甲肾上腺素"},"answer":["A"],"rationale":"麻黄碱作用温和持久、可口服，适用于支气管哮喘轻症治疗及预防发作。","expl":{"A":"正确，麻黄碱作用缓和持久，宜用于哮喘轻症。","B":"错误，肾上腺素用于哮喘急性发作，非轻症首选。","C":"错误，异丙肾上腺素用于急性发作。","D":"错误，阿托品非哮喘治疗首选药。","E":"错误，去甲肾上腺素不用于哮喘。"},"id":"ph09_q28","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":28},{"type":"B","stem":"小剂量静滴肾上腺素可引起","options":{"A":"心率减慢，血压升高","B":"心率增快，脉压增大","C":"收缩压、舒张压明显升高，脉压变小","D":"增加收缩压、脉压，舒张肾血管","E":"收缩压下降，舒张压上升"},"answer":["B"],"rationale":"小剂量肾上腺素以兴奋β受体为主，心脏兴奋使心率增快，收缩压升高、舒张压略降，脉压增大。","expl":{"A":"错误，小剂量肾上腺素不引起心率减慢。","B":"正确，心率增快，收缩压升高而舒张压不变或稍降，脉压增大。","C":"错误，小剂量时舒张压不明显升高。","D":"错误，肾上腺素不舒张肾血管。","E":"错误，肾上腺素使收缩压上升而非下降。"},"id":"ph09_q29","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":29},{"type":"B","stem":"小剂量静滴去甲肾上腺素可引起","options":{"A":"心率减慢，血压升高","B":"心率增快，脉压增大","C":"收缩压、舒张压明显升高，脉压变小","D":"增加收缩压、脉压，舒张肾血管","E":"收缩压下降，舒张压上升"},"answer":["A"],"rationale":"小剂量去甲肾上腺素主要收缩血管升高血压，反射性使心率减慢。","expl":{"A":"正确，升压作用强，反射性兴奋迷走神经使心率减慢。","B":"错误，去甲肾上腺素反射性减慢心率，并非增快。","C":"错误，小剂量去甲肾上腺素舒张压升高不明显。","D":"错误，去甲肾上腺素收缩肾血管，不舒张。","E":"错误，去甲肾上腺素使收缩压上升而非下降。"},"id":"ph09_q30","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":30},{"type":"B","stem":"大剂量静滴去甲肾上腺素可引起","options":{"A":"心率减慢，血压升高","B":"心率增快，脉压增大","C":"收缩压、舒张压明显升高，脉压变小","D":"增加收缩压、脉压，舒张肾血管","E":"收缩压下降，舒张压上升"},"answer":["C"],"rationale":"大剂量去甲肾上腺素α受体作用占优势，外周阻力显著升高，收缩压、舒张压均明显升高，脉压变小。","expl":{"A":"错误，大剂量时血压明显升高并反射性减慢心率，非仅此。","B":"错误，大剂量时脉压变小而非增大。","C":"正确，收缩压、舒张压明显升高，脉压变小。","D":"错误，去甲肾上腺素收缩肾血管，不舒张。","E":"错误，去甲肾上腺素使收缩压上升。"},"id":"ph09_q31","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":31},{"type":"B","stem":"治疗量静滴多巴胺可引起","options":{"A":"心率减慢，血压升高","B":"心率增快，脉压增大","C":"收缩压、舒张压明显升高，脉压变小","D":"增加收缩压、脉压，舒张肾血管","E":"收缩压下降，舒张压上升"},"answer":["D"],"rationale":"治疗量多巴胺激动β1受体及D1受体，增加收缩压和脉压，并舒张肾血管。","expl":{"A":"错误，多巴胺一般不引起心率减慢。","B":"错误，多巴胺虽增收缩压与脉压，但更重要是舒张肾血管。","C":"错误，多巴胺舒张压升高不明显。","D":"正确，增加收缩压和脉压，并舒张肾血管增加肾血流。","E":"错误，多巴胺使收缩压上升而非下降。"},"id":"ph09_q32","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":32},{"type":"B","stem":"肾上腺素可用于","options":{"A":"过敏性休克","B":"出血性休克","C":"早期神经原性休克","D":"感染中毒性休克","E":"心源性休克"},"answer":["A"],"rationale":"肾上腺素激动α、β受体，升高血压、扩张支气管、抑制过敏介质释放，是过敏性休克首选药。","expl":{"A":"正确，肾上腺素为过敏性休克的首选药。","B":"错误，出血性休克以补液输血及去甲肾上腺素升压为主。","C":"错误，早期神经原性休克多用去甲肾上腺素。","D":"错误，感染中毒性休克在抗感染基础上可用阿托品等。","E":"错误，心源性休克需针对病因处理，不首选肾上腺素。"},"id":"ph09_q33","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":33},{"type":"B","stem":"去甲肾上腺素可用于","options":{"A":"过敏性休克","B":"出血性休克","C":"早期神经原性休克","D":"感染中毒性休克","E":"心源性休克"},"answer":["C"],"rationale":"去甲肾上腺素收缩血管升高血压，适用于早期神经原性休克时的低血压。","expl":{"A":"错误，过敏性休克首选肾上腺素。","B":"错误，出血性休克应补液输血，去甲肾上腺素非首选。","C":"正确，早期神经原性休克因血管扩张血压下降，去甲肾上腺素收缩血管升压适宜。","D":"错误，感染中毒性休克以阿托品等扩血管改善微循环为主。","E":"错误，心源性休克不宜单用去甲肾上腺素强升压。"},"id":"ph09_q34","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":34},{"type":"B","stem":"阿托品可用于","options":{"A":"过敏性休克","B":"出血性休克","C":"早期神经原性休克","D":"感染中毒性休克","E":"心源性休克"},"answer":["D"],"rationale":"感染中毒性休克存在微循环障碍，阿托品解除小血管痉挛、改善微循环，故可用于其治疗。","expl":{"A":"错误，过敏性休克首选肾上腺素。","B":"错误，出血性休克以补液输血为主。","C":"错误，早期神经原性休克多用去甲肾上腺素。","D":"正确，阿托品扩张血管改善微循环，用于感染中毒性休克。","E":"错误，心源性休克不首选阿托品。"},"id":"ph09_q35","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":35},{"type":"C","stem":"直接与受体结合","options":{"A":"多巴胺","B":"麻黄碱","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"多巴胺直接激动多巴胺受体及α、β受体，麻黄碱亦能直接激动α、β受体，故两者均直接与受体结合。","expl":{"A":"错误，多巴胺可激动D1、β1等受体，但此项不完整。","B":"错误，麻黄碱亦可直接激动α、β受体，但此项不完整。","C":"正确，两者均能直接与受体结合。","D":"错误，两者均能直接与受体结合。"},"id":"ph09_q36","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":36},{"type":"C","stem":"促进去甲肾上腺素释放","options":{"A":"多巴胺","B":"麻黄碱","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"多巴胺和麻黄碱均能促进去甲肾上腺素能神经末梢释放去甲肾上腺素。","expl":{"A":"错误，多巴胺可促进NA释放，但此项不完整。","B":"错误，麻黄碱可促进NA释放，但此项不完整。","C":"正确，两者均可促进去甲肾上腺素释放。","D":"错误，两者均能促进NA释放。"},"id":"ph09_q37","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":37},{"type":"C","stem":"激动 D1-R","options":{"A":"多巴胺","B":"麻黄碱","C":"两者均是","D":"两者均否"},"answer":["A"],"rationale":"多巴胺可激动肾血管等部位D1受体，麻黄碱无此作用。","expl":{"A":"正确，多巴胺激动D1受体，扩张肾血管。","B":"错误，麻黄碱主要激动α、β受体，不激动D1受体。","C":"错误，麻黄碱不激动D1受体。","D":"错误，多巴胺可激动D1受体。"},"id":"ph09_q38","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":38},{"type":"C","stem":"具排钠利尿作用","options":{"A":"多巴胺","B":"麻黄碱","C":"两者均是","D":"两者均否"},"answer":["A"],"rationale":"小剂量多巴胺激动肾D1受体，扩张肾血管、增加肾血流，产生排钠利尿作用。","expl":{"A":"正确，多巴胺增加肾血流，有排钠利尿作用。","B":"错误，麻黄碱无排钠利尿作用。","C":"错误，麻黄碱不具排钠利尿作用。","D":"错误，多巴胺具排钠利尿作用。"},"id":"ph09_q39","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":39},{"type":"X","stem":"儿茶酚胺类包括","options":{"A":"肾上腺素","B":"去甲肾上腺素","C":"异丙肾上腺素","D":"多巴胺","E":"麻黄碱"},"answer":["A","B","C","D"],"rationale":"肾上腺素、去甲肾上腺素、异丙肾上腺素、多巴胺均含儿茶酚（邻苯二酚）核，属儿茶酚胺类；麻黄碱无儿茶酚核。","expl":{"A":"正确，肾上腺素属儿茶酚胺类。","B":"正确，去甲肾上腺素属儿茶酚胺类。","C":"正确，异丙肾上腺素属儿茶酚胺类。","D":"正确，多巴胺属儿茶酚胺类。","E":"错误，麻黄碱无儿茶酚核，属非儿茶酚胺类。"},"id":"ph09_q40","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":40},{"type":"X","stem":"可促进 NA 释放的药物是","options":{"A":"肾上腺素","B":"多巴胺","C":"麻黄碱","D":"间羟胺","E":"去甲肾上腺素"},"answer":["B","C","D"],"rationale":"多巴胺、麻黄碱、间羟胺均可促进去甲肾上腺素能神经末梢释放NA；肾上腺素、去甲肾上腺素为直接激动剂。","expl":{"A":"错误，肾上腺素直接激动受体，不促进NA释放。","B":"正确，多巴胺可促进NA释放。","C":"正确，麻黄碱可促进NA释放。","D":"正确，间羟胺可促进NA释放。","E":"错误，去甲肾上腺素为直接激动剂，不促进自身释放。"},"id":"ph09_q41","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":41},{"type":"X","stem":"间羟胺与 NA 相比有以下特点","options":{"A":"可肌注给药","B":"升压作用较弱但持久","C":"不易被 MAO 代谢","D":"不易引起心律失常","E":"收缩肾血管作用弱"},"answer":["A","B","C","D","E"],"rationale":"间羟胺升压作用较去甲肾上腺素弱而持久，可肌注，不易被MAO代谢，较少引起心律失常，收缩肾血管作用弱。","expl":{"A":"正确，间羟胺性质稳定，可肌注给药。","B":"正确，间羟胺升压作用较弱但持久。","C":"正确，间羟胺为非儿茶酚胺类，不易被MAO代谢。","D":"正确，间羟胺不易引起心律失常。","E":"正确，间羟胺收缩肾血管作用较NA弱。"},"id":"ph09_q42","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":42},{"type":"X","stem":"肾上腺素抢救过敏性休克的作用机制有","options":{"A":"增加心输出量","B":"升高外周阻力和血压","C":"松驰支气管平滑肌","D":"抑制组胺等过敏物质释放","E":"减轻支气管粘膜水肿"},"answer":["A","B","C","D","E"],"rationale":"肾上腺素激动α、β受体，增加心输出量、升高血压、松弛支气管平滑肌、抑制过敏介质释放并减轻黏膜水肿，从而抗过敏性休克。","expl":{"A":"正确，激动β1受体增强心肌收缩、增加心输出量。","B":"正确，激动α受体收缩血管，升高外周阻力和血压。","C":"正确，激动β2受体松弛支气管平滑肌。","D":"正确，抑制组胺等过敏介质释放。","E":"正确，收缩支气管黏膜血管，减轻黏膜水肿。"},"id":"ph09_q43","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":43},{"type":"A","stem":"小剂量多巴胺静脉滴注使肾血管扩张、尿量增加，其机制是","options":{"A":"激动α1受体","B":"激动β1受体","C":"激动D1受体","D":"阻断α受体","E":"直接抑制肾小管重吸收"},"answer":["C"],"rationale":"小剂量多巴胺选择性激动肾、肠系膜血管的D1受体，使血管扩张、肾血流量增加而利尿，故答案为 C。","expl":{"A":"错误，激动α1受体使血管收缩，大剂量多巴胺才表现此作用。","B":"错误，激动β1受体主要增强心肌收缩力和加快心率，不引起肾血管扩张。","C":"正确，小剂量多巴胺激动D1受体扩张肾血管，增加肾血流量和尿量。","D":"错误，多巴胺是受体激动药，小剂量不通过阻断α受体起作用。","E":"错误，多巴胺的利尿作用源于增加肾血流，而非直接抑制肾小管重吸收。"},"id":"ph09_q44","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":44}]},{"title":"第十章 肾上腺素受体阻断药","questions":[{"type":"A","stem":"外周血管痉挛性疾病可选用何药治疗","options":{"A":"山莨菪碱","B":"异丙肾上腺素","C":"间羟胺","D":"普萘洛尔","E":"酚妥拉明"},"answer":["E"],"rationale":"酚妥拉明为α受体阻断药，能扩张血管、改善微循环，故可用于治疗外周血管痉挛性疾病。","expl":{"A":"山莨菪碱为M胆碱受体阻断药，主要解除内脏平滑肌痉挛，非外周血管痉挛性疾病首选。","B":"异丙肾上腺素为β受体激动药，虽可扩张血管，但不用于外周血管痉挛性疾病。","C":"间羟胺为α受体激动药，收缩血管，反而加重外周血管痉挛。","D":"普萘洛尔为β受体阻断药，可使外周血管收缩，不宜用于血管痉挛性疾病。","E":"正确，酚妥拉明阻断α受体、扩张血管，用于治疗外周血管痉挛性疾病。"},"id":"ph10_q01","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":1},{"type":"A","stem":"“ 肾上腺素升压作用的翻转”是指","options":{"A":"给予 β 受体阻断药后出现升压效应","B":"给予 α 受体阻断药后出现降压效应","C":"肾上腺素具有 α 、β 受体激动效应","D":"收缩上升，舒张压不变或下降","E":"由于升高血压，对脑血管的被动扩张作用"},"answer":["B"],"rationale":"α受体阻断药阻断α受体后，肾上腺素仅激动β2受体，血管扩张使血压下降，即升压作用翻转为降压。","expl":{"A":"错，给予β受体阻断药后肾上腺素仍以α作用为主，表现为升压而非降压。","B":"正确，阻断α受体后肾上腺素只兴奋β2受体，出现降压效应。","C":"此为肾上腺素本身的双重激动效应，并非升压翻转的含义。","D":"描述的是肾上腺素正常升压效应，与翻转无关。","E":"脑血管被动扩张是升压的后果之一，不属翻转作用。"},"id":"ph10_q02","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":2},{"type":"A","stem":"普萘洛尔不具有下述哪项药理作用","options":{"A":"阻断心脏 β1受体及支气管 β2 受体","B":"生物利用度低","C":"抑制肾素释放","D":"膜稳定作用","E":"内在拟交感作用"},"answer":["E"],"rationale":"普萘洛尔无内在拟交感活性，其余如阻断β1/β2受体、生物利用度低、抑制肾素释放及膜稳定作用均具备。","expl":{"A":"普萘洛尔非选择性阻断心脏β1及支气管β2受体，属于其作用。","B":"普萘洛尔首过消除明显，生物利用度低，属于其特征。","C":"普萘洛尔可阻断肾小球旁器β受体而抑制肾素释放。","D":"普萘洛尔有膜稳定（局麻）作用，属于其作用。","E":"正确，普萘洛尔无内在拟交感活性，故不具有此项。"},"id":"ph10_q03","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":3},{"type":"A","stem":"下列具有拟胆碱作用的药物是","options":{"A":"间羟胺","B":"多巴酚丁胺","C":"酚苄明","D":"酚妥拉明","E":"山莨菪碱"},"answer":["D"],"rationale":"酚妥拉明可激动M胆碱受体，产生拟胆碱样作用，如兴奋胃肠道平滑肌、促进蠕动。","expl":{"A":"间羟胺为α受体激动药，无拟胆碱作用。","B":"多巴酚丁胺为选择性β1受体激动药，无拟胆碱作用。","C":"酚苄明为α受体阻断药，无拟胆碱样作用。","D":"正确，酚妥拉明有拟胆碱样作用，可兴奋胃肠道平滑肌。","E":"山莨菪碱为M胆碱受体阻断药，具有抗胆碱而非拟胆碱作用。"},"id":"ph10_q04","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":4},{"type":"A","stem":"静注普萘洛尔后再静注下列哪一种药物可表现升压效应","options":{"A":"肾上腺素","B":"异丙肾上腺素","C":"氯丙嗪","D":"东莨菪碱","E":"新斯的明"},"answer":["A"],"rationale":"阻断β受体后，肾上腺素仅保留α受体激动作用，使血管收缩、血压升高。","expl":{"A":"正确，β受体被阻断后肾上腺素只激动α受体，表现为升压效应。","B":"异丙肾上腺素主要激动β受体，β受体被阻断后作用减弱，不升压。","C":"氯丙嗪为α受体阻断药，反引起降压，不表现升压。","D":"东莨菪碱为M受体阻断药，不产生升压效应。","E":"新斯的明为抗胆碱酯酶药，不引起升压。"},"id":"ph10_q05","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":5},{"type":"A","stem":"静滴去甲肾上腺素发生外漏，最佳的处理方式是","options":{"A":"局部注射局部麻醉药","B":"肌内注射酚妥拉明","C":"局部注射酚妥拉明","D":"局部注射 β 受体阻断药","E":"局部浸润用肤轻松软膏"},"answer":["C"],"rationale":"去甲肾上腺素外漏致局部血管强烈收缩、组织缺血坏死，应用α受体阻断药酚妥拉明局部浸润注射对抗。","expl":{"A":"局部麻醉药不能对抗去甲肾上腺素的血管收缩作用。","B":"酚妥拉明应局部浸润注射，而非肌内注射。","C":"正确，局部注射酚妥拉明阻断α受体、扩张血管，防止组织坏死。","D":"β受体阻断药无对抗α受体收缩血管的作用。","E":"肤轻松软膏为糖皮质激素，不能解除局部血管痉挛。"},"id":"ph10_q06","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":6},{"type":"A","stem":"酚妥拉明治疗充血性心力衰竭是因为","options":{"A":"能增强心肌收缩力","B":"有抗胆碱作用，心率加快","C":"利尿消肿，减轻心脏负担","D":"降低心肌耗氧量","E":"扩张血管，降低外周阻力，减轻心脏后负荷"},"answer":["E"],"rationale":"酚妥拉明阻断α受体并直接扩张血管，降低外周阻力、减轻心脏后负荷，从而改善心功能。","expl":{"A":"酚妥拉明主要扩张血管，并不直接增强心肌收缩力。","B":"抗胆碱作用并非其治疗心衰的主要机制。","C":"酚妥拉明无明显利尿作用，非通过消肿减负。","D":"扩张血管可反射性加快心率、增加耗氧，并非降低心肌耗氧量。","E":"正确，扩张血管降低外周阻力、减轻心脏后负荷。"},"id":"ph10_q07","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":7},{"type":"A","stem":"用于诊断嗜铬细胞瘤的药物是","options":{"A":"肾上腺素","B":"酚妥拉明","C":"阿托品","D":"组胺","E":"普萘洛尔"},"answer":["B"],"rationale":"酚妥拉明为α受体阻断药，可阻断儿茶酚胺的α受体升压作用；静脉注射酚妥拉明后血压明显下降者提示嗜铬细胞瘤，即酚妥拉明试验。","expl":{"A":"错误，肾上腺素激动α、β受体使血压升高，不能用于诊断。","B":"正确，酚妥拉明试验用于诊断嗜铬细胞瘤。","C":"错误，阿托品为M受体阻断药，与嗜铬细胞瘤诊断无关。","D":"错误，组胺虽可促使儿茶酚胺释放，但危险且不特异，不用于诊断。","E":"错误，普萘洛尔为β受体阻断药；在嗜铬细胞瘤未先用α阻断药时使用可致血压骤升，不能用于诊断。"},"id":"ph10_q08","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":8},{"type":"A","stem":"下列哪一种药物有拟胆碱和组胺样作用","options":{"A":"regitinE.","B":"phenoxybenzaminE.","C":"dobutaminE.","D":"araminE.","E":"anisodamine"},"answer":["A"],"rationale":"酚妥拉明（regitine，立其丁）具有拟胆碱样作用和组胺样作用。","expl":{"A":"正确，酚妥拉明（立其丁）有拟胆碱和组胺样作用。","B":"酚苄明为α受体阻断药，无拟胆碱和组胺样作用。","C":"多巴酚丁胺为β1受体激动药，无此作用。","D":"间羟胺为α受体激动药，无此作用。","E":"山莨菪碱为M受体阻断药，有抗胆碱作用，无拟胆碱及组胺样作用。"},"id":"ph10_q09","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":9},{"type":"A","stem":"给 β 受体阻断药，异丙肾上腺素的降压作用将会","options":{"A":"出现升压效应","B":"进一步降压","C":"先升压再降压","D":"减弱","E":"导致休克产生"},"answer":["D"],"rationale":"异丙肾上腺素的降压作用由激动β2受体引起，β受体被阻断后其作用减弱。","expl":{"A":"异丙肾上腺素主要激动β受体，β受体阻断后不会出现升压。","B":"β受体被阻断后异丙肾上腺素作用减弱，不会进一步降压。","C":"无先升后降效应，阻断后直接减弱。","D":"正确，β受体被阻断后异丙肾上腺素降压作用减弱。","E":"作用减弱不致导致休克。"},"id":"ph10_q10","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":10},{"type":"A","stem":"可选择性阻断 α 1-R 的药物是","options":{"A":"氯丙嗪","B":"异丙嗪","C":"肼屈嗪","D":"丙咪嗪","E":"哌唑嗪"},"answer":["E"],"rationale":"哌唑嗪为选择性α1受体阻断药，用于高血压及前列腺增生。","expl":{"A":"氯丙嗪为抗精神病药，虽有α受体阻断作用但非选择性。","B":"异丙嗪为H1受体阻断药，无选择性阻断α1受体作用。","C":"肼屈嗪为直接扩血管降压药，不阻断α1受体。","D":"丙咪嗪为抗抑郁药，不选择性阻断α1受体。","E":"正确，哌唑嗪选择性阻断α1受体。"},"id":"ph10_q11","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":11},{"type":"A","stem":"属长效类 α-R 阻断药的是","options":{"A":"酚妥拉明","B":"妥拉唑啉","C":"哌唑嗪","D":"酚苄明","E":"甲氧明"},"answer":["D"],"rationale":"酚苄明与α受体共价结合，阻断作用持久，属长效α受体阻断药。","expl":{"A":"酚妥拉明为短效α受体阻断药，作用短暂。","B":"妥拉唑啉为短效α受体阻断药。","C":"哌唑嗪为选择性α1受体阻断药，非长效类。","D":"正确，酚苄明与α受体共价结合、作用持久，属长效类。","E":"甲氧明为α受体激动药，非阻断药。"},"id":"ph10_q12","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":12},{"type":"A","stem":"可用于治疗外周血管痉挛性疾病的药物是","options":{"A":"阿托品","B":"山莨菪碱","C":"多巴胺","D":"肼屈嗪","E":"酚妥拉明"},"answer":["E"],"rationale":"酚妥拉明阻断α受体、扩张血管，是外周血管痉挛性疾病的常用药。","expl":{"A":"阿托品为M受体阻断药，不用于外周血管痉挛性疾病。","B":"山莨菪碱主要解除内脏平滑肌痉挛，不用于外周血管痉挛。","C":"多巴胺为α、β及多巴胺受体激动药，非外周血管痉挛性疾病常用药。","D":"肼屈嗪为直接扩血管降压药，非外周血管痉挛性疾病常用药。","E":"正确，酚妥拉明扩张血管，用于外周血管痉挛性疾病。"},"id":"ph10_q13","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":13},{"type":"B","stem":"可用于治疗青光眼的是","options":{"A":"酚妥拉明","B":"普萘洛尔","C":"噻吗洛尔","D":"拉贝洛尔","E":"妥拉唑啉"},"answer":["C"],"rationale":"噻吗洛尔为β受体阻断药，减少房水生成，滴眼用于治疗青光眼。","expl":{"A":"酚妥拉明为α受体阻断药，不用于青光眼治疗。","B":"普萘洛尔虽为β受体阻断药，但不用于滴眼治疗青光眼。","C":"正确，噻吗洛尔减少房水生成、降低眼压，治疗青光眼。","D":"拉贝洛尔为α、β受体阻断药，用于高血压，不用于青光眼。","E":"妥拉唑啉为α受体阻断药，不用于青光眼。"},"id":"ph10_q14","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":14},{"type":"B","stem":"可用于治疗甲亢的是","options":{"A":"酚妥拉明","B":"普萘洛尔","C":"噻吗洛尔","D":"拉贝洛尔","E":"妥拉唑啉"},"answer":["B"],"rationale":"普萘洛尔阻断β受体，可减轻甲亢所致的交感神经过度兴奋症状如心悸、震颤等。","expl":{"A":"酚妥拉明为α受体阻断药，不用于甲亢的辅助治疗。","B":"正确，普萘洛尔阻断β受体，缓解甲亢心悸、震颤等交感兴奋症状。","C":"噻吗洛尔为β受体阻断药，主要用于青光眼，非甲亢常规用药。","D":"拉贝洛尔为α、β受体阻断药，主要用于高血压。","E":"妥拉唑啉为α受体阻断药，不用于甲亢。"},"id":"ph10_q15","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":15},{"type":"C","stem":"支气管哮喘禁用","options":{"A":"普萘洛尔","B":"酚妥拉明","C":"两者均是","D":"两者均否"},"answer":["A"],"rationale":"普萘洛尔阻断支气管β2受体使支气管平滑肌收缩、加重哮喘，故支气管哮喘禁用。","expl":{"A":"正确，普萘洛尔阻断β2受体致支气管收缩，哮喘患者禁用。","B":"酚妥拉明为α受体阻断药，不引起支气管收缩，不属哮喘禁用。","C":"酚妥拉明不禁用于哮喘，故不选。","D":"普萘洛尔确应禁用，故不选。"},"id":"ph10_q16","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":16},{"type":"C","stem":"冠心病患者慎用","options":{"A":"普萘洛尔","B":"酚妥拉明","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"酚妥拉明扩张血管、反射性加快心率并增加心肌耗氧，可诱发或加重心绞痛，故冠心病患者慎用。","expl":{"A":"普萘洛尔可降低心肌耗氧，对冠心病心绞痛有益，非慎用。","B":"正确，酚妥拉明反射性加快心率、增加心肌耗氧，冠心病患者慎用。","C":"普萘洛尔对冠心病有利，不属慎用，故不选。","D":"酚妥拉明确需慎用，故不选。"},"id":"ph10_q17","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":17},{"type":"C","stem":"具有拟胆碱样作用的药物是","options":{"A":"普萘洛尔","B":"酚妥拉明","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"酚妥拉明具有拟胆碱样作用，可兴奋胃肠道平滑肌。","expl":{"A":"普萘洛尔无拟胆碱样作用。","B":"正确，酚妥拉明具有拟胆碱样作用。","C":"普萘洛尔无此作用，故不选。","D":"酚妥拉明有此作用，故不选。"},"id":"ph10_q18","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":18},{"type":"C","stem":"具有抗胆碱样作用的药物是","options":{"A":"普萘洛尔","B":"酚妥拉明","C":"两者均是","D":"两者均否"},"answer":["D"],"rationale":"普萘洛尔和酚妥拉明均无抗胆碱（M受体阻断）作用。","expl":{"A":"普萘洛尔无抗胆碱作用。","B":"酚妥拉明为拟胆碱而非抗胆碱作用。","C":"两者均无抗胆碱作用，故不选。","D":"正确，两者均无抗胆碱样作用。"},"id":"ph10_q19","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":19},{"type":"C","stem":"育亨宾","options":{"A":"α 1-R 阻断药","B":"α2-R 阻断药","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"育亨宾为选择性α2受体阻断药。","expl":{"A":"育亨宾不阻断α1受体。","B":"正确，育亨宾选择性阻断α2受体。","C":"育亨宾仅阻断α2受体，故不选。","D":"育亨宾确为α2受体阻断药，故不选。"},"id":"ph10_q20","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":20},{"type":"C","stem":"酚妥拉明","options":{"A":"α 1-R 阻断药","B":"α2-R 阻断药","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"酚妥拉明为非选择性α受体阻断药，同时阻断α1和α2受体。","expl":{"A":"酚妥拉明可阻断α1受体。","B":"酚妥拉明也可阻断α2受体。","C":"正确，酚妥拉明同时阻断α1和α2受体。","D":"酚妥拉明确能阻断α受体，故不选。"},"id":"ph10_q21","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":21},{"type":"C","stem":"哌唑嗪","options":{"A":"α 1-R 阻断药","B":"α2-R 阻断药","C":"两者均是","D":"两者均否"},"answer":["A"],"rationale":"哌唑嗪为选择性α1受体阻断药。","expl":{"A":"正确，哌唑嗪选择性阻断α1受体。","B":"哌唑嗪不阻断α2受体。","C":"哌唑嗪仅阻断α1受体，故不选。","D":"哌唑嗪确为α1受体阻断药，故不选。"},"id":"ph10_q22","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":22},{"type":"C","stem":"吲哚洛尔","options":{"A":"α 1-R 阻断药","B":"α2-R 阻断药","C":"两者均是","D":"两者均否"},"answer":["D"],"rationale":"吲哚洛尔为β受体阻断药，不阻断α1或α2受体。","expl":{"A":"吲哚洛尔不阻断α1受体。","B":"吲哚洛尔不阻断α2受体。","C":"吲哚洛尔不阻断α受体，故不选。","D":"正确，吲哚洛尔为β受体阻断药，两者均否。"},"id":"ph10_q23","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":23},{"type":"X","stem":"可以翻转肾上腺素升压作用的药物有","options":{"A":"阿替洛尔","B":"噻吗洛尔","C":"酚妥拉明","D":"妥拉唑林","E":"氯丙嗪"},"answer":["C","D","E"],"rationale":"酚妥拉明、妥拉唑林为α受体阻断药，氯丙嗪有α受体阻断作用，三者均可翻转肾上腺素升压作用。","expl":{"A":"阿替洛尔为选择性β1受体阻断药，不能翻转肾上腺素升压。","B":"噻吗洛尔为β受体阻断药，不能翻转升压。","C":"正确，酚妥拉明阻断α受体可翻转肾上腺素升压作用。","D":"正确，妥拉唑林为α受体阻断药，可翻转升压作用。","E":"正确，氯丙嗪有α受体阻断作用，可翻转肾上腺素升压。"},"id":"ph10_q24","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":24},{"type":"X","stem":"酚妥拉明的药理作用有","options":{"A":"直接舒张血管","B":"阻 α1 受体","C":"阻 α2 受体","D":"拟胆碱作用","E":"兼有阻 β 受体作用"},"answer":["A","B","C","D"],"rationale":"酚妥拉明直接舒张血管，阻断α1和α2受体，并有拟胆碱作用。","expl":{"A":"正确，酚妥拉明可直接扩张血管。","B":"正确，酚妥拉明阻断α1受体。","C":"正确，酚妥拉明阻断α2受体。","D":"正确，酚妥拉明有拟胆碱样作用。","E":"酚妥拉明无阻断β受体作用。"},"id":"ph10_q25","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":25},{"type":"X","stem":"普萘洛尔能够阻断肾上腺素哪些作用","options":{"A":"心输出量增加","B":"瞳孔扩大","C":"支气管扩张","D":"血管收缩","E":"脂肪分解"},"answer":["A","C","E"],"rationale":"肾上腺素的心输出量增加(β1)、支气管扩张(β2)和脂肪分解(β)均由β受体介导，可被普萘洛尔阻断。","expl":{"A":"正确，心输出量增加经β1受体介导，可被普萘洛尔阻断。","B":"瞳孔扩大为α受体介导，普萘洛尔不能阻断。","C":"正确，支气管扩张经β2受体介导，可被阻断。","D":"血管收缩为α受体介导，普萘洛尔不能阻断。","E":"正确，脂肪分解经β受体介导，可被阻断。"},"id":"ph10_q26","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":26},{"type":"X","stem":"下列关于噻吗洛尔的描述中，哪些是正确的","options":{"A":"β 受体阻断作用强","B":"可以减少房水生成","C":"无缩瞳作用","D":"有调节痉挛作用","E":"常用其滴眼剂"},"answer":["A","B","C","E"],"rationale":"噻吗洛尔β受体阻断作用强，可减少房水生成，无缩瞳和调节痉挛作用，常用其滴眼剂。","expl":{"A":"正确，噻吗洛尔β受体阻断作用强。","B":"正确，减少房水生成而降低眼压。","C":"正确，β受体阻断药不影响瞳孔大小，无缩瞳作用。","D":"错，噻吗洛尔无调节痉挛作用。","E":"正确，治疗青光眼常用其滴眼剂。"},"id":"ph10_q27","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":27},{"type":"X","stem":"选择性阻断 β1受体的药有","options":{"A":"阿替洛尔 （ atenolol）","B":"纳多洛尔 （nadolol）","C":"普萘洛尔 （propranolol）","D":"美托洛尔 （metoprolol）","E":"吲哚洛尔 (pindolol)"},"answer":["A","D"],"rationale":"阿替洛尔和美托洛尔为选择性β1受体阻断药。","expl":{"A":"正确，阿替洛尔选择性阻断β1受体。","B":"纳多洛尔为非选择性β受体阻断药。","C":"普萘洛尔为非选择性β受体阻断药。","D":"正确，美托洛尔选择性阻断β1受体。","E":"吲哚洛尔为非选择性β受体阻断药。"},"id":"ph10_q28","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":28},{"type":"X","stem":"有内在拟交感活性的 β 受体阻断药有","options":{"A":"propranolol","B":"pindolol","C":"esmolol","D":"acebutolol","E":"metoprolol"},"answer":["B","D"],"rationale":"吲哚洛尔和醋丁洛尔具有内在拟交感活性。","expl":{"A":"普萘洛尔无内在拟交感活性。","B":"正确，吲哚洛尔有内在拟交感活性。","C":"艾司洛尔几乎无内在拟交感活性。","D":"正确，醋丁洛尔有内在拟交感活性。","E":"美托洛尔无内在拟交感活性。"},"id":"ph10_q29","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":29},{"type":"X","stem":"酚妥拉明的不良反应有","options":{"A":"低血压","B":"腹痛腹泻","C":"心率失常","D":"过敏反应","E":"心绞痛"},"answer":["A","B","C","E"],"rationale":"酚妥拉明常见不良反应包括低血压、胃肠兴奋所致的腹痛腹泻、心律失常，并可诱发心绞痛。","expl":{"A":"正确，扩血管及阻断α受体可致体位性低血压。","B":"正确，拟胆碱作用兴奋胃肠平滑肌可致腹痛腹泻。","C":"正确，反射性兴奋及β作用可致心律失常。","D":"酚妥拉明不良反应中无典型过敏反应。","E":"正确，反射性加快心率、增加耗氧可诱发心绞痛。"},"id":"ph10_q30","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":30},{"type":"X","stem":"对艾可洛尔的叙述正确的有","options":{"A":"是作用时间较长的 β 受体阻断药","B":"几乎无内在拟交感活性","C":"缺乏膜稳定作用","D":"可用于室上性快速型心率失常的紧急状态","E":"可短时用于伴心动过速、心衰的高血压的危急病例"},"answer":["B","C","D","E"],"rationale":"艾司洛尔为超短效β受体阻断药，几乎无内在拟交感活性、缺乏膜稳定作用，可用于室上性快速型心律失常及伴心动过速、心衰的高血压危急病例。","expl":{"A":"错，艾司洛尔为超短效β受体阻断药，作用时间短。","B":"正确，艾司洛尔几乎无内在拟交感活性。","C":"正确，艾司洛尔缺乏膜稳定作用。","D":"正确，可用于室上性快速型心律失常的紧急状态。","E":"正确，可短时用于伴心动过速、心衰的高血压危急病例。"},"id":"ph10_q31","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":31},{"type":"X","stem":"对纳多洛尔叙述正确的是","options":{"A":"对 β1和对 β2 的亲和力大致相同","B":"阻断作用持续时间长，t1/210-12 小时","C":"肾功不全时需要 β 受体阻断药的首选","D":"可每天给一次药","E":"肾功不全时应调整剂量"},"answer":["A","B","C","D","E"],"rationale":"纳多洛尔为非选择性、长效β受体阻断药，半衰期长可每日一次给药，主要经肾排泄，肾功能不全时需调整剂量。","expl":{"A":"正确，纳多洛尔对β1、β2受体亲和力大致相同，属非选择性阻断药。","B":"正确，纳多洛尔半衰期约10~12小时，作用持久。","C":"正确，肾功能不全需用β受体阻断药时，纳多洛尔可作为选用药之一。","D":"正确，因作用持久，可每日给药一次。","E":"正确，纳多洛尔主要经肾排泄，肾功能不全时应调整剂量。"},"id":"ph10_q32","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":32},{"type":"X","stem":"关于普萘洛尔的禁忌证，下列叙述正确的有","options":{"A":"支气管哮喘","B":"重度房室传导阻滞","C":"窦性心动过缓","D":"心功能不全","E":"高血压"},"answer":["A","B","C","D"],"rationale":"普萘洛尔阻断β2受体可诱发支气管痉挛，阻断β1受体可抑制心脏传导和收缩力，故支气管哮喘、重度房室传导阻滞、窦性心动过缓和心功能不全均属禁忌，而高血压是其适应证。","expl":{"A":"正确，阻断支气管β2受体使支气管平滑肌收缩，可诱发或加重哮喘。","B":"正确，抑制房室传导可加重阻滞，甚至引起心脏停搏。","C":"正确，阻断窦房结β1受体使心率进一步减慢，故窦性心动过缓禁用。","D":"正确，负性肌力作用可加重心功能不全，急性心衰时禁用。","E":"错误，高血压是普萘洛尔的适应证之一，不属于禁忌证。"},"id":"ph10_q33","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":33}]},{"title":"第十一章 中枢神经系统药理学概论","questions":[{"type":"A","stem":"血脑屏障限制药物进入脑组织的主要结构基础是","options":{"A":"脑毛细血管内皮细胞之间的紧密连接","B":"星形胶质细胞足突构成限制物质通过的主要屏障","C":"脉络丛上皮细胞之间的缝隙连接","D":"室管膜细胞及其表面的纤毛","E":"软脑膜与蛛网膜下腔中的脑脊液"},"answer":["A"],"rationale":"血脑屏障由脑毛细血管内皮细胞间的紧密连接、基膜和星形胶质细胞足突共同构成，其中内皮细胞间的紧密连接是限制物质透过的关键结构，故答案为A。脂溶性高、分子小的药物易通过血脑屏障，而水溶性、解离型和大分子药物难以入脑，这是中枢用药需选择高脂溶性药物的原因。","expl":{"A":"正确。内皮细胞间的紧密连接是血脑屏障限制药物透过的关键结构。","B":"星形胶质细胞足突参与构成血脑屏障，但并非限制物质通过的主要屏障。","C":"脉络丛上皮参与脑脊液的生成，不是血脑屏障的主要结构基础。","D":"室管膜细胞衬于脑室壁，与血脑屏障的限制作用无直接关系。","E":"软脑膜和脑脊液不构成药物由血入脑的主要透过屏障。"},"id":"ph11_q01","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":1},{"type":"A","stem":"兴奋性突触后电位（EPSP）产生的主要离子机制是","options":{"A":"突触后膜对Na+通透性增大，Na+内流引起局部去极化","B":"突触后膜对Cl-通透性增大，Cl-内流引起超极化","C":"突触后膜对K+通透性增大，K+外流引起超极化","D":"突触前膜Ca2+内流触发递质囊泡的胞裂外排","E":"突触后膜对Ca2+通透性增大，Ca2+内流引起去极化"},"answer":["A"],"rationale":"兴奋性递质作用于突触后膜受体，使后膜对Na+和K+的通透性增大，以Na+内流为主，产生局部去极化即兴奋性突触后电位，故答案为A。EPSP属局部电位，可进行空间和时间总和；而抑制性递质使后膜对Cl-和K+通透性增大产生超极化，即IPSP。突触前膜Ca2+内流是触发递质释放的环节，不是EPSP的离子基础。","expl":{"A":"正确。Na+内流引起的局部去极化即兴奋性突触后电位。","B":"Cl-内流使后膜超极化，产生的是抑制性突触后电位。","C":"K+外流使后膜超极化，同样属于抑制性突触后电位。","D":"突触前Ca2+内流触发递质释放，不是突触后电位的离子机制。","E":"突触后膜去极化主要依赖Na+内流，而非Ca2+内流。"},"id":"ph11_q02","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":2},{"type":"A","stem":"关于GABA-A受体及其调节药的叙述，正确的是","options":{"A":"GABA-A受体是配体门控氯通道，苯二氮䓬类增加其开放频率，巴比妥类延长其开放时间","B":"GABA-A受体属G蛋白偶联受体，通过开放钾通道产生抑制","C":"苯二氮䓬类可直接开放氯通道，不需要GABA存在","D":"巴比妥类通过增加氯通道开放频率而增强GABA的作用","E":"GABA-A受体激活后使突触后膜去极化，从而提高神经元兴奋性"},"answer":["A"],"rationale":"GABA是中枢最主要的抑制性递质，GABA-A受体本身就是配体门控的氯离子通道，激活后Cl-内流产生IPSP，故答案为A。苯二氮䓬类作用于其变构位点，需有GABA存在时增加氯通道开放频率；巴比妥类则延长通道开放时间，高浓度下可直接开放通道。G蛋白偶联并开放钾通道的是GABA-B受体。","expl":{"A":"正确。二者均增强GABA作用，但分别增加开放频率和延长开放时间。","B":"GABA-B受体才是G蛋白偶联受体，通过开放钾通道产生抑制。","C":"苯二氮䓬类必须有GABA存在才能增强氯通道开放，不能直接开放通道。","D":"增加氯通道开放频率的是苯二氮䓬类，巴比妥类延长开放时间。","E":"GABA-A受体激活引起Cl-内流和超极化，降低神经元兴奋性。"},"id":"ph11_q03","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":3},{"type":"X","stem":"关于中枢多巴胺能神经通路的叙述，正确的有","options":{"A":"黑质-纹状体通路主要调节锥体外系运动功能","B":"中脑-边缘系统和中脑-皮质通路与情绪及精神活动有关","C":"结节-漏斗通路参与催乳素分泌的调节","D":"中枢多巴胺能神经元的胞体主要位于脑干蓝斑核","E":"纹状体多巴胺减少而胆碱能功能相对亢进是帕金森病的病理基础"},"answer":["A","B","C","E"],"rationale":"中枢多巴胺通路有四条：黑质-纹状体调节运动，中脑-边缘系统和中脑-皮质参与情绪与精神活动，结节-漏斗调控催乳素分泌，故A、B、C正确；帕金森病正是黑质多巴胺能神经元变性、纹状体多巴胺减少而胆碱能功能相对亢进所致，E正确。多巴胺能神经元胞体位于黑质和中脑腹侧被盖区，蓝斑核是去甲肾上腺素能神经元胞体所在部位，D错误。","expl":{"A":"正确。该通路受损或受阻即出现锥体外系反应。","B":"正确。抗精神病药阻断此二通路的多巴胺受体而发挥抗精神病作用。","C":"正确。该通路的多巴胺抑制催乳素分泌，被阻断后血中催乳素升高。","D":"蓝斑核集中去甲肾上腺素能神经元胞体，不是多巴胺能神经元的主要核团。","E":"正确。这一失衡是补充多巴胺或阻断胆碱受体治疗帕金森病的依据。"},"id":"ph11_q04","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":4}]},{"title":"第十二章 麻醉药","questions":[{"type":"A","stem":"局麻药的作用机制","options":{"A":"阻滞 Na+内流","B":"阻滞 K+外流","C":"阻滞 CL-内流","D":"阻滞 Ca2+内流","E":"降低静息电位"},"answer":["A"],"rationale":"局麻药阻滞神经细胞膜Na+通道、抑制Na+内流，从而阻断神经冲动的产生和传导。","expl":{"A":"正确，局麻药阻滞Na+通道、抑制Na+内流。","B":"局麻药不阻滞K+外流。","C":"局麻药不阻滞Cl-内流。","D":"局麻药不阻滞Ca2+内流。","E":"局麻药不降低静息电位。"},"id":"ph12_q01","chapter":"第十二章 麻醉药","chapterIdx":11,"num":1},{"type":"A","stem":"为延长局麻药的作用时间并减少吸收，宜采用的措施是","options":{"A":"增加局麻药的用量","B":"加大局麻药的浓度","C":"加入少量的去甲肾上腺素","D":"加入少量肾上腺素","E":"调节药物的 PH 至弱酸性"},"answer":["D"],"rationale":"局麻药液中加入少量肾上腺素可使局部血管收缩，延缓吸收、延长作用时间并减少毒性。","expl":{"A":"增加用量会加重毒性，不能减少吸收。","B":"加大浓度不能减少吸收，反增毒性。","C":"去甲肾上腺素收缩血管过强，易致组织缺血坏死，不宜加入。","D":"正确，加入少量肾上腺素收缩局部血管，减少吸收、延长作用。","E":"弱酸性pH不利于局麻药发挥作用，不能延长作用。"},"id":"ph12_q02","chapter":"第十二章 麻醉药","chapterIdx":11,"num":2},{"type":"A","stem":"蛛网膜下腔麻醉前注射麻黄碱的意义是","options":{"A":"可预防呼吸抑制","B":"可预防发生心率失常","C":"可预防血压下降","D":"可减少局麻药在作用部位吸收","E":"可延长局麻药作用时间"},"answer":["C"],"rationale":"蛛网膜下腔麻醉易致交感神经阻滞、血管扩张而血压下降，术前注射麻黄碱可收缩血管、预防低血压。","expl":{"A":"麻黄碱不用于预防呼吸抑制。","B":"麻黄碱主要升血压，不是预防心律失常。","C":"正确，麻黄碱升血压，可预防腰麻所致的血压下降。","D":"麻黄碱不能减少局麻药在作用部位的吸收。","E":"麻黄碱不能延长局麻药作用时间。"},"id":"ph12_q03","chapter":"第十二章 麻醉药","chapterIdx":11,"num":3},{"type":"A","stem":"局麻药过量中毒发生惊厥，宜选哪个药对抗","options":{"A":"硫酸镁","B":"异戊巴比妥钠","C":"水合氯醛","D":"苯巴比妥","E":"安定"},"answer":["E"],"rationale":"局麻药中毒致中枢兴奋、惊厥，首选地西泮（安定）静脉注射对抗。","expl":{"A":"硫酸镁用于子痫惊厥，非局麻药中毒惊厥首选。","B":"巴比妥类可对抗惊厥，但地西泮更常用、更安全。","C":"水合氯醛非局麻药中毒惊厥的首选。","D":"苯巴比妥可用但非首选，地西泮更常用。","E":"正确，地西泮是局麻药中毒惊厥的首选对抗药。"},"id":"ph12_q04","chapter":"第十二章 麻醉药","chapterIdx":11,"num":4},{"type":"A","stem":"局麻作用时间最长的是","options":{"A":"lidocainE.","B":"procainE.","C":"tetracainE.","D":"popivacainE.","E":"bupivacaine"},"answer":["E"],"rationale":"布比卡因属长效局麻药，局麻作用时间在常用局麻药中最长。","expl":{"A":"利多卡因为中效局麻药。","B":"普鲁卡因为短效局麻药。","C":"丁卡因虽为长效局麻药，但作用时间仍短于布比卡因。","D":"罗哌卡因为长效局麻药，作用时间较长，但不及布比卡因。","E":"正确，布比卡因为长效局麻药，作用时间最长。"},"id":"ph12_q05","chapter":"第十二章 麻醉药","chapterIdx":11,"num":5},{"type":"A","stem":"普鲁卡因不可用于哪种局麻","options":{"A":"蛛网膜下腔麻醉","B":"浸润麻醉","C":"表面麻醉","D":"传导麻醉","E":"硬膜外麻醉"},"answer":["C"],"rationale":"普鲁卡因穿透力弱，不能穿透完整黏膜，故不用于表面麻醉。","expl":{"A":"普鲁卡因可用于蛛网膜下腔麻醉。","B":"普鲁卡因可用于浸润麻醉。","C":"正确，普鲁卡因穿透力弱，不用于表面麻醉。","D":"普鲁卡因可用于传导麻醉。","E":"普鲁卡因可用于硬膜外麻醉。"},"id":"ph12_q06","chapter":"第十二章 麻醉药","chapterIdx":11,"num":6},{"type":"A","stem":"局麻药在炎症组织中","options":{"A":"作用增强","B":"作用减弱","C":"易被灭活","D":"不受影响","E":"无麻醉作用"},"answer":["B"],"rationale":"炎症组织pH偏酸性，使局麻药解离型增多、非解离型减少，不易透过神经膜，故作用减弱。","expl":{"A":"炎症组织中局麻药作用减弱而非增强。","B":"正确，炎症组织pH降低，局麻药作用减弱。","C":"炎症组织不加速局麻药灭活。","D":"炎症组织的酸性环境影响局麻药作用。","E":"并非完全无麻醉作用，只是减弱。"},"id":"ph12_q07","chapter":"第十二章 麻醉药","chapterIdx":11,"num":7},{"type":"A","stem":"关于利用多卡因具有的特征哪项是错误的","options":{"A":"能穿透粘膜，作用比普鲁卡因快、强、持久","B":"安全范围大","C":"引起过敏反应","D":"有抗心律失常作用","E":"可用于各种局麻方法"},"answer":["C"],"rationale":"利多卡因为酰胺类局麻药，一般不引起过敏反应，其余各项均符合利多卡因特点。","expl":{"A":"利多卡因能穿透黏膜，作用比普鲁卡因快、强、持久，正确。","B":"利多卡因安全范围大，正确。","C":"正确（错误项），利多卡因一般不引起过敏反应。","D":"利多卡因有抗心律失常作用，正确。","E":"利多卡因可用于各种局麻方法，正确。"},"id":"ph12_q08","chapter":"第十二章 麻醉药","chapterIdx":11,"num":8},{"type":"A","stem":"比普鲁卡因作用强且毒性大的常用局麻药是","options":{"A":"利多卡因","B":"普鲁卡因","C":"布比卡因","D":"丁卡因","E":"可卡因"},"answer":["D"],"rationale":"丁卡因的作用及毒性均比普鲁卡因强，是常用的强效局麻药。","expl":{"A":"利多卡因作用比普鲁卡因强，但毒性不及丁卡因显著。","B":"普鲁卡因为参照药，作用、毒性均较弱。","C":"布比卡因作用强，但本题所指作用及毒性均强于普鲁卡因者为丁卡因。","D":"正确，丁卡因作用及毒性均比普鲁卡因强。","E":"可卡因毒性大但少用，非本题所指常用局麻药。"},"id":"ph12_q09","chapter":"第十二章 麻醉药","chapterIdx":11,"num":9},{"type":"A","stem":"下列局部麻醉方法中，不应用普鲁卡因是","options":{"A":"浸润麻醉","B":"传导麻醉","C":"蛛网膜下隙麻醉","D":"硬膜外麻醉","E":"表面麻醉"},"answer":["E"],"rationale":"普鲁卡因穿透力差，不能用于表面麻醉。","expl":{"A":"普鲁卡因可用于浸润麻醉。","B":"普鲁卡因可用于传导麻醉。","C":"普鲁卡因可用于蛛网膜下隙麻醉。","D":"普鲁卡因可用于硬膜外麻醉。","E":"正确，普鲁卡因不用于表面麻醉。"},"id":"ph12_q10","chapter":"第十二章 麻醉药","chapterIdx":11,"num":10},{"type":"A","stem":"影响局麻药作用的因素不包括","options":{"A":"神经纤维的粗细","B":"体液的pH","C":"药物的的浓度","D":"肝脏的功能","E":"血管收缩药"},"answer":["D"],"rationale":"神经纤维粗细、体液pH、药物浓度及血管收缩药均影响局麻作用，而肝脏功能不属于影响局麻药作用的因素。","expl":{"A":"神经纤维粗细影响局麻药作用，属影响因素。","B":"体液pH影响局麻药解离与穿透，属影响因素。","C":"药物浓度影响局麻作用，属影响因素。","D":"正确（不包括项），肝脏功能不是影响局麻药作用的因素。","E":"血管收缩药影响吸收与作用时间，属影响因素。"},"id":"ph12_q11","chapter":"第十二章 麻醉药","chapterIdx":11,"num":11},{"type":"B","stem":"普鲁卡因","options":{"A":"可用于心律失常","B":"作用最弱","C":"毒性最大","D":"无血管扩张作用","E":"可升高血压"},"answer":["B"],"rationale":"在所列常用局麻药中，普鲁卡因的局麻作用最弱。","expl":{"A":"利多卡因可用于心律失常，普鲁卡因不用于心律失常。","B":"正确，普鲁卡因局麻作用最弱。","C":"丁卡因毒性最大，非普鲁卡因。","D":"普鲁卡因有轻度血管扩张作用。","E":"普鲁卡因不升高血压。"},"id":"ph12_q12","chapter":"第十二章 麻醉药","chapterIdx":11,"num":12},{"type":"B","stem":"丁卡因","options":{"A":"可用于心律失常","B":"作用最弱","C":"毒性最大","D":"无血管扩张作用","E":"可升高血压"},"answer":["C"],"rationale":"丁卡因是常用局麻药中毒性最大者。","expl":{"A":"丁卡因不用于心律失常。","B":"丁卡因作用强，非最弱。","C":"正确，丁卡因毒性最大。","D":"丁卡因有血管扩张作用。","E":"丁卡因不升高血压。"},"id":"ph12_q13","chapter":"第十二章 麻醉药","chapterIdx":11,"num":13},{"type":"B","stem":"利多卡因","options":{"A":"可用于心律失常","B":"作用最弱","C":"毒性最大","D":"无血管扩张作用","E":"可升高血压"},"answer":["A"],"rationale":"利多卡因有抗心律失常作用，可用于室性心律失常。","expl":{"A":"正确，利多卡因可用于心律失常。","B":"利多卡因作用较强，非最弱。","C":"利多卡因毒性较小，非最大。","D":"利多卡因有血管扩张作用。","E":"利多卡因不升高血压。"},"id":"ph12_q14","chapter":"第十二章 麻醉药","chapterIdx":11,"num":14},{"type":"C","stem":"利多卡因","options":{"A":"浸润麻醉","B":"传导麻醉","C":"两者均可","D":"两者均否"},"answer":["B"],"rationale":"利多卡因穿透力强、作用快，常用于传导麻醉。","expl":{"A":"利多卡因虽可用于浸润麻醉，但本题配对答案为传导麻醉。","B":"正确，利多卡因可用于传导麻醉。","C":"本题利多卡因对应传导麻醉，不选两者均可。","D":"利多卡因可用于传导麻醉，不选两者均否。"},"id":"ph12_q15","chapter":"第十二章 麻醉药","chapterIdx":11,"num":15},{"type":"C","stem":"布比卡因","options":{"A":"浸润麻醉","B":"传导麻醉","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"布比卡因既可用于浸润麻醉，也可用于传导麻醉。","expl":{"A":"布比卡因可用于浸润麻醉。","B":"布比卡因可用于传导麻醉。","C":"正确，布比卡因两者均可。","D":"布比卡因可用于上述麻醉，故不选。"},"id":"ph12_q16","chapter":"第十二章 麻醉药","chapterIdx":11,"num":16},{"type":"C","stem":"普鲁卡因","options":{"A":"浸润麻醉","B":"传导麻醉","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"普鲁卡因可用于浸润麻醉和传导麻醉。","expl":{"A":"普鲁卡因可用于浸润麻醉。","B":"普鲁卡因可用于传导麻醉。","C":"正确，普鲁卡因两者均可。","D":"普鲁卡因两者均可用，故不选。"},"id":"ph12_q17","chapter":"第十二章 麻醉药","chapterIdx":11,"num":17},{"type":"C","stem":"丁卡因","options":{"A":"浸润麻醉","B":"传导麻醉","C":"两者均可","D":"两者均否"},"answer":["D"],"rationale":"丁卡因毒性大、穿透力强，主要用于表面麻醉及腰麻，不用于浸润和传导麻醉。","expl":{"A":"丁卡因毒性大，不用于浸润麻醉。","B":"丁卡因不用于传导麻醉。","C":"丁卡因两者均不用，故不选。","D":"正确，丁卡因不用于浸润及传导麻醉。"},"id":"ph12_q18","chapter":"第十二章 麻醉药","chapterIdx":11,"num":18},{"type":"X","stem":"局麻药、吸收过量可以引起的不良反应是","options":{"A":"血压上升","B":"心脏传导减慢","C":"中枢神经系统先兴奋后抑制","D":"心肌收缩性减弱","E":"呼吸麻痹"},"answer":["B","C","D","E"],"rationale":"局麻药吸收过量可抑制心血管和中枢，表现为心脏传导减慢、心肌收缩力减弱、中枢先兴奋后抑制及呼吸麻痹；血压为下降而非上升。","expl":{"A":"局麻药过量使血管扩张、抑制心血管，表现为血压下降而非上升。","B":"正确，过量可抑制心脏传导。","C":"正确，中枢神经系统先兴奋后抑制。","D":"正确，过量可减弱心肌收缩性。","E":"正确，过量抑制呼吸中枢可致呼吸麻痹。"},"id":"ph12_q19","chapter":"第十二章 麻醉药","chapterIdx":11,"num":19},{"type":"X","stem":"丁卡因有下列作用特点","options":{"A":"作用及毒性比普鲁卡因强约 10 倍","B":"亲脂性及穿透力强","C":"作用较持久","D":"作用快","E":"毒性小"},"answer":["A","B","C","D"],"rationale":"丁卡因亲脂性和穿透力强，作用及毒性约为普鲁卡因的10倍，起效快、作用持久。","expl":{"A":"正确，丁卡因作用及毒性比普鲁卡因强约10倍。","B":"正确，丁卡因亲脂性及穿透力强。","C":"正确，丁卡因作用较持久。","D":"正确，丁卡因起效较快。","E":"错，丁卡因毒性大而非小。"},"id":"ph12_q20","chapter":"第十二章 麻醉药","chapterIdx":11,"num":20},{"type":"X","stem":"影响局麻药作用的因素","options":{"A":"神经纤维的粗细","B":"细胞外液的 PH","C":"药物的浓度","D":"血管收缩药物","E":"局麻药的比重及病人的体位"},"answer":["A","B","C","D","E"],"rationale":"神经纤维粗细、细胞外液pH、药物浓度、血管收缩药以及局麻药比重和病人体位均影响局麻药作用。","expl":{"A":"正确，神经纤维粗细影响局麻药作用。","B":"正确，细胞外液pH影响局麻药解离与穿透。","C":"正确，药物浓度影响局麻作用。","D":"正确，血管收缩药影响吸收与作用时间。","E":"正确，局麻药比重及病人体位影响药液扩散与阻滞平面。"},"id":"ph12_q21","chapter":"第十二章 麻醉药","chapterIdx":11,"num":21},{"type":"A","stem":"硫喷妥钠静脉注射后作用迅速而短暂，其主要原因是","options":{"A":"迅速再分布至脂肪等组织","B":"迅速经肾排泄","C":"迅速经肝代谢","D":"血浆蛋白结合率低","E":"难以透过血脑屏障"},"answer":["A"],"rationale":"硫喷妥钠脂溶性极高，静注后迅速进入脑组织产生麻醉，随后迅速再分布至脂肪和肌肉使脑内浓度下降，故作用快而短，答案为 A。","expl":{"A":"正确，药物自脑组织向脂肪、肌肉再分布，使脑内浓度迅速降低而苏醒。","B":"错误，硫喷妥钠主要经肝代谢和再分布消除，肾排泄不是作用短暂的主因。","C":"错误，肝代谢速度并非其超短效的决定因素，再分布才是关键环节。","D":"错误，其血浆蛋白结合率高，且结合率高低不能解释作用为何短暂。","E":"错误，其脂溶性高，极易透过血脑屏障，正因如此才迅速起效。"},"id":"ph12_q22","chapter":"第十二章 麻醉药","chapterIdx":11,"num":22},{"type":"A","stem":"氯胺酮的麻醉作用特点是","options":{"A":"意识完全消失但镇痛作用很弱","B":"引起分离麻醉，镇痛作用强，苏醒期可出现梦幻和躁动","C":"明显抑制呼吸","D":"有明显骨骼肌松弛作用","E":"使血压明显下降"},"answer":["B"],"rationale":"氯胺酮阻断NMDA受体，选择性抑制痛觉传导而部分保留意识，产生痛觉与意识分离的分离麻醉，镇痛强但苏醒期易致幻觉躁动，故答案为 B。","expl":{"A":"错误，氯胺酮镇痛作用强，这正是其突出优点，并非镇痛弱。","B":"正确，痛觉消失而意识部分保留称分离麻醉，苏醒期精神症状为其缺点。","C":"错误，其对呼吸抑制轻微，有时甚至出现呼吸短暂兴奋。","D":"错误，氯胺酮无肌松作用，反而使骨骼肌张力增高。","E":"错误，氯胺酮兴奋交感神经，使血压升高、心率加快。"},"id":"ph12_q23","chapter":"第十二章 麻醉药","chapterIdx":11,"num":23},{"type":"A","stem":"丙泊酚静脉麻醉的突出特点是","options":{"A":"镇痛作用强","B":"明显肌松作用","C":"兴奋心血管系统","D":"起效快、维持短、苏醒迅速而完全","E":"主要经肺排泄"},"answer":["D"],"rationale":"丙泊酚脂溶性高，静注后迅速分布至脑组织，起效快、维持时间短、苏醒迅速而完全，广泛用于麻醉诱导与维持，故答案为 D。","expl":{"A":"错误，丙泊酚镇痛作用弱，常需复合镇痛药才能满足手术需要。","B":"错误，其肌松作用不明显，气管插管时需合用肌松药。","C":"错误，丙泊酚抑制心血管系统，使血压下降、心率减慢。","D":"正确，起效快、代谢清除快、苏醒完全而舒适，是其最大优点。","E":"错误，丙泊酚主要在肝内代谢，经肺排泄不是其主要消除途径。"},"id":"ph12_q24","chapter":"第十二章 麻醉药","chapterIdx":11,"num":24}]},{"title":"第十三章 镇静催眠药","questions":[{"type":"A","stem":"地西泮的作用机制是","options":{"A":"不通过受体，直接抑制中枢","B":"作用于苯二氮卓受体，增加 GABA 与 GABA 受体的亲和力","C":"作用于 GABA 受体，增加体内抑制性递质的作用","D":"诱导生成一种新蛋白质而起作用","E":"以上都不是"},"answer":["C"],"rationale":"地西泮与苯二氮卓受体结合，增强中枢抑制性递质GABA的抑制作用，从而产生中枢抑制效应。","expl":{"A":"错，地西泮需经受体介导，并非直接抑制中枢。","B":"不选，地西泮直接结合的是苯二氮卓受体，增强GABA效应为核心机制。","C":"正确，地西泮通过增强抑制性递质GABA的作用发挥中枢抑制。","D":"错，诱导新蛋白质合成是糖皮质激素等的作用方式。","E":"错，C项符合地西泮作用机制。"},"id":"ph13_q01","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":1},{"type":"A","stem":"地西泮抗焦虑作用的主要部位是","options":{"A":"中脑网状结构","B":"下丘脑","C":"边缘系统","D":"大脑皮层","E":"纹状体"},"answer":["C"],"rationale":"苯二氮卓受体在边缘系统（海马、杏仁核）分布密集，地西泮抗焦虑作用的主要部位为边缘系统。","expl":{"A":"错，中脑网状结构主要与睡眠觉醒有关。","B":"错，下丘脑不是地西泮抗焦虑的主要部位。","C":"正确，边缘系统是地西泮抗焦虑作用的主要部位。","D":"错，大脑皮层非其抗焦虑主要作用部位。","E":"错，纹状体主要与锥体外系功能有关。"},"id":"ph13_q02","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":2},{"type":"A","stem":"苯巴比妥钠连续应用产生耐受性的主要原因是","options":{"A":"再分布于脂肪组织","B":"排泄加快","C":"被假性胆碱酯酶破坏","D":"被单胺氧化酶破坏","E":"诱导肝药酶使自身代谢加快"},"answer":["E"],"rationale":"苯巴比妥为肝药酶诱导剂，长期应用诱导肝药酶加速自身代谢，是产生耐受性的主要原因。","expl":{"A":"错，再分布于脂肪组织是硫喷妥钠作用短暂的原因。","B":"错，排泄加快并非耐受的主要原因。","C":"错，假性胆碱酯酶破坏的是琥珀胆碱。","D":"错，单胺氧化酶代谢的是儿茶酚胺类递质。","E":"正确，诱导肝药酶加速自身代谢导致耐受。"},"id":"ph13_q03","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":3},{"type":"A","stem":"下列药物中 t1/2 最长的是","options":{"A":"地西泮","B":"氯氮卓","C":"氟西泮","D":"奥可西泮","E":"三唑仑"},"answer":["C"],"rationale":"氟西泮及其活性代谢物半衰期长，总作用持续时间在所列药物中最长。","expl":{"A":"错，地西泮半衰期约20~80小时，较氟西泮短。","B":"错，氯氮卓为长效类但作用时间不及氟西泮。","C":"正确，氟西泮代谢物半衰期长，作用时间最长。","D":"错，奥沙西泮为短效苯二氮卓类。","E":"错，三唑仑为短效催眠药。"},"id":"ph13_q04","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":4},{"type":"A","stem":"有关地西泮的叙述，错误的为","options":{"A":"口服的肌注吸收迅速","B":"口服治疗量对呼吸及循环影响小","C":"能治疗癫痫持续状态","D":"较大量可引起全身麻醉","E":"其代谢产物也有作用"},"answer":["D"],"rationale":"地西泮无全身麻醉作用，即使较大剂量也不能引起全身麻醉，故D为错误叙述。","expl":{"A":"不选，地西泮口服吸收快而完全。","B":"不选，治疗量对呼吸循环影响小，较安全。","C":"不选，地西泮是癫痫持续状态的首选药之一。","D":"正确，地西泮无全身麻醉作用。","E":"不选，其代谢产物去甲地西泮等仍有活性。"},"id":"ph13_q05","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":5},{"type":"A","stem":"治疗新生儿黄疸并发惊厥宜选用","options":{"A":"水合氯醛","B":"异戊巴比妥","C":"地西泮","D":"苯巴比妥","E":"甲丙氨酶"},"answer":["D"],"rationale":"苯巴比妥能诱导肝药酶和葡萄糖醛酸转移酶，促进胆红素代谢，同时可抗惊厥，故首选。","expl":{"A":"错，水合氯醛对新生儿黄疸无利胆作用。","B":"错，异戊巴比妥不用于新生儿黄疸惊厥。","C":"错，地西泮可与胆红素竞争白蛋白，不宜选用。","D":"正确，苯巴比妥促进胆红素排泄且能抗惊厥。","E":"错，甲丙氨酯无此适应症。"},"id":"ph13_q06","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":6},{"type":"A","stem":"巴比妥类禁用于下列哪种病人","options":{"A":"高血压患者精神紧张","B":"甲亢病人兴奋失眠","C":"肺功能不全病人烦躁不安","D":"手术前病人恐惧心理","E":"神经官能症性失眠"},"answer":["C"],"rationale":"巴比妥类抑制呼吸中枢，肺功能不全者呼吸储备差，易诱发或加重呼吸抑制，故禁用。","expl":{"A":"错，精神紧张可用小剂量镇静。","B":"错，甲亢失眠可慎用镇静催眠药。","C":"正确，肺功能不全者禁用巴比妥类。","D":"错，手术前可用作麻醉前给药。","E":"错，神经官能症失眠可用巴比妥类。"},"id":"ph13_q07","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":7},{"type":"A","stem":"地西泮不用于","options":{"A":"焦虑症和焦虑性失眠","B":"麻醉前给药","C":"高热惊厥","D":"癫痫持续状态","E":"诱导麻醉"},"answer":["E"],"rationale":"地西泮无麻醉作用，不能用于诱导麻醉，诱导麻醉多选用硫喷妥钠。","expl":{"A":"错，地西泮可用于焦虑症及焦虑性失眠。","B":"错，地西泮可用作麻醉前给药。","C":"错，地西泮可用于高热惊厥。","D":"错，地西泮是癫痫持续状态首选药。","E":"正确，地西泮无麻醉作用，不用于诱导麻醉。"},"id":"ph13_q08","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":8},{"type":"A","stem":"苯二氮卓类中毒的特异解毒药是","options":{"A":"尼可刹米","B":"纳络酮","C":"氟马西尼","D":"钙剂","E":"美解眠"},"answer":["C"],"rationale":"氟马西尼是苯二氮卓受体的特异性拮抗剂，可竞争性拮抗苯二氮卓类的中毒效应。","expl":{"A":"错，尼可刹米为呼吸中枢兴奋药。","B":"错，纳洛酮是阿片受体拮抗剂。","C":"正确，氟马西尼为苯二氮卓类中毒的特效解毒药。","D":"错，钙剂与苯二氮卓中毒无关。","E":"错，美解眠主要用于巴比妥类中毒。"},"id":"ph13_q09","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":9},{"type":"A","stem":"苯巴比妥过量中毒，为了促使其快速排泄","options":{"A":"碱化尿液，使解离度增大，增加肾小管再吸收","B":"碱化尿液，使解离度减小，增加肾小管再吸收","C":"碱化尿液，使解离度增大，减少肾小管再吸收","D":"酸化尿液，使解离度增大，减少肾小管再吸收","E":"以上均不对"},"answer":["C"],"rationale":"苯巴比妥为弱酸性药物，碱化尿液使其解离度增大，肾小管重吸收减少，排泄加快。","expl":{"A":"错，碱化尿液是减少而非增加肾小管重吸收。","B":"错，碱化尿液使解离度增大而非减小。","C":"正确，碱化尿液增大解离度、减少重吸收促排泄。","D":"错，应碱化而非酸化尿液。","E":"错，C项正确。"},"id":"ph13_q10","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":10},{"type":"A","stem":"下列巴比妥类药物中，起效最快、维持最短的经物是","options":{"A":"苯巴比妥","B":"司可巴比妥","C":"硫喷妥","D":"巴比妥","E":"戊巴比妥"},"answer":["C"],"rationale":"硫喷妥脂溶性高，静脉注射后迅速入脑起效，随后快速再分布使作用短暂。","expl":{"A":"错，苯巴比妥为长效类。","B":"错，司可巴比妥为短效类。","C":"正确，硫喷妥起效最快、维持最短。","D":"错，巴比妥为长效类。","E":"错，戊巴比妥为中短效类。"},"id":"ph13_q11","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":11},{"type":"A","stem":"镇静催眠药中有抗癫痫作用的药物是","options":{"A":"苯巴比妥","B":"司可巴比妥","C":"巴比妥","D":"硫喷妥","E":"以是都不是"},"answer":["A"],"rationale":"苯巴比妥具有抗癫痫作用，可用于癫痫大发作和癫痫持续状态。","expl":{"A":"正确，苯巴比妥有抗癫痫作用。","B":"错，司可巴比妥无抗癫痫用途。","C":"错，巴比妥无抗癫痫用途。","D":"错，硫喷妥用于静脉麻醉。","E":"错，A项正确。"},"id":"ph13_q12","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":12},{"type":"A","stem":"对各型癫痫均有一定作用的苯二氮卓类药物是","options":{"A":"地西泮","B":"氯氮卓","C":"三唑仑","D":"氯硝西泮","E":"奥沙西泮"},"answer":["D"],"rationale":"氯硝西泮抗癫痫谱广，对各型癫痫均有较好疗效，是苯二氮卓类中抗癫痫作用突出者。","expl":{"A":"错，地西泮主要用于癫痫持续状态。","B":"错，氯氮卓少用于抗癫痫。","C":"错，三唑仑为催眠药，无抗癫痫用途。","D":"正确，氯硝西泮对各型癫痫均有一定作用。","E":"错，奥沙西泮无突出抗癫痫作用。"},"id":"ph13_q13","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":13},{"type":"A","stem":"苯二氮卓类受体的分布与何种中枢性抑制递质的分布一致？","options":{"A":"多巴胺","B":"脑啡肽","C":"咪唑啉","D":"i－氨基丁酸","E":"以上都不是"},"answer":["D"],"rationale":"苯二氮卓受体与GABAA受体相伴存在，其分布与抑制性递质γ-氨基丁酸（GABA）分布一致。","expl":{"A":"错，多巴胺与苯二氮卓受体分布不一致。","B":"错，脑啡肽属内阿片肽。","C":"错，咪唑啉受体与可乐定作用有关。","D":"正确，与γ-氨基丁酸（GABA）分布一致。","E":"错，D项正确。"},"id":"ph13_q14","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":14},{"type":"A","stem":"引起病人对巴比妥类药物成瘾的主要原因是","options":{"A":"使病人产生欣快感","B":"能诱导肝药酶","C":"抑制肝药酶","D":"停药后快动眼睡眠时间延长，梦魇增多","E":"以是都不是"},"answer":["D"],"rationale":"巴比妥类缩短快动眼睡眠，停药后快动眼睡眠反跳性延长、梦魇增多，促使病人继续用药而成瘾。","expl":{"A":"错，欣快感不是巴比妥类成瘾的主要原因。","B":"错，诱导肝药酶是产生耐受性的机制。","C":"错，巴比妥类为诱导而非抑制肝药酶。","D":"正确，停药后REM反跳、梦魇增多促进成瘾。","E":"错，D项正确。"},"id":"ph13_q15","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":15},{"type":"A","stem":"地西泮的药理作用不包括","options":{"A":"抗焦虑","B":"镇静催眠","C":"抗惊厥","D":"肌肉松弛","E":"抗晕动"},"answer":["E"],"rationale":"地西泮无抗晕动作用，抗晕动药主要为东莨菪碱、苯海拉明等。","expl":{"A":"错，地西泮有镇静催眠作用。","B":"错，地西泮有抗焦虑作用。","C":"错，地西泮有抗惊厥作用。","D":"错，地西泮有中枢性肌肉松弛作用。","E":"正确，地西泮无抗晕动作用。"},"id":"ph13_q16","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":16},{"type":"A","stem":"苯二氮卓类无下列哪种不良反应？","options":{"A":"头昏","B":"嗜睡","C":"乏力","D":"共济失调","E":"口干"},"answer":["E"],"rationale":"口干为抗胆碱药（阿托品类）的不良反应，苯二氮卓类无此不良反应。","expl":{"A":"错，头昏是苯二氮卓类常见不良反应。","B":"错，嗜睡是苯二氮卓类常见不良反应。","C":"错，乏力是苯二氮卓类常见不良反应。","D":"错，共济失调是苯二氮卓类不良反应。","E":"正确，口干非苯二氮卓类不良反应。"},"id":"ph13_q17","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":17},{"type":"A","stem":"地西泮的药理作用不包括","options":{"A":"镇静催眠","B":"抗焦虑","C":"抗震颤麻痹","D":"抗惊厥","E":"抗癫痫"},"answer":["C"],"rationale":"抗震颤麻痹是左旋多巴、苯海索等抗帕金森药的作用，地西泮无此作用。","expl":{"A":"错，地西泮有镇静催眠作用。","B":"错，地西泮有抗焦虑作用。","C":"正确，地西泮无抗震颤麻痹作用。","D":"错，地西泮有抗惊厥作用。","E":"错，地西泮有抗癫痫作用。"},"id":"ph13_q18","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":18},{"type":"A","stem":"下列哪和种情况不宜用巴比妥类催眠药？","options":{"A":"焦虑性失眠","B":"麻醉前给药","C":"高热惊厥","D":"肺心病引起的失眠","E":"癫痫"},"answer":["D"],"rationale":"肺心病患者呼吸功能不全，巴比妥类抑制呼吸中枢，故不宜用于其失眠。","expl":{"A":"错，焦虑性失眠可用巴比妥类。","B":"错，巴比妥类可作麻醉前给药。","C":"错，巴比妥类可用于高热惊厥。","D":"正确，肺心病失眠禁用巴比妥类。","E":"错，苯巴比妥可用于癫痫。"},"id":"ph13_q19","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":19},{"type":"A","stem":"下列哪种药物不属于巴比妥类？","options":{"A":"司可巴比妥","B":"鲁米那","C":"格鲁米特","D":"硫喷妥","E":"戊巴比妥"},"answer":["C"],"rationale":"格鲁米特（导眠能）属哌啶二酮类，不属于巴比妥类。","expl":{"A":"错，司可巴比妥为巴比妥类。","B":"错，鲁米那即苯巴比妥，属巴比妥类。","C":"正确，格鲁米特不属于巴比妥类。","D":"错，硫喷妥为巴比妥类。","E":"错，戊巴比妥为巴比妥类。"},"id":"ph13_q20","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":20},{"type":"A","stem":"巴比妥类产生镇静催眠作用的机理是","options":{"A":"抑制中脑及网状结构中的多突触通路","B":"抑制大脑边缘系统的海马和杏仁核","C":"抑制脑干网状结构上行激活系统","D":"抑制脑室－导水管周围灰质","E":"以上均不是"},"answer":["C"],"rationale":"巴比妥类主要抑制脑干网状结构上行激活系统，使大脑皮层由兴奋转入抑制而催眠。","expl":{"A":"错，抑制多突触通路与肌松有关。","B":"错，抑制边缘系统是苯二氮卓类抗焦虑部位。","C":"正确，抑制脑干网状结构上行激活系统。","D":"错，导水管周围灰质与镇痛有关。","E":"错，C项正确。"},"id":"ph13_q21","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":21},{"type":"A","stem":"关于 g－氨基丁酸（GABA）的描述，哪一种是错误的？","options":{"A":"GABA 是中枢神经系统的抑制性递质","B":"当脑内 GABA 水平降低时可引起惊厥发作","C":"地西泮的中枢性肌肉松弛作用与增强脊髓中 GABA 作用有关","D":"癫痫患者大脑皮质 GABA 含量减少，苯巴比妥的抗癫痫作用与其增加脑内GABA 含量有关","E":"丙戊酸钠是一种抑制 GABA 生物合成的药物"},"answer":["E"],"rationale":"丙戊酸钠抑制GABA转氨酶、减少GABA降解而升高脑内GABA含量，并非抑制其合成。","expl":{"A":"不选，GABA是中枢抑制性递质。","B":"不选，脑内GABA降低可致惊厥。","C":"不选，地西泮中枢肌松与增强脊髓GABA作用有关。","D":"不选，苯巴比妥可增加脑内GABA含量。","E":"正确，丙戊酸钠抑制GABA降解而非合成。"},"id":"ph13_q22","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":22},{"type":"A","stem":"没有成瘾作用的镇静催眠药是","options":{"A":"苯巴比妥","B":"水合氯醛","C":"甲丙氨酯","D":"地西泮","E":"以上都不是"},"answer":["E"],"rationale":"所列各类镇静催眠药长期应用均可产生耐受性和依赖性，均有成瘾作用。","expl":{"A":"错，苯巴比妥长期使用可成瘾。","B":"错，水合氯醛长期使用可成瘾。","C":"错，甲丙氨酯长期使用可成瘾。","D":"错，地西泮可产生依赖性。","E":"正确，以上药物均有成瘾作用。"},"id":"ph13_q23","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":23},{"type":"A","stem":"地西泮的抗焦虑作用主要是由于","options":{"A":"增强中枢神经递质 g－氨基丁酸的作用","B":"抑制脊髓多突触的反射作用","C":"抑制网状结构上行激活系统","D":"抑制大脑－丘脑异常电活动扩散","E":"阻断中脑－边缘系统的多巴胺通路"},"answer":["A"],"rationale":"地西泮抗焦虑作用主要与增强中枢抑制性递质GABA的作用有关。","expl":{"A":"正确，增强GABA的作用是其抗焦虑基础。","B":"错，抑制脊髓多突触反射是其中枢肌松机制。","C":"错，抑制网状结构上行激活系统是巴比妥类催眠机制。","D":"错，抑制异常电活动扩散与抗癫痫有关。","E":"错，阻断中脑-边缘多巴胺通路是抗精神病药机制。"},"id":"ph13_q24","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":24},{"type":"A","stem":"对快波睡眠时间影响小，成瘾性较轻的催眠药是","options":{"A":"苯巴比妥","B":"地西泮","C":"戊巴比妥","D":"苯妥英钠","E":"氯丙嗪"},"answer":["B"],"rationale":"苯二氮卓类对快波睡眠影响较小、成瘾性较轻，地西泮属于此类。","expl":{"A":"错，苯巴比妥明显缩短快波睡眠。","B":"正确，地西泮对快波睡眠影响小、成瘾轻。","C":"错，戊巴比妥属巴比妥类，缩短REM。","D":"错，苯妥英钠为抗癫痫药。","E":"错，氯丙嗪为抗精神病药。"},"id":"ph13_q25","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":25},{"type":"B","stem":"癫痫持续状态的首选药物","options":{"A":"地西泮","B":"硫喷妥钠","C":"水合氯醛","D":"吗啡","E":"硫酸镁"},"answer":["A"],"rationale":"地西泮静脉注射起效快、安全，是癫痫持续状态的首选药物。","expl":{"A":"正确，地西泮为癫痫持续状态首选。","B":"错，硫喷妥钠用于静脉麻醉。","C":"错，水合氯醛非首选。","D":"错，吗啡可抑制呼吸，不宜用于癫痫。","E":"错，硫酸镁用于子痫。"},"id":"ph13_q26","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":26},{"type":"B","stem":"作静脉麻醉的首选药","options":{"A":"地西泮","B":"硫喷妥钠","C":"水合氯醛","D":"吗啡","E":"硫酸镁"},"answer":["B"],"rationale":"硫喷妥钠起效快、作用短，是临床常用的静脉麻醉药。","expl":{"A":"错，地西泮无麻醉作用。","B":"正确，硫喷妥钠为静脉麻醉首选药。","C":"错，水合氯醛为催眠药。","D":"错，吗啡为镇痛药。","E":"错，硫酸镁为抗惊厥药。"},"id":"ph13_q27","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":27},{"type":"B","stem":"心源性哮喘的首选药","options":{"A":"地西泮","B":"硫喷妥钠","C":"水合氯醛","D":"吗啡","E":"硫酸镁"},"answer":["D"],"rationale":"吗啡可扩张外周血管、减轻心脏前后负荷并缓解呼吸困难，是心源性哮喘的首选药。","expl":{"A":"错，地西泮不是心源性哮喘首选。","B":"错，硫喷妥钠为麻醉药。","C":"错，水合氯醛为催眠药。","D":"正确，吗啡是心源性哮喘首选药。","E":"错，硫酸镁用于子痫。"},"id":"ph13_q28","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":28},{"type":"B","stem":"治疗子痫的首选药物","options":{"A":"地西泮","B":"硫喷妥钠","C":"水合氯醛","D":"吗啡","E":"硫酸镁"},"answer":["E"],"rationale":"硫酸镁可解除血管痉挛、降低血压并抗惊厥，是子痫的首选药物。","expl":{"A":"错，地西泮仅作辅助。","B":"错，硫喷妥钠为麻醉药。","C":"错，水合氯醛非首选。","D":"错，吗啡抑制呼吸，不宜用于子痫。","E":"正确，硫酸镁为子痫首选药。"},"id":"ph13_q29","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":29},{"type":"B","stem":"作用维持最长的巴比妥药物","options":{"A":"苯巴比妥","B":"司可巴比妥","C":"戊巴比妥","D":"硫喷妥","E":"异戊巴比妥"},"answer":["A"],"rationale":"苯巴比妥为长效巴比妥类，作用维持时间最长（约6~8小时）。","expl":{"A":"正确，苯巴比妥属长效类，作用维持最长。","B":"错误，司可巴比妥属短效类，维持约2~3小时。","C":"错误，戊巴比妥属中效类，维持约3~6小时。","D":"错误，硫喷妥属超短效类，仅维持约15分钟。","E":"错误，异戊巴比妥属中效类，维持时间短于苯巴比妥。"},"id":"ph13_q30","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":30},{"type":"B","stem":"作用维持最短的巴比妥类药物","options":{"A":"苯巴比妥","B":"司可巴比妥","C":"戊巴比妥","D":"硫喷妥","E":"异戊巴比妥"},"answer":["D"],"rationale":"硫喷妥钠为超短效巴比妥类，静脉给药后迅速入脑、再快速再分布，作用仅维持约15分钟，故维持最短。","expl":{"A":"错误，苯巴比妥为长效类。","B":"错误，司可巴比妥为短效类。","C":"错误，戊巴比妥为中效类。","D":"正确，硫喷妥为超短效类，作用维持最短。","E":"错误，异戊巴比妥为中效类。"},"id":"ph13_q31","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":31},{"type":"C","stem":"三唑仑的用途是","options":{"A":"镇静催眠","B":"治疗破伤风惊厥","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"三唑仑为苯二氮卓类，具有镇静催眠作用，也具有抗惊厥作用，可用于破伤风惊厥。","expl":{"A":"不完整，镇静催眠是其用途之一。","B":"不完整，治疗破伤风惊厥是其用途之一。","C":"正确，两者均可。","D":"错，三唑仑具镇静催眠及抗惊厥作用。"},"id":"ph13_q32","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":32},{"type":"C","stem":"水合氯醛的用途是","options":{"A":"镇静催眠","B":"治疗破伤风惊厥","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"水合氯醛既有镇静催眠作用，又有抗惊厥作用，可用于破伤风惊厥。","expl":{"A":"不完整，镇静催眠为其用途之一。","B":"不完整，治疗破伤风惊厥为其用途之一。","C":"正确，两者均可。","D":"错，水合氯醛两者均可。"},"id":"ph13_q33","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":33},{"type":"C","stem":"治疗癫痫持续状态和小儿惊厥","options":{"A":"氯丙嗪","B":"苯巴比妥","C":"两者均可","D":"两者均否"},"answer":["B"],"rationale":"苯巴比妥可治疗癫痫持续状态和小儿惊厥，氯丙嗪无此作用。","expl":{"A":"错，氯丙嗪不用于癫痫和小儿惊厥。","B":"正确，苯巴比妥两者均可治疗。","C":"错，仅苯巴比妥有效。","D":"错，苯巴比妥有效。"},"id":"ph13_q34","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":34},{"type":"C","stem":"治疗晕车晕船引起的呕吐","options":{"A":"氯丙嗪","B":"苯巴比妥","C":"两者均可","D":"两者均否"},"answer":["D"],"rationale":"氯丙嗪镇吐对前庭性晕动病无效，苯巴比妥无抗晕动作用，故两者均不宜。","expl":{"A":"错，氯丙嗪对晕动病呕吐无效。","B":"错，苯巴比妥无抗晕动镇吐作用。","C":"错，两者均不能治疗晕动病呕吐。","D":"正确，两者均否。"},"id":"ph13_q35","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":35},{"type":"X","stem":"苯二氮卓类具有下列哪些药理作用？","options":{"A":"镇静催眠作用","B":"抗焦虑作用","C":"抗惊厥作用","D":"镇吐作用","E":"抗晕动作用"},"answer":["A","B","C"],"rationale":"苯二氮卓类具有镇静催眠、抗焦虑、抗惊厥作用，但无镇吐和抗晕动作用。","expl":{"A":"正确，有镇静催眠作用。","B":"正确，有抗焦虑作用。","C":"正确，有抗惊厥作用。","D":"错，无镇吐作用。","E":"错，无抗晕动作用。"},"id":"ph13_q36","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":36},{"type":"X","stem":"地西泮用作麻醉前给药的优点有","options":{"A":"安全范围大","B":"镇静作用发生快","C":"使病人对手术中不良反应不复记忆","D":"减少麻醉药的用量","E":"缓解病人对手术的恐惧情绪"},"answer":["A","B","C","D","E"],"rationale":"地西泮安全范围大、起效快、有遗忘作用，可减少麻醉药用量并缓解恐惧，均是其麻醉前给药的优点。","expl":{"A":"正确，安全范围大。","B":"正确，镇静作用发生快。","C":"正确，产生顺行性遗忘。","D":"正确，可减少麻醉药用量。","E":"正确，缓解对手术的恐惧。"},"id":"ph13_q37","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":37},{"type":"X","stem":"关于苯二氮卓类抗焦虑作用，下列叙述哪些正确？","options":{"A":"小于镇静剂量即有良好的抗焦虑作用","B":"抗焦虑作用的部位在边缘系统","C":"对持续性症状且选用长效类药物","D":"对间断性严重焦虑者宜选用中、短效类药物","E":"地西泮和氯氮卓是常用的抗焦虑药"},"answer":["A","B","C","D","E"],"rationale":"苯二氮卓类小剂量即抗焦虑、作用部位在边缘系统，持续性选长效、间断性选短效，地西泮和氯氮卓为常用药。","expl":{"A":"正确，小于镇静剂量即抗焦虑。","B":"正确，抗焦虑部位在边缘系统。","C":"正确，持续性症状宜选长效类。","D":"正确，间断性严重焦虑宜选中短效类。","E":"正确，两者均为常用抗焦虑药。"},"id":"ph13_q38","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":38},{"type":"X","stem":"苯二氮卓类可能引起下列哪些不良反应？","options":{"A":"嗜睡","B":"共济失调","C":"依赖性","D":"成瘾性","E":"长期使用后突然停药可出现戒断症状"},"answer":["A","B","C","D","E"],"rationale":"苯二氮卓类可引起嗜睡、共济失调，长期使用可产生依赖和成瘾，骤停出现戒断症状。","expl":{"A":"正确，可致嗜睡。","B":"正确，可致共济失调。","C":"正确，可产生依赖性。","D":"正确，可产生成瘾性。","E":"正确，骤停可出现戒断症状。"},"id":"ph13_q39","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":39},{"type":"X","stem":"关于苯二氮卓类的不良反应特点，下列哪些是正确的？","options":{"A":"过量致急性中毒和呼吸抑制","B":"安全范围比巴妥类大","C":"可透过胎盘屏障和随乳汁分泌，孕妇和哺乳妇女忌用","D":"长期作药仍可产生耐受性","E":"与巴比妥类相比，其戒断症状发生较迟、较轻"},"answer":["A","B","C","D","E"],"rationale":"苯二氮卓类过量可致中毒和呼吸抑制，安全范围大于巴比妥类，可透过胎盘和乳汁，长期用可耐受，戒断较轻迟。","expl":{"A":"正确，过量可急性中毒和呼吸抑制。","B":"正确，安全范围比巴比妥类大。","C":"正确，可透过胎盘和乳汁，孕妇哺乳忌用。","D":"正确，长期使用仍可耐受。","E":"正确，戒断症状较迟、较轻。"},"id":"ph13_q40","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":40},{"type":"X","stem":"巴比妥类可能出现下列哪些不良反应","options":{"A":"眩晕、困倦","B":"精神运动不协调","C":"偶见致剥脱性皮炎","D":"中等剂量即可轻度抑制呼吸中枢","E":"严重肺功能不全或颅脑损伤致呼吸抑制者禁用"},"answer":["A","B","C","D","E"],"rationale":"巴比妥类可引起眩晕困倦、共济失调、偶见剥脱性皮炎，中等剂量抑制呼吸，肺功能不全者禁用。","expl":{"A":"正确，可引起眩晕、困倦。","B":"正确，可引起精神运动不协调。","C":"正确，偶可致剥脱性皮炎。","D":"正确，中等剂量即轻度抑制呼吸。","E":"正确，严重肺功能不全者禁用。"},"id":"ph13_q41","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":41},{"type":"X","stem":"巴比妥类镇静催眠药的特点是","options":{"A":"连续久服可引起习惯性","B":"突然停药易发生反跳现象","C":"长期使用突然停药可使梦魇增多","D":"长期使用突然停药可使快动眼时间延长","E":"长期使用可以成瘾"},"answer":["A","B","C","D","E"],"rationale":"巴比妥类久用可成瘾和产生习惯性，停药易反跳、REM延长、梦魇增多。","expl":{"A":"正确，连续久服可引起习惯性。","B":"正确，突然停药易反跳。","C":"正确，停药可使梦魇增多。","D":"正确，停药使REM时间延长。","E":"正确，长期使用可成瘾。"},"id":"ph13_q42","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":42},{"type":"X","stem":"关于巴比妥类剂量的叙述，下列哪些是正确的？","options":{"A":"小剂量产生镇静作用","B":"必须用到镇静剂量才有抗焦虑作用","C":"剂量由小到大，可相继出现镇静、催眠、抗惊厥、麻醉作用","D":"中等量可轻度抑制呼吸中枢","E":"10 倍催眠剂量可致病人死亡"},"answer":["A","B","C","D","E"],"rationale":"巴比妥类剂量由小到大相继出现镇静、催眠、抗惊厥、麻醉作用，中等量抑制呼吸，10倍催眠量可致死。","expl":{"A":"正确，小剂量产生镇静。","B":"正确，镇静剂量才有抗焦虑作用。","C":"正确，随剂量增大出现镇静至麻醉作用。","D":"正确，中等量轻度抑制呼吸。","E":"正确，10倍催眠量可致死。"},"id":"ph13_q43","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":43},{"type":"X","stem":"关于苯二氮卓类的作用机制，下列哪些是正确的？","options":{"A":"促进 GABA 与 GABAA 受体结合","B":"促进 Cl－通道开放","C":"使 Cl－开放时间处长","D":"使用权 Cl－ 内流增大","E":"使用权 Cl－通道开放的频率增加"},"answer":["A","E"],"rationale":"苯二氮卓类促进GABA与GABAA受体结合，并增加氯离子通道开放频率；延长开放时间的是巴比妥类。","expl":{"A":"正确，促进GABA与GABAA受体结合。","B":"错，不直接促进通道开放，而是增频。","C":"错，延长Cl-开放时间是巴比妥类作用。","D":"错，并非直接增大Cl-内流。","E":"正确，增加Cl-通道开放频率。"},"id":"ph13_q44","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":44},{"type":"X","stem":"关于苯二氮卓类体内过程，下列叙述哪些正确？","options":{"A":"口服吸收良好","B":"与血浆蛋白结合率高","C":"分布容积大","D":"脑脊液中浓度与血清游离药物浓度相等","E":"主要在肝脏进行生物转化"},"answer":["A","B","C","D","E"],"rationale":"苯二氮卓类口服吸收良好、血浆蛋白结合率高、分布容积大，脑脊液浓度与游离药物浓度相等，主要经肝代谢。","expl":{"A":"正确，口服吸收良好。","B":"正确，血浆蛋白结合率高。","C":"正确，分布容积大。","D":"正确，脑脊液浓度与血清游离浓度相等。","E":"正确，主要在肝内生物转化。"},"id":"ph13_q45","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":45},{"type":"X","stem":"短期内反复应用巴比妥类产生耐受性的主要原因是","options":{"A":"血浆蛋白结合率高，消除缓慢","B":"神经组织对药物产生适应症","C":"促进肝细胞葡萄糖醛酸转移酶的生成","D":"诱导肝药酶加速自身代谢","E":"以上均不是"},"answer":["B","D"],"rationale":"短期内反复应用产生耐受性，与神经组织适应性和诱导肝药酶加速自身代谢有关。","expl":{"A":"错，蛋白结合率高、消除缓慢非耐受原因。","B":"正确，神经组织产生适应性。","C":"错，促进葡萄糖醛酸转移酶是利胆机制。","D":"正确，诱导肝药酶加速自身代谢。","E":"错，B、D正确。"},"id":"ph13_q46","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":46},{"type":"X","stem":"下述哪些疾病可应用苯巴比妥？","options":{"A":"甲亢病人 的精神紧张","B":"神经衰弱所致的失眠","C":"小儿高热所致的失眠","D":"癫痫持续状态","E":"以是均不是"},"answer":["A","B","C","D"],"rationale":"苯巴比妥可镇静抗焦虑、抗惊厥和抗癫痫，故可用于甲亢精神紧张、神经衰弱失眠、小儿高热惊厥及癫痫持续状态。","expl":{"A":"正确，可镇静缓解甲亢精神紧张。","B":"正确，可用于神经衰弱失眠。","C":"正确，可用于小儿高热惊厥。","D":"正确，可用于癫痫持续状态。","E":"错，A~D均可应用。"},"id":"ph13_q47","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":47},{"type":"X","stem":"下列关于地西泮的描述，正确的是","options":{"A":"对精神分裂症无效","B":"可用作麻醉前给药","C":"有中枢性骨骼肌松弛作用","D":"无成瘾性","E":"以上均是"},"answer":["A","B","C"],"rationale":"地西泮对精神分裂症无效，可用作麻醉前给药并有中枢性肌松作用，但长期用可成瘾。","expl":{"A":"正确，对精神分裂症无效。","B":"正确，可用作麻醉前给药。","C":"正确，有中枢性骨骼肌松弛作用。","D":"错，地西泮可产生依赖性。","E":"错，D项不正确。"},"id":"ph13_q48","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":48},{"type":"X","stem":"解救口服巴比妥类药物中毒的病人，应采取","options":{"A":"补液并加利尿药","B":"用硫酸钠导泻","C":"用碳酸氢钠碱化尿液","D":"用中枢兴奋药维持呼吸","E":"洗胃"},"answer":["A","B","C","D","E"],"rationale":"解救巴比妥类中毒应洗胃、硫酸钠导泻、碱化尿液加速排泄、补液利尿，必要时用中枢兴奋药维持呼吸。","expl":{"A":"正确，补液并用利尿药促排泄。","B":"正确，用硫酸钠导泻（忌硫酸镁）。","C":"正确，碳酸氢钠碱化尿液促排泄。","D":"正确，中枢兴奋药维持呼吸。","E":"正确，应及时洗胃。"},"id":"ph13_q49","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":49},{"type":"X","stem":"对快波睡眠时相影响极小的药物是","options":{"A":"苯巴比妥","B":"水合氯醛","C":"甲丙氮酯","D":"地西泮","E":"戊巴比妥"},"answer":["B","D"],"rationale":"水合氯醛和地西泮对快波睡眠（REM）时相影响极小，其余药物可缩短REM。","expl":{"A":"错，苯巴比妥明显缩短REM。","B":"正确，水合氯醛对REM影响小。","C":"错，甲丙氨酯可缩短REM。","D":"正确，地西泮对REM影响较小。","E":"错，戊巴比妥缩短REM。"},"id":"ph13_q50","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":50},{"type":"A","stem":"苯二氮䓬类与巴比妥类作用于GABA-A受体-Cl-通道复合物的不同点在于","options":{"A":"前者延长氯通道开放时间，后者增加开放频率","B":"前者增加氯通道开放频率，后者延长开放时间","C":"两者均延长氯通道开放时间","D":"两者均增加氯通道开放频率","E":"前者直接开放氯通道，后者需GABA参与"},"answer":["B"],"rationale":"苯二氮䓬类增强GABA与受体的亲和力，增加氯通道开放的频率；巴比妥类则延长氯通道开放时间，故答案为 B。","expl":{"A":"错误，两种药物对氯通道的作用方式正好与选项所述相反。","B":"正确，前者增加开放频率，后者延长开放时间，这是两类药作用强度不同的基础。","C":"错误，只有巴比妥类延长开放时间，苯二氮䓬类不延长开放时间。","D":"错误，只有苯二氮䓬类增加开放频率，巴比妥类不增加频率。","E":"错误，两药均需GABA存在才能发挥作用，都不能直接开放氯通道。"},"id":"ph13_q51","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":51},{"type":"X","stem":"关于苯二氮䓬类与巴比妥类的比较，下列叙述正确的有","options":{"A":"苯二氮䓬类对快速眼动睡眠影响较小","B":"苯二氮䓬类治疗指数大，安全性较高","C":"苯二氮䓬类增加氯通道开放频率，巴比妥类延长开放时间","D":"苯二氮䓬类过量可用氟马西尼解救","E":"两药均无肝药酶诱导作用"},"answer":["A","B","C","D"],"rationale":"苯二氮䓬类对REM睡眠影响小、治疗指数大、安全性高，过量时可用特异性拮抗药氟马西尼；巴比妥类则有明显的肝药酶诱导作用，故E错误。","expl":{"A":"正确，苯二氮䓬类对快速眼动睡眠影响小，停药后反跳性多梦较轻。","B":"正确，其治疗指数大，单独过量很少引起致死性呼吸抑制。","C":"正确，前者增加氯通道开放频率，后者延长开放时间。","D":"正确，氟马西尼为苯二氮䓬受体拮抗药，可迅速逆转其中枢抑制。","E":"错误，巴比妥类可诱导肝药酶，加速自身及多种药物代谢而产生耐受。"},"id":"ph13_q52","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":52}]},{"title":"第十四章 抗癫痫药与抗惊厥药","questions":[{"type":"A","stem":"硫酸镁抗惊厥的作用机制是","options":{"A":"特异性地竞争 Ca2＋受点，拮抗 Ca2＋的作用","B":"阻碍高频异常放电的神经元的 Na＋通道","C":"作用同苯二氮卓类","D":"抑制中枢多突触反应，减弱易化，增强抑制","E":"以是都不是"},"answer":["A"],"rationale":"硫酸镁通过竞争性拮抗Ca2+结合位点，抑制神经肌肉接头兴奋传递和中枢兴奋性，从而产生抗惊厥作用。","expl":{"A":"正确，硫酸镁特异竞争Ca2+结合位点、拮抗Ca2+作用，是其抗惊厥的关键机制。","B":"阻滞高频异常放电神经元Na+通道是苯妥英钠等抗癫痫药的机制，与硫酸镁无关。","C":"硫酸镁不作用于苯二氮卓类受体-氯通道复合物，作用机制与苯二氮卓类不同。","D":"抑制中枢多突触反应、增强GABA抑制是苯二氮卓类和巴比妥类的作用特点。","E":"该项否定正确答案，表述错误。"},"id":"ph14_q01","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":1},{"type":"A","stem":"苯妥英钠是何种疾病的首选药物？","options":{"A":"癫痫小发作","B":"癫痫大发作","C":"癫痫精神运动性发作","D":"帕金森病发作","E":"小儿惊厥"},"answer":["B"],"rationale":"苯妥英钠是癫痫大发作（强直-阵挛发作）的首选药物，疗效确切。","expl":{"A":"癫痫小发作首选乙琥胺，苯妥英钠无效甚至可加重小发作。","B":"正确，苯妥英钠是癫痫大发作的首选药物。","C":"精神运动性发作首选卡马西平，苯妥英钠非首选。","D":"帕金森病与抗癫痫药无关，苯妥英钠不适用。","E":"小儿惊厥常用地西泮或苯巴比妥，苯妥英钠非首选。"},"id":"ph14_q02","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":2},{"type":"A","stem":"苯妥英钠可能使下列何种癫痫症状恶化？","options":{"A":"大发作","B":"失神小发作","C":"部分性发作","D":"中枢疼痛综合症","E":"癫痫持续状态"},"answer":["B"],"rationale":"苯妥英钠可加重失神小发作，因此失神小发作患者禁用或慎用该药。","expl":{"A":"癫痫大发作是苯妥英钠的适应症，不会使之恶化。","B":"正确，苯妥英钠可加重失神小发作。","C":"部分性发作是苯妥英钠的适应症，可有效控制。","D":"中枢疼痛综合征可用苯妥英钠治疗，不属恶化。","E":"癫痫持续状态可静脉注射苯妥英钠，不使之恶化。"},"id":"ph14_q03","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":3},{"type":"A","stem":"乙琥胺是治疗何种癫痫的常用药物？","options":{"A":"失神小发作","B":"大发作","C":"癫痫持续状态","D":"部分性发作","E":"中枢疼痛综合症"},"answer":["A"],"rationale":"乙琥胺是失神小发作的首选药，疗效好且不良反应相对较少。","expl":{"A":"正确，乙琥胺是治疗失神小发作的首选药。","B":"癫痫大发作首选苯妥英钠，乙琥胺无效。","C":"癫痫持续状态首选地西泮，乙琥胺不适用。","D":"部分性发作常用卡马西平或苯妥英钠，乙琥胺无效。","E":"中枢疼痛综合征常用苯妥英钠或卡马西平，乙琥胺无效。"},"id":"ph14_q04","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":4},{"type":"A","stem":"硫酸镁中毒时，特异性的解救措施是","options":{"A":"静脉输注 NaHCO3 ，加快排泄","B":"静脉滴注毒扁豆碱","C":"静脉缓慢注射氯化钙","D":"进行人工呼吸","E":"静脉注射呋塞米，加速药物排泄"},"answer":["C"],"rationale":"硫酸镁中毒时静注钙剂可竞争性拮抗Mg2+对Ca2+结合位点的作用，是特异性解救措施。","expl":{"A":"输注碳酸氢钠碱化尿液主要用于促进某些弱酸性药排泄，不拮抗镁中毒。","B":"毒扁豆碱是胆碱酯酶抑制剂，用于解救阿托品中毒，与镁中毒无关。","C":"正确，静脉缓慢注射氯化钙可拮抗镁离子，是硫酸镁中毒的特异性解救。","D":"人工呼吸只是维持呼吸的辅助措施，非特异性拮抗。","E":"呋塞米利尿不能特异性拮抗镁离子对钙结合位点的作用。"},"id":"ph14_q05","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":5},{"type":"A","stem":"治疗中枢疼痛综合症的首选药物是","options":{"A":"苯妥英钠","B":"吲哚美辛","C":"苯巴比妥","D":"乙琥胺","E":"地西泮"},"answer":["A"],"rationale":"苯妥英钠能稳定神经细胞膜、抑制异常放电，对中枢性疼痛综合征有良好疗效，被列为首选药。","expl":{"A":"正确，苯妥英钠是治疗中枢性疼痛综合征的首选药。","B":"吲哚美辛是解热镇痛抗炎药，对神经病理性疼痛疗效差，非首选。","C":"苯巴比妥主要抗癫痫、镇静催眠，不用于中枢性疼痛。","D":"乙琥胺仅用于失神小发作，对神经痛无效。","E":"地西泮是镇静抗焦虑药，非中枢疼痛综合征首选。"},"id":"ph14_q06","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":6},{"type":"A","stem":"治疗三叉神经痛和舌咽神经痛的首选药物是","options":{"A":"卡马西平","B":"阿司匹林","C":"苯巴比妥","D":"戊巴比妥钠","E":"乙琥胺"},"answer":["A"],"rationale":"卡马西平对三叉神经痛和舌咽神经痛疗效显著，是治疗该类神经痛的首选药物。","expl":{"A":"正确，卡马西平对三叉神经痛和舌咽神经痛疗效好，是首选药。","B":"阿司匹林对神经病理性疼痛疗效差，非首选。","C":"苯巴比妥不用于神经痛。","D":"戊巴比妥钠主要镇静催眠，不用于神经痛。","E":"乙琥胺仅用于失神小发作，对神经痛无效。"},"id":"ph14_q07","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":7},{"type":"A","stem":"下列哪种药物属于广谱抗癫痫药？","options":{"A":"卡马西平","B":"丙戊酸钠","C":"苯巴比妥","D":"苯妥英钠","E":"乙琥胺"},"answer":["B"],"rationale":"丙戊酸钠对各型癫痫均有效，属广谱抗癫痫药，其余药物作用谱较窄。","expl":{"A":"卡马西平对失神发作无效，非广谱。","B":"正确，丙戊酸钠对各型癫痫均有效，属广谱抗癫痫药。","C":"苯巴比妥对失神发作无效，非广谱。","D":"苯妥英钠对失神发作无效甚至加重，非广谱。","E":"乙琥胺仅对失神小发作有效，非广谱。"},"id":"ph14_q08","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":8},{"type":"A","stem":"适用于治疗癫痫不典型不发作和婴儿痉挛的药物是","options":{"A":"地西泮","B":"苯妥英钠","C":"硝西泮","D":"丙戊酸钠","E":"卡马西平"},"answer":["C"],"rationale":"硝西泮属苯二氮卓类，对癫痫不典型失神发作和婴儿痉挛有较好疗效。","expl":{"A":"地西泮主要用于癫痫持续状态，非此类发作的首选。","B":"苯妥英钠对失神发作及婴儿痉挛无效甚至加重。","C":"正确，硝西泮对不典型失神发作和婴儿痉挛有效。","D":"丙戊酸钠虽广谱，但婴儿痉挛常选硝西泮等苯二氮卓类。","E":"卡马西平对失神发作无效。"},"id":"ph14_q09","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":9},{"type":"A","stem":"关于苯妥英钠作用的叙述，下列哪项是错误的？","options":{"A":"降低各种细胞膜的兴奋必性","B":"能阴滞 Na＋通道，减少 Na＋ ，内流","C":"对正常的低频异常放电的 Na＋通道阻滞作用明显","D":"对正常的低频放电也有明显阻滞作用","E":"也能阻滞T型 Na＋通道，阻滞 Ca2＋内流"},"answer":["D"],"rationale":"苯妥英钠选择性阻滞高频异常放电神经元的Na+通道，对正常低频放电无明显影响，故D项错误。","expl":{"A":"正确，苯妥英钠能降低各种细胞膜的兴奋性。","B":"正确，其能阻滞Na+通道、减少Na+内流。","C":"正确，对高频异常放电神经元的Na+通道阻滞作用明显。","D":"错误，苯妥英钠对正常低频放电无明显阻滞作用，此为该题答案。","E":"正确，高浓度时也能阻滞钙通道、减少Ca2+内流。"},"id":"ph14_q10","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":10},{"type":"A","stem":"关于苯妥英钠体内过程，下列叙述哪项不正确？","options":{"A":"口服吸收慢而不规则，宜肌肉注射","B":"癫痫持续状态时可作静脉注射","C":"血浆蛋白结合率高","D":"生物利用度有明显个体差异","E":"主要在肝脏代谢"},"answer":["A"],"rationale":"苯妥英钠口服吸收慢而不规则，但刺激性大、肌注吸收差且易沉淀，不宜肌内注射，故A项不正确。","expl":{"A":"错误，苯妥英钠不宜肌内注射（刺激性大、吸收差），此为该题答案。","B":"正确，癫痫持续状态时可静脉注射苯妥英钠。","C":"正确，血浆蛋白结合率约90%，结合率高。","D":"正确，生物利用度有明显个体差异。","E":"正确，主要在肝脏经药酶代谢。"},"id":"ph14_q11","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":11},{"type":"A","stem":"列何种抗癫痫药没有明显的阻滞 Na＋通道的作用？","options":{"A":"苯妥英钠","B":"卡马西平","C":"苯巴比妥","D":"丙戊酸钠","E":"乙琥胺"},"answer":["E"],"rationale":"乙琥胺主要阻滞T型钙通道，无明显阻滞Na+通道作用，其余药物均有Na+通道阻滞作用。","expl":{"A":"苯妥英钠主要阻滞Na+通道。","B":"卡马西平能阻滞Na+通道。","C":"苯巴比妥高浓度时也能阻滞Na+通道。","D":"丙戊酸钠也能阻滞Na+通道。","E":"正确，乙琥胺阻滞T型钙通道，无明显阻滞Na+通道作用。"},"id":"ph14_q12","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":12},{"type":"B","stem":"对子痫有良好的治疗作用","options":{"A":"卡马西平","B":"硫酸镁","C":"苯巴比妥","D":"扑米酮","E":"戊巴比妥钠"},"answer":["B"],"rationale":"硫酸镁可抗惊厥并降压，是子痫（妊娠高血压综合征）的首选药。","expl":{"A":"卡马西平主要抗癫痫、治神经痛，不用于子痫。","B":"正确，硫酸镁对子痫有良好治疗作用，是首选药。","C":"苯巴比妥虽有抗惊厥作用，但非子痫首选。","D":"扑米酮用于癫痫大发作，不用于子痫。","E":"戊巴比妥钠主要用于镇静催眠，不用于子痫。"},"id":"ph14_q13","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":13},{"type":"B","stem":"对三叉神经痛和舌咽神经痛有较好疗效","options":{"A":"卡马西平","B":"硫酸镁","C":"苯巴比妥","D":"扑米酮","E":"戊巴比妥钠"},"answer":["A"],"rationale":"卡马西平对三叉神经痛和舌咽神经痛疗效较好，是治疗此类神经痛的常用药。","expl":{"A":"正确，卡马西平对三叉神经痛和舌咽神经痛有较好疗效。","B":"硫酸镁用于子痫抗惊厥，不用于神经痛。","C":"苯巴比妥不用于神经痛。","D":"扑米酮不用于神经痛。","E":"戊巴比妥钠不用于神经痛。"},"id":"ph14_q14","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":14},{"type":"B","stem":"治疗癫痫持续状态的首选药物","options":{"A":"卡马西平","B":"苯妥英钠","C":"地西泮","D":"乙琥胺","E":"扑米酮"},"answer":["C"],"rationale":"地西泮静脉注射起效快、疗效好，是治疗癫痫持续状态的首选药物。","expl":{"A":"卡马西平不宜用于癫痫持续状态。","B":"苯妥英钠可用于持续状态，但非首选。","C":"正确，地西泮静注是癫痫持续状态的首选药。","D":"乙琥胺仅用于失神小发作。","E":"扑米酮不用于癫痫持续状态。"},"id":"ph14_q15","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":15},{"type":"B","stem":"治疗癫痫小发作的首选药物","options":{"A":"卡马西平","B":"苯妥英钠","C":"地西泮","D":"乙琥胺","E":"扑米酮"},"answer":["D"],"rationale":"乙琥胺对失神小发作疗效好、毒性较低，是治疗癫痫小发作的首选药物。","expl":{"A":"卡马西平对失神发作无效。","B":"苯妥英钠对失神发作无效甚至加重。","C":"地西泮用于癫痫持续状态，非小发作首选。","D":"正确，乙琥胺是癫痫小发作（失神）的首选药。","E":"扑米酮用于大发作，对小发作无效。"},"id":"ph14_q16","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":16},{"type":"B","stem":"治疗癫痫精神运动性发作的首选药物","options":{"A":"卡马西平","B":"苯妥英钠","C":"地西泮","D":"乙琥胺","E":"扑米酮"},"answer":["A"],"rationale":"卡马西平对精神运动性（复杂部分性）发作疗效良好，是首选药物。","expl":{"A":"正确，卡马西平是癫痫精神运动性发作的首选药。","B":"苯妥英钠非精神运动性发作的首选。","C":"地西泮不作为精神运动性发作首选。","D":"乙琥胺仅用于失神小发作。","E":"扑米酮不作为精神运动性发作首选。"},"id":"ph14_q17","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":17},{"type":"C","stem":"对各种类型的癫痫都有效","options":{"A":"苯妥英钠","B":"丙戊酸钠","C":"两者均是","D":"两者均否"},"answer":["B"],"rationale":"丙戊酸钠是广谱抗癫痫药，对各型癫痫均有效；苯妥英钠对失神发作无效，故答案仅B。","expl":{"A":"苯妥英钠对失神小发作无效甚至加重，非对各型均有效。","B":"正确，丙戊酸钠为广谱抗癫痫药，对各种类型癫痫均有效。","C":"苯妥英钠并非对各型均有效，故两者均是错误。","D":"丙戊酸钠确实广谱，故两者均否错误。"},"id":"ph14_q18","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":18},{"type":"C","stem":"妊娠早期用药有致畸胎作用","options":{"A":"苯妥英钠","B":"丙戊酸钠","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"苯妥英钠可致胎儿海因综合征，丙戊酸钠可致神经管畸形，两者妊娠早期应用均有致畸作用。","expl":{"A":"苯妥英钠有致畸作用（胎儿海因综合征）。","B":"丙戊酸钠有致畸作用（神经管畸形）。","C":"正确，两者妊娠早期应用均有致畸胎作用。","D":"两者确有致畸作用，故两者均否错误。"},"id":"ph14_q19","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":19},{"type":"X","stem":"下列哪些药物对癫痫失神发作无效","options":{"A":"苯妥英钠","B":"卡马西平","C":"苯巴比妥","D":"扑米酮","E":"丙戊酸钠"},"answer":["A","B","C","D"],"rationale":"失神发作首选乙琥胺或丙戊酸钠；苯妥英钠、卡马西平、苯巴比妥、扑米酮对失神发作均无效。","expl":{"A":"正确，苯妥英钠对失神发作无效甚至加重。","B":"正确，卡马西平对失神发作无效。","C":"正确，苯巴比妥对失神发作无效。","D":"正确，扑米酮对失神发作无效。","E":"丙戊酸钠对失神发作有效，故不选。"},"id":"ph14_q20","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":20},{"type":"X","stem":"下列哪些药物在妊娠早期应用有致畸胎作用？","options":{"A":"苯妥英钠","B":"丙戊酸钠","C":"乙琥胺","D":"卡马西平","E":"扑米酮"},"answer":["A","B"],"rationale":"苯妥英钠和丙戊酸钠妊娠早期应用有明显致畸作用；乙琥胺、卡马西平、扑米酮未被列为此类致畸药。","expl":{"A":"正确，苯妥英钠可致胎儿海因综合征。","B":"正确，丙戊酸钠可致神经管畸形。","C":"乙琥胺无明确致畸报道，不选。","D":"卡马西平未列入该题所指妊娠早期致畸药，不选。","E":"扑米酮无明确致畸报道，不选。"},"id":"ph14_q21","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":21},{"type":"X","stem":"下列哪些药物大剂量或长期使用可能引起再生障碍性贫血？","options":{"A":"乙琥胺","B":"卡马西平","C":"苯妥英钠","D":"地西泮","E":"扑米酮"},"answer":["A","B","C"],"rationale":"乙琥胺、卡马西平、苯妥英钠大剂量或长期应用均可抑制骨髓，引起再生障碍性贫血。","expl":{"A":"正确，乙琥胺可致再生障碍性贫血。","B":"正确，卡马西平可致再生障碍性贫血。","C":"正确，苯妥英钠可致再生障碍性贫血。","D":"地西泮不引起再生障碍性贫血，不选。","E":"扑米酮主要致巨幼红细胞性贫血，非再生障碍性贫血，不选。"},"id":"ph14_q22","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":22},{"type":"X","stem":"下列哪些药物可致巨幼红细胞贫血？","options":{"A":"扑米酮","B":"苯妥英钠","C":"地西泮","D":"丙戊酸钠","E":"乙琥胺"},"answer":["A","B"],"rationale":"苯妥英钠和扑米酮长期应用可干扰叶酸吸收和代谢，引起巨幼红细胞性贫血。","expl":{"A":"正确，扑米酮可致巨幼红细胞性贫血。","B":"正确，苯妥英钠可致巨幼红细胞性贫血。","C":"地西泮不引起巨幼红细胞性贫血，不选。","D":"丙戊酸钠不引起巨幼红细胞性贫血，不选。","E":"乙琥胺可致再障，但非巨幼红细胞性贫血，不选。"},"id":"ph14_q23","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":23},{"type":"X","stem":"关于卡马西平作用叙述，下列哪些是正确的？","options":{"A":"能阻滞 Na＋通道","B":"能抑制癫痫病灶放电","C":"能阻滞周围神经原放电","D":"对精神运动性癫痫有良好疗效","E":"治疗舌咽神经痛"},"answer":["A","B","C","D","E"],"rationale":"卡马西平阻滞Na+通道、抑制癫痫病灶及外周神经元放电，对精神运动性癫痫疗效好并治舌咽神经痛，各项均正确。","expl":{"A":"正确，卡马西平能阻滞Na+通道。","B":"正确，能抑制癫痫病灶放电。","C":"正确，能抑制周围神经元放电。","D":"正确，对精神运动性癫痫有良好疗效。","E":"正确，可用于治疗舌咽神经痛。"},"id":"ph14_q24","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":24},{"type":"X","stem":"卡马西平的是","options":{"A":"作用机制与苯妥英钠相似","B":"对精神运动性发作有较好疗效","C":"对中枢疼痛综合症的效果优于苯妥英钠","D":"可作为大发作和部分性发作的首选药物","E":"对癫痫并发的躁狂、抑郁症有效"},"answer":["A","B","C","D","E"],"rationale":"卡马西平机制类似苯妥英钠，对精神运动性发作好、中枢疼痛综合征疗效优于苯妥英钠，并可用于大发作、部分性发作及躁狂抑郁。","expl":{"A":"正确，作用机制与苯妥英钠相似（阻滞Na+通道）。","B":"正确，对精神运动性发作有较好疗效。","C":"正确，对中枢疼痛综合征的效果优于苯妥英钠。","D":"正确，可作为大发作和部分性发作的首选药。","E":"正确，对癫痫并发的躁狂、抑郁症有效。"},"id":"ph14_q25","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":25},{"type":"X","stem":"下列哪些药物可治疗癫痫持续状态？","options":{"A":"地西泮","B":"卡马西平","C":"戊巴比妥钠","D":"苯巴比妥","E":"扑米酮"},"answer":["A","C","D"],"rationale":"地西泮静注是持续状态首选，苯巴比妥和戊巴比妥钠等巴比妥类也可静脉用于癫痫持续状态。","expl":{"A":"正确，地西泮静注是癫痫持续状态的首选药。","B":"卡马西平不宜用于癫痫持续状态，不选。","C":"正确，戊巴比妥钠可静注治疗癫痫持续状态。","D":"正确，苯巴比妥可用于治疗癫痫持续状态。","E":"扑米酮不用于癫痫持续状态，不选。"},"id":"ph14_q26","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":26},{"type":"X","stem":"下列哪些药物可治疗破伤风惊厥？","options":{"A":"地西泮","B":"苯巴比妥","C":"戊巴比妥钠","D":"乙琥胺","E":"卡马西平"},"answer":["A","B","C"],"rationale":"地西泮及巴比妥类（苯巴比妥、戊巴比妥钠）均有抗惊厥作用，可用于治疗破伤风惊厥。","expl":{"A":"正确，地西泮可治疗破伤风惊厥。","B":"正确，苯巴比妥可治疗破伤风惊厥。","C":"正确，戊巴比妥钠可治疗破伤风惊厥。","D":"乙琥胺仅用于失神小发作，对破伤风惊厥无效，不选。","E":"卡马西平不用于破伤风惊厥，不选。"},"id":"ph14_q27","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":27},{"type":"X","stem":"对小儿高热惊厥有效的药物有","options":{"A":"苯巴比妥","B":"水合氯醛","C":"地西泮","D":"苯妥英钠","E":"卡马西平"},"answer":["A","B","C"],"rationale":"苯巴比妥、水合氯醛、地西泮均可用于小儿高热惊厥的防治，苯妥英钠和卡马西平非常用。","expl":{"A":"正确，苯巴比妥可防治小儿高热惊厥。","B":"正确，水合氯醛可治疗小儿高热惊厥。","C":"正确，地西泮可治疗小儿高热惊厥。","D":"苯妥英钠对高热惊厥疗效差，不选。","E":"卡马西平不用于高热惊厥，不选。"},"id":"ph14_q28","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":28},{"type":"X","stem":"苯妥英钠可以治疗下列哪些疾病？","options":{"A":"快速型心律失常","B":"癫痫大发作","C":"三叉神经痛","D":"舌咽神经痛","E":"癫痫小发作"},"answer":["A","B","C","D"],"rationale":"苯妥英钠可抗快速型心律失常，治疗癫痫大发作及三叉神经痛、舌咽神经痛，但对小发作无效。","expl":{"A":"正确，苯妥英钠可治疗快速型心律失常。","B":"正确，可治疗癫痫大发作。","C":"正确，可治疗三叉神经痛。","D":"正确，可治疗舌咽神经痛。","E":"癫痫小发作苯妥英钠无效甚至加重，不选。"},"id":"ph14_q29","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":29},{"type":"X","stem":"硫酸镁的作用包括","options":{"A":"注射硫酸镁可产生降压作用","B":"注射硫酸镁可产生骨骼肌松弛作用","C":"注射和口服硫酸镁均可产生骨骼肌松弛作用","D":"口吸硫酸镁有导泻作用","E":"口服或用导管直接注入十二指肠，可引起利胆作用"},"answer":["A","B","D","E"],"rationale":"注射硫酸镁可降压并松弛骨骼肌，口服有导泻作用，口服或十二指肠注入可利胆；口服不吸收，不产生肌松。","expl":{"A":"正确，注射硫酸镁可产生降压作用。","B":"正确，注射硫酸镁可产生骨骼肌松弛作用。","C":"口服硫酸镁不吸收，不产生骨骼肌松弛，此项错误。","D":"正确，口服硫酸镁有导泻作用。","E":"正确，口服或十二指肠注入可产生利胆作用。"},"id":"ph14_q30","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":30},{"type":"A","stem":"癫痫复杂部分性发作（精神运动性发作）的首选药是","options":{"A":"苯妥英钠","B":"乙琥胺","C":"丙戊酸钠","D":"卡马西平","E":"苯巴比妥"},"answer":["D"],"rationale":"卡马西平是复杂部分性发作的首选药，对简单部分性发作及继发性全面强直阵挛发作也有效，故答案为 D。","expl":{"A":"错误，苯妥英钠对强直阵挛发作和部分性发作有效，但复杂部分性发作首选卡马西平。","B":"错误，乙琥胺只对失神发作有效，对其他类型发作无效。","C":"错误，丙戊酸钠为广谱抗癫痫药，可作为替代选择而非首选。","D":"正确，卡马西平对复杂部分性发作疗效好，为首选药物。","E":"错误，苯巴比妥多用于小儿癫痫及预防高热惊厥，不作复杂部分性发作首选。"},"id":"ph14_q31","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":31},{"type":"A","stem":"丙戊酸钠抗癫痫作用的主要机制是","options":{"A":"选择性阻滞丘脑T型钙通道","B":"阻断谷氨酸NMDA受体","C":"抑制GABA转氨酶和琥珀酸半醛脱氢酶，并阻滞Na+通道","D":"增强GABA-A受体对GABA的敏感性","E":"抑制碳酸酐酶"},"answer":["C"],"rationale":"丙戊酸钠抑制GABA转氨酶和琥珀酸半醛脱氢酶提高脑内GABA含量，同时阻滞电压依赖性Na+通道，因而成为广谱抗癫痫药，答案为 C。","expl":{"A":"错误，阻滞丘脑T型钙通道是乙琥胺治疗失神发作的机制。","B":"错误，阻断NMDA受体并非丙戊酸钠的主要抗癫痫机制。","C":"正确，提高脑内GABA含量并阻滞Na+通道，使其对多种发作类型均有效。","D":"错误，增强GABA-A受体敏感性是苯二氮䓬类和巴比妥类的作用特点。","E":"错误，抑制碳酸酐酶是乙酰唑胺的作用，与丙戊酸钠无关。"},"id":"ph14_q32","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":32},{"type":"X","stem":"关于抗癫痫药的临床应用，下列叙述正确的有","options":{"A":"苯妥英钠对失神发作无效，甚至可诱发失神发作","B":"乙琥胺是失神发作的首选药，但可使强直阵挛发作加重","C":"卡马西平是复杂部分性发作的首选药","D":"癫痫持续状态首选静脉注射地西泮","E":"抗癫痫药取得疗效后应立即停药以防耐受"},"answer":["A","B","C","D"],"rationale":"苯妥英钠对失神发作无效甚至可诱发，乙琥胺只对失神发作有效且可能加重强直阵挛发作，卡马西平为复杂部分性发作首选，地西泮静注为癫痫持续状态首选，故E错误。","expl":{"A":"正确，苯妥英钠对失神发作无效，用药不当可使发作增多。","B":"正确，乙琥胺仅对失神发作有效，单用可能诱发全面强直阵挛发作。","C":"正确，卡马西平对复杂部分性发作疗效确切，为首选药。","D":"正确，地西泮静脉注射起效快，是癫痫持续状态的首选措施。","E":"错误，抗癫痫药须长期规律服用并逐渐减量停药，突然停药可诱发发作。"},"id":"ph14_q33","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":33}]},{"title":"第十五章 治疗中枢神经系统退行性疾病药","questions":[{"type":"A","stem":"左旋多巴治疗帕金森病的疗效特点是","options":{"A":"对肌强直和运动迟缓改善明显，对震颤疗效较差","B":"对震颤疗效最好，对肌强直和运动迟缓基本无效","C":"首次服药即可迅速显效，无需连续用药","D":"对吩噻嗪类抗精神病药引起的帕金森综合征同样有效","E":"可阻止黑质多巴胺能神经元变性，从而根治帕金森病"},"answer":["A"],"rationale":"左旋多巴是多巴胺的前体，易透过血脑屏障后在脑内脱羧生成多巴胺，补充纹状体递质不足，对肌强直和运动迟缓改善最明显，对震颤疗效较差，故答案为A。其起效较慢，常需连续用药数周才显效；抗精神病药阻断多巴胺受体，所致帕金森综合征用左旋多巴无效，应改用苯海索；左旋多巴仅对症治疗，不能阻止神经元变性。","expl":{"A":"正确。肌强直和运动迟缓改善明显而震颤改善较差是本药的特点。","B":"颠倒了疗效顺序，震颤恰恰是左旋多巴疗效较差的表现。","C":"左旋多巴起效较慢，常需连续用药数周才出现明显疗效。","D":"抗精神病药阻断多巴胺受体，左旋多巴对其所致帕金森综合征无效。","E":"左旋多巴仅补充递质、改善症状，不能阻止多巴胺能神经元变性。"},"id":"ph15_q01","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":1},{"type":"A","stem":"卡比多巴与左旋多巴组成复方制剂的主要药理学依据是","options":{"A":"抑制外周多巴脱羧酶，增加左旋多巴入脑量并减少外周不良反应","B":"抑制脑内多巴脱羧酶，直接增加纹状体多巴胺含量","C":"选择性抑制单胺氧化酶B，减少脑内多巴胺的降解","D":"直接激动纹状体多巴胺D2受体而发挥抗帕金森病作用","E":"阻断中枢胆碱受体，纠正胆碱能功能的相对亢进"},"answer":["A"],"rationale":"卡比多巴为外周多巴脱羧酶抑制剂，本身不易透过血脑屏障，仅抑制外周左旋多巴的脱羧，使更多左旋多巴进入脑内脱羧生成多巴胺，同时减少外周多巴胺引起的心血管和胃肠道反应，故答案为A。抑制单胺氧化酶B的是司来吉兰，激动多巴胺受体的是溴隐亭和普拉克索，阻断中枢胆碱受体的是苯海索。","expl":{"A":"正确。这就是卡比多巴与左旋多巴配伍增效减毒的原理。","B":"卡比多巴不易入脑，不能抑制脑内脱羧酶，脑内脱羧仍由左旋多巴完成。","C":"抑制单胺氧化酶B的是司来吉兰和雷沙吉兰，不是卡比多巴。","D":"直接激动多巴胺受体的是溴隐亭、普拉克索等受体激动药。","E":"阻断中枢胆碱受体的是苯海索等中枢性抗胆碱药。"},"id":"ph15_q02","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":2},{"type":"A","stem":"美金刚治疗中重度阿尔茨海默病的作用机制是","options":{"A":"非竞争性拮抗NMDA受体，减轻谷氨酸的兴奋性毒性","B":"可逆性抑制脑内乙酰胆碱酯酶，增加乙酰胆碱含量","C":"选择性激动M1受体，改善学习记忆功能","D":"抑制β-淀粉样蛋白的生成与沉积","E":"激动烟碱受体并促进乙酰胆碱的释放"},"answer":["A"],"rationale":"美金刚是电压依赖性、非竞争性NMDA受体拮抗药，可阻断病理状态下谷氨酸过度激活所致的兴奋性毒性而保护神经元，对正常生理性传递影响小、耐受性较好，用于中重度阿尔茨海默病，可与胆碱酯酶抑制药合用，故答案为A。抑制胆碱酯酶的是多奈哌齐等，激动M受体或烟碱受体均非美金刚的作用。","expl":{"A":"正确。阻断NMDA受体介导的钙超载和兴奋性毒性是其作用基础。","B":"抑制乙酰胆碱酯酶的是多奈哌齐、加兰他敏和石杉碱甲。","C":"美金刚不激动M1受体，激动M受体并非其治疗阿尔茨海默病的机制。","D":"抑制β-淀粉样蛋白生成目前尚缺乏成熟的临床药物。","E":"激动烟碱受体、促进乙酰胆碱释放不是美金刚的作用方式。"},"id":"ph15_q03","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":3},{"type":"X","stem":"关于抗帕金森病药物的叙述，正确的有","options":{"A":"溴隐亭和普拉克索直接激动多巴胺受体，可用于早期帕金森病","B":"司来吉兰选择性抑制单胺氧化酶B，减少脑内多巴胺的降解","C":"恩他卡朋抑制外周儿茶酚氧位甲基转移酶，可改善剂末现象","D":"金刚烷胺的抗帕金森病作用主要来自阻断中枢胆碱受体","E":"苯海索阻断中枢胆碱受体，对震颤疗效较好，青光眼和前列腺肥大者禁用"},"answer":["A","B","C","E"],"rationale":"溴隐亭、普拉克索直接激动多巴胺受体，不依赖残存的多巴胺能神经元，早期单用可延缓运动并发症，A正确；司来吉兰选择性抑制单胺氧化酶B而减少多巴胺降解，B正确；恩他卡朋抑制外周儿茶酚氧位甲基转移酶、延长左旋多巴作用时间，用于改善剂末现象，C正确；苯海索阻断中枢胆碱受体，对震颤疗效较好，因抗胆碱作用致眼压升高和排尿困难，青光眼和前列腺肥大者禁用，E正确。金刚烷胺主要促进纹状体多巴胺释放并抑制其再摄取，兼有较弱的NMDA受体拮抗作用，并非以阻断胆碱受体为主，D错误。","expl":{"A":"正确。受体激动药早期单用可减少或延缓运动并发症的发生。","B":"正确。抑制单胺氧化酶B可延长脑内多巴胺的作用时间。","C":"正确。延长左旋多巴作用时间，主要用于改善剂末现象。","D":"金刚烷胺以促进多巴胺释放、抑制再摄取为主，兼有较弱的NMDA受体拮抗作用。","E":"正确。抗胆碱作用可致眼压升高和排尿困难，故有上述禁忌。"},"id":"ph15_q04","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":4}]},{"title":"第十六章 抗精神失常药","questions":[{"type":"A","stem":"抗精神失常药是指","options":{"A":"治疗精神活动障碍的药物","B":"治疗精神分裂症的药物","C":"治疗躁狂症的药物","D":"治疗抑郁症的药物","E":"治疗焦虑症的药物"},"answer":["A"],"rationale":"抗精神失常药是用于治疗各种精神活动障碍的一类药物总称，涵盖抗精神病、抗躁狂、抗抑郁和抗焦虑等药物。","expl":{"A":"正确，抗精神失常药是治疗各类精神活动障碍药物的统称，范围最广。","B":"错误，治疗精神分裂症的药物是抗精神病药，仅属抗精神失常药的一类。","C":"错误，治疗躁狂症的药物是抗躁狂药，仅属抗精神失常药的一部分。","D":"错误，治疗抑郁症的药物是抗抑郁药，仅属抗精神失常药的一部分。","E":"错误，治疗焦虑症的药物是抗焦虑药，仅属抗精神失常药的一部分。"},"id":"ph16_q01","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":1},{"type":"A","stem":"氯丙嗪口服生物利用度低的原因是","options":{"A":"吸收少","B":"排泄快","C":"首关消除","D":"血浆蛋白结合率高","E":"分布容积大"},"answer":["C"],"rationale":"氯丙嗪口服吸收良好，但经肝脏首关消除明显，故生物利用度低。","expl":{"A":"错误，氯丙嗪口服吸收良好，生物利用度低并非吸收少所致。","B":"错误，排泄快不是氯丙嗪口服生物利用度低的主要原因。","C":"正确，氯丙嗪有明显首关消除，故口服生物利用度低。","D":"错误，血浆蛋白结合率高主要影响分布与游离浓度，与生物利用度低关系不大。","E":"错误，分布容积大反映组织分布广，不直接导致口服生物利用度低。"},"id":"ph16_q02","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":2},{"type":"A","stem":"作用最强的吩噻类药物是","options":{"A":"氯丙嗪","B":"奋乃静","C":"硫利达嗪","D":"氟奋乃静","E":"三氟拉嗪"},"answer":["D"],"rationale":"氟奋乃静属高效价吩噻嗪类，抗精神病作用最强，所需剂量小。","expl":{"A":"错误，氯丙嗪为低效价代表，抗精神病作用强度弱于氟奋乃静。","B":"错误，奋乃静作用比氯丙嗪强，但弱于氟奋乃静。","C":"错误，硫利达嗪抗精神病作用较弱，锥体外系反应也较轻。","D":"正确，氟奋乃静为高效价吩噻嗪类，抗精神病作用最强。","E":"错误，三氟拉嗪作用较强，但仍不及氟奋乃静。"},"id":"ph16_q03","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":3},{"type":"A","stem":"可用于治疗抑郁症的药物是","options":{"A":"五氟利多","B":"舒必利","C":"奋乃静","D":"氟哌啶醇","E":"氯氮平"},"answer":["B"],"rationale":"舒必利小剂量具有抗抑郁作用，可用于抑郁症的治疗。","expl":{"A":"错误，五氟利多是长效抗精神病药，用于精神分裂症的维持治疗。","B":"正确，舒必利小剂量有抗抑郁作用，可用于治疗抑郁症。","C":"错误，奋乃静为抗精神病药，主要用于精神分裂症。","D":"错误，氟哌啶醇为抗精神病药，用于精神分裂症、躁狂等。","E":"错误，氯氮平为抗精神病药，用于难治性精神分裂症。"},"id":"ph16_q04","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":4},{"type":"A","stem":"锥体外系反应较轻的药物是","options":{"A":"氯丙嗪","B":"奋乃静","C":"硫利达嗪","D":"氟奋乃静","E":"三氟拉嗪"},"answer":["C"],"rationale":"硫利达嗪抗精神病作用较弱，锥体外系反应也较轻。","expl":{"A":"错误，氯丙嗪锥体外系反应较明显。","B":"错误，奋乃静属高效价类，锥体外系反应明显。","C":"正确，硫利达嗪作用较弱，锥体外系反应较轻。","D":"错误，氟奋乃静锥体外系反应强。","E":"错误，三氟拉嗪锥体外系反应明显。"},"id":"ph16_q05","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":5},{"type":"A","stem":"下列哪种药物可以用于处理氯丙嗪引起的低血压？","options":{"A":"肾上腺素","B":"多巴胺","C":"麻黄碱","D":"去甲肾上腺素","E":"异丙肾上腺素"},"answer":["D"],"rationale":"氯丙嗪阻断α受体致低血压，应选用去甲肾上腺素等α受体激动药升压；肾上腺素升压作用被翻转，故禁用。","expl":{"A":"错误，氯丙嗪阻断α受体，肾上腺素升压作用被翻转，反使血压进一步下降。","B":"错误，多巴胺作用复杂，小剂量扩张血管，非处理氯丙嗪低血压的选择。","C":"错误，麻黄碱兼有α、β作用且升压作用可被α阻断削弱，非首选。","D":"正确，去甲肾上腺素激动α受体，可对抗氯丙嗪α阻断引起的低血压。","E":"错误，异丙肾上腺素激动β受体，扩张血管，不能升压。"},"id":"ph16_q06","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":6},{"type":"A","stem":"氯丙嗪的禁忌证是","options":{"A":"溃疡病","B":"癫痫","C":"肾功能不全","D":"痛风","E":"焦虑症"},"answer":["B"],"rationale":"氯丙嗪降低惊厥阈值，可诱发或加重癫痫，故癫痫患者禁用。","expl":{"A":"错误，氯丙嗪抗胆碱作用可抑制胃酸分泌，溃疡病并非禁忌。","B":"正确，氯丙嗪降低惊厥阈值，可诱发癫痫，癫痫患者禁用。","C":"错误，氯丙嗪主要经肝代谢，肾功能不全非其主要禁忌。","D":"错误，氯丙嗪与痛风无直接禁忌关系。","E":"错误，氯丙嗪有镇静作用，焦虑症并非禁忌。"},"id":"ph16_q07","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":7},{"type":"A","stem":"氯丙嗪不应作皮下注射的原因是","options":{"A":"吸收不规则","B":"局部刺激性强","C":"与蛋白质结合","D":"吸收太慢","E":"吸收太快"},"answer":["B"],"rationale":"氯丙嗪局部刺激性强，皮下注射易引起疼痛和组织损伤，故不作皮下注射。","expl":{"A":"错误，不作皮下注射的主要原因是局部刺激，而非吸收不规则。","B":"正确，氯丙嗪局部刺激性强，皮下注射可引起疼痛和组织损伤。","C":"错误，与蛋白质结合与给药途径选择无关。","D":"错误，并非因吸收太慢而不作皮下注射。","E":"错误，并非因吸收太快而不作皮下注射。"},"id":"ph16_q08","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":8},{"type":"A","stem":"氯丙嗪引起的视力模糊、心动过速和口干、便秘等是由于阻断","options":{"A":"多巴胺（DA）受体","B":"a 肾上腺素受体","C":"b 肾上腺素受体","D":"M胆碱受体","E":"N 胆碱受体"},"answer":["D"],"rationale":"视力模糊、心动过速、口干、便秘为阻断M胆碱受体引起的阿托品样作用。","expl":{"A":"错误，阻断DA受体主要引起锥体外系反应和内分泌改变。","B":"错误，阻断α肾上腺素受体主要引起体位性低血压。","C":"错误，氯丙嗪不阻断β肾上腺素受体。","D":"正确，阻断M胆碱受体引起视力模糊、口干、便秘、心动过速等。","E":"错误，阻断N胆碱受体主要影响神经节和骨骼肌，与上述表现不符。"},"id":"ph16_q09","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":9},{"type":"A","stem":"小剂量氯丙嗪镇吐作用的部位是","options":{"A":"呕吐中枢","B":"胃粘膜传入纤维","C":"黑质－纹状体通路","D":"结节－漏斗通路","E":"延脑催吐化学感觉区"},"answer":["E"],"rationale":"小剂量氯丙嗪抑制延髓催吐化学感受区（CTZ）而镇吐，大剂量才直接抑制呕吐中枢。","expl":{"A":"错误，大剂量氯丙嗪才直接抑制呕吐中枢。","B":"错误，氯丙嗪镇吐与胃粘膜传入纤维无关。","C":"错误，黑质-纹状体通路与锥体外系反应有关。","D":"错误，结节-漏斗通路与内分泌调节有关。","E":"正确，小剂量氯丙嗪抑制延髓催吐化学感受区（CTZ）而镇吐。"},"id":"ph16_q10","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":10},{"type":"A","stem":"氯丙嗪的药浓度最高的部位是","options":{"A":"血液","B":"肝脏","C":"肾脏","D":"脑","E":"心脏"},"answer":["D"],"rationale":"氯丙嗪脂溶性高，易透过血脑屏障，脑内浓度远高于血浆浓度。","expl":{"A":"错误，氯丙嗪血浆浓度低于脑内浓度。","B":"错误，肝脏为代谢部位，药物浓度不及脑。","C":"错误，肾脏为排泄器官，浓度非最高。","D":"正确，氯丙嗪脂溶性高、易入脑，脑内浓度可达血浆浓度的数十倍。","E":"错误，心脏浓度非最高。"},"id":"ph16_q11","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":11},{"type":"A","stem":"适用于伴有焦虑或焦虑性抑郁的精神分裂症的药物是","options":{"A":"氟哌啶醇","B":"奋乃静","C":"硫利达嗪","D":"氯普噻吨","E":"三氟拉嗪"},"answer":["D"],"rationale":"氯普噻吨兼具抗焦虑、抗抑郁作用，适用于伴有焦虑或焦虑性抑郁的精神分裂症。","expl":{"A":"错误，氟哌啶醇无明显抗焦虑、抗抑郁作用。","B":"错误，奋乃静无突出抗焦虑、抗抑郁作用。","C":"错误，硫利达嗪以镇静为主，无突出抗抑郁作用。","D":"正确，氯普噻吨有抗焦虑和抗抑郁作用，适用于伴焦虑或焦虑性抑郁的精神分裂症。","E":"错误，三氟拉嗪无抗抑郁作用。"},"id":"ph16_q12","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":12},{"type":"A","stem":"常用于治疗以兴奋躁动、幻觉、妄想为主的精神分裂症的药物是","options":{"A":"氟哌啶醇","B":"氟奋乃静","C":"硫利达嗪","D":"氯普噻吨","E":"三氟拉嗪"},"answer":["A"],"rationale":"氟哌啶醇抗精神病作用强，对兴奋躁动、幻觉、妄想为主的精神分裂症疗效好。","expl":{"A":"正确，氟哌啶醇作用强，对兴奋躁动、幻觉、妄想为主的精神分裂症效果好。","B":"错误，氟奋乃静主要用于慢性精神分裂症。","C":"错误，硫利达嗪作用较弱，以镇静为主。","D":"错误，氯普噻吨抗精神病作用较弱，用于伴焦虑抑郁者。","E":"错误，三氟拉嗪对躁动兴奋的控制不如氟哌啶醇。"},"id":"ph16_q13","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":13},{"type":"A","stem":"可作为安定麻醉术成分的药物是","options":{"A":"氟哌啶醇","B":"氟奋乃静","C":"氟哌利多","D":"氯普噻吨","E":"五氟利多"},"answer":["C"],"rationale":"氟哌利多与芬太尼合用组成神经安定镇痛术（安定麻醉术）。","expl":{"A":"错误，氟哌啶醇为抗精神病药，不作安定麻醉术成分。","B":"错误，氟奋乃静为长效抗精神病药，不作安定麻醉术成分。","C":"正确，氟哌利多与芬太尼合用组成神经安定镇痛术（安定麻醉术）。","D":"错误，氯普噻吨用于伴焦虑抑郁的精神分裂症，不作安定麻醉术成分。","E":"错误，五氟利多为长效抗精神病药，不作安定麻醉术成分。"},"id":"ph16_q14","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":14},{"type":"A","stem":"吩噻嗪类药物降压作用最强的是","options":{"A":"奋乃静","B":"氯丙嗪","C":"硫利达嗪","D":"氟奋乃静","E":"三氟拉嗪"},"answer":["B"],"rationale":"氯丙嗪阻断α肾上腺素受体作用明显，降压作用在吩噻嗪类中最强。","expl":{"A":"错误，奋乃静降压作用弱于氯丙嗪。","B":"正确，氯丙嗪阻断α受体作用强，降压作用在吩噻嗪类中最强。","C":"错误，硫利达嗪降压作用较弱。","D":"错误，氟奋乃静降压作用弱于氯丙嗪。","E":"错误，三氟拉嗪降压作用弱于氯丙嗪。"},"id":"ph16_q15","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":15},{"type":"A","stem":"氯丙嗪在正常人引起的作用是","options":{"A":"烦躁不安","B":"情绪高涨","C":"紧张失眠","D":"感情淡漠","E":"以上都不是"},"answer":["D"],"rationale":"氯丙嗪使正常人表现为安静、活动减少、感情淡漠、对周围事物缺乏兴趣。","expl":{"A":"错误，氯丙嗪有镇静作用，不引起烦躁不安。","B":"错误，氯丙嗪不引起情绪高涨。","C":"错误，氯丙嗪镇静，不引起紧张失眠。","D":"正确，氯丙嗪使正常人表现为感情淡漠、活动减少。","E":"错误，感情淡漠是氯丙嗪对正常人的典型作用，故以上都不是不成立。"},"id":"ph16_q16","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":16},{"type":"A","stem":"米帕明最常见的副作用是","options":{"A":"阿托品样作用","B":"变态反应","C":"中枢神经症状","D":"造血系统损害","E":"奎尼丁样作用"},"answer":["A"],"rationale":"米帕明阻断M胆碱受体，产生口干、便秘、视力模糊、尿潴留等阿托品样作用，最常见。","expl":{"A":"正确，米帕明阻断M胆碱受体，出现口干、便秘、视物模糊等阿托品样作用，最常见。","B":"错误，变态反应少见，非最常见副作用。","C":"错误，中枢神经症状可出现，但非最常见。","D":"错误，造血系统损害少见。","E":"错误，奎尼丁样心脏毒性可出现，但非最常见。"},"id":"ph16_q17","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":17},{"type":"A","stem":"氯丙嗪可引起下列哪种激素分泌？","options":{"A":"甲状腺激素","B":"催乳素","C":"促肾上腺皮质激素","D":"促性腺激素","E":"生长激素"},"answer":["B"],"rationale":"氯丙嗪阻断结节-漏斗通路DA受体，解除对催乳素分泌的抑制，使催乳素分泌增加。","expl":{"A":"错误，氯丙嗪不促进甲状腺激素分泌。","B":"正确，氯丙嗪阻断结节-漏斗通路DA受体，使催乳素分泌增加。","C":"错误，氯丙嗪不促进促肾上腺皮质激素分泌。","D":"错误，氯丙嗪抑制促性腺激素释放，而非促进其分泌。","E":"错误，氯丙嗪不促进生长激素分泌。"},"id":"ph16_q18","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":18},{"type":"A","stem":"使用胆碱受体阻断药反可使氯丙的哪种不良反应加重？","options":{"A":"帕金森综合症","B":"迟发性运动障碍","C":"静坐不能","D":"体位性低血压","E":"急性肌张障碍"},"answer":["B"],"rationale":"迟发性运动障碍与DA受体长期阻断后超敏有关，使用抗胆碱药可使其加重。","expl":{"A":"错误，帕金森综合征可用抗胆碱药（苯海索）缓解。","B":"正确，抗胆碱药可使迟发性运动障碍加重，故不宜使用。","C":"错误，静坐不能可用抗胆碱药缓解。","D":"错误，体位性低血压与抗胆碱药关系不大。","E":"错误，急性肌张力障碍可用抗胆碱药缓解。"},"id":"ph16_q19","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":19},{"type":"A","stem":"氟奋乃静的作用特点是","options":{"A":"抗精神病和降压作用都强","B":"抗精神病和锥体外系作用都强","C":"抗精神病和降压作用都弱","D":"抗精神病和锥体外系作用都弱","E":"抗精神现和镇静作用都强"},"answer":["B"],"rationale":"氟奋乃静为高效价类，抗精神病作用强，锥体外系反应也强，而降压、镇静作用弱。","expl":{"A":"错误，氟奋乃静降压作用弱。","B":"正确，氟奋乃静抗精神病作用强，锥体外系反应也强。","C":"错误，氟奋乃静抗精神病作用强而非弱。","D":"错误，氟奋乃静锥体外系作用强而非弱。","E":"错误，氟奋乃静镇静作用弱。"},"id":"ph16_q20","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":20},{"type":"A","stem":"氯丙嗪长期大剂量应用最严重的不良反应","options":{"A":"胃肠道反应","B":"体位性低血压","C":"中枢神经系统反应","D":"锥体外系反应","E":"变态反应"},"answer":["D"],"rationale":"锥体外系反应是氯丙嗪长期大剂量应用最常见且较严重的不良反应。","expl":{"A":"错误，胃肠道反应较轻，不突出。","B":"错误，体位性低血压多见于用药初期，易耐受。","C":"错误，中枢抑制（嗜睡）可逐渐耐受，不如锥体外系反应严重。","D":"正确，锥体外系反应是氯丙嗪长期大剂量最严重的不良反应。","E":"错误，变态反应少见。"},"id":"ph16_q21","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":21},{"type":"A","stem":"可用于治疗氯丙嗪引起的帕金森综合症的药物是","options":{"A":"多巴胺","B":"地西泮","C":"苯海索","D":"左旋多巴","E":"美多巴"},"answer":["C"],"rationale":"苯海索为中枢抗胆碱药，可缓解帕金森综合征；左旋多巴因DA受体被阻断而无效。","expl":{"A":"错误，多巴胺不能透过血脑屏障，无效。","B":"错误，地西泮无抗帕金森作用。","C":"正确，苯海索为中枢抗胆碱药，可对抗氯丙嗪引起的帕金森综合征。","D":"错误，左旋多巴因DA受体被氯丙嗪阻断而无效。","E":"错误，美多巴（左旋多巴+卡比多巴）同样无效。"},"id":"ph16_q22","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":22},{"type":"A","stem":"吩噻嗪类药物引起锥体外系反应的机制是阻断","options":{"A":"中脑－边缘叶通路 DA 受体","B":"结节－漏斗通路 DA 受体","C":"黑质－纹状体通路 DA 受体","D":"中脑－皮质通路 DA 受体","E":"中枢 M 胆碱受体"},"answer":["C"],"rationale":"阻断黑质-纹状体通路DA受体，使胆碱能功能相对亢进，产生锥体外系反应。","expl":{"A":"错误，阻断中脑-边缘叶通路DA受体与抗精神病作用有关。","B":"错误，阻断结节-漏斗通路DA受体与内分泌改变有关。","C":"正确，阻断黑质-纹状体通路DA受体引起锥体外系反应。","D":"错误，阻断中脑-皮质通路DA受体与抗精神病作用有关。","E":"错误，锥体外系反应源于DA受体阻断，并非直接阻断M胆碱受体。"},"id":"ph16_q23","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":23},{"type":"A","stem":"碳酸锂主要用于治疗","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"焦虑症","E":"多动症"},"answer":["A"],"rationale":"碳酸锂为抗躁狂药，主要用于治疗躁狂症。","expl":{"A":"正确，碳酸锂是抗躁狂药，主要用于治疗躁狂症。","B":"错误，抑郁症主要用抗抑郁药，碳酸锂非首选。","C":"错误，精神分裂症主要用抗精神病药。","D":"错误，焦虑症主要用抗焦虑药。","E":"错误，多动症主要用中枢兴奋药。"},"id":"ph16_q24","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":24},{"type":"A","stem":"氯丙嗪对下列哪种病因所致的呕吐无效？","options":{"A":"癌症","B":"晕动病","C":"胃肠炎","D":"吗啡","E":"放射病"},"answer":["B"],"rationale":"氯丙嗪镇吐作用强，对多种原因呕吐有效，但对前庭性呕吐（晕动病）无效。","expl":{"A":"错误，氯丙嗪对癌症（化疗）引起的呕吐有效。","B":"正确，氯丙嗪对晕动病（前庭性呕吐）无效。","C":"错误，氯丙嗪对胃肠炎引起的呕吐有效。","D":"错误，氯丙嗪对吗啡等引起的呕吐有效。","E":"错误，氯丙嗪对放射病引起的呕吐有效。"},"id":"ph16_q25","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":25},{"type":"A","stem":"不属于三环类的抗抑郁药是","options":{"A":"米帕明","B":"地昔帕明","C":"马普替林","D":"阿米替林","E":"多塞平"},"answer":["C"],"rationale":"马普替林为四环类抗抑郁药，不属于三环类抗抑郁药。","expl":{"A":"错误，米帕明（丙米嗪）为三环类抗抑郁药。","B":"错误，地昔帕明为三环类抗抑郁药。","C":"正确，马普替林为四环类抗抑郁药，不属三环类。","D":"错误，阿米替林为三环类抗抑郁药。","E":"错误，多塞平为三环类抗抑郁药。"},"id":"ph16_q26","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":26},{"type":"B","stem":"氯丙嗪主要用于","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"晕动病","E":"安定麻醉术"},"answer":["C"],"rationale":"氯丙嗪是经典抗精神病药，主要用于治疗精神分裂症。","expl":{"A":"错误，躁狂症主要用碳酸锂，氯丙嗪非首选。","B":"错误，抑郁症应用抗抑郁药。","C":"正确，氯丙嗪为经典抗精神病药，主要用于精神分裂症。","D":"错误，氯丙嗪对晕动病引起的呕吐无效。","E":"错误，安定麻醉术用氟哌利多与芬太尼。"},"id":"ph16_q27","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":27},{"type":"B","stem":"氟哌利多主要用于","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"晕动病","E":"安定麻醉术"},"answer":["E"],"rationale":"氟哌利多与芬太尼合用组成神经安定镇痛术（安定麻醉术），是其最主要的临床用途。","expl":{"A":"错误，躁狂症主要用锂盐、氯丙嗪等，氟哌利多不用于躁狂症。","B":"错误，抑郁症用抗抑郁药治疗，氟哌利多无效。","C":"错误，精神分裂症主要用氯丙嗪、氟哌啶醇等，氟哌利多并非首选。","D":"错误，晕动病用东莨菪碱、苯海拉明等抗胆碱/抗组胺药。","E":"正确，氟哌利多与芬太尼合用组成神经安定镇痛术（安定麻醉术）。"},"id":"ph16_q28","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":28},{"type":"B","stem":"碳酸锂主要用于","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"晕动病","E":"安定麻醉术"},"answer":["A"],"rationale":"碳酸锂为抗躁狂药，主要用于治疗躁狂症。","expl":{"A":"正确，碳酸锂是抗躁狂药，主要用于躁狂症的治疗和预防。","B":"错误，抑郁症用抗抑郁药，碳酸锂非首选。","C":"错误，精神分裂症用抗精神病药。","D":"错误，晕动病用抗组胺药、东莨菪碱等。","E":"错误，安定麻醉术用氟哌利多与芬太尼。"},"id":"ph16_q29","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":29},{"type":"B","stem":"米帕明主要用于","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"晕动病","E":"安定麻醉术"},"answer":["B"],"rationale":"米帕明（丙米嗪）为三环类抗抑郁药，主要用于治疗抑郁症。","expl":{"A":"错误，躁狂症用碳酸锂。","B":"正确，米帕明为三环类抗抑郁药，主要用于抑郁症。","C":"错误，精神分裂症用抗精神病药。","D":"错误，晕动病用抗组胺药、东莨菪碱等。","E":"错误，安定麻醉术用氟哌利多与芬太尼。"},"id":"ph16_q30","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":30},{"type":"B","stem":"氯普噻吨主要用于","options":{"A":"躁狂症","B":"抑郁症","C":"精神分裂症","D":"晕动病","E":"安定麻醉术"},"answer":["C"],"rationale":"氯普噻吨为硫杂蒽类抗精神病药，主要用于伴有焦虑、抑郁的精神分裂症。","expl":{"A":"错误，躁狂症用碳酸锂。","B":"错误，抑郁症用抗抑郁药。","C":"正确，氯普噻吨为抗精神病药，主要用于伴焦虑抑郁的精神分裂症。","D":"错误，晕动病用抗组胺药、东莨菪碱等。","E":"错误，安定麻醉术用氟哌利多与芬太尼。"},"id":"ph16_q31","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":31},{"type":"C","stem":"碳酸锂","options":{"A":"阻断M胆碱","B":"阻断 DA 受体","C":"两者均可","D":"两者均否"},"answer":["D"],"rationale":"碳酸锂既不阻断M胆碱受体，也不阻断DA受体，其抗躁狂作用与影响神经递质代谢有关。","expl":{"A":"错误，碳酸锂不阻断M胆碱受体。","B":"错误，碳酸锂不阻断DA受体。","C":"错误，碳酸锂两者均不阻断。","D":"正确，碳酸锂不阻断M胆碱受体，也不阻断DA受体。"},"id":"ph16_q32","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":32},{"type":"C","stem":"米帕明","options":{"A":"阻断M胆碱","B":"阻断 DA 受体","C":"两者均可","D":"两者均否"},"answer":["A"],"rationale":"米帕明阻断M胆碱受体，产生阿托品样作用；不阻断DA受体。","expl":{"A":"正确，米帕明阻断M胆碱受体，引起口干、便秘、视力模糊等阿托品样作用。","B":"错误，米帕明不阻断DA受体。","C":"错误，米帕明仅阻断M胆碱受体，不阻断DA受体。","D":"错误，米帕明可阻断M胆碱受体，故非两者均否。"},"id":"ph16_q33","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":33},{"type":"C","stem":"氯丙嗪","options":{"A":"阻断M胆碱","B":"阻断 DA 受体","C":"两者均可","D":"两者均否"},"answer":["B"],"rationale":"氯丙嗪的抗精神病作用主要通过阻断DA受体实现，故本题按其主要机制选阻断DA受体。","expl":{"A":"错误，氯丙嗪虽有一定抗胆碱作用，但其代表机制是阻断DA受体，不按两者均可计。","B":"正确，氯丙嗪通过阻断中脑-边缘叶、中脑-皮质通路DA受体发挥抗精神病作用。","C":"错误，本题按氯丙嗪的主要作用机制计为阻断DA受体，非两者均可。","D":"错误，氯丙嗪确实阻断DA受体。"},"id":"ph16_q34","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":34},{"type":"C","stem":"氟哌啶醇","options":{"A":"阻断M胆碱","B":"阻断 DA 受体","C":"两者均可","D":"两者均否"},"answer":["B"],"rationale":"氟哌啶醇为丁酰苯类，通过强效阻断DA受体发挥抗精神病作用，无阻断M胆碱受体作用。","expl":{"A":"错误，氟哌啶醇无明显阻断M胆碱受体作用。","B":"正确，氟哌啶醇通过强效阻断DA受体发挥抗精神病作用。","C":"错误，氟哌啶醇主要阻断DA受体，不阻断M胆碱受体。","D":"错误，氟哌啶醇确实阻断DA受体。"},"id":"ph16_q35","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":35},{"type":"X","stem":"氯丙嗪扩张血管的原因包括","options":{"A":"阻断 a 肾上腺素受体","B":"阻断M胆碱受体","C":"抑制血管运动中枢","D":"减少NA的释放","E":"直接舒张血管平滑肌"},"answer":["A","C","D"],"rationale":"氯丙嗪通过阻断α受体、抑制血管运动中枢及减少去甲肾上腺素释放，共同引起血管扩张、血压下降。","expl":{"A":"正确，氯丙嗪阻断α肾上腺素受体，使血管扩张。","B":"错误，阻断M胆碱受体与扩张血管关系不大。","C":"正确，氯丙嗪抑制血管运动中枢，降低交感缩血管张力。","D":"正确，氯丙嗪减少去甲肾上腺素释放，降低血管收缩作用。","E":"错误，氯丙嗪扩张血管主要经受体阻断和中枢抑制，非直接舒张血管平滑肌。"},"id":"ph16_q36","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":36},{"type":"X","stem":"氯丙嗪的中枢药理作用包括","options":{"A":"昏迷病人","B":"癫痫","C":"严重肝功能损害","D":"高血压","E":"胃溃疡"},"answer":["A","B","D"],"rationale":"本题考查氯丙嗪的禁忌证：氯丙嗪可加重中枢抑制、降低惊厥阈值并影响心血管功能，故昏迷病人、癫痫及高血压患者禁用或慎用。","expl":{"A":"正确，氯丙嗪抑制中枢，昏迷病人（尤其中枢抑制药中毒）禁用，以免加重呼吸循环抑制。","B":"正确，氯丙嗪降低惊厥阈值，可诱发或加重癫痫，癫痫患者禁用。","C":"错误，氯丙嗪主要经肝代谢、可致肝损害，严重肝功能损害者须慎用，但本题未将其列为正确项。","D":"正确，氯丙嗪阻断α受体可致体位性低血压，高血压（心血管疾病）患者须慎用。","E":"错误，胃溃疡并非氯丙嗪禁忌，其抗胆碱作用反可减少胃酸分泌。"},"id":"ph16_q37","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":37},{"type":"X","stem":"治疗躁狂症的药物有","options":{"A":"碳酸锂","B":"马普替林","C":"氯丙嗪","D":"氟哌啶醇","E":"多塞平"},"answer":["A","C","D"],"rationale":"碳酸锂为抗躁狂药，氯丙嗪、氟哌啶醇等抗精神病药也可控制躁狂症的兴奋躁动。","expl":{"A":"正确，碳酸锂为经典抗躁狂药，是治疗躁狂症的首选。","B":"错误，马普替林为抗抑郁药，用于抑郁症。","C":"正确，氯丙嗪可控制躁狂症的兴奋躁动。","D":"正确，氟哌啶醇可有效控制躁狂发作的兴奋躁动。","E":"错误，多塞平为三环类抗抑郁药，用于抑郁症。"},"id":"ph16_q38","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":38},{"type":"X","stem":"氯丙嗪降温特点包括","options":{"A":"抑制体温调节中枢，使体温调节失灵","B":"不仅降低发热体温，也降低正常体温","C":"临床上配合物理降温用于低温麻醉","D":"对体温的影响与环境温度无关","E":"作为人工冬眠，使体温、代谢及耗氧量均降低"},"answer":["A","B","C","E"],"rationale":"氯丙嗪抑制下丘脑体温调节中枢，使体温调节失灵，降低发热和正常体温，其降温作用受环境温度影响。","expl":{"A":"正确，氯丙嗪抑制下丘脑体温调节中枢，使体温调节功能失灵。","B":"正确，氯丙嗪不仅降低发热体温，也降低正常体温。","C":"正确，临床配合物理降温可用于低温麻醉。","D":"错误，氯丙嗪降温作用受环境温度影响，环境温度越低降温越明显。","E":"正确，作为人工冬眠成分，使体温、代谢及耗氧量均降低。"},"id":"ph16_q39","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":39},{"type":"X","stem":"氯丙嗪可阻断的受体包括","options":{"A":"DA 受体","B":"5－HT 受体","C":"M胆碱受体","D":"a 肾上腺素受体","E":"甲状腺素受体"},"answer":["A","B","C","D"],"rationale":"氯丙嗪可阻断多种受体：DA受体、α肾上腺素受体、M胆碱受体、5-HT2受体及H1受体等，除甲状腺素受体外均正确。","expl":{"A":"正确，阻断中脑-边缘/皮质通路DA受体是氯丙嗪抗精神病作用的主要机制。","B":"正确，氯丙嗪可阻断5-HT2受体。","C":"正确，阻断M受体可产生口干、便秘、视力模糊等副作用。","D":"正确，阻断α受体可引起体位性低血压。","E":"错误，氯丙嗪不阻断甲状腺素受体。"},"id":"ph16_q40","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":40},{"type":"X","stem":"对抑郁症有效的药物有","options":{"A":"氯丙嗪","B":"氯普噻吨","C":"米帕明","D":"舒必利","E":"碳酸锂"},"answer":["B","C","D","E"],"rationale":"氯普噻吨、米帕明、舒必利均有抗抑郁作用，碳酸锂对抑郁症（尤其双相）也有一定疗效。","expl":{"A":"错误，氯丙嗪为抗精神病药，无抗抑郁作用。","B":"正确，氯普噻吨兼具抗抑郁作用，可用于伴抑郁的精神分裂症。","C":"正确，米帕明为三环类抗抑郁药，对抑郁症有效。","D":"正确，舒必利小剂量有抗抑郁作用。","E":"正确，碳酸锂对抑郁症（尤其双相障碍）有一定治疗和预防作用。"},"id":"ph16_q41","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":41},{"type":"X","stem":"氯丙嗪的锥体外系反应有","options":{"A":"急性肌张力障碍","B":"体位性低血压","C":"静坐不能","D":"帕金森综合症","E":"迟发性运动障碍"},"answer":["A","C","D","E"],"rationale":"锥体外系反应包括帕金森综合征、静坐不能、急性肌张力障碍和迟发性运动障碍；体位性低血压属心血管反应。","expl":{"A":"正确，急性肌张力障碍属锥体外系反应。","B":"错误，体位性低血压是阻断α受体所致的心血管反应，非锥体外系反应。","C":"正确，静坐不能属锥体外系反应。","D":"正确，帕金森综合征属锥体外系反应。","E":"正确，迟发性运动障碍属锥体外系反应。"},"id":"ph16_q42","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":42},{"type":"X","stem":"苯海索对氯丙嗪引起的哪些不良反应有效？","options":{"A":"急性肌张力障碍","B":"体位性低血压","C":"静坐不能","D":"帕金森综合症","E":"迟发性运动障碍"},"answer":["A","C","D"],"rationale":"苯海索为中枢抗胆碱药，可缓解帕金森综合征、急性肌张力障碍和静坐不能，对迟发性运动障碍反而加重。","expl":{"A":"正确，苯海索可缓解急性肌张力障碍。","B":"错误，苯海索不能纠正体位性低血压。","C":"正确，苯海索可缓解静坐不能。","D":"正确，苯海索可缓解帕金森综合征。","E":"错误，苯海索可使迟发性运动障碍加重，不宜使用。"},"id":"ph16_q43","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":43},{"type":"X","stem":"与氯丙嗪抗精神病作用机制有关的DA神经通路有","options":{"A":"中脑－边缘叶通路","B":"黑质－纹状体通路","C":"结节－漏斗通路","D":"中脑－皮质通路","E":"脑干网状结构上行激活系统"},"answer":["A","D"],"rationale":"氯丙嗪抗精神病作用主要与阻断中脑-边缘叶通路和中脑-皮质通路的DA受体有关。","expl":{"A":"正确，阻断中脑-边缘叶通路DA受体与抗精神病（阳性症状）作用有关。","B":"错误，阻断黑质-纹状体通路DA受体引起锥体外系反应。","C":"错误，阻断结节-漏斗通路DA受体引起内分泌改变。","D":"正确，阻断中脑-皮质通路DA受体与抗精神病（阴性症状）作用有关。","E":"错误，脑干网状结构上行激活系统与觉醒有关，非抗精神病作用机制。"},"id":"ph16_q44","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":44},{"type":"A","stem":"氯氮平最严重的不良反应是","options":{"A":"锥体外系反应","B":"迟发性运动障碍","C":"催乳素升高","D":"体位性低血压","E":"粒细胞减少"},"answer":["E"],"rationale":"氯氮平虽锥体外系反应轻微，但可引起粒细胞减少甚至粒细胞缺乏，用药期间须定期监测血象，故答案为 E。","expl":{"A":"错误，氯氮平对D2受体阻断作用弱，锥体外系反应在抗精神病药中相对轻微。","B":"错误，迟发性运动障碍多见于长期应用经典抗精神病药者。","C":"错误，氯氮平较少引起催乳素升高，是少数不升高催乳素者之一。","D":"错误，体位性低血压较常见，但并非最严重的不良反应。","E":"正确，粒细胞缺乏可危及生命，是限制其使用的关键不良反应。"},"id":"ph16_q45","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":45},{"type":"A","stem":"氟哌啶醇的作用特点是","options":{"A":"镇静作用强，锥体外系反应轻","B":"主要用于抑郁症的治疗","C":"无抗幻觉妄想作用","D":"主要用于躁狂症的治疗","E":"抗精神病作用强，锥体外系反应明显"},"answer":["E"],"rationale":"氟哌啶醇属丁酰苯类，阻断D2受体作用强，抗幻觉妄想和抗躁狂作用显著，但锥体外系反应发生率高，故答案为 E。","expl":{"A":"错误，其镇静作用较弱，且锥体外系反应明显而非轻微。","B":"错误，氟哌啶醇用于精神分裂症和躁狂症，不是抗抑郁药。","C":"错误，其抗幻觉妄想作用很强，是治疗精神分裂症的常用药物。","D":"错误，虽可用于躁狂症，但其主要适应证是精神分裂症。","E":"正确，其抗精神病作用强而锥体外系反应突出，是丁酰苯类的代表药。"},"id":"ph16_q46","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":46}]},{"title":"第十七章 镇痛药","questions":[{"type":"A","stem":"典型的镇痛药其特点是","options":{"A":"有镇痛、解热作用","B":"有镇痛、抗炎作用","C":"有镇痛、解热、抗炎作用","D":"有强大的镇痛作用，无成瘾性","E":"有强大的镇痛作用，反复应用容易成瘾"},"answer":["E"],"rationale":"典型镇痛药（阿片类）主要作用于中枢，镇痛作用强大，但反复应用易产生成瘾性，故选E。","expl":{"A":"错误，解热作用是解热镇痛抗炎药的特点，阿片类无解热作用。","B":"错误，阿片类无抗炎作用，抗炎属于阿司匹林类特点。","C":"错误，解热、抗炎均为解热镇痛抗炎药作用，阿片类不具备。","D":"错误，成瘾性是阿片类镇痛药的突出缺点，并非无成瘾性。","E":"正确，镇痛强大且反复应用易成瘾是典型镇痛药的特点。"},"id":"ph17_q01","chapter":"第十七章 镇痛药","chapterIdx":16,"num":1},{"type":"A","stem":"吗啡常用注射给药的原因是","options":{"A":"口服不吸收","B":"片剂不稳定","C":"易被肠道破坏","D":"首关消除明显","E":"口服刺激性大"},"answer":["D"],"rationale":"吗啡口服可吸收，但经肝脏首关消除明显，生物利用度低，故多采用注射给药。","expl":{"A":"错误，吗啡口服可被吸收，只是首关消除多。","B":"错误，与片剂稳定性无关。","C":"错误，吗啡主要在肝脏代谢，而非被肠道破坏。","D":"正确，首关消除明显使口服生物利用度低，故注射给药。","E":"错误，刺激性并非注射给药的主要原因。"},"id":"ph17_q02","chapter":"第十七章 镇痛药","chapterIdx":16,"num":2},{"type":"A","stem":"吗啡一次给药，镇痛作用可持续","options":{"A":"导水管周围灰质","B":"蓝斑核","C":"延脑的孤束核","D":"中脑盖前核","E":"边缘系统"},"answer":["B"],"rationale":"蓝斑核阿片受体与吗啡的欣快感、成瘾性及戒断症状密切相关（题干与选项存在错位，按正确答案解析）。","expl":{"A":"错误，导水管周围灰质是吗啡镇痛作用的主要部位。","B":"正确，蓝斑核与欣快、成瘾及戒断症状有关。","C":"错误，延脑孤束核与吗啡镇咳作用有关。","D":"错误，中脑盖前核与吗啡缩瞳作用有关。","E":"错误，边缘系统主要参与情绪等活动。"},"id":"ph17_q03","chapter":"第十七章 镇痛药","chapterIdx":16,"num":3},{"type":"A","stem":"吗啡镇咳的部位是","options":{"A":"迷走神经背核","B":"延脑的孤束核","C":"中脑盖前核","D":"导水管周围灰","E":"蓝斑核"},"answer":["B"],"rationale":"吗啡抑制延脑孤束核的咳嗽中枢，从而产生镇咳作用。","expl":{"A":"错误，迷走神经背核与镇咳无关。","B":"正确，延脑孤束核是吗啡镇咳的作用部位。","C":"错误，中脑盖前核是缩瞳作用部位。","D":"错误，导水管周围灰质是镇痛作用部位。","E":"错误，蓝斑核与欣快、成瘾有关。"},"id":"ph17_q04","chapter":"第十七章 镇痛药","chapterIdx":16,"num":4},{"type":"A","stem":"吗啡抑制呼吸的主要原因是","options":{"A":"作用于时水管周围灰质","B":"作用于蓝斑核","C":"降低呼吸中枢对血液 CO2 张力的敏感区","D":"作用于脑干极后区","E":"作用于迷走神经背核"},"answer":["C"],"rationale":"吗啡抑制呼吸主要是降低延脑呼吸中枢对血液CO2张力的敏感性，使呼吸变慢变浅。","expl":{"A":"错误，导水管周围灰质与镇痛作用有关。","B":"错误，蓝斑核与欣快、成瘾有关。","C":"正确，降低呼吸中枢对CO2敏感性是其抑制呼吸的原因。","D":"错误，脑干极后区与催吐作用有关。","E":"错误，迷走神经背核与呼吸抑制无关。"},"id":"ph17_q05","chapter":"第十七章 镇痛药","chapterIdx":16,"num":5},{"type":"A","stem":"吗啡缩瞳的原因是","options":{"A":"作用于中脑盖前核的阿片受体","B":"作用于导水管周围灰质","C":"作用于延脑孤束核的阿片受体","D":"作用于蓝斑核","E":"作用于边缘系统"},"answer":["A"],"rationale":"吗啡兴奋中脑盖前核阿片受体，进而兴奋动眼神经缩瞳核，引起瞳孔缩小。","expl":{"A":"正确，中脑盖前核阿片受体介导吗啡的缩瞳作用。","B":"错误，导水管周围灰质与镇痛有关。","C":"错误，延脑孤束核与镇咳有关。","D":"错误，蓝斑核与欣快、成瘾有关。","E":"错误，边缘系统与情绪活动有关。"},"id":"ph17_q06","chapter":"第十七章 镇痛药","chapterIdx":16,"num":6},{"type":"A","stem":"镇痛作用最强的药物是","options":{"A":"吗啡","B":"喷他佐辛","C":"芬太尼","D":"美沙酮","E":"可待因"},"answer":["C"],"rationale":"芬太尼镇痛作用强，约为吗啡的100倍，是所列药物中镇痛作用最强的。","expl":{"A":"错误，吗啡镇痛强但弱于芬太尼。","B":"错误，喷他佐辛镇痛效力仅为吗啡的1/3。","C":"正确，芬太尼镇痛约为吗啡的100倍，最强。","D":"错误，美沙酮镇痛强度与吗啡相当。","E":"错误，可待因镇痛约为吗啡的1/10，较弱。"},"id":"ph17_q07","chapter":"第十七章 镇痛药","chapterIdx":16,"num":7},{"type":"A","stem":"哌替啶比吗啡应用多的原因是","options":{"A":"无便秘作用","B":"呼吸抑制作用轻","C":"作用较慢，维持时间短","D":"成瘾性较吗啡轻","E":"对支气平滑肌无影响"},"answer":["D"],"rationale":"哌替啶的成瘾性较吗啡轻，且对平滑肌影响较小，故临床上较吗啡应用更广。","expl":{"A":"错误，哌替啶亦有便秘作用，只是较吗啡轻。","B":"错误，哌替啶同样可抑制呼吸。","C":"错误，哌替啶作用较快且维持时间短。","D":"正确，成瘾性较吗啡轻是哌替啶应用较多的原因。","E":"错误，哌替啶对支气管平滑肌也有一定影响。"},"id":"ph17_q08","chapter":"第十七章 镇痛药","chapterIdx":16,"num":8},{"type":"A","stem":"胆绞痛病人最好选用","options":{"A":"阿托品","B":"哌替啶","C":"氯丙嗪＋阿托品","D":"哌替啶＋阿托品","E":"阿司匹林＋阿托品．"},"answer":["D"],"rationale":"胆绞痛为平滑肌痉挛性疼痛，哌替啶镇痛、阿托品解除痉挛，合用效果最佳。","expl":{"A":"错误，阿托品只解痉，镇痛作用不足。","B":"错误，单用哌替啶镇痛但无解痉作用，且可提高胆道平滑肌张力。","C":"错误，氯丙嗪无解痉作用，不能替代哌替啶。","D":"正确，哌替啶镇痛配合阿托品解痉，为胆绞痛优选。","E":"错误，阿司匹林对内脏绞痛效果差。"},"id":"ph17_q09","chapter":"第十七章 镇痛药","chapterIdx":16,"num":9},{"type":"A","stem":"心源性哮喘可以选用","options":{"A":"肾上腺素","B":"沙丁胺醇","C":"地塞米松","D":"格列齐特","E":"吗啡"},"answer":["E"],"rationale":"吗啡扩张外周血管、降低心脏前后负荷，并抑制呼吸中枢，可缓解心源性哮喘。","expl":{"A":"错误，肾上腺素用于支气管哮喘或过敏性休克。","B":"错误，沙丁胺醇用于支气管哮喘。","C":"错误，地塞米松不用于心源性哮喘急性发作。","D":"错误，格列齐特是降血糖药。","E":"正确，吗啡可用于心源性哮喘。"},"id":"ph17_q10","chapter":"第十七章 镇痛药","chapterIdx":16,"num":10},{"type":"A","stem":"吗啡镇痛作用的主要部位是","options":{"A":"蓝斑核的阿片受体","B":"丘脑内侧、脑室及导水管周围灰质","C":"黑质－纹状体通路","D":"脑干网状结构","E":"大脑边缘系统"},"answer":["B"],"rationale":"吗啡主要作用于丘脑内侧、脑室及导水管周围灰质的阿片受体，产生镇痛作用。","expl":{"A":"错误，蓝斑核与欣快、成瘾有关。","B":"正确，丘脑内侧、脑室及导水管周围灰质是镇痛主要部位。","C":"错误，黑质-纹状体通路与锥体外系运动有关。","D":"错误，脑干网状结构与镇痛关系不大。","E":"错误，大脑边缘系统与情绪活动有关。"},"id":"ph17_q11","chapter":"第十七章 镇痛药","chapterIdx":16,"num":11},{"type":"A","stem":"吗啡的镇痛作用最适用于","options":{"A":"其他镇痛药无效时的急性锐痛","B":"神经痛","C":"脑外伤疼痛","D":"分娩止痛","E":"诊断未明的急腹症疼痛"},"answer":["A"],"rationale":"吗啡镇痛作用强，最适用于其他镇痛药无效的急性锐痛，如严重创伤、心肌梗死等剧痛。","expl":{"A":"正确，其他镇痛药无效的急性锐痛是吗啡的主要适应证。","B":"错误，吗啡对神经痛效果差。","C":"错误，脑外伤时吗啡可抑制呼吸、升高颅压，属禁用。","D":"错误，分娩止痛不宜用吗啡，以免抑制新生儿呼吸。","E":"错误，诊断未明的急腹症禁用吗啡，以免掩盖病情。"},"id":"ph17_q12","chapter":"第十七章 镇痛药","chapterIdx":16,"num":12},{"type":"A","stem":"二氢埃托啡镇痛作用的主要部位是","options":{"A":"壳核","B":"大脑边缘系统","C":"延脑苍白球","D":"延髓孤束核","E":"丘脑内侧、脑室及导水管周围灰质"},"answer":["E"],"rationale":"二氢埃托啡与吗啡相似，其镇痛作用部位亦在丘脑内侧、脑室及导水管周围灰质。","expl":{"A":"错误，壳核属基底节，与镇痛无关。","B":"错误，大脑边缘系统与情绪活动有关。","C":"错误，苍白球属基底节，无“延脑苍白球”这一结构。","D":"错误，延髓孤束核主要参与内脏反射调节，不是二氢埃托啡镇痛作用的主要部位。","E":"正确，丘脑内侧、脑室及导水管周围灰质是镇痛主要部位。"},"id":"ph17_q13","chapter":"第十七章 镇痛药","chapterIdx":16,"num":13},{"type":"A","stem":"人工冬眠合剂的组成是","options":{"A":"哌替啶、氯丙嗪、异丙嗪","B":"派替啶、吗啡、异丙嗪","C":"哌替啶、芬太尼、氯丙嗪","D":"哌替啶、芬太尼、异丙嗪","E":"芬太尼、氯丙嗪、异丙嗪"},"answer":["A"],"rationale":"人工冬眠合剂Ⅰ号由哌替啶、氯丙嗪、异丙嗪组成。","expl":{"A":"正确，三者组成人工冬眠合剂Ⅰ号。","B":"错误，含吗啡而非氯丙嗪。","C":"错误，含芬太尼而非异丙嗪。","D":"错误，含芬太尼而非氯丙嗪。","E":"错误，含芬太尼而非哌替啶。"},"id":"ph17_q14","chapter":"第十七章 镇痛药","chapterIdx":16,"num":14},{"type":"A","stem":"镇痛作用较吗啡强 100 倍的药物是","options":{"A":"哌替啶","B":"安那度","C":"芬太尼","D":"可待因","E":"曲马朵"},"answer":["C"],"rationale":"芬太尼镇痛作用强，约为吗啡的80~100倍（常记为100倍）。","expl":{"A":"错误，哌替啶镇痛约为吗啡的1/10。","B":"错误，安那度镇痛较吗啡弱，起效快、维持短。","C":"正确，芬太尼镇痛较吗啡强约100倍。","D":"错误，可待因镇痛约为吗啡的1/10。","E":"错误，曲马朵镇痛强度与喷他佐辛相近，较弱。"},"id":"ph17_q15","chapter":"第十七章 镇痛药","chapterIdx":16,"num":15},{"type":"A","stem":"主要激动阿片 k、s 受体，又可拮抗 m 受体的药物是","options":{"A":"美沙酮","B":"吗啡","C":"喷他佐辛","D":"曲马朵","E":"二氢埃托啡"},"answer":["C"],"rationale":"喷他佐辛为激动-拮抗型镇痛药，主要激动κ、σ受体，同时又可拮抗μ受体。","expl":{"A":"错误，美沙酮为μ受体激动剂。","B":"错误，吗啡主要激动μ受体。","C":"正确，喷他佐辛激动κ、σ受体并拮抗μ受体。","D":"错误，曲马朵主要激动μ受体并抑制单胺再摄取。","E":"错误，二氢埃托啡为μ受体激动剂。"},"id":"ph17_q16","chapter":"第十七章 镇痛药","chapterIdx":16,"num":16},{"type":"A","stem":"在药政管理上已列入非麻醉品的镇痛药是","options":{"A":"哌替啶","B":"芬太尼","C":"安那度","D":"喷他佐辛","E":"美沙酮"},"answer":["D"],"rationale":"喷他佐辛成瘾性小，在药政管理上已列入非麻醉药品。","expl":{"A":"错误，哌替啶属麻醉药品管理。","B":"错误，芬太尼属麻醉药品管理。","C":"错误，安那度属麻醉药品管理。","D":"正确，喷他佐辛已列入非麻醉药品。","E":"错误，美沙酮属麻醉药品管理。"},"id":"ph17_q17","chapter":"第十七章 镇痛药","chapterIdx":16,"num":17},{"type":"A","stem":"与吗啡成瘾性及戒断症状有直接联系的部位是","options":{"A":"孤束核","B":"盖前核","C":"蓝斑核","D":"壳核","E":"迷走神经背核"},"answer":["C"],"rationale":"蓝斑核阿片受体与吗啡的欣快、成瘾及戒断症状有直接联系。","expl":{"A":"错误，孤束核与镇咳有关。","B":"错误，盖前核与缩瞳有关。","C":"正确，蓝斑核与成瘾及戒断症状直接相关。","D":"错误，壳核属基底节，与运动调节有关。","E":"错误，迷走神经背核与成瘾戒断无关。"},"id":"ph17_q18","chapter":"第十七章 镇痛药","chapterIdx":16,"num":18},{"type":"A","stem":"对吗啡急性中毒呼吸抑制有显著疗效的药和物是","options":{"A":"多巴胺","B":"肾上腺素","C":"咖啡因","D":"纳洛酮","E":"山梗菜碱"},"answer":["D"],"rationale":"纳洛酮为阿片受体拮抗剂，能迅速对抗吗啡的呼吸抑制，用于急性中毒解救。","expl":{"A":"错误，多巴胺用于休克等，不能拮抗阿片。","B":"错误，肾上腺素用于过敏性休克等。","C":"错误，咖啡因为中枢兴奋药，非特异性拮抗剂。","D":"正确，纳洛酮能迅速逆转吗啡呼吸抑制。","E":"错误，山梗菜碱为呼吸兴奋药，非阿片拮抗剂。"},"id":"ph17_q19","chapter":"第十七章 镇痛药","chapterIdx":16,"num":19},{"type":"A","stem":"镇痛作用最强的药物是","options":{"A":"吗啡","B":"芬太尼","C":"二氢埃托啡","D":"哌替啶","E":"美沙酮"},"answer":["C"],"rationale":"二氢埃托啡镇痛作用极强，强于吗啡和芬太尼，是所列药物中最强者。","expl":{"A":"错误，吗啡强但弱于芬太尼和二氢埃托啡。","B":"错误，芬太尼强于吗啡但弱于二氢埃托啡。","C":"正确，二氢埃托啡镇痛作用最强。","D":"错误，哌替啶镇痛较弱。","E":"错误，美沙酮镇痛与吗啡相当。"},"id":"ph17_q20","chapter":"第十七章 镇痛药","chapterIdx":16,"num":20},{"type":"A","stem":"喷他佐辛最突出的优点是","options":{"A":"适用于各种慢性钝痛","B":"可口服给药","C":"无呼吸抑制作用","D":"成瘾性很小，已列入非麻醉药口","E":"兴奋心血管系统"},"answer":["D"],"rationale":"喷他佐辛成瘾性很小，药政管理上已列入非麻醉药品，是其最突出的优点。","expl":{"A":"错误，适用于慢性疼痛是其用途之一，但非最突出优点。","B":"错误，可口服是其特点，但非最突出优点。","C":"错误，喷他佐辛仍有呼吸抑制作用。","D":"正确，成瘾性小、列入非麻醉药品是最突出优点。","E":"错误，兴奋心血管属不良反应而非优点。"},"id":"ph17_q21","chapter":"第十七章 镇痛药","chapterIdx":16,"num":21},{"type":"A","stem":"阿片受体的拮抗剂是","options":{"A":"哌替啶","B":"美沙酮","C":"喷他佐辛","D":"芬太尼","E":"以是都不是"},"answer":["E"],"rationale":"哌替啶、美沙酮、芬太尼为阿片受体激动剂，喷他佐辛为激动-拮抗剂，均非纯拮抗剂，故以上都不是。","expl":{"A":"错误，哌替啶为μ受体激动剂。","B":"错误，美沙酮为μ受体激动剂。","C":"错误，喷他佐辛为激动-拮抗剂，非纯拮抗剂。","D":"错误，芬太尼为μ受体激动剂。","E":"正确，所列药物均非纯阿片受体拮抗剂。"},"id":"ph17_q22","chapter":"第十七章 镇痛药","chapterIdx":16,"num":22},{"type":"A","stem":"阿片受体的拮抗剂是","options":{"A":"纳曲酮","B":"喷他佐辛","C":"可待因","D":"延胡索乙素","E":"罗通定"},"answer":["A"],"rationale":"纳曲酮与纳洛酮相似，为纯阿片受体拮抗剂。","expl":{"A":"正确，纳曲酮为阿片受体拮抗剂。","B":"错误，喷他佐辛为激动-拮抗剂。","C":"错误，可待因为μ受体激动剂。","D":"错误，延胡索乙素为非阿片类中枢镇痛药。","E":"错误，罗通定为延胡索乙素左旋体，非阿片拮抗剂。"},"id":"ph17_q23","chapter":"第十七章 镇痛药","chapterIdx":16,"num":23},{"type":"A","stem":"对吗啡成瘾者可迅速诱发戒断症状的药物是","options":{"A":"哌替啶","B":"曲马朵","C":"纳洛酮","D":"美沙酮","E":"以是都不是"},"answer":["C"],"rationale":"纳洛酮阻断阿片受体，可使吗啡成瘾者迅速诱发戒断症状。","expl":{"A":"错误，哌替啶可替代吗啡，缓解戒断症状。","B":"错误，曲马朵激动阿片受体，不诱发戒断。","C":"正确，纳洛酮可迅速诱发戒断症状。","D":"错误，美沙酮用于替代脱毒治疗。","E":"错误。"},"id":"ph17_q24","chapter":"第十七章 镇痛药","chapterIdx":16,"num":24},{"type":"A","stem":"吗啡无下列哪种不良反应？","options":{"A":"引起腹泻","B":"引起便秘","C":"抑制呼吸中枢","D":"抑制咳嗽中枢","E":"引起体们性低血压"},"answer":["A"],"rationale":"吗啡提高胃肠平滑肌张力并抑制蠕动，引起便秘而非腹泻。","expl":{"A":"正确，吗啡无腹泻不良反应，反而引起便秘。","B":"错误，便秘是吗啡常见不良反应。","C":"错误，呼吸抑制是吗啡主要不良反应。","D":"错误，吗啡可抑制咳嗽中枢。","E":"错误，吗啡扩张血管可致体位性低血压。"},"id":"ph17_q25","chapter":"第十七章 镇痛药","chapterIdx":16,"num":25},{"type":"A","stem":"与脑内阿片受体无关的镇痛药是","options":{"A":"哌替啶","B":"罗通定","C":"美沙酮","D":"喷他佐辛","E":"二氢埃托啡"},"answer":["B"],"rationale":"罗通定（延胡索乙素左旋体）的镇痛作用与脑内阿片受体无关，主要与中枢抑制有关。","expl":{"A":"错误，哌替啶通过阿片受体发挥镇痛。","B":"正确，罗通定镇痛不依赖阿片受体。","C":"错误，美沙酮通过阿片受体镇痛。","D":"错误，喷他佐辛作用于阿片受体。","E":"错误，二氢埃托啡激动阿片受体。"},"id":"ph17_q26","chapter":"第十七章 镇痛药","chapterIdx":16,"num":26},{"type":"A","stem":"下列哪种情况不宜用哌替啶镇痛？","options":{"A":"创伤性疼痛","B":"手术后疼痛","C":"慢性钝痛","D":"内脏绞痛","E":"晚期癌症痛"},"answer":["C"],"rationale":"慢性钝痛长期反复应用哌替啶易产生成瘾性，故不宜选用。","expl":{"A":"错误，创伤性疼痛可选用哌替啶。","B":"错误，手术后疼痛可选用哌替啶。","C":"正确，慢性钝痛不宜反复应用，以免成瘾。","D":"错误，内脏绞痛可配阿托品应用。","E":"错误，晚期癌症痛可应用。"},"id":"ph17_q27","chapter":"第十七章 镇痛药","chapterIdx":16,"num":27},{"type":"A","stem":"吗啡不具备下列哪种药理作用？","options":{"A":"引起恶心","B":"引起体位性低血压","C":"致颅压增高","D":"引起腹泻","E":"抑制呼吸"},"answer":["D"],"rationale":"吗啡抑制肠蠕动、提高平滑肌张力，引起便秘而非腹泻。","expl":{"A":"错误，吗啡兴奋催吐化学感受区可致恶心。","B":"错误，吗啡扩张血管可致体位性低血压。","C":"错误，吗啡抑制呼吸、CO2潴留可致颅内压增高。","D":"正确，吗啡引起便秘，不引起腹泻。","E":"错误，吗啡可抑制呼吸。"},"id":"ph17_q28","chapter":"第十七章 镇痛药","chapterIdx":16,"num":28},{"type":"B","stem":"吗啡作用于延脑孤束核的阿片受体产生","options":{"A":"欣快作用","B":"镇痛作用","C":"缩瞳作用","D":"镇咳作用","E":"便秘作用"},"answer":["D"],"rationale":"延脑孤束核与咳嗽反射有关，吗啡作用于此处阿片受体产生镇咳作用。","expl":{"A":"错误，欣快作用与蓝斑核有关。","B":"错误，镇痛作用与丘脑内侧、脑室及导水管周围灰质有关。","C":"错误，缩瞳作用与中脑盖前核有关。","D":"正确，延脑孤束核介导镇咳作用。","E":"错误，便秘与胃肠平滑肌阿片受体有关。"},"id":"ph17_q29","chapter":"第十七章 镇痛药","chapterIdx":16,"num":29},{"type":"B","stem":"吗啡作用于蓝斑核的阿片受体产生","options":{"A":"欣快作用","B":"镇痛作用","C":"缩瞳作用","D":"镇咳作用","E":"便秘作用"},"answer":["A"],"rationale":"蓝斑核阿片受体与情绪活动有关，吗啡兴奋后产生欣快作用。","expl":{"A":"正确，蓝斑核介导欣快作用。","B":"错误，镇痛部位在丘脑内侧、脑室及导水管周围灰质。","C":"错误，缩瞳部位在中脑盖前核。","D":"错误，镇咳部位在延脑孤束核。","E":"错误，便秘与胃肠平滑肌有关。"},"id":"ph17_q30","chapter":"第十七章 镇痛药","chapterIdx":16,"num":30},{"type":"B","stem":"吗啡作用于中脑盖前核的阿片受体产生","options":{"A":"欣快作用","B":"镇痛作用","C":"缩瞳作用","D":"镇咳作用","E":"便秘作用"},"answer":["C"],"rationale":"中脑盖前核与动眼神经缩瞳核相连，吗啡兴奋后引起缩瞳。","expl":{"A":"错误，欣快作用与蓝斑核有关。","B":"错误，镇痛部位在丘脑内侧、脑室及导水管周围灰质。","C":"正确，中脑盖前核介导缩瞳作用。","D":"错误，镇咳部位在延脑孤束核。","E":"错误，便秘与胃肠平滑肌有关。"},"id":"ph17_q31","chapter":"第十七章 镇痛药","chapterIdx":16,"num":31},{"type":"B","stem":"吗啡作用于脑室及导水管周围灰质的阿片受体产生","options":{"A":"欣快作用","B":"镇痛作用","C":"缩瞳作用","D":"镇咳作用","E":"便秘作用"},"answer":["B"],"rationale":"脑室及导水管周围灰质是吗啡产生镇痛作用的主要部位。","expl":{"A":"错误，欣快作用与蓝斑核有关。","B":"正确，脑室及导水管周围灰质介导镇痛。","C":"错误，缩瞳部位在中脑盖前核。","D":"错误，镇咳部位在延脑孤束核。","E":"错误，便秘与胃肠平滑肌有关。"},"id":"ph17_q32","chapter":"第十七章 镇痛药","chapterIdx":16,"num":32},{"type":"B","stem":"可用于镇痛或吗啡成瘾戒毒","options":{"A":"延胡索乙素","B":"纳洛酮","C":"喷他佐辛","D":"哌替啶","E":"二氢埃托啡"},"answer":["E"],"rationale":"二氢埃托啡镇痛作用强，且曾用于吗啡成瘾的脱瘾（戒毒）治疗。","expl":{"A":"错误，延胡索乙素镇痛弱，不用于戒毒。","B":"错误，纳洛酮为拮抗剂，用于中毒解救。","C":"错误，喷他佐辛不用于戒毒。","D":"错误，哌替啶本身成瘾，不用于戒毒。","E":"正确，二氢埃托啡可用于镇痛及戒毒。"},"id":"ph17_q33","chapter":"第十七章 镇痛药","chapterIdx":16,"num":33},{"type":"B","stem":"镇痛效果个体差异大","options":{"A":"延胡索乙素","B":"纳洛酮","C":"喷他佐辛","D":"哌替啶","E":"二氢埃托啡"},"answer":["C"],"rationale":"喷他佐辛的镇痛作用存在较大的个体差异。","expl":{"A":"错误，延胡索乙素个体差异并非其特点。","B":"错误，纳洛酮无镇痛作用。","C":"正确，喷他佐辛镇痛效果个体差异大。","D":"错误，哌替啶个体差异相对较小。","E":"错误，二氢埃托啡个体差异并非其特点。"},"id":"ph17_q34","chapter":"第十七章 镇痛药","chapterIdx":16,"num":34},{"type":"B","stem":"为阿片受体拮抗剂","options":{"A":"延胡索乙素","B":"纳洛酮","C":"喷他佐辛","D":"哌替啶","E":"二氢埃托啡"},"answer":["B"],"rationale":"纳洛酮为纯阿片受体拮抗剂。","expl":{"A":"错误，延胡索乙素不作用于阿片受体。","B":"正确，纳洛酮为阿片受体拮抗剂。","C":"错误，喷他佐辛为激动-拮抗剂。","D":"错误，哌替啶为μ受体激动剂。","E":"错误，二氢埃托啡为μ受体激动剂。"},"id":"ph17_q35","chapter":"第十七章 镇痛药","chapterIdx":16,"num":35},{"type":"B","stem":"有活血散瘀，行气止痛作用","options":{"A":"延胡索乙素","B":"纳洛酮","C":"喷他佐辛","D":"哌替啶","E":"二氢埃托啡"},"answer":["A"],"rationale":"延胡索乙素为中药延胡索的有效成分，具活血散瘀、行气止痛作用。","expl":{"A":"正确，延胡索乙素有活血散瘀、行气止痛之功。","B":"错误，纳洛酮为阿片受体拮抗剂，无此功效。","C":"错误，喷他佐辛无活血化瘀功效。","D":"错误，哌替啶无活血化瘀功效。","E":"错误，二氢埃托啡无活血化瘀功效。"},"id":"ph17_q36","chapter":"第十七章 镇痛药","chapterIdx":16,"num":36},{"type":"C","stem":"吗啡激动 m 受体产生","options":{"A":"镇痛作用","B":"缩瞳作用","C":"两者均有","D":"两者均无"},"answer":["C"],"rationale":"μ受体激动与镇痛和缩瞳均有关，故两者均有。","expl":{"A":"错误（不完整），μ受体激动还产生缩瞳。","B":"错误（不完整），μ受体激动还产生镇痛。","C":"正确，μ受体激动产生镇痛和缩瞳。","D":"错误。"},"id":"ph17_q37","chapter":"第十七章 镇痛药","chapterIdx":16,"num":37},{"type":"C","stem":"吗啡激动 k 受体产生","options":{"A":"镇痛作用","B":"缩瞳作用","C":"两者均有","D":"两者均无"},"answer":["A"],"rationale":"κ受体激动主要产生镇痛作用，不引起缩瞳。","expl":{"A":"正确，κ受体激动可产生镇痛作用。","B":"错误，κ受体激动不产生缩瞳。","C":"错误，κ受体不介导缩瞳。","D":"错误，κ受体介导镇痛。"},"id":"ph17_q38","chapter":"第十七章 镇痛药","chapterIdx":16,"num":38},{"type":"C","stem":"吗啡激动 s 受体产生","options":{"A":"镇痛作用","B":"缩瞳作用","C":"两者均有","D":"两者均无"},"answer":["D"],"rationale":"σ受体激动与镇痛、缩瞳均无关，主要与烦躁不安、幻觉等精神症状有关。","expl":{"A":"错误，σ受体激动不产生镇痛。","B":"错误，σ受体激动不产生缩瞳。","C":"错误。","D":"正确，σ受体与镇痛、缩瞳均无关。"},"id":"ph17_q39","chapter":"第十七章 镇痛药","chapterIdx":16,"num":39},{"type":"C","stem":"芬太尼","options":{"A":"镇压痛作用比吗啡强","B":"成瘾性比吗啡小","C":"两者均是","D":"两者均否"},"answer":["C"],"rationale":"芬太尼镇痛作用比吗啡强约100倍，且依赖性较吗啡小，故两者均是。","expl":{"A":"错误（不完整），芬太尼成瘾性也较吗啡小。","B":"错误（不完整），芬太尼镇痛作用也强于吗啡。","C":"正确，芬太尼镇痛强于吗啡且成瘾性较小。","D":"错误。"},"id":"ph17_q40","chapter":"第十七章 镇痛药","chapterIdx":16,"num":40},{"type":"C","stem":"罗通定","options":{"A":"镇压痛作用比吗啡强","B":"成瘾性比吗啡小","C":"两者均是","D":"两者均否"},"answer":["D"],"rationale":"罗通定镇痛作用比吗啡弱，且本身无成瘾性，故两者均否。","expl":{"A":"错误，罗通定镇痛作用弱于吗啡。","B":"错误，罗通定无成瘾性，而非仅较吗啡小。","C":"错误。","D":"正确，罗通定镇痛弱且无成瘾性。"},"id":"ph17_q41","chapter":"第十七章 镇痛药","chapterIdx":16,"num":41},{"type":"C","stem":"哌替啶","options":{"A":"欣快感","B":"镇咳作用","C":"两者均有","D":"两者均无"},"answer":["A"],"rationale":"哌替啶可产生欣快感，但无明显镇咳作用。","expl":{"A":"正确，哌替啶可产生欣快感。","B":"错误，哌替啶无明显镇咳作用。","C":"错误，哌替啶无镇咳作用。","D":"错误，哌替啶有欣快感。"},"id":"ph17_q42","chapter":"第十七章 镇痛药","chapterIdx":16,"num":42},{"type":"C","stem":"二氢埃托啡","options":{"A":"欣快感","B":"镇咳作用","C":"两者均有","D":"两者均无"},"answer":["C"],"rationale":"二氢埃托啡兼有欣快感和镇咳作用，故两者均有。","expl":{"A":"错误（不完整），二氢埃托啡也有镇咳作用。","B":"错误（不完整），二氢埃托啡也有欣快感。","C":"正确，二氢埃托啡两者均有。","D":"错误。"},"id":"ph17_q43","chapter":"第十七章 镇痛药","chapterIdx":16,"num":43},{"type":"C","stem":"吗啡","options":{"A":"欣快感","B":"镇咳作用","C":"两者均有","D":"两者均无"},"answer":["C"],"rationale":"吗啡既有欣快感又有镇咳作用，故两者均有。","expl":{"A":"错误（不完整），吗啡也有镇咳作用。","B":"错误（不完整），吗啡也有欣快感。","C":"正确，吗啡两者均有。","D":"错误。"},"id":"ph17_q44","chapter":"第十七章 镇痛药","chapterIdx":16,"num":44},{"type":"X","stem":"吗啡禁用于","options":{"A":"哺乳妇女止痛","B":"支气管哮喘病人","C":"肺心病病人","D":"肝功能严重减退病人","E":"颅脑损伤昏迷病人"},"answer":["A","B","C","D","E"],"rationale":"吗啡可透过乳汁、收缩支气管、抑制呼吸并经肝代谢，故哺乳妇女、哮喘、肺心病、严重肝损及颅脑损伤昏迷者均禁用。","expl":{"A":"正确，吗啡可进入乳汁，影响婴儿。","B":"正确，吗啡收缩支气管、抑制呼吸，哮喘禁用。","C":"正确，肺心病呼吸储备差，禁用吗啡。","D":"正确，吗啡经肝代谢，严重肝功能减退禁用。","E":"正确，颅脑损伤时吗啡抑制呼吸并升高颅压，禁用。"},"id":"ph17_q45","chapter":"第十七章 镇痛药","chapterIdx":16,"num":45},{"type":"X","stem":"吗啡的临床应用有","options":{"A":"心肌梗死引起的剧痛","B":"严重创伤痛","C":"心源性哮喘","D":"止泻","E":"与氯丙嗪、异丙嗪组成人工冬眠合剂"},"answer":["A","B","C","D"],"rationale":"吗啡用于心肌梗死剧痛、严重创伤痛、心源性哮喘和止泻，但人工冬眠合剂用哌替啶而非吗啡。","expl":{"A":"正确，心肌梗死剧痛可用吗啡。","B":"正确，严重创伤痛可用吗啡。","C":"正确，心源性哮喘可用吗啡。","D":"正确，可用吗啡类（如复方樟脑酊）止泻。","E":"错误，人工冬眠合剂含哌替啶，不含吗啡。"},"id":"ph17_q46","chapter":"第十七章 镇痛药","chapterIdx":16,"num":46},{"type":"X","stem":"哌替啶的临床应用有","options":{"A":"创伤性疼痛","B":"内脏绞痛","C":"麻醉前给药","D":"与氯丙嗪、异丙嗪组成人工冬眠合剂","E":"心源性哮喘"},"answer":["B","C","D","E"],"rationale":"哌替啶用于内脏绞痛、麻醉前给药、心源性哮喘，并与氯丙嗪、异丙嗪组成人工冬眠合剂；创伤性剧痛多选用吗啡。","expl":{"A":"错误，创伤性剧痛多选用吗啡镇痛。","B":"正确，内脏绞痛可配阿托品应用。","C":"正确，哌替啶用于麻醉前给药。","D":"正确，与氯丙嗪、异丙嗪组成冬眠合剂。","E":"正确，哌替啶可用于心源性哮喘。"},"id":"ph17_q47","chapter":"第十七章 镇痛药","chapterIdx":16,"num":47},{"type":"X","stem":"人工合成的镇痛药有","options":{"A":"安那度","B":"罗通定","C":"二氢埃托啡","D":"美沙酮","E":"纳洛酮"},"answer":["A","C","D"],"rationale":"安那度、二氢埃托啡、美沙酮为人工合成镇痛药；罗通定来源于天然植物，纳洛酮为拮抗剂。","expl":{"A":"正确，安那度为人工合成镇痛药。","B":"错误，罗通定来自延胡索，非人工合成。","C":"正确，二氢埃托啡为人工合成镇痛药。","D":"正确，美沙酮为人工合成镇痛药。","E":"错误，纳洛酮为拮抗剂，非镇痛药。"},"id":"ph17_q48","chapter":"第十七章 镇痛药","chapterIdx":16,"num":48},{"type":"X","stem":"喷他佐辛的特点有","options":{"A":"为苯并吗啡烷类衍生物","B":"主要激动 k 和s 受体，又可拮抗 m 受体","C":"镇痛效力为吗啡的 1/3","D":"对冠心病病人，静脉注射可增加心脏作功量","E":"成瘾性很小，在药政管理上已列入非麻醉药品"},"answer":["A","B","C","D","E"],"rationale":"喷他佐辛为苯并吗啡烷类衍生物，激动κ、σ受体并拮抗μ受体，镇痛为吗啡1/3，可增加心脏作功，成瘾性小已列入非麻醉药品。","expl":{"A":"正确，喷他佐辛属苯并吗啡烷类衍生物。","B":"正确，主要激动κ、σ受体并可拮抗μ受体。","C":"正确，镇痛效力约为吗啡的1/3。","D":"正确，对冠心病患者静注可增加心脏作功量。","E":"正确，成瘾性很小，已列入非麻醉药品。"},"id":"ph17_q49","chapter":"第十七章 镇痛药","chapterIdx":16,"num":49},{"type":"X","stem":"阿片受体拮抗剂有","options":{"A":"纳洛酮","B":"二氢埃托啡","C":"芬太尼","D":"烯丙吗啡","E":"纳曲酮"},"answer":["A","E"],"rationale":"纳洛酮和纳曲酮为纯阿片受体拮抗剂；烯丙吗啡为部分激动剂（激动-拮抗剂）。","expl":{"A":"正确，纳洛酮为纯阿片受体拮抗剂。","B":"错误，二氢埃托啡为μ受体激动剂。","C":"错误，芬太尼为μ受体激动剂。","D":"错误，烯丙吗啡为激动-拮抗剂，非纯拮抗剂。","E":"正确，纳曲酮为纯阿片受体拮抗剂。"},"id":"ph17_q50","chapter":"第十七章 镇痛药","chapterIdx":16,"num":50},{"type":"A","stem":"吗啡急性中毒的典型表现是","options":{"A":"昏迷、瞳孔散大、呼吸抑制","B":"烦躁、瞳孔散大、心动过速","C":"昏迷、瞳孔缩小、呼吸抑制","D":"昏迷、瞳孔缩小、血压升高","E":"抽搐、瞳孔缩小、呼吸加快"},"answer":["C"],"rationale":"吗啡急性中毒的三大特征是昏迷、针尖样瞳孔和呼吸深度抑制，其中呼吸抑制是致死的主要原因，故答案为 C。","expl":{"A":"错误，吗啡中毒时瞳孔缩小而非散大，瞳孔散大见于阿托品中毒。","B":"错误，吗啡中毒表现为中枢抑制，不会出现烦躁和瞳孔散大。","C":"正确，昏迷、针尖样瞳孔和呼吸抑制构成吗啡急性中毒三联征。","D":"错误，吗啡扩张血管使血压下降而非升高，尤以体位性低血压常见。","E":"错误，吗啡抑制呼吸中枢使呼吸减慢而非加快，也不引起抽搐。"},"id":"ph17_q51","chapter":"第十七章 镇痛药","chapterIdx":16,"num":51}]},{"title":"第十八章 中枢兴奋药","questions":[{"type":"A","stem":"咖啡因治疗量兴奋中枢神经系统的主要机制是","options":{"A":"阻断腺苷A1和A2受体","B":"抑制磷酸二酯酶，增加细胞内环磷酸腺苷","C":"直接激动腺苷A1受体","D":"抑制细胞膜Na+-K+-ATP酶","E":"阻断GABA-A受体的氯离子通道"},"answer":["A"],"rationale":"咖啡因属甲基黄嘌呤类，治疗量主要通过阻断腺苷A1和A2受体而产生中枢兴奋作用，故答案为A。只有大剂量才抑制磷酸二酯酶并促进儿茶酚胺释放；其效应随剂量增加呈大脑皮质、延髓、脊髓三级递进，中毒量兴奋脊髓引起惊厥。咖啡因并不激动腺苷受体，也不作用于钠钾泵或GABA-A受体。","expl":{"A":"正确。阻断腺苷受体解除腺苷对中枢的抑制，是治疗量下的主要机制。","B":"抑制磷酸二酯酶需大剂量才能发生，不是治疗量的主要机制。","C":"咖啡因阻断而非激动腺苷受体，激动腺苷受体反而抑制中枢。","D":"抑制Na+-K+-ATP酶是强心苷的作用机制，与咖啡因无关。","E":"阻断GABA-A受体氯通道不是咖啡因的作用方式。"},"id":"ph18_q01","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":1},{"type":"A","stem":"洛贝林兴奋呼吸中枢的作用方式是","options":{"A":"刺激颈动脉体和主动脉体化学感受器，反射性兴奋呼吸中枢","B":"直接兴奋延髓呼吸中枢","C":"直接兴奋脊髓前角运动神经元，增强骨骼肌张力","D":"抑制延髓碳酸酐酶，提高血中二氧化碳的刺激作用","E":"阻断延髓内抑制性中间神经元的甘氨酸受体"},"answer":["A"],"rationale":"洛贝林（山梗菜碱）并不直接作用于延髓呼吸中枢，而是激动颈动脉体和主动脉体化学感受器，通过反射途径兴奋呼吸中枢，故答案为A。其作用快而弱、维持时间短，安全范围较大，不易引起惊厥，适用于新生儿窒息和一氧化碳中毒。直接兴奋延髓呼吸中枢的是尼可刹米、二甲弗林和多沙普仑。","expl":{"A":"正确。反射性兴奋是其区别于直接呼吸兴奋药的特点。","B":"直接兴奋延髓呼吸中枢的是尼可刹米、二甲弗林和多沙普仑。","C":"兴奋脊髓的是士的宁和一叶萩碱，洛贝林主要作用于呼吸中枢。","D":"抑制碳酸酐酶并非洛贝林的作用机制。","E":"阻断甘氨酸受体是士的宁兴奋脊髓的机制。"},"id":"ph18_q02","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":2},{"type":"A","stem":"士的宁引起反射亢进和强直性惊厥的机制是","options":{"A":"选择性阻断脊髓Renshaw细胞的甘氨酸受体，取消抑制性突触传递","B":"阻断中枢GABA-A受体，减弱抑制性递质的作用","C":"直接兴奋延髓呼吸中枢和血管运动中枢","D":"激动脊髓NMDA受体，增强兴奋性突触传递","E":"抑制脊髓胆碱酯酶，使乙酰胆碱蓄积"},"answer":["A"],"rationale":"士的宁选择性阻断脊髓抑制性中间神经元即Renshaw细胞的甘氨酸受体，使回返性抑制被取消，运动神经元兴奋性相对增高，表现为反射亢进和强直性惊厥，故答案为A。其安全范围极窄，现已少用；一叶萩碱作用与之相似而较弱、毒性较小。阻断GABA-A受体并非其机制，它也不直接兴奋呼吸中枢或抑制胆碱酯酶。","expl":{"A":"正确。取消脊髓回返抑制是其致惊厥的根本原因。","B":"阻断GABA-A受体的是印防己毒素等，不是士的宁。","C":"直接兴奋延髓呼吸中枢的是尼可刹米、二甲弗林等呼吸兴奋药。","D":"士的宁通过解除抑制而非激动NMDA受体使兴奋性增高。","E":"抑制胆碱酯酶是抗胆碱酯酶药的作用，与士的宁无关。"},"id":"ph18_q03","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":3},{"type":"X","stem":"关于中枢兴奋药临床应用与不良反应的叙述，正确的有","options":{"A":"呼吸兴奋药仅适用于中枢性呼吸抑制，气道阻塞或呼吸肌麻痹者无效且有害","B":"尼可刹米作用温和而短暂，过量可致血压升高、肌震颤甚至惊厥","C":"洛贝林作用快而弱、维持时间短，安全范围较大，可用于新生儿窒息","D":"哌甲酯用于注意缺陷多动障碍和发作性睡病，长期应用有滥用倾向","E":"二甲弗林安全范围宽，治疗量下不会引起惊厥"},"answer":["A","B","C","D"],"rationale":"呼吸兴奋药只对中枢性呼吸抑制有效，气道阻塞、呼吸肌麻痹和肺水肿时不仅无效，反因耗氧增加而有害，A正确；尼可刹米直接兴奋延髓呼吸中枢，作用温和而短暂，过量出现血压升高、心动过速、肌震颤乃至惊厥，B正确；洛贝林反射性兴奋呼吸中枢，快而弱、维持短、安全范围较大，用于新生儿窒息和一氧化碳中毒，C正确；哌甲酯促进多巴胺和去甲肾上腺素释放，用于注意缺陷多动障碍和发作性睡病，有滥用倾向，D正确。二甲弗林作用强而快、安全范围窄，易致惊厥，E错误。","expl":{"A":"正确。使用呼吸兴奋药必须以气道通畅和充分供氧为前提。","B":"正确。过量时的惊厥先兆应及时识别并减量处理。","C":"正确。安全范围较大、不易惊厥是其优点。","D":"正确。属精神兴奋药，长期应用可产生耐受性和依赖性。","E":"二甲弗林作用强而快、安全范围窄，过量极易引起惊厥。"},"id":"ph18_q04","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":4}]},{"title":"第十九章 解热镇痛抗炎药与抗痛风药","questions":[{"type":"A","stem":"解热镇痛药的退热作用机制是","options":{"A":"抑制中枢 PG 合成","B":"抑制外周 PG 合成","C":"抑制中枢 PG 降解","D":"抑制外周 PG 降解","E":"增加中枢 PG 释放"},"answer":["A"],"rationale":"解热镇痛药通过抑制下丘脑体温调节中枢的环氧酶，减少中枢前列腺素（PG）合成，使异常升高的体温调定点恢复而退热。","expl":{"A":"正确，退热主要靠抑制下丘脑体温调节中枢的 PG 合成，使调定点下移。","B":"错误，抑制外周 PG 合成主要与抗炎镇痛有关，非退热主因。","C":"错误，本类药物不抑制中枢 PG 降解。","D":"错误，本类药物不抑制外周 PG 降解。","E":"错误，药物是减少而非增加中枢 PG 释放。"},"id":"ph19_q01","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":1},{"type":"A","stem":"解热镇痛药镇痛的主要作用部位在","options":{"A":"导水管周围灰质","B":"脊髓","C":"丘脑","D":"脑干","E":"外周"},"answer":["E"],"rationale":"解热镇痛药主要通过抑制外周炎症部位 PG 合成，降低痛觉感受器对缓激肽等致痛物质的敏感性而镇痛，作用部位在外周。","expl":{"A":"错误，导水管周围灰质是阿片类镇痛药的主要作用部位。","B":"错误，脊髓主要参与中枢性镇痛，非此类药主要部位。","C":"错误，丘脑是痛觉传导中枢，但非此类药主要作用部位。","D":"错误，脑干不是解热镇痛药镇痛的主要部位。","E":"正确，镇痛作用部位主要在外周炎症局部。"},"id":"ph19_q02","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":2},{"type":"A","stem":"解热镇痛药的镇痛作用机制是","options":{"A":"阻断传入神经的冲动传导","B":"降低感觉纤维感受器的敏感性","C":"阻止炎症时 PG 的合成","D":"激动阿片受体","E":"以上都不是"},"answer":["C"],"rationale":"解热镇痛药通过抑制环氧酶，减少炎症部位 PG 合成，消除 PG 对痛觉感受器的增敏作用而镇痛。","expl":{"A":"错误，其不阻断传入神经冲动传导，那是局麻药作用。","B":"错误，降低感受器敏感性是结果，根本机制是减少 PG。","C":"正确，阻止炎症时 PG 合成是其镇痛的核心机制。","D":"错误，激动阿片受体是阿片类镇痛药的机制。","E":"错误，C 项已准确说明其机制。"},"id":"ph19_q03","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":3},{"type":"A","stem":"治疗类风湿性关节炎的首选药的是","options":{"A":"水杨酸钠","B":"阿司匹林","C":"保泰松","D":"吲哚美辛","E":"对乙酰氨基酚"},"answer":["B"],"rationale":"阿司匹林抗炎抗风湿作用明确、疗效可靠且经验成熟，是治疗类风湿性关节炎的首选药物。","expl":{"A":"错误，水杨酸钠刺激性大，疗效与耐受性不及阿司匹林。","B":"正确，阿司匹林是治疗类风湿性关节炎的首选药。","C":"错误，保泰松毒性大，不作首选。","D":"错误，吲哚美辛不良反应多，不作首选。","E":"错误，对乙酰氨基酚抗炎作用很弱，不用于类风湿。"},"id":"ph19_q04","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":4},{"type":"A","stem":"可防止脑血栓形成的药物是","options":{"A":"水杨酸钠","B":"阿司匹林","C":"保泰松","D":"吲哚美辛","E":"布洛芬"},"answer":["B"],"rationale":"小剂量阿司匹林抑制血小板环氧酶，减少血栓素 A2 生成而抗血小板聚集，可防止脑血栓形成。","expl":{"A":"错误，水杨酸钠无明显抗血小板作用。","B":"正确，阿司匹林抗血小板聚集，可防止脑血栓形成。","C":"错误，保泰松无此明确用途。","D":"错误，吲哚美辛抑制 PG 合成但无临床抗血栓用途。","E":"错误，布洛芬无明确抗血栓形成作用。"},"id":"ph19_q05","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":5},{"type":"A","stem":"丙磺舒增加青霉素疗效的机制是","options":{"A":"减慢其在肝脏代谢","B":"增加其对细菌膜的通透性","C":"减少其在皮肤小管分泌排泄","D":"对细菌起双重杀菌作用","E":"增加其与细菌蛋白结合力"},"answer":["C"],"rationale":"丙磺舒与青霉素竞争肾小管有机酸分泌转运体，减少青霉素排泄、提高其血药浓度而增效。","expl":{"A":"错误，与减慢肝代谢无关。","B":"错误，不增加青霉素对细菌膜的通透性。","C":"正确，竞争性抑制肾小管分泌，减少青霉素排泄。","D":"错误，无双重杀菌作用。","E":"错误，不增加其与细菌蛋白的结合力。"},"id":"ph19_q06","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":6},{"type":"A","stem":"秋水仙碱治疗痛风的机制 是","options":{"A":"减少尿酸的生成","B":"促进尿酸的排泄","C":"抑制肾小管对尿酸的再吸收","D":"抑制黄嘌呤投氧化酶","E":"选择性消炎作用"},"answer":["E"],"rationale":"秋水仙碱抑制中性粒细胞趋化与吞噬、减少炎症介质释放，对痛风性关节炎有选择性抗炎作用，但不影响尿酸代谢。","expl":{"A":"错误，秋水仙碱不减少尿酸生成。","B":"错误，不促进尿酸排泄。","C":"错误，不抑制肾小管对尿酸的重吸收。","D":"错误，抑制黄嘌呤氧化酶的是别嘌醇。","E":"正确，通过选择性消炎作用缓解痛风急性发作。"},"id":"ph19_q07","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":7},{"type":"A","stem":"阿司匹林防止血栓形成的机制是","options":{"A":"激活环加氧酶，增加血栓素生成，抗血小板聚集及抗血栓形成","B":"抑制环加氧酶，减少前列环素生成，抗血小板聚集及抗血栓形成","C":"抑制环加氧酶，减少血栓素生成，抗血小板聚集及抗血栓形成","D":"抑制环氧酶，增加前列环素生成，抗血小板聚集及抗血栓形成","E":"激活环加氧酶，减少血栓素生成，抗血小板聚集及抗血栓形成"},"answer":["C"],"rationale":"小剂量阿司匹林不可逆抑制血小板环加氧酶，减少血栓素 A2 生成，从而抗血小板聚集、抗血栓形成。","expl":{"A":"错误，其抑制而非激活环加氧酶。","B":"错误，主要减少血栓素 A2 而非前列环素。","C":"正确，抑制环加氧酶、减少血栓素 A2，抗血小板聚集。","D":"错误，抑制环氧酶但并非增加前列环素生成。","E":"错误，其抑制而非激活环加氧酶。"},"id":"ph19_q08","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":8},{"type":"A","stem":"解热镇痛药的抗炎作用机制是","options":{"A":"促进炎症消散","B":"抑制炎症时PG的合成","C":"抑制抑黄嘌呤氧化酶","D":"促进PG从肾脏排泄","E":"激活黄嘌呤氧化酶"},"answer":["B"],"rationale":"解热镇痛抗炎药通过抑制环氧酶，减少炎症部位 PG 等致炎物质的合成而发挥抗炎作用。","expl":{"A":"错误，非直接促进炎症消散。","B":"正确，抑制炎症时 PG 合成是其抗炎的基本机制。","C":"错误，抑制黄嘌呤氧化酶是别嘌醇的作用。","D":"错误，与促进 PG 从肾脏排泄无关。","E":"错误，激活黄嘌呤氧化酶非其作用。"},"id":"ph19_q09","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":9},{"type":"A","stem":"阿司匹林与甲磺丁脲合用易引起低血糖反应是由于前者","options":{"A":"从血浆蛋白结合部位置换甲磺丁脲","B":"抑制肝药酶，减慢甲磺丁脲代谢","C":"加快胃粘膜血流,增加甲磺丁脲吸收","D":"酸化尿液增加甲磺丁脲在肾小管重吸收","E":"以是都不是"},"answer":["A"],"rationale":"阿司匹林血浆蛋白结合率高，可把甲磺丁脲从血浆蛋白结合部位置换出来，使其游离浓度升高而致低血糖。","expl":{"A":"正确，竞争性置换血浆蛋白结合，使游离甲磺丁脲增多。","B":"错误，主要经蛋白置换而非抑制其代谢。","C":"错误，与加快胃黏膜血流无关。","D":"错误，并非通过酸化尿液增加重吸收所致。","E":"错误，A 项已准确说明原因。"},"id":"ph19_q10","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":10},{"type":"A","stem":"保泰松降低强心甙作用的原因是","options":{"A":"增加其与血浆蛋白结合","B":"增加其排泄","C":"减少其吸收","D":"增加其代谢","E":"增加其分布容积"},"answer":["D"],"rationale":"保泰松为肝药酶诱导剂，可加速强心苷的代谢，使其血药浓度降低而作用减弱。","expl":{"A":"错误，不增加强心苷与血浆蛋白的结合。","B":"错误，并非增加其排泄所致。","C":"错误，并非减少其吸收。","D":"正确，诱导肝药酶、加速强心苷代谢而降低其作用。","E":"错误，并非增加其分布容积。"},"id":"ph19_q11","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":11},{"type":"A","stem":"胃溃疡病人宜选用下列哪种药物解热镇痛？","options":{"A":"吲哚美辛","B":"乙酰氨基酚","C":"吡罗昔康","D":"保泰松","E":"阿司匹林"},"answer":["B"],"rationale":"对乙酰氨基酚对胃黏膜刺激性小、几乎不抑制胃黏膜 PG 合成，胃肠反应轻，故胃溃疡患者宜选用。","expl":{"A":"错误，吲哚美辛胃肠刺激明显，不宜用于溃疡者。","B":"正确，对乙酰氨基酚胃刺激小，适合溃疡患者解热镇痛。","C":"错误，吡罗昔康有胃肠反应，不宜选用。","D":"错误，保泰松易致溃疡，禁用。","E":"错误，阿司匹林抑制胃 PG 并直接刺激胃黏膜，禁用。"},"id":"ph19_q12","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":12},{"type":"A","stem":"保泰松作用特点为","options":{"A":"解热镇痛作用强、抗炎抗风湿作用强、毒性小","B":"解热镇痛作用强、抗炎抗风湿作用弱、毒性小","C":"解热镇痛作用弱、抗炎抗风湿作用强、毒性小","D":"解热镇痛作用弱、抗炎抗风湿作用强、毒性大","E":"解热镇痛作用强、抗炎抗风湿作用强、毒性大"},"answer":["D"],"rationale":"保泰松解热镇痛作用弱，但抗炎抗风湿作用强，且不良反应多、毒性大。","expl":{"A":"错误，其解热镇痛作用弱且毒性大。","B":"错误，其抗炎抗风湿作用强而非弱。","C":"错误，其毒性大而非小。","D":"正确，解热镇痛弱、抗炎抗风湿强、毒性大。","E":"错误，其解热镇痛作用弱。"},"id":"ph19_q13","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":13},{"type":"A","stem":"代谢为有毒性代谢产物的药物是","options":{"A":"阿司匹林","B":"保泰松","C":"非那西丁","D":"吲哚美辛","E":"甲芬那酸"},"answer":["C"],"rationale":"非那西丁在体内代谢可生成对氨基苯乙醚等有毒产物，可引起高铁血红蛋白血症和肾损害。","expl":{"A":"错误，阿司匹林代谢产物无此明显毒性。","B":"错误，保泰松的毒性主要与药物本身相关。","C":"正确，非那西丁代谢生成有毒产物，可致高铁血红蛋白血症、肾毒性。","D":"错误，吲哚美辛无此特点。","E":"错误，甲芬那酸无此特点。"},"id":"ph19_q14","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":14},{"type":"A","stem":"布洛芬的主要特点是","options":{"A":"解热镇痛作用强","B":"口服吸收慢","C":"与血浆蛋白结合少","D":"胃肠反应较轻，易耐受","E":"半衰期长"},"answer":["D"],"rationale":"布洛芬抗炎镇痛疗效与阿司匹林相似，但胃肠反应较轻、患者较易耐受，是其主要特点。","expl":{"A":"错误，布洛芬解热镇痛作用与阿司匹林相似，并非特点为强。","B":"错误，布洛芬口服吸收快。","C":"错误，布洛芬血浆蛋白结合率高。","D":"正确，布洛芬胃肠反应较轻、易耐受。","E":"错误，布洛芬半衰期短（约 2 小时）。"},"id":"ph19_q15","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":15},{"type":"A","stem":"呋塞米（速尿）可引起水杨酸蓄积中毒的原因 是","options":{"A":"减慢其代谢","B":"减少其与血浆蛋白结合","C":"缩小其表观分布容积","D":"减少其排泄","E":"以上都不是"},"answer":["D"],"rationale":"水杨酸经肾小管有机酸分泌排泄，呋塞米竞争性抑制其分泌而减少排泄，导致水杨酸蓄积中毒。","expl":{"A":"错误，与减慢其代谢无关。","B":"错误，并非减少其与血浆蛋白结合。","C":"错误，并非缩小表观分布容积。","D":"正确，竞争肾小管分泌、减少水杨酸排泄而蓄积。","E":"错误，D 项已准确说明原因。"},"id":"ph19_q16","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":16},{"type":"A","stem":"保泰松禁用于高血压、心功能不全是由于该药引起","options":{"A":"水钠潴留","B":"激动 a 肾上腺素受体","C":"激动肾上腺素受体","D":"收缩血管","E":"兴奋心脏"},"answer":["A"],"rationale":"保泰松可促进肾小管对钠、水的重吸收，引起水钠潴留，从而加重高血压和心功能不全。","expl":{"A":"正确，保泰松致水钠潴留，加重高血压和心衰。","B":"错误，不激动 α 肾上腺素受体。","C":"错误，不激动肾上腺素受体。","D":"错误，不直接收缩血管。","E":"错误，不兴奋心脏。"},"id":"ph19_q17","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":17},{"type":"A","stem":"溃疡病禁用的药物是","options":{"A":"布洛芬","B":"对乙酰氨基酚","C":"保泰松","D":"非那西丁","E":"酮洛芬"},"answer":["C"],"rationale":"保泰松抑制 PG 合成并直接刺激胃黏膜，易诱发或加重溃疡及胃出血，溃疡病患者禁用。","expl":{"A":"错误，布洛芬胃肠反应较轻，相对可用。","B":"错误，对乙酰氨基酚胃刺激小，溃疡者可用。","C":"正确，保泰松胃肠刺激重、易致溃疡，溃疡病禁用。","D":"错误，非那西丁胃刺激较小。","E":"错误，酮洛芬虽刺激胃，但本题典型禁用者为保泰松。"},"id":"ph19_q18","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":18},{"type":"A","stem":"支气管哮喘病人禁用的药物是","options":{"A":"吡罗昔康","B":"阿司匹林","C":"丙磺舒","D":"布洛芬","E":"氯芬那酸"},"answer":["B"],"rationale":"阿司匹林抑制 PG 合成，使花生四烯酸转向脂氧酶途径、白三烯增多，可诱发“阿司匹林哮喘”，故哮喘者禁用。","expl":{"A":"错误，吡罗昔康非典型诱发“阿司匹林哮喘”的药物。","B":"正确，阿司匹林可诱发阿司匹林哮喘，哮喘者禁用。","C":"错误，丙磺舒不诱发哮喘。","D":"错误，布洛芬虽可诱发，但本题所指典型禁用者为阿司匹林。","E":"错误，氯芬那酸非典型诱发药物。"},"id":"ph19_q19","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":19},{"type":"A","stem":"癫痫病人禁用的药物是","options":{"A":"阿司匹林","B":"吲哚美辛","C":"水杨酸钠","D":"非那西丁","E":"布洛芬"},"answer":["B"],"rationale":"吲哚美辛中枢神经系统不良反应明显，可诱发或加重癫痫等神经精神症状，癫痫患者禁用。","expl":{"A":"错误，阿司匹林一般不诱发癫痫。","B":"正确，吲哚美辛中枢不良反应多、可诱发癫痫，癫痫者禁用。","C":"错误，水杨酸钠无此禁忌。","D":"错误，非那西丁无此禁忌。","E":"错误，布洛芬无此禁忌。"},"id":"ph19_q20","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":20},{"type":"A","stem":"孕妇禁用的药物是","options":{"A":"水杨酸钠","B":"阿司匹林","C":"保泰松","D":"吲哚美辛","E":"布洛芬"},"answer":["D"],"rationale":"吲哚美辛易通过胎盘并抑制 PG 合成，可致胎儿动脉导管早闭等损害，故孕妇禁用。","expl":{"A":"错误，水杨酸钠非本题所指典型孕妇禁用药物。","B":"错误，阿司匹林虽孕晚期慎用，但非本题所指。","C":"错误，保泰松非本题所指典型禁用药物。","D":"正确，吲哚美辛可致胎儿损害，孕妇禁用。","E":"错误，布洛芬非本题所指典型禁用药物。"},"id":"ph19_q21","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":21},{"type":"A","stem":"胃肠反应常见的药物有","options":{"A":"吲哚美辛","B":"保泰松","C":"布洛芬","D":"甲芬那酸","E":"水杨酸钠"},"answer":["C"],"rationale":"所列药物中，布洛芬对胃黏膜刺激较小、胃肠反应较轻且易耐受，是胃肠安全性较好的选择。","expl":{"A":"错误，吲哚美辛胃肠反应明显，可致溃疡和出血。","B":"错误，保泰松胃肠刺激重、易致溃疡。","C":"正确，布洛芬胃肠反应较轻、易耐受。","D":"错误，甲芬那酸胃肠反应较明显。","E":"错误，水杨酸钠刺激性大，胃肠反应较重。"},"id":"ph19_q22","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":22},{"type":"A","stem":"阿司匹林的不良反应不包括","options":{"A":"凝血障碍","B":"水钠潴留","C":"变态反应","D":"水杨酸反应","E":"瑞夷综合症"},"answer":["B"],"rationale":"阿司匹林常见不良反应包括胃肠道反应、凝血障碍、变态反应、水杨酸反应及瑞夷综合征，但不引起水钠潴留（水钠潴留见于保泰松）。","expl":{"A":"错误，凝血障碍是阿司匹林不良反应之一。","B":"正确，水钠潴留是保泰松等药物的反应，非阿司匹林所致。","C":"错误，变态反应是阿司匹林不良反应之一。","D":"错误，水杨酸反应是阿司匹林过量中毒的表现。","E":"错误，瑞夷综合征是阿司匹林的严重不良反应。"},"id":"ph19_q23","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":23},{"type":"A","stem":"羟基保泰松的临床应用不包括","options":{"A":"风湿性关节炎","B":"恶性肿瘤引起的发热","C":"急性痛风","D":"强直性脊柱","E":"寄生虫病引起的发热"},"answer":["C"],"rationale":"羟基保泰松主要用于风湿性关节炎、强直性脊柱炎及难治性发热，急性痛风不宜选用。","expl":{"A":"错误，风湿性关节炎是羟基保泰松的适应证。","B":"错误，可用于恶性肿瘤等引起的难治性发热。","C":"正确，急性痛风宜用秋水仙碱、吲哚美辛等，羟基保泰松不用于此。","D":"错误，强直性脊柱炎是其适应证。","E":"错误，可用于寄生虫病等引起的发热。"},"id":"ph19_q24","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":24},{"type":"A","stem":"不用于抗炎的药物是","options":{"A":"水杨酸钠","B":"羟基保泰松","C":"吲哚美辛","D":"布洛芬","E":"对乙酰氨基酚"},"answer":["E"],"rationale":"对乙酰氨基酚解热镇痛作用强，但抗炎作用很弱、几无抗炎抗风湿作用，故不用于抗炎。","expl":{"A":"错误，水杨酸钠有抗炎作用。","B":"错误，羟基保泰松抗炎作用强。","C":"错误，吲哚美辛抗炎作用强。","D":"错误，布洛芬有抗炎作用。","E":"正确，对乙酰氨基酚抗炎作用很弱，不用于抗炎。"},"id":"ph19_q25","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":25},{"type":"B","stem":"治疗风湿性、类风湿性关节炎和急性痛风","options":{"A":"吡罗昔康","B":"别嘌醇","C":"保泰松","D":"非那西丁","E":"阿司匹林"},"answer":["C"],"rationale":"保泰松抗炎抗风湿作用强，并可用于急性痛风，兼顾风湿性、类风湿性关节炎和急性痛风。","expl":{"A":"错误，吡罗昔康用于风湿性疾病，但急性痛风一般不用。","B":"错误，别嘌醇用于慢性痛风（减少尿酸生成）。","C":"正确，保泰松可治疗风湿、类风湿关节炎及急性痛风。","D":"错误，非那西丁抗炎作用很弱。","E":"错误，阿司匹林用于风湿，但急性痛风非其主要用途。"},"id":"ph19_q26","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":26},{"type":"B","stem":"具有血浆 T1/2 长、用药剂量小的强效抗炎镇痛作用","options":{"A":"吡罗昔康","B":"别嘌醇","C":"保泰松","D":"非那西丁","E":"阿司匹林"},"answer":["A"],"rationale":"吡罗昔康血浆半衰期长，每日一次小剂量即可维持强效抗炎镇痛作用。","expl":{"A":"正确，吡罗昔康半衰期长、用药剂量小。","B":"错误，别嘌醇是抗痛风药，非抗炎镇痛药。","C":"错误，保泰松虽半衰期长但毒性大，不强调小剂量。","D":"错误，非那西丁抗炎作用弱。","E":"错误，阿司匹林半衰期短、需频繁给药。"},"id":"ph19_q27","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":27},{"type":"B","stem":"解热镇痛和抗炎抗风湿作用均强","options":{"A":"吡罗昔康","B":"别嘌醇","C":"保泰松","D":"非那西丁","E":"阿司匹林"},"answer":["E"],"rationale":"阿司匹林解热镇痛作用显著，且较大剂量时抗炎抗风湿作用强，两者兼备。","expl":{"A":"错误，吡罗昔康以抗炎镇痛为主，解热作用不突出。","B":"错误，别嘌醇非解热镇痛抗炎药。","C":"错误，保泰松解热镇痛作用弱。","D":"错误，非那西丁抗炎抗风湿作用弱。","E":"正确，阿司匹林解热镇痛与抗炎抗风湿作用均强。"},"id":"ph19_q28","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":28},{"type":"B","stem":"解热镇痛作用强，抗炎作用很弱","options":{"A":"吡罗昔康","B":"别嘌醇","C":"保泰松","D":"非那西丁","E":"阿司匹林"},"answer":["D"],"rationale":"非那西丁解热镇痛作用强，但抗炎作用很弱，与其活性代谢物对乙酰氨基酚的特点一致。","expl":{"A":"错误，吡罗昔康抗炎镇痛作用强。","B":"错误，别嘌醇非此类药。","C":"错误，保泰松抗炎强而解热镇痛弱。","D":"正确，非那西丁解热镇痛强、抗炎作用很弱。","E":"错误，阿司匹林抗炎抗风湿作用强。"},"id":"ph19_q29","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":29},{"type":"B","stem":"防止慢性痛风性关节炎或肾病变","options":{"A":"吡罗昔康","B":"别嘌醇","C":"保泰松","D":"非那西丁","E":"阿司匹林"},"answer":["B"],"rationale":"别嘌醇抑制黄嘌呤氧化酶、减少尿酸生成、降低血尿酸，可防止慢性痛风性关节炎及痛风性肾病。","expl":{"A":"错误，吡罗昔康不降低尿酸。","B":"正确，别嘌醇减少尿酸生成，防治慢性痛风及其肾损害。","C":"错误，保泰松仅缓解急性痛风症状，不降尿酸。","D":"错误，非那西丁无此作用。","E":"错误，阿司匹林不降尿酸，小剂量还可减少尿酸排泄。"},"id":"ph19_q30","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":30},{"type":"C","stem":"阿司匹林","options":{"A":"解热镇痛","B":"抗炎抗风湿","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"阿司匹林既有较强的解热镇痛作用，也有显著的抗炎抗风湿作用，两者兼具。","expl":{"A":"不完整，阿司匹林不仅有解热镇痛作用，还能抗炎抗风湿。","B":"不完整，阿司匹林不仅有抗炎抗风湿作用，也有解热镇痛作用。","C":"正确，阿司匹林既解热镇痛又抗炎抗风湿。","D":"错误，阿司匹林具有上述两类作用。"},"id":"ph19_q31","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":31},{"type":"C","stem":"对乙酰氨基酚","options":{"A":"解热镇痛","B":"抗炎抗风湿","C":"两者均可","D":"两者均否"},"answer":["A"],"rationale":"对乙酰氨基酚解热镇痛作用强、与阿司匹林相当，但抗炎抗风湿作用很弱。","expl":{"A":"正确，对乙酰氨基酚解热镇痛作用强。","B":"错误，对乙酰氨基酚抗炎抗风湿作用很弱，几无。","C":"错误，其抗炎作用很弱，不能两者兼有。","D":"错误，其解热镇痛作用明确。"},"id":"ph19_q32","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":32},{"type":"C","stem":"保泰松","options":{"A":"解热镇痛","B":"抗炎抗风湿","C":"两者均可","D":"两者均否"},"answer":["B"],"rationale":"保泰松抗炎抗风湿作用强，但解热镇痛作用弱，故仅具抗炎抗风湿作用。","expl":{"A":"错误，保泰松解热镇痛作用弱。","B":"正确，保泰松抗炎抗风湿作用强。","C":"错误，其解热镇痛作用弱，不能两者兼有。","D":"错误，其抗炎抗风湿作用明确且强。"},"id":"ph19_q33","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":33},{"type":"C","stem":"吲哚美辛","options":{"A":"解热镇痛","B":"抗炎抗风湿","C":"两者均可","D":"两者均否"},"answer":["C"],"rationale":"吲哚美辛解热镇痛和抗炎抗风湿作用均强，两者兼具。","expl":{"A":"不完整，吲哚美辛不仅能解热镇痛，抗炎抗风湿作用也强。","B":"不完整，吲哚美辛不仅有抗炎抗风湿作用，也有解热镇痛作用。","C":"正确，吲哚美辛解热镇痛与抗炎抗风湿作用均强。","D":"错误，吲哚美辛具有上述两类作用。"},"id":"ph19_q34","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":34},{"type":"X","stem":"治疗急性痛风的药物有","options":{"A":"保泰松","B":"羟基保泰松","C":"甲芬那酸","D":"秋水仙碱","E":"水杨酸钠"},"answer":["A","D"],"rationale":"急性痛风发作可选用秋水仙碱（特效）及保泰松、吲哚美辛等缓解症状。","expl":{"A":"正确，保泰松可用于急性痛风缓解症状。","B":"错误，羟基保泰松不用于急性痛风。","C":"错误，甲芬那酸一般不用于急性痛风。","D":"正确，秋水仙碱是急性痛风的特效药。","E":"错误，水杨酸钠不用于急性痛风。"},"id":"ph19_q35","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":35},{"type":"X","stem":"引起＂阿司匹林哮喘＂的药物有","options":{"A":"羟基保泰松","B":"阿司匹林","C":"吲哚美辛","D":"布洛芬","E":"吡罗昔康"},"answer":["B","D"],"rationale":"抑制环氧酶可使花生四烯酸转向脂氧酶途径、白三烯生成增多而诱发支气管哮喘，阿司匹林与布洛芬均可引起。","expl":{"A":"错误，羟基保泰松诱发哮喘少见，非典型。","B":"正确，阿司匹林可诱发“阿司匹林哮喘”。","C":"错误，吲哚美辛以中枢和胃肠反应为主，本题典型诱发者为阿司匹林、布洛芬。","D":"正确，布洛芬可诱发“阿司匹林哮喘”。","E":"错误，吡罗昔康非本题所指典型诱发药物。"},"id":"ph19_q36","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":36},{"type":"X","stem":"治疗慢性痛风的药物有","options":{"A":"保泰松","B":"别嘌醇","C":"布洛芬","D":"苯溴马隆","E":"丙磺舒"},"answer":["B","D","E"],"rationale":"慢性痛风需降低血尿酸：别嘌醇减少尿酸生成，苯溴马隆、丙磺舒促进尿酸排泄。","expl":{"A":"错误，保泰松仅用于急性痛风缓解症状。","B":"正确，别嘌醇减少尿酸生成，用于慢性痛风。","C":"错误，布洛芬不降尿酸，不用于慢性痛风。","D":"正确，苯溴马隆促进尿酸排泄，用于慢性痛风。","E":"正确，丙磺舒促进尿酸排泄，用于慢性痛风。"},"id":"ph19_q37","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":37},{"type":"X","stem":"阿司匹林的镇痛作用特点是","options":{"A":"镇痛作用部位主要在外周","B":"对慢性钝痛效果好","C":"镇痛作用机制是防止炎症时 PG 合成","D":"常与其他解热镇痛药配成复方使用","E":"对锐痛和内脏平滑肌绞痛也有效"},"answer":["A","B","C","D"],"rationale":"阿司匹林镇痛部位在外周，对慢性钝痛效果好，机制为抑制炎症 PG 合成，常配成复方使用；但对锐痛和内脏绞痛效果差。","expl":{"A":"正确，镇痛作用部位主要在外周。","B":"正确，对慢性钝痛效果好。","C":"正确，机制是抑制炎症时 PG 合成。","D":"正确，常与其他解热镇痛药配成复方使用。","E":"错误，对锐痛和内脏平滑肌绞痛效果差。"},"id":"ph19_q38","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":38},{"type":"X","stem":"保泰松的禁忌证有","options":{"A":"糖尿病","B":"高血压","C":"溃疡病","D":"心功能不全","E":"肝肾功能不良"},"answer":["B","C","D","E"],"rationale":"保泰松可致水钠潴留、胃肠溃疡及肝肾、血液毒性，故高血压、心功能不全、溃疡病及肝肾功能不良者禁用。","expl":{"A":"错误，糖尿病不是保泰松的禁忌证。","B":"正确，水钠潴留加重病情，高血压者禁用。","C":"正确，易诱发溃疡，溃疡病者禁用。","D":"正确，水钠潴留加重心衰，心功能不全者禁用。","E":"正确，肝肾功能不良者禁用。"},"id":"ph19_q39","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":39},{"type":"X","stem":"阿司匹林引起胃出血和诱发胃溃疡的原因是","options":{"A":"凝血障碍","B":"变态反应","C":"局部刺激","D":"抑制 PG 合成","E":"水杨酸反应"},"answer":["C","D"],"rationale":"阿司匹林直接刺激胃黏膜，并抑制胃黏膜 PG 合成、削弱其保护作用，共同导致胃出血和溃疡。","expl":{"A":"错误，凝血障碍是全身出血倾向，非胃溃疡的直接原因。","B":"错误，变态反应与胃溃疡无直接关系。","C":"正确，直接刺激胃黏膜是其原因之一。","D":"正确，抑制胃黏膜 PG 合成、削弱胃黏膜屏障是主要原因。","E":"错误，水杨酸反应是中枢毒性表现，与胃溃疡无直接关系。"},"id":"ph19_q40","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":40},{"type":"A","stem":"儿童在病毒感染发热时禁用阿司匹林，其原因是可能诱发","options":{"A":"再生障碍性贫血","B":"溶血性贫血","C":"高铁血红蛋白血症","D":"粒细胞缺乏","E":"瑞夷综合征"},"answer":["E"],"rationale":"儿童病毒感染伴发热时应用阿司匹林可诱发瑞夷综合征，表现为急性脑病合并肝功能损害，病死率高，故答案为 E。","expl":{"A":"错误，再生障碍性贫血与氯霉素、保泰松等有关，不是阿司匹林的主要危险。","B":"错误，溶血性贫血多见于G6PD缺乏者应用磺胺类、伯氨喹等药物。","C":"错误，高铁血红蛋白血症见于亚硝酸盐、伯氨喹等药物中毒。","D":"错误，粒细胞缺乏是氯氮平、抗甲状腺药的典型不良反应。","E":"正确，瑞夷综合征以急性脑病和肝脂肪变性为特征，故儿童病毒感染时禁用。"},"id":"ph19_q41","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":41}]},{"title":"第二十章 利尿药与脱水药","questions":[{"type":"A","stem":"噻嗪类利尿药长期应用最易引起的电解质紊乱是","options":{"A":"高钾血症","B":"低钾血症","C":"低钙血症","D":"高钠血症","E":"高镁血症"},"answer":["B"],"rationale":"噻嗪类抑制远曲小管Na+-Cl-同向转运体，使到达集合管的Na+增多，Na+-K+交换增强，K+排出增多，故易致低钾血症，答案为 B。","expl":{"A":"错误，高钾血症见于保钾利尿药和ACEI，噻嗪类引起的是低钾。","B":"正确，长期应用可使血钾降低，必要时需补钾或与保钾利尿药合用。","C":"错误，噻嗪类促进远曲小管钙重吸收，可引起高钙血症而非低钙血症。","D":"错误，噻嗪类以排钠为主，可引起低钠血症而非高钠血症。","E":"错误，噻嗪类增加镁排泄，可引起低镁血症而非高镁血症。"},"id":"ph20_q01","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":1},{"type":"A","stem":"螺内酯的利尿作用特点是","options":{"A":"抑制髓袢升支粗段Na+-K+-2Cl-同向转运体","B":"竞争性拮抗醛固酮受体，属保钾利尿药","C":"抑制碳酸酐酶","D":"阻断肾小管上皮钠通道","E":"提高血浆渗透压产生渗透性利尿"},"answer":["B"],"rationale":"螺内酯结构与醛固酮相似，竞争性拮抗远曲小管和集合管醛固酮受体，减少Na+重吸收和K+排出，属保钾利尿药，故答案为 B。","expl":{"A":"错误，抑制Na+-K+-2Cl-同向转运体的是呋塞米等袢利尿药。","B":"正确，通过拮抗醛固酮受体排钠保钾，长期应用需警惕高钾血症。","C":"错误，抑制碳酸酐酶的是乙酰唑胺，作用部位在近曲小管。","D":"错误，阻断上皮钠通道的是氨苯蝶啶和阿米洛利，机制与螺内酯不同。","E":"错误，提高血浆渗透压产生渗透性利尿的是甘露醇等脱水药。"},"id":"ph20_q02","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":2},{"type":"A","stem":"呋塞米产生强大利尿作用的靶点是","options":{"A":"髓袢升支粗段的Na+-K+-2Cl-同向转运体","B":"远曲小管近端的Na+-Cl-同向转运体","C":"集合管上皮细胞的醛固酮受体","D":"近曲小管上皮细胞的碳酸酐酶","E":"集合管上皮细胞的钠通道"},"answer":["A"],"rationale":"呋塞米属袢利尿药，抑制髓袢升支粗段的Na+-K+-2Cl-同向转运体，使氯化钠重吸收显著减少并破坏肾髓质高渗状态，排钠量可达滤过量的两成以上，利尿作用最强，故答案为A。抑制远曲小管近端Na+-Cl-同向转运体的是噻嗪类，拮抗醛固酮受体的是螺内酯，抑制碳酸酐酶的是乙酰唑胺，阻断集合管钠通道的是氨苯蝶啶。","expl":{"A":"正确。抑制该转运体是袢利尿药强大排钠作用的根本原因。","B":"远曲小管近端的Na+-Cl-同向转运体是噻嗪类的作用靶点。","C":"集合管醛固酮受体是螺内酯的作用靶点。","D":"抑制碳酸酐酶是乙酰唑胺的作用机制，利尿作用很弱。","E":"阻断集合管钠通道是氨苯蝶啶的作用方式。"},"id":"ph20_q03","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":3},{"type":"A","stem":"甘露醇用于脑水肿和颅内高压的药理学依据是","options":{"A":"静脉给药提高血浆渗透压，使脑组织水分向血管内转移","B":"抑制脑内碳酸酐酶，减少脑脊液的生成","C":"阻断脑血管α受体，减少脑血流量","D":"抑制髓袢升支粗段转运体，产生强大利尿作用","E":"激动醛固酮受体，促进钠和水的排出"},"answer":["A"],"rationale":"甘露醇属脱水药（渗透性利尿药），静脉滴注后提高血浆渗透压，在血浆与脑组织之间形成渗透压梯度，使脑组织和房水的水分向血管内转移而脱水，故答案为A。它经肾小球滤过后几乎不被重吸收，产生渗透性利尿。心功能不全者禁用，因可一过性增加血容量；静脉滴注外漏可引起组织坏死。","expl":{"A":"正确。提高血浆渗透压形成渗透压梯度是脱水作用的本质。","B":"抑制碳酸酐酶、减少脑脊液生成的是乙酰唑胺。","C":"甘露醇不阻断α受体，其脱水作用与受体无关。","D":"抑制髓袢升支粗段转运体是呋塞米等袢利尿药的作用。","E":"激动醛固酮受体将促进钠水重吸收，与甘露醇作用相反。"},"id":"ph20_q04","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":4}]},{"title":"第二十一章 抗高血压药","questions":[{"type":"A","stem":"卡托普利引起干咳的主要机制是","options":{"A":"阻断AT1受体","B":"抑制血管紧张素转换酶，使缓激肽降解减少","C":"抑制血管紧张素原生成","D":"阻滞钙通道","E":"促进前列腺素降解"},"answer":["B"],"rationale":"卡托普利抑制血管紧张素转换酶，同时使缓激肽、P物质等在肺内降解减少而蓄积，刺激气道引起刺激性干咳，故答案为 B。","expl":{"A":"错误，阻断AT1受体的是氯沙坦等ARB类，一般不引起干咳。","B":"正确，缓激肽蓄积是ACEI引起干咳的主要原因，换用ARB可缓解。","C":"错误，ACEI抑制的是血管紧张素Ⅰ转化为血管紧张素Ⅱ的环节。","D":"错误，阻滞钙通道是硝苯地平等钙拮抗药的作用机制。","E":"错误，ACEI使前列腺素合成增多而非降解增加，与咳嗽无关。"},"id":"ph21_q01","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":1},{"type":"A","stem":"硝苯地平降压的主要作用机制是","options":{"A":"阻断β1受体","B":"抑制血管紧张素转换酶","C":"阻滞L型钙通道，减少血管平滑肌细胞内Ca2+内流","D":"激动α2受体","E":"开放钾通道"},"answer":["C"],"rationale":"硝苯地平阻滞血管平滑肌细胞膜L型钙通道，减少Ca2+内流，使血管舒张、外周阻力下降而降压，故答案为 C。","expl":{"A":"错误，阻断β1受体的是美托洛尔等β受体阻断药，可减慢心率。","B":"错误，抑制血管紧张素转换酶是卡托普利等ACEI的机制。","C":"正确，减少钙内流使血管平滑肌松弛，外周阻力下降，血压降低。","D":"错误，激动α2受体是可乐定的中枢性降压机制。","E":"错误，开放钾通道是米诺地尔、二氮嗪等药物的作用机制。"},"id":"ph21_q02","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":2},{"type":"X","stem":"关于血管紧张素转换酶抑制剂的叙述，正确的有","options":{"A":"抑制血管紧张素Ⅱ的生成","B":"减少醛固酮分泌","C":"抑制缓激肽降解，可引起干咳","D":"可致血钾升高，与保钾利尿药合用应慎重","E":"妊娠期高血压可安全使用"},"answer":["A","B","C","D"],"rationale":"ACEI减少血管紧张素Ⅱ生成和醛固酮分泌，使缓激肽蓄积而引起干咳，并可致血钾升高；因有致畸性，妊娠期高血压禁用，故E错误。","expl":{"A":"正确，抑制血管紧张素转换酶使血管紧张素Ⅱ生成减少，血管舒张。","B":"正确，血管紧张素Ⅱ减少使醛固酮分泌下降，促进排钠保钾。","C":"正确，缓激肽蓄积导致刺激性干咳，是其常见停药原因。","D":"正确，血钾升高明显，与保钾利尿药或补钾合用时须密切监测。","E":"错误，ACEI有致畸性，妊娠期高血压禁用，可用甲基多巴等替代。"},"id":"ph21_q03","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":3},{"type":"X","stem":"关于抗高血压药的联合应用，下列叙述正确的有","options":{"A":"利尿药与ACEI合用可减少低钾血症的发生","B":"二氢吡啶类钙拮抗药与β受体阻断药合用可互相抵消反射性心率加快","C":"ACEI与保钾利尿药合用易致高钾血症","D":"β受体阻断药与维拉帕米合用可加重心脏抑制","E":"各类抗高血压药均可安全用于妊娠期高血压"},"answer":["A","B","C","D"],"rationale":"利尿药排钾而ACEI保钾，合用可减少低钾；二氢吡啶类反射性心率加快可被β受体阻断药抵消；ACEI与保钾利尿药合用易高钾，β受体阻断药与维拉帕米合用加重心脏抑制，故E错误。","expl":{"A":"正确，两者对血钾的影响相反，合用可减少低钾血症。","B":"正确，β受体阻断药可抑制二氢吡啶类引起的反射性心动过速。","C":"正确，两者均使血钾升高，合用有高钾血症风险。","D":"正确，两者均抑制窦房结和房室结，合用易致心动过缓和传导阻滞。","E":"错误，ACEI和ARB妊娠期禁用，仅甲基多巴、拉贝洛尔等可选用。"},"id":"ph21_q04","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":4}]},{"title":"第二十二章 抗心律失常药","questions":[{"type":"A","stem":"胺碘酮长期应用最需警惕的不良反应是","options":{"A":"牙龈增生","B":"干咳","C":"低钾血症","D":"耳毒性","E":"肺间质纤维化"},"answer":["E"],"rationale":"胺碘酮长期应用可沉积于肺组织引起肺间质纤维化，是最严重的非心脏不良反应之一，故答案为 E。","expl":{"A":"错误，牙龈增生见于苯妥英钠和硝苯地平长期应用。","B":"错误，干咳是ACEI类药物的典型不良反应。","C":"错误，胺碘酮本身不引起低钾血症，但低钾可加重其致心律失常作用。","D":"错误，耳毒性是氨基糖苷类抗生素和袢利尿药的典型不良反应。","E":"正确，肺间质纤维化可致命，用药期间须定期检查胸片和肺功能。"},"id":"ph22_q01","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":1},{"type":"A","stem":"维拉帕米终止阵发性室上性心动过速的主要机制是","options":{"A":"阻滞L型钙通道，减慢窦房结和房室结的传导，阻断折返","B":"阻滞钠通道，减慢心房和心室肌的传导","C":"阻断心脏β1受体，降低窦房结的自律性","D":"阻滞钾通道，延长动作电位时程和有效不应期","E":"激动心肌A1受体，缩短心房肌的有效不应期"},"answer":["A"],"rationale":"维拉帕米属Ⅳ类钙通道阻滞药，阻滞L型钙通道，对窦房结和房室结等慢反应细胞作用最明显，减慢房室传导、延长房室结不应期而中断折返环，是阵发性室上性心动过速的首选药，故答案为A。阻滞钠通道属Ⅰ类，阻断β受体属Ⅱ类，阻滞钾通道属Ⅲ类，激动A1受体而终止室上速的是腺苷。","expl":{"A":"正确。抑制房室结慢反应细胞的钙内流而阻断折返是其主要机制。","B":"阻滞钠通道、减慢心房和心室肌传导是Ⅰ类药的作用。","C":"阻断心脏β1受体是普萘洛尔等Ⅱ类药的作用。","D":"阻滞钾通道、延长动作电位时程是胺碘酮等Ⅲ类药的作用。","E":"激动A1受体而迅速终止室上速的是腺苷，不是维拉帕米。"},"id":"ph22_q02","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":2},{"type":"A","stem":"利多卡因治疗急性心肌梗死所致室性心律失常的药理学基础是","options":{"A":"轻度阻滞钠通道，缩短动作电位时程和有效不应期，主要作用于浦肯野纤维","B":"明显阻滞钠通道，显著减慢传导，对复极过程影响很小","C":"阻滞钾通道，延长动作电位时程和有效不应期","D":"阻滞L型钙通道，减慢房室结的传导","E":"阻断β受体，降低交感神经对心脏的兴奋作用"},"answer":["A"],"rationale":"利多卡因属Ⅰb类，轻度阻滞钠通道并促进钾外流，缩短动作电位时程和有效不应期，对缺血区的浦肯野纤维作用最强，故对急性心肌梗死和洋地黄中毒所致的室性心律失常疗效好，答案为A。其首过消除明显，须静脉给药，过量可致嗜睡、抽搐等中枢症状。选项B为Ⅰc类，C为Ⅲ类，D为Ⅳ类，E为Ⅱ类。","expl":{"A":"正确。轻度阻滞钠通道并缩短复极是其Ⅰb类的典型特点。","B":"明显阻滞钠通道、对复极影响小是Ⅰc类普罗帕酮的特点。","C":"阻滞钾通道、延长动作电位时程属于Ⅲ类胺碘酮的作用。","D":"阻滞L型钙通道、减慢房室传导属于Ⅳ类维拉帕米的作用。","E":"阻断β受体是Ⅱ类药的作用机制，利多卡因无此作用。"},"id":"ph22_q03","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":3},{"type":"X","stem":"关于抗心律失常药应用与不良反应的叙述，正确的有","options":{"A":"奎尼丁可致金鸡纳反应和奎尼丁晕厥，用药前应纠正低钾血症","B":"利多卡因首过消除明显，须静脉给药","C":"缓慢型心律失常应选用Ⅰ至Ⅳ类抗心律失常药治疗","D":"抗心律失常药本身可致心律失常，用药期间应监测QRS时限和QT间期","E":"普罗帕酮适用于器质性心脏病合并心功能不全的患者"},"answer":["A","B","D"],"rationale":"奎尼丁为Ⅰa类药，可致金鸡纳反应（耳鸣、头晕、恶心、视物模糊）和以尖端扭转型室速为表现的奎尼丁晕厥，用药前须纠正低钾和心功能不全，A正确；利多卡因首过消除明显，口服无效而须静脉给药，B正确；抗心律失常药均有致心律失常作用，应监测QRS时限和QT间期并及时纠正低钾、低镁，D正确。缓慢型心律失常不用Ⅰ至Ⅳ类药，而用阿托品或异丙肾上腺素，C错误；普罗帕酮有明显负性肌力和负性传导作用，器质性心脏病和心功能不全者应慎用或禁用，E错误。","expl":{"A":"正确。低钾可加重QT延长，用药前纠正可减少晕厥发生。","B":"正确。口服生物利用度低，故临床多用静脉给药。","C":"缓慢型心律失常应使用阿托品或异丙肾上腺素提高心率、改善传导。","D":"正确。致心律失常作用是本类药物的共性，须心电监测。","E":"普罗帕酮抑制心肌收缩和传导，此类患者应慎用或禁用。"},"id":"ph22_q04","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":4}]},{"title":"第二十三章 调血脂药与抗动脉粥样硬化药","questions":[{"type":"A","stem":"他汀类药物降低血浆胆固醇的主要机制是","options":{"A":"抑制肠道胆固醇吸收","B":"促进胆固醇转化为胆汁酸","C":"抑制HMG-CoA还原酶，减少肝内胆固醇合成","D":"激活PPARα","E":"抑制脂蛋白脂酶"},"answer":["C"],"rationale":"他汀类竞争性抑制羟甲基戊二酰辅酶A还原酶，减少肝内胆固醇合成，并上调肝细胞LDL受体使血浆LDL降低，故答案为 C。","expl":{"A":"错误，抑制肠道胆固醇吸收的是依折麦布。","B":"错误，促进胆固醇转化为胆汁酸的是考来烯胺等胆汁酸螯合药的作用结果。","C":"正确，抑制限速酶减少合成，继而上调LDL受体清除血浆胆固醇。","D":"错误，激活PPARα是贝特类调脂药的作用机制。","E":"错误，贝特类激活脂蛋白脂酶而非抑制，他汀类也不抑制该酶。"},"id":"ph23_q01","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":1},{"type":"A","stem":"贝特类调血脂药降低血浆甘油三酯的主要机制是","options":{"A":"激活过氧化物酶体增殖物激活受体α，增强脂蛋白脂酶活性","B":"竞争性抑制HMG-CoA还原酶，减少肝内胆固醇合成","C":"抑制小肠黏膜刷状缘的胆固醇转运蛋白","D":"在肠道与胆汁酸结合并阻断其重吸收","E":"抑制前蛋白转化酶枯草溶菌素9，减少低密度脂蛋白受体降解"},"answer":["A"],"rationale":"贝特类激活过氧化物酶体增殖物激活受体α，增强脂蛋白脂酶活性、促进甘油三酯分解，同时减少肝脏极低密度脂蛋白分泌，主要降低甘油三酯并升高高密度脂蛋白，是高甘油三酯血症的首选药，故答案为A。抑制HMG-CoA还原酶的是他汀类，抑制肠道胆固醇吸收的是依折麦布，结合胆汁酸的是考来烯胺，抑制PCSK9的是依洛尤单抗等。","expl":{"A":"正确。激活PPARα并增强脂蛋白脂酶活性是其降甘油三酯的核心机制。","B":"抑制HMG-CoA还原酶是他汀类的机制，主要降低胆固醇。","C":"抑制肠道胆固醇转运蛋白的是依折麦布。","D":"在肠道结合胆汁酸的是考来烯胺等胆汁酸螯合药。","E":"抑制PCSK9的是新型单克隆抗体类药物。"},"id":"ph23_q02","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":2},{"type":"A","stem":"他汀类药物最需警惕的不良反应是","options":{"A":"肌痛、肌病甚至横纹肌溶解","B":"面部潮红、皮肤瘙痒和高尿酸血症","C":"胆结石形成和明显的胃肠道反应","D":"降低高密度脂蛋白胆固醇并延长QT间期","E":"便秘并明显影响其他药物的吸收"},"answer":["A"],"rationale":"他汀类可引起肝酶升高和骨骼肌毒性，表现为肌痛、肌病，严重者发生横纹肌溶解并致急性肾衰竭，与贝特类、大环内酯类和唑类抗真菌药合用时风险明显增加，用药期间应监测肌酸激酶，故答案为A。面部潮红和高尿酸见于烟酸，胆结石和胃肠反应见于贝特类，降低高密度脂蛋白并延长QT间期见于普罗布考，便秘和影响其他药物吸收见于胆汁酸螯合药。","expl":{"A":"正确。肌毒性是他汀类最具临床意义的不良反应。","B":"面部潮红、瘙痒和高尿酸血症是烟酸的典型不良反应。","C":"胆结石和胃肠道反应是贝特类较常见的不良反应。","D":"降低高密度脂蛋白胆固醇并延长QT间期是普罗布考的特点。","E":"便秘和干扰其他药物吸收是考来烯胺等胆汁酸螯合药的问题。"},"id":"ph23_q03","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":3},{"type":"X","stem":"关于调血脂药与抗动脉粥样硬化的叙述，正确的有","options":{"A":"降低低密度脂蛋白胆固醇是防治动脉粥样硬化性心血管病的首要调脂目标","B":"他汀类可上调肝细胞低密度脂蛋白受体，加速血浆低密度脂蛋白的清除","C":"考来烯胺在肠道与胆汁酸结合，阻断其重吸收","D":"普罗布考可升高高密度脂蛋白胆固醇并缩短QT间期","E":"烟酸大剂量可显著升高高密度脂蛋白胆固醇，但面部潮红明显"},"answer":["A","B","C","E"],"rationale":"低密度脂蛋白胆固醇升高是动脉粥样硬化最重要的致病因素，降低它是调脂治疗的首要目标，A正确；他汀类抑制HMG-CoA还原酶减少肝内胆固醇合成，反馈性上调肝细胞低密度脂蛋白受体，加速血浆低密度脂蛋白清除，B正确；考来烯胺在肠道与胆汁酸结合、阻断重吸收，促使胆固醇转化为胆汁酸而降低血胆固醇，C正确；烟酸大剂量降低甘油三酯和低密度脂蛋白、显著升高高密度脂蛋白，但面部潮红、皮肤瘙痒明显，E正确。普罗布考降低高密度脂蛋白胆固醇并延长QT间期，D错误。","expl":{"A":"正确。这也是他汀类成为抗动脉粥样硬化基础用药的原因。","B":"正确。受体上调使血浆低密度脂蛋白清除增加。","C":"正确。阻断胆汁酸重吸收即阻断其肠肝循环。","D":"普罗布考降低而非升高高密度脂蛋白胆固醇，并使QT间期延长。","E":"正确。面部潮红是烟酸最突出的不良反应，限制了其应用。"},"id":"ph23_q04","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":4}]},{"title":"第二十四章 抗心绞痛药","questions":[{"type":"A","stem":"硝酸甘油缓解心绞痛的主要机制是","options":{"A":"减慢心率","B":"增强心肌收缩力","C":"抑制血小板聚集","D":"扩张静脉、降低心脏前负荷，减少心肌耗氧","E":"阻断β受体"},"answer":["D"],"rationale":"硝酸甘油释放一氧化氮激活鸟苷酸环化酶，主要扩张容量血管，降低前负荷和心室壁张力，使心肌耗氧量减少而缓解心绞痛，答案为 D。","expl":{"A":"错误，硝酸甘油可反射性引起心率加快，而不是减慢心率。","B":"错误，它不增强心肌收缩力，过量时反而因前负荷过低使心输出量下降。","C":"错误，抑制血小板聚集是阿司匹林等抗血小板药的作用。","D":"正确，扩张静脉降低前负荷、减少耗氧是其主要抗心绞痛机制。","E":"错误，阻断β受体是普萘洛尔等β受体阻断药的作用。"},"id":"ph24_q01","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":1},{"type":"A","stem":"普萘洛尔抗心绞痛的主要机制是","options":{"A":"减慢心率、减弱心肌收缩力，降低心肌耗氧量","B":"直接扩张冠状动脉","C":"促进冠状动脉侧支循环形成","D":"增加心肌供氧","E":"抑制血小板聚集"},"answer":["A"],"rationale":"普萘洛尔阻断心脏β1受体，减慢心率、减弱心肌收缩力并降低后负荷，使心肌耗氧量明显减少，故答案为 A。","expl":{"A":"正确，通过负性频率和负性肌力作用降低耗氧，是抗心绞痛的主要机制。","B":"错误，β受体阻断药不直接扩张冠状动脉，反而可增加冠脉阻力。","C":"错误，促进侧支循环形成并非其急性抗心绞痛的主要机制。","D":"错误，它不能增加心肌供氧，而是通过减少需氧来恢复供需平衡。","E":"错误，抑制血小板聚集是阿司匹林的作用，与普萘洛尔无关。"},"id":"ph24_q02","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":2},{"type":"A","stem":"变异型心绞痛患者不宜单独应用的抗心绞痛药是","options":{"A":"普萘洛尔","B":"硝苯地平","C":"地尔硫䓬","D":"硝酸甘油","E":"尼可地尔"},"answer":["A"],"rationale":"变异型心绞痛由冠状动脉痉挛引起，治疗首选钙通道阻滞药和硝酸酯类，故硝苯地平、地尔硫䓬和硝酸甘油均可选用；β受体阻断药阻断β2受体后α受体缩血管作用占优势，可加重冠状动脉痉挛，故不宜单独应用，答案为A。此外β受体阻断药禁用于支气管哮喘、重度心动过缓和房室传导阻滞，长期用药不可突然停药。","expl":{"A":"正确。阻断β2受体使α受体缩血管作用占优，可能加重冠脉痉挛。","B":"硝苯地平扩张冠脉、解除痉挛，是变异型心绞痛的首选药之一。","C":"地尔硫䓬可扩张冠状动脉并减慢心率，适用于变异型心绞痛。","D":"硝酸甘油释放一氧化氮舒张血管，可缓解痉挛性发作。","E":"尼可地尔兼有硝酸酯样作用，可用于各型心绞痛。"},"id":"ph24_q03","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":3},{"type":"A","stem":"硝酸酯类连续用药产生耐受性的机制及避免措施是","options":{"A":"与巯基耗竭和神经内分泌激活有关，采用偏心给药并留出无药间期","B":"与血管α受体上调有关，应及时增加给药剂量","C":"与肝药酶诱导有关，应改为口服给药","D":"与血浆蛋白结合率下降有关，应缩短给药间隔","E":"属于变态反应，应合用抗组胺药"},"answer":["A"],"rationale":"连续应用硝酸酯类后血管反应性降低、疗效减弱即为耐受性，其机制与体内巯基耗竭、神经内分泌反射性激活和血管超氧化物增多有关，故答案为A。临床采用偏心给药方案，每天保证足够长的无硝酸酯间期，可减轻耐受性并避免反跳性心肌缺血。增加剂量或缩短间隔不能解决耐受性，反而加重不良反应；耐受性也不是变态反应。","expl":{"A":"正确。留出无药间期是目前减轻耐受性最有效的方法。","B":"盲目增加剂量不能逆转耐受性，只会加重头痛和低血压。","C":"耐受性与肝药酶诱导无关，改口服也不能避免。","D":"缩短给药间隔会使血管始终处于药物暴露状态，加重耐受。","E":"耐受性是药效学适应现象，与变态反应无关。"},"id":"ph24_q04","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":4}]},{"title":"第二十五章 治疗充血性心力衰竭药","questions":[{"type":"A","stem":"强心苷中毒引起窦性心动过缓或房室传导阻滞时，宜选用","options":{"A":"苯妥英钠","B":"利多卡因","C":"氯化钾","D":"阿托品","E":"普萘洛尔"},"answer":["D"],"rationale":"强心苷中毒所致缓慢性心律失常与迷走神经张力过高有关，阿托品阻断M受体可提高心率、改善传导，此时不宜补钾，故答案为 D。","expl":{"A":"错误，苯妥英钠用于强心苷中毒引起的室性心律失常，对传导阻滞无效。","B":"错误，利多卡因主要用于室性心律失常，不能纠正心动过缓。","C":"错误，钾盐会加重强心苷对心脏的毒性，传导阻滞时禁忌补钾。","D":"正确，阿托品解除迷走神经对窦房结和房室结的抑制，提高心率。","E":"错误，普萘洛尔进一步抑制传导和心率，可使阻滞加重。"},"id":"ph25_q01","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":1},{"type":"A","stem":"地高辛增强心肌收缩力的机制是","options":{"A":"抑制心肌细胞膜Na+-K+-ATP酶，使细胞内Ca2+增多","B":"激动β1受体","C":"阻滞钙通道","D":"开放钠通道","E":"抑制磷酸二酯酶"},"answer":["A"],"rationale":"地高辛抑制心肌细胞膜Na+-K+-ATP酶，使细胞内Na+增多，通过Na+-Ca2+交换使细胞内Ca2+增加，从而增强心肌收缩力，故答案为 A。","expl":{"A":"正确，抑制钠钾泵间接提高细胞内钙浓度，产生正性肌力作用。","B":"错误，激动β1受体是肾上腺素、多巴酚丁胺等药物的机制。","C":"错误，阻滞钙通道产生负性肌力作用，与强心苷作用相反。","D":"错误，强心苷并非开放钠通道，而是抑制钠钾泵。","E":"错误，抑制磷酸二酯酶是米力农等磷酸二酯酶抑制药的作用机制。"},"id":"ph25_q02","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":2},{"type":"A","stem":"沙库巴曲缬沙坦治疗心力衰竭的作用特点是","options":{"A":"缬沙坦阻断AT1受体，沙库巴曲的活性代谢物抑制脑啡肽酶、增加利钠肽","B":"抑制磷酸二酯酶Ⅲ，增加心肌细胞内环磷酸腺苷","C":"抑制心肌细胞膜Na+-K+-ATP酶，增强心肌收缩力","D":"选择性激动β1受体，增强心肌收缩力","E":"抑制窦房结起搏电流，减慢心率"},"answer":["A"],"rationale":"沙库巴曲缬沙坦是血管紧张素受体-脑啡肽酶抑制药，缬沙坦阻断AT1受体，沙库巴曲的活性代谢物抑制脑啡肽酶、减少利钠肽降解，从而排钠利尿、扩张血管并抑制重构，可替代ACEI用于射血分数降低的心衰，故答案为A。因其与ACEI合用增加血管神经性水肿风险，转换时须停用ACEI一段时间。抑制磷酸二酯酶Ⅲ的是米力农，抑制钠钾泵的是强心苷，抑制窦房结起搏电流的是伊伐布雷定。","expl":{"A":"正确。双重作用即阻断AT1受体与抑制脑啡肽酶。","B":"抑制磷酸二酯酶Ⅲ而增加环磷酸腺苷的是米力农等正性肌力药。","C":"抑制Na+-K+-ATP酶是强心苷增强收缩力的机制。","D":"激动β1受体增强收缩力并非本药作用，反而应阻断交感。","E":"抑制窦房结起搏电流而减慢心率的是伊伐布雷定。"},"id":"ph25_q03","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":3},{"type":"A","stem":"关于β受体阻断药治疗慢性心力衰竭的叙述，正确的是","options":{"A":"须在病情稳定后从小剂量开始并逐渐递增，急性失代偿期不宜使用","B":"急性失代偿期应首选，以迅速缓解肺循环淤血","C":"通过激动β1受体增强心肌收缩力而改善症状","D":"只能改善症状，不能降低心力衰竭患者的死亡率","E":"起始即应给予目标剂量，以便尽快拮抗交感神经"},"answer":["A"],"rationale":"β受体阻断药长期应用可拮抗交感神经过度激活、逆转心肌重构、改善心功能并显著降低死亡率，是慢性心衰改善预后的基石；但其负性肌力和负性传导作用使急性失代偿期禁用，须在病情稳定、无明显淤血时从很小剂量开始，逐渐递增至患者可耐受的剂量，故答案为A。其作用机制是阻断而非激动β受体，也不能起始即用大剂量。","expl":{"A":"正确。稳定期小剂量起始、缓慢递增是安全用药的关键。","B":"急性失代偿期使用会加重血流动力学障碍，属禁忌。","C":"β受体阻断药阻断而非激动β1受体，作用是拮抗交感过度激活。","D":"长期应用可显著降低死亡率和再住院率，并非仅改善症状。","E":"起始大剂量易致心衰恶化，必须从小剂量逐步递增。"},"id":"ph25_q04","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":4}]},{"title":"第二十六章 作用于血液系统的药物","questions":[{"type":"A","stem":"华法林抗凝作用的主要机制是","options":{"A":"直接抑制凝血酶","B":"激活抗凝血酶Ⅲ","C":"抑制维生素K环氧化物还原酶，减少凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成","D":"抑制血小板聚集","E":"促进纤维蛋白溶解"},"answer":["C"],"rationale":"华法林抑制维生素K环氧化物还原酶，阻碍维生素K的循环利用，使凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化受阻而抗凝，故答案为 C。","expl":{"A":"错误，直接抑制凝血酶的是达比加群、阿加曲班等。","B":"错误，激活抗凝血酶Ⅲ的是肝素。","C":"正确，须待已合成的凝血因子耗竭后才起效，故起效慢，需测定INR。","D":"错误，抑制血小板聚集的是阿司匹林、氯吡格雷。","E":"错误，促进纤维蛋白溶解的是尿激酶、链激酶。"},"id":"ph26_q01","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":1},{"type":"A","stem":"肝素过量引起出血时，应选用的拮抗药是","options":{"A":"维生素K","B":"鱼精蛋白","C":"氨甲环酸","D":"硫酸亚铁","E":"叶酸"},"answer":["B"],"rationale":"鱼精蛋白带强正电荷，可与带负电荷的肝素结合形成无活性复合物，是肝素过量的特效拮抗药，故答案为 B。","expl":{"A":"错误，维生素K用于拮抗华法林过量，对肝素无效。","B":"正确，按1 mg中和100单位肝素计算缓慢静注，可迅速纠正出血。","C":"错误，氨甲环酸是抗纤溶药，不能中和肝素。","D":"错误，硫酸亚铁用于缺铁性贫血的补铁治疗。","E":"错误，叶酸用于巨幼细胞性贫血，与肝素无拮抗关系。"},"id":"ph26_q02","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":2},{"type":"A","stem":"口服铁剂治疗缺铁性贫血时，能促进铁吸收的合用措施是","options":{"A":"同服维生素C","B":"同服浓茶","C":"同服抗酸药","D":"同服四环素","E":"与牛奶同服"},"answer":["A"],"rationale":"二价铁比三价铁易于吸收，维生素C既可使高价铁还原为亚铁，又能与之形成可溶性螯合物，从而明显提高铁的吸收率；浓茶中的鞣酸、抗酸药、四环素和牛奶中的钙均妨碍铁吸收，故答案为 A。","expl":{"A":"正确，维生素C促进铁的还原与溶解，是提高铁剂吸收的常用措施。","B":"错误，浓茶含大量鞣酸，与铁形成难溶性沉淀而妨碍吸收。","C":"错误，抗酸药升高胃内pH，使铁盐难以溶解，吸收减少。","D":"错误，四环素与铁形成络合物，两者吸收均减少，应分开服用。","E":"错误，牛奶中的钙和磷酸盐可抑制铁的吸收，不宜同服。"},"id":"ph26_q03","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":3},{"type":"A","stem":"巨幼细胞性贫血患者单用叶酸治疗，最主要的危险是","options":{"A":"引起急性溶血性贫血","B":"掩盖维生素B12缺乏所致的神经系统损害","C":"诱发再生障碍性贫血","D":"造成体内铁负荷过重","E":"引起粒细胞缺乏症"},"answer":["B"],"rationale":"叶酸参与一碳单位转移和DNA合成，可纠正巨幼细胞性贫血的血液学异常，但不能改善维生素B12缺乏引起的神经损害，单用叶酸会掩盖神经症状、延误诊治，故用药前应查明病因并检测维生素B12水平，答案为 B。","expl":{"A":"错误，叶酸并不引起溶血，溶血性贫血另有病因，与叶酸缺乏无关。","B":"正确，血液学指标改善而神经损害继续进展，是单用叶酸的主要风险。","C":"错误，再生障碍性贫血源于骨髓造血功能衰竭，与叶酸治疗无关。","D":"错误，铁负荷过重见于反复输血或长期过量补铁者。","E":"错误，粒细胞缺乏多见于抗甲状腺药、氯氮平等药物，与叶酸无关。"},"id":"ph26_q04","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":4}]},{"title":"第二十七章 作用于呼吸系统的药物","questions":[{"type":"A","stem":"沙丁胺醇缓解支气管哮喘急性发作的主要机制是","options":{"A":"激动支气管平滑肌β2受体，舒张支气管","B":"阻断M受体","C":"抑制磷酸二酯酶","D":"激动糖皮质激素受体","E":"拮抗白三烯受体"},"answer":["A"],"rationale":"沙丁胺醇选择性激动支气管平滑肌β2受体，激活腺苷酸环化酶使cAMP增多，支气管迅速舒张，是缓解急性发作的首选药，答案为 A。","expl":{"A":"正确，激动β2受体舒张支气管，起效快，为急性发作的首选缓解药。","B":"错误，阻断M受体的是异丙托溴铵等抗胆碱药，起效较慢。","C":"错误，抑制磷酸二酯酶的是氨茶碱。","D":"错误，糖皮质激素起效慢，主要用于长期控制气道炎症而非急性缓解。","E":"错误，拮抗白三烯受体的是孟鲁司特，用于长期控制。"},"id":"ph27_q01","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":1},{"type":"A","stem":"氨茶碱平喘的主要作用机制是","options":{"A":"激动β2受体","B":"阻断白三烯受体","C":"抑制磷酸二酯酶使cAMP增多，并阻断腺苷受体","D":"抑制IgE生成","E":"激动M受体"},"answer":["C"],"rationale":"氨茶碱抑制磷酸二酯酶使cAMP降解减少，并可阻断腺苷受体、增强膈肌收缩力，从而舒张支气管、改善通气，答案为 C。","expl":{"A":"错误，激动β2受体的是沙丁胺醇等选择性β2受体激动药。","B":"错误，阻断白三烯受体的是孟鲁司特、扎鲁司特。","C":"正确，通过抑制磷酸二酯酶和阻断腺苷受体发挥平喘作用。","D":"错误，抑制IgE生成的是奥马珠单抗等生物制剂。","E":"错误，激动M受体使支气管收缩，与平喘作用方向相反。"},"id":"ph27_q02","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":2},{"type":"A","stem":"色甘酸钠预防哮喘发作的主要机制是","options":{"A":"激动β2受体","B":"阻断组胺H1受体","C":"抑制磷酸二酯酶","D":"阻断M受体","E":"稳定肥大细胞膜，抑制过敏介质释放"},"answer":["E"],"rationale":"色甘酸钠稳定肥大细胞膜，阻止钙内流和脱颗粒，减少组胺、白三烯等过敏介质释放，故仅用于预防发作，答案为 E。","expl":{"A":"错误，它无β2受体激动作用，不能直接舒张支气管平滑肌。","B":"错误，阻断H1受体的是抗组胺药，对哮喘疗效有限。","C":"错误，抑制磷酸二酯酶的是茶碱类药物。","D":"错误，阻断M受体的是异丙托溴铵等抗胆碱药。","E":"正确，抑制肥大细胞脱颗粒，须在接触抗原前给药才有预防作用。"},"id":"ph27_q03","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":3},{"type":"X","stem":"关于平喘药的应用，下列叙述正确的有","options":{"A":"β2受体激动剂是缓解哮喘急性发作的首选药","B":"糖皮质激素是控制哮喘气道炎症最有效的药物","C":"吸入型糖皮质激素可减少口服激素的用量","D":"色甘酸钠适用于哮喘急性发作","E":"氨茶碱安全范围窄，应监测血药浓度"},"answer":["A","B","C","E"],"rationale":"β2受体激动剂起效快，为急性发作首选；糖皮质激素是最有效的抗炎控制药，吸入制剂可减少全身用量；氨茶碱安全范围窄需监测血药浓度，而色甘酸钠仅用于预防，故D错误。","expl":{"A":"正确，短效β2受体激动剂吸入后数分钟起效，为急性缓解的首选。","B":"正确，糖皮质激素抑制气道炎症，是长期控制哮喘的基石。","C":"正确，吸入给药局部浓度高、全身不良反应少，可减少口服激素用量。","D":"错误，色甘酸钠无直接舒张支气管作用，对已发作的哮喘无效。","E":"正确，其有效浓度与中毒浓度接近，静注过快可致心律失常和惊厥。"},"id":"ph27_q04","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":4}]},{"title":"第二十八章 作用于消化系统的药物","questions":[{"type":"A","stem":"奥美拉唑抑制胃酸分泌的机制是","options":{"A":"阻断胃壁细胞H2受体","B":"不可逆抑制胃壁细胞H+-K+-ATP酶","C":"中和胃酸","D":"阻断M受体","E":"在溃疡面形成保护膜"},"answer":["B"],"rationale":"奥美拉唑在壁细胞分泌小管的酸性环境中转化为活性物，与H+-K+-ATP酶巯基共价结合而不可逆抑制质子泵，故答案为 B。","expl":{"A":"错误，阻断H2受体的是西咪替丁、雷尼替丁等。","B":"正确，不可逆抑制质子泵，抑酸作用强而持久，是消化性溃疡的一线用药。","C":"错误，中和胃酸的是氢氧化铝、碳酸氢钠等抗酸药。","D":"错误，阻断M受体的是哌仑西平。","E":"错误，在溃疡面形成保护膜的是硫糖铝和枸橼酸铋钾。"},"id":"ph28_q01","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":1},{"type":"A","stem":"昂丹司琼止吐的主要作用机制是","options":{"A":"阻断D2受体","B":"阻断H1受体","C":"阻断M受体","D":"阻断5-HT3受体","E":"激动GABA受体"},"answer":["D"],"rationale":"昂丹司琼选择性阻断中枢及外周5-HT3受体，对肿瘤化疗和放疗引起的呕吐疗效显著，故答案为 D。","expl":{"A":"错误，阻断D2受体的是甲氧氯普胺和氯丙嗪。","B":"错误，阻断H1受体的是苯海拉明等抗晕动药。","C":"错误，阻断M受体的是东莨菪碱。","D":"正确，阻断5-HT3受体对化疗所致呕吐效果最好。","E":"错误，激动GABA受体的是苯二氮䓬类，不用于止吐。"},"id":"ph28_q02","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":2},{"type":"A","stem":"关于硫糖铝用药指导的叙述，正确的是","options":{"A":"需在酸性环境中形成保护膜，不宜与抑酸药同服","B":"与奥美拉唑同服可增强其保护作用","C":"主要通过中和胃酸发挥抗溃疡作用","D":"长期服用可致舌头发黑和黑便","E":"应与两种抗生素联用以根除幽门螺杆菌"},"answer":["A"],"rationale":"硫糖铝在胃酸作用下解离出硫酸蔗糖复合物，聚合成胶体黏附于溃疡面才能形成保护膜，抑酸药升高胃内pH后会妨碍其成膜而降低疗效，故二者不宜同服，答案为 A。","expl":{"A":"正确，酸性环境是硫糖铝成膜的前提，故宜空腹或餐前单独服用。","B":"错误，奥美拉唑抑制胃酸分泌，反而妨碍硫糖铝解离成膜。","C":"错误，中和胃酸的是氢氧化铝、碳酸氢钠等抗酸药，硫糖铝不中和胃酸。","D":"错误，致舌头发黑和黑便的是枸橼酸铋钾，须与消化道出血鉴别。","E":"错误，根除幽门螺杆菌用质子泵抑制剂加铋剂加两种抗生素，硫糖铝不参与。"},"id":"ph28_q03","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":3},{"type":"A","stem":"应用洛哌丁胺止泻时，属于禁忌的情况是","options":{"A":"肠易激综合征所致的慢性腹泻","B":"细菌性痢疾等侵袭性感染性腹泻","C":"精神紧张引起的功能性腹泻","D":"糖尿病自主神经病变所致腹泻","E":"甲状腺功能亢进所致腹泻"},"answer":["B"],"rationale":"洛哌丁胺抑制肠蠕动，使粪便与细菌毒素在肠腔内滞留，细菌性痢疾等侵袭性腹泻应用后可加重中毒症状，甚至诱发中毒性巨结肠，故此类腹泻禁用，答案为 B。","expl":{"A":"错误，肠易激综合征的慢性腹泻属非感染性，可用洛哌丁胺对症处理。","B":"正确，感染性侵袭性腹泻须先抗感染并补液，止泻会滞留毒素而加重病情。","C":"错误，功能性腹泻并非感染性，必要时可短期对症使用。","D":"错误，糖尿病性腹泻属非感染性，可酌情对症处理并控制血糖。","E":"错误，甲亢性腹泻由肠蠕动增快所致，治疗以控制甲亢为主，并非用药禁忌。"},"id":"ph28_q04","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":4}]},{"title":"第二十九章 自体活性物质及其影响药物","questions":[{"type":"A","stem":"组胺激动H2受体后产生的主要效应是","options":{"A":"支气管平滑肌收缩","B":"毛细血管通透性增高","C":"胃酸分泌增加","D":"皮肤瘙痒","E":"子宫平滑肌收缩"},"answer":["C"],"rationale":"H2受体主要分布于胃壁细胞、心肌与子宫，激动后使胃酸分泌增加、心率加快、心肌收缩力增强，是消化性溃疡抑酸治疗的受体基础，故答案为 C。","expl":{"A":"错误，支气管平滑肌收缩由H1受体介导，是过敏性哮喘的环节之一。","B":"错误，毛细血管通透性增高属H1受体激动后血管内皮收缩的效应。","C":"正确，胃壁细胞H2受体激动使胃酸分泌增多，可被西咪替丁等阻断。","D":"错误，瘙痒主要与H1受体及H4受体有关，与H2受体关系不大。","E":"错误，子宫虽含H2受体，但收缩并非其激动后的主要效应。"},"id":"ph29_q01","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":1},{"type":"A","stem":"舒马普坦治疗偏头痛急性发作的机制是","options":{"A":"阻断5-HT3受体","B":"激动5-HT1B/1D受体","C":"阻断多巴胺D2受体","D":"抑制5-羟色胺的再摄取","E":"阻断半胱氨酰白三烯受体"},"answer":["B"],"rationale":"舒马普坦选择性激动脑膜血管的5-HT1B/1D受体，使已扩张的脑血管收缩，并抑制三叉神经末梢释放降钙素基因相关肽等致痛物质，从而终止偏头痛发作，故答案为 B。","expl":{"A":"错误，阻断5-HT3受体的是昂丹司琼等止吐药，用于化疗呕吐。","B":"正确，激动5-HT1B/1D受体是曲普坦类治疗偏头痛急性发作的共同机制。","C":"错误，阻断D2受体的是甲氧氯普胺、氯丙嗪等药物。","D":"错误，抑制5-羟色胺再摄取的是选择性5-羟色胺再摄取抑制药，与单胺氧化酶抑制药合用可致5-HT综合征。","E":"错误，阻断半胱氨酰白三烯受体的是孟鲁司特等抗哮喘药。"},"id":"ph29_q02","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":2},{"type":"A","stem":"关于孟鲁司特等白三烯受体阻断药的叙述，正确的是","options":{"A":"可迅速松弛支气管平滑肌，用于哮喘急性发作的解救","B":"须长期规律服用以预防发作，不能替代β2受体激动药急救","C":"通过阻断组胺H1受体而减轻气道黏膜水肿","D":"通过抑制肥大细胞脱颗粒而预防哮喘发作","E":"主要用于缓解慢性阻塞性肺疾病急性加重期的呼吸困难"},"answer":["B"],"rationale":"孟鲁司特阻断半胱氨酰白三烯CysLT1受体，减轻气道平滑肌收缩、黏膜水肿与嗜酸性粒细胞浸润，须长期规律服用才能减少发作，不具备即时平喘作用，故不能用于急性发作的解救，答案为 B。","expl":{"A":"错误，其无即时支气管扩张作用，急性发作须吸入β2受体激动药。","B":"正确，其价值在于减少发作次数与激素用量，属长期控制药。","C":"错误，其阻断的是白三烯受体，与组胺H1受体无关。","D":"错误，稳定肥大细胞膜、抑制脱颗粒的是色甘酸钠。","E":"错误，其适应证是哮喘的长期预防治疗，而非慢阻肺急性加重。"},"id":"ph29_q03","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":3},{"type":"X","stem":"关于第一代H1受体阻断药的叙述，正确的有","options":{"A":"脂溶性高，易透过血脑屏障，镇静作用明显","B":"具抗胆碱作用，可致口干、视物模糊和尿潴留","C":"可直接阻断H2受体而抑制胃酸分泌","D":"青光眼与前列腺肥大患者应慎用","E":"能阻止肥大细胞释放组胺，可用于过敏发作的预防"},"answer":["A","B","D"],"rationale":"第一代H1受体阻断药脂溶性高、易入脑，故镇静与抗胆碱作用明显，青光眼和前列腺肥大者应慎用；它们仅竞争性阻断H1受体，既不能阻断H2受体，也不能阻止组胺释放，故答案为 A、B、D。","expl":{"A":"正确，易入脑是其嗜睡、注意力下降等中枢抑制作用的根源。","B":"正确，抗胆碱作用可致口干、视物模糊、便秘和尿潴留。","C":"错误，阻断H2受体的是西咪替丁等，H1受体阻断药对胃酸分泌无影响。","D":"正确，抗胆碱作用可升高眼压、加重排尿困难，故须慎用。","E":"错误，它们不能阻止肥大细胞脱颗粒，仅对抗已释放组胺的效应。"},"id":"ph29_q04","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":4}]},{"title":"第三十章 雌激素、孕激素和女性生殖道药物","questions":[{"type":"A","stem":"缩宫素小剂量静脉滴注用于催产时，其子宫效应的特点是","options":{"A":"引起子宫强直性收缩","B":"加强子宫体节律性收缩，对子宫颈作用弱","C":"对子宫体和子宫颈均产生强而持久的收缩","D":"抑制子宫平滑肌收缩，延长产程","E":"仅兴奋子宫颈而不影响子宫体"},"answer":["B"],"rationale":"缩宫素选择性兴奋子宫平滑肌，小剂量加强子宫体的节律性收缩并使收缩与舒张交替，同时其对子宫颈的兴奋作用弱，有利于胎儿娩出，故可用于催产引产，答案为 B。","expl":{"A":"错误，大剂量缩宫素才引起强直性收缩，催产时必须避免。","B":"正确，小剂量保留节律性、对宫颈作用弱，是可用于催产的药理基础。","C":"错误，对子宫体与宫颈均强直收缩的是麦角新碱，只能用于产后止血。","D":"错误，抑制子宫收缩的是利托君、硫酸镁等保胎药。","E":"错误，缩宫素主要兴奋子宫体，对子宫颈作用反而较弱。"},"id":"ph30_q01","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":1},{"type":"A","stem":"他莫昔芬用于乳腺癌治疗的药理基础是","options":{"A":"竞争性阻断乳腺组织的雌激素受体","B":"抑制芳香化酶而减少雌激素合成","C":"拮抗下丘脑雌激素受体而促进排卵","D":"抑制肿瘤细胞的二氢叶酸还原酶","E":"激动乳腺组织的雌激素受体"},"answer":["A"],"rationale":"他莫昔芬属选择性雌激素受体调节剂，在乳腺组织竞争性阻断雌激素受体而抑制肿瘤生长，在骨与子宫内膜却表现为激动作用，故长期应用须警惕子宫内膜增生，答案为 A。","expl":{"A":"正确，乳腺组织拮抗、骨与子宫内膜激动是其组织选择性的体现。","B":"错误，抑制芳香化酶的是来曲唑等芳香化酶抑制剂。","C":"错误，拮抗下丘脑雌激素受体而促排卵的是氯米芬。","D":"错误，抑制二氢叶酸还原酶的是甲氨蝶呤等抗叶酸药。","E":"错误，若激动乳腺雌激素受体反而促进肿瘤生长，与其治疗作用相反。"},"id":"ph30_q02","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":2},{"type":"A","stem":"米非司酮终止早期妊娠的主要机制是","options":{"A":"竞争性阻断孕激素受体，使蜕膜变性坏死","B":"直接兴奋子宫平滑肌引起强直性收缩","C":"抑制排卵并改变宫颈黏液性状","D":"激动前列腺素受体而促进子宫收缩","E":"阻断雌激素受体而抑制内膜增生"},"answer":["A"],"rationale":"米非司酮竞争性阻断孕激素受体，使蜕膜变性坏死、绒毛膜促性腺激素下降，胚胎失去孕激素支持而停止发育，须与米索前列醇序贯应用才能提高完全流产率，答案为 A。","expl":{"A":"正确，抗孕激素作用是其终止早孕的药理基础，单用完全流产率低。","B":"错误，直接兴奋子宫平滑肌的是缩宫素、麦角新碱和前列腺素类。","C":"错误，抑制排卵、改变宫颈黏液是甾体避孕药的作用环节。","D":"错误，激动前列腺素受体的是米索前列醇，与其序贯应用。","E":"错误，阻断雌激素受体的是他莫昔芬等选择性雌激素受体调节剂。"},"id":"ph30_q03","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":3},{"type":"X","stem":"关于雌激素类药物作用与应用的叙述，正确的有","options":{"A":"促进子宫内膜增生，有子宫的妇女长期单用可增加子宫内膜癌风险","B":"促进水钠潴留，可致水肿和血压升高","C":"促进凝血因子合成，增加血栓栓塞风险","D":"降低低密度脂蛋白并升高高密度脂蛋白","E":"长期单用可致子宫内膜萎缩和月经量明显减少"},"answer":["A","B","C","D"],"rationale":"雌激素促进子宫内膜增生、引起水钠潴留、促进凝血因子合成并改善脂蛋白谱，因此有子宫者长期单用须加用孕激素保护内膜；使子宫内膜萎缩、月经量减少的是孕激素的长期作用，故 E 错误，答案为 A、B、C、D。","expl":{"A":"正确，故有子宫的妇女须加用孕激素转化内膜，即孕激素保护。","B":"正确，水钠潴留可致体重增加、水肿甚至血压升高。","C":"正确，凝血因子合成增多使静脉血栓风险上升，吸烟者尤须注意。","D":"正确，雌激素可降低低密度脂蛋白、升高高密度脂蛋白，对心血管有一定保护倾向。","E":"错误，使内膜萎缩、月经量减少的是孕激素长期作用，雌激素的作用相反。"},"id":"ph30_q04","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":4}]},{"title":"第三十一章 雄激素和男科药物","questions":[{"type":"A","stem":"非那雄胺治疗良性前列腺增生的作用机制是","options":{"A":"阻断前列腺与膀胱颈的α1受体","B":"抑制5α-还原酶，降低前列腺内双氢睾酮浓度","C":"阻断雄激素受体","D":"抑制磷酸二酯酶5的活性","E":"激动膀胱平滑肌的β2受体"},"answer":["B"],"rationale":"非那雄胺选择性抑制Ⅱ型5α-还原酶，使睾酮不能转化为活性更强的双氢睾酮，前列腺上皮逐渐萎缩、体积缩小而尿道阻力下降，故起效慢、需长期服药，答案为 B。","expl":{"A":"错误，阻断α1受体而迅速缓解排尿症状的是特拉唑嗪、坦索罗辛。","B":"正确，降低前列腺内双氢睾酮浓度是缩小腺体的关键机制。","C":"错误，阻断雄激素受体的是氟他胺等抗雄激素药，用于前列腺癌。","D":"错误，抑制磷酸二酯酶5的是西地那非等治疗勃起功能障碍的药物。","E":"错误，激动β2受体松弛平滑肌的是利托君等，与前列腺增生治疗无关。"},"id":"ph31_q01","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":1},{"type":"A","stem":"磷酸二酯酶5抑制药治疗勃起功能障碍时，最严重的用药禁忌是合用","options":{"A":"硝酸酯类药物","B":"α1受体阻断药","C":"二甲双胍","D":"他汀类调脂药","E":"β受体阻断药"},"answer":["A"],"rationale":"西地那非等抑制磷酸二酯酶5而减少环磷酸鸟苷降解，硝酸酯类则促进环磷酸鸟苷生成，二者合用使血管急剧扩张、血压骤降甚至危及生命，属绝对禁忌，答案为 A。","expl":{"A":"正确，两药均提高环磷酸鸟苷水平，合用可致严重低血压，须绝对避免。","B":"错误，α1受体阻断药可加重体位性低血压，应错开服用并监测血压，但非绝对禁忌。","C":"错误，二甲双胍与磷酸二酯酶5抑制药之间无禁忌性相互作用。","D":"错误，他汀类调脂药与西地那非无合用禁忌性相互作用。","E":"错误，β受体阻断药不通过环磷酸鸟苷途径发挥作用，不属绝对禁忌。"},"id":"ph31_q02","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":2},{"type":"A","stem":"儿童长期应用雄激素最可能导致的不良后果是","options":{"A":"骨骺过早闭合，影响最终身高","B":"骨骺延迟闭合，身材异常高大","C":"甲状腺功能减退","D":"骨钙大量丢失导致骨质疏松","E":"骨髓抑制导致再生障碍性贫血"},"answer":["A"],"rationale":"雄激素既促进骨骼生长又促进骨骺闭合，儿童过早或长期应用虽短期生长加快，但骨骺提前闭合终致最终身高降低，并可出现性早熟，故儿童用药须严格掌握适应证，答案为 A。","expl":{"A":"正确，骨骺早闭使生长年限缩短，最终身高反而低于预期。","B":"错误，雄激素加速而非延迟骨骺闭合，不会使身材异常高大。","C":"错误，雄激素不引起甲状腺功能减退，与甲状腺激素无关。","D":"错误，雄激素促进骨钙沉积，可用于骨质疏松的辅助治疗。","E":"错误，雄激素与同化激素可用于治疗再生障碍性贫血，而非引起骨髓抑制。"},"id":"ph31_q03","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":3},{"type":"X","stem":"关于良性前列腺增生药物治疗的叙述，正确的有","options":{"A":"α1受体阻断药松弛前列腺与膀胱颈平滑肌，改善排尿症状快","B":"5α-还原酶抑制药缩小前列腺体积，起效慢而需长期服用","C":"非那雄胺可使血清前列腺特异性抗原水平下降，用药前应排除前列腺癌","D":"α1受体阻断药首剂可致体位性低血压，宜从小剂量睡前服用","E":"5α-还原酶抑制药可迅速缓解排尿困难，适用于所有前列腺增生患者"},"answer":["A","B","C","D"],"rationale":"前列腺增生用药可记一快一慢：α1受体阻断药松弛平滑肌、改善症状快但首剂易致体位性低血压；5α-还原酶抑制药缩小腺体慢且降低前列腺特异性抗原，用药前须排除前列腺癌；故 A、B、C、D 正确，E 错误。","expl":{"A":"正确，松弛前列腺与膀胱颈平滑肌是其迅速缓解排尿困难的基础。","B":"正确，腺体缩小需数月，须长期服药才能显效。","C":"正确，前列腺特异性抗原约降至原来的一半，可掩盖前列腺癌的筛查信号。","D":"正确，首剂效应明显，睡前小剂量起始可减少体位性低血压的发生。","E":"错误，其起效慢，且主要适用于腺体明显增大的患者，不能迅速缓解症状。"},"id":"ph31_q04","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":4}]},{"title":"第三十二章 肾上腺皮质激素类药物","questions":[{"type":"A","stem":"糖皮质激素抗炎作用的主要机制是","options":{"A":"直接杀灭炎症细胞","B":"增加毛细血管通透性","C":"促进抗体生成","D":"抑制磷脂酶A2，减少前列腺素和白三烯生成","E":"增强巨噬细胞吞噬功能"},"answer":["D"],"rationale":"糖皮质激素诱导脂皮素-1生成，抑制磷脂酶A2，使花生四烯酸释放减少，前列腺素和白三烯生成下降，从而产生强大的抗炎作用，答案为 D。","expl":{"A":"错误，糖皮质激素并无杀菌作用，也不直接杀灭炎症细胞。","B":"错误，它降低毛细血管通透性、减少渗出，而不是增加通透性。","C":"错误，大剂量糖皮质激素抑制抗体生成，而不是促进抗体生成。","D":"正确，抑制磷脂酶A2使炎症介质生成减少，是其抗炎作用的核心环节。","E":"错误，它抑制巨噬细胞的吞噬和抗原提呈功能，而非增强。"},"id":"ph32_q01","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":1},{"type":"A","stem":"长期应用糖皮质激素后突然停药可出现","options":{"A":"肾上腺皮质功能亢进","B":"肾上腺皮质萎缩、功能不全，出现停药症状或反跳","C":"甲状腺功能亢进","D":"胰岛素抵抗","E":"骨质疏松迅速恢复"},"answer":["B"],"rationale":"长期外源性糖皮质激素反馈抑制下丘脑-垂体-肾上腺轴，使肾上腺皮质萎缩、功能减退，突然停药可出现皮质功能不全或原病反跳，答案为 B。","expl":{"A":"错误，用药期间可表现为医源性皮质功能亢进，但停药时表现的是功能不全。","B":"正确，反馈抑制使皮质萎缩，需逐渐减量停药并必要时补充ACTH。","C":"错误，糖皮质激素不影响甲状腺功能，不会引起甲状腺功能亢进。","D":"错误，激素可使血糖升高，但停药不会出现胰岛素抵抗。","E":"错误，长期用药引起骨质疏松，停药后不会迅速恢复，需较长时间治疗。"},"id":"ph32_q02","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":2},{"type":"A","stem":"糖皮质激素用于严重感染或感染性休克时，必须","options":{"A":"单独使用","B":"大剂量长期使用","C":"局部给药","D":"与活疫苗同时接种","E":"与足量有效的抗菌药物合用"},"answer":["E"],"rationale":"糖皮质激素抑制免疫和炎症反应，用于严重感染时必须与足量有效的抗菌药物合用，否则可致感染扩散，答案为 E。","expl":{"A":"错误，单独应用会削弱机体防御功能，导致感染扩散。","B":"错误，应早期、短程、大剂量给药，症状控制后迅速减量停药。","C":"错误，严重感染和休克需全身给药，局部用药达不到治疗目的。","D":"错误，使用激素期间接种活疫苗可能引起严重感染，属禁忌。","E":"正确，抗菌药物控制病原体，激素减轻中毒症状，二者必须合用。"},"id":"ph32_q03","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":3},{"type":"X","stem":"关于糖皮质激素药理作用的叙述，正确的有","options":{"A":"大剂量可抑制免疫反应和炎症反应","B":"可使红细胞、血小板和中性粒细胞增多，淋巴细胞减少","C":"可提高中枢神经系统兴奋性","D":"促进胃酸和胃蛋白酶分泌","E":"可使血钾升高"},"answer":["A","B","C","D"],"rationale":"糖皮质激素具有强大的抗炎和免疫抑制作用，可使红细胞、血小板和中性粒细胞增多而淋巴细胞减少，提高中枢兴奋性并促进胃酸分泌；因其保钠排钾，血钾降低而非升高，故E错误。","expl":{"A":"正确，大剂量激素抑制巨噬细胞功能、减少炎症介质生成和抗体产生。","B":"正确，血象呈红细胞、血小板、中性粒细胞增多，淋巴细胞和嗜酸性粒细胞减少。","C":"正确，可致欣快、失眠、激动，甚至诱发精神症状。","D":"正确，胃酸和胃蛋白酶分泌增加，易诱发或加重溃疡。","E":"错误，激素有弱盐皮质激素样作用，促进排钾保钠，血钾降低。"},"id":"ph32_q04","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":4}]},{"title":"第三十三章 甲状腺激素与抗甲状腺药","questions":[{"type":"A","stem":"丙硫氧嘧啶抗甲状腺作用的主要机制是","options":{"A":"抑制甲状腺过氧化物酶，阻止碘的活化和酪氨酸偶联","B":"破坏甲状腺滤泡细胞","C":"抑制促甲状腺激素分泌","D":"抑制肠道对碘的吸收","E":"拮抗甲状腺激素受体"},"answer":["A"],"rationale":"丙硫氧嘧啶抑制甲状腺过氧化物酶，阻止碘离子活化和碘化酪氨酸的偶联，减少甲状腺激素合成，故答案为 A。","expl":{"A":"正确，抑制过氧化物酶使甲状腺激素合成减少，起效较慢，需数周才显效。","B":"错误，破坏甲状腺滤泡细胞是放射性碘的作用。","C":"错误，它不直接作用于垂体抑制促甲状腺激素分泌。","D":"错误，药物不抑制碘的吸收，而是干扰碘的活化与酪氨酸偶联。","E":"错误，其作用在于减少激素合成，并不拮抗甲状腺激素受体。"},"id":"ph33_q01","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":1},{"type":"A","stem":"甲状腺危象时，除大剂量碘剂外，宜首选","options":{"A":"甲巯咪唑","B":"放射性131I","C":"丙硫氧嘧啶","D":"左甲状腺素","E":"卡比马唑"},"answer":["C"],"rationale":"甲状腺危象时首选丙硫氧嘧啶，因其除抑制激素合成外，还能抑制外周T4向T3转化，可较快降低血中T3水平，答案为 C。","expl":{"A":"错误，甲巯咪唑不能抑制外周T4向T3转化，危象时不作首选。","B":"错误，放射性碘起效慢，甲状腺危象时禁用。","C":"正确，抑制合成并阻止T4转化为活性更强的T3，是危象治疗的首选。","D":"错误，左甲状腺素是甲状腺激素替代药，用于甲状腺功能减退。","E":"错误，卡比马唑需在体内转化为甲巯咪唑，起效慢且不能抑制T4转化。"},"id":"ph33_q02","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":2},{"type":"A","stem":"硫脲类抗甲状腺药最严重的不良反应是","options":{"A":"皮疹","B":"粒细胞缺乏症","C":"轻度肝功能异常","D":"关节痛","E":"甲状腺功能减退"},"answer":["B"],"rationale":"硫脲类最严重的不良反应是粒细胞缺乏症，多发生于用药最初数月内且起病急骤，故用药期间须监测血象，一旦出现咽痛、发热应立即停药并查血，答案为 B。","expl":{"A":"错误，皮疹较常见，停药或抗过敏处理多可缓解，并非最严重者。","B":"正确，粒细胞缺乏可继发严重感染，是硫脲类用药监测的重点。","C":"错误，肝损害确可发生，但其发生率和凶险程度不及粒细胞缺乏。","D":"错误，关节痛少见且轻微，不构成严重后果。","E":"错误，甲状腺功能减退是剂量过大所致的预期药理效应，减量即可纠正。"},"id":"ph33_q03","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":3},{"type":"X","stem":"关于碘及碘化物用于甲状腺功能亢进治疗的叙述，正确的有","options":{"A":"小剂量碘是甲状腺激素合成的原料","B":"大剂量碘抑制甲状腺激素的释放和合成，即Wolff-Chaikoff效应","C":"大剂量碘起效快而短暂，可用于甲状腺危象和术前准备","D":"长期应用可发生碘逃逸，使甲亢复发或加重","E":"可单独用于甲状腺功能亢进的长期内科治疗"},"answer":["A","B","C","D"],"rationale":"碘的作用随剂量而变：小剂量作为合成原料，大剂量产生Wolff-Chaikoff效应而抑制激素释放与合成，起效快但短暂，长期应用出现碘逃逸使甲亢复发，因此只用于甲状腺危象和术前准备，不能单独长期治疗甲亢，故 A、B、C、D 正确。","expl":{"A":"正确，碘是合成甲状腺激素的必需原料，缺碘可致单纯性甲状腺肿。","B":"正确，该效应是碘剂用于危象和术前准备的药理依据。","C":"正确，其起效迅速但维持短暂，须与硫脲类等联合应用。","D":"正确，碘逃逸使抑制作用消失，故碘剂不宜长期单独使用。","E":"错误，碘剂不能单独用于甲亢的长期内科治疗，长期应用反而使病情反复。"},"id":"ph33_q04","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":4}]},{"title":"第三十四章 胰岛素与口服降糖药","questions":[{"type":"A","stem":"胰岛素最主要的不良反应是","options":{"A":"过敏反应","B":"注射部位脂肪萎缩","C":"胰岛素抵抗","D":"高钾血症","E":"低血糖反应"},"answer":["E"],"rationale":"胰岛素过量或用药后未及时进食可引起低血糖反应，严重者出现低血糖昏迷甚至死亡，是最主要和最常见的不良反应，答案为 E。","expl":{"A":"错误，随制剂纯度提高，过敏反应已明显减少，并非最主要的不良反应。","B":"错误，注射部位脂肪萎缩属局部反应，轮换注射部位可避免。","C":"错误，胰岛素抵抗见于长期大剂量应用者，发生率较低。","D":"错误，胰岛素促进钾进入细胞内，引起血钾降低而不是升高。","E":"正确，低血糖是最常见也最危险的不良反应，用药须个体化并监测血糖。"},"id":"ph34_q01","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":1},{"type":"A","stem":"二甲双胍降血糖的主要机制是","options":{"A":"刺激胰岛β细胞释放胰岛素","B":"抑制α-葡萄糖苷酶","C":"激动PPARγ","D":"减少肝糖输出、增加外周组织对葡萄糖的摄取和利用","E":"抑制肾小管SGLT2"},"answer":["D"],"rationale":"二甲双胍不刺激胰岛素分泌，主要通过减少肝糖异生和肝糖输出、增加外周组织对葡萄糖的摄取利用而降糖，答案为 D。","expl":{"A":"错误，刺激β细胞释放胰岛素是磺酰脲类和格列奈类的机制。","B":"错误，抑制α-葡萄糖苷酶的是阿卡波糖等药物。","C":"错误，激动PPARγ的是罗格列酮等噻唑烷二酮类。","D":"正确，减少肝糖输出并改善外周胰岛素敏感性，单用不引起低血糖。","E":"错误，抑制SGLT2的是达格列净等新型降糖药。"},"id":"ph34_q02","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":2},{"type":"A","stem":"磺酰脲类降糖药的主要作用机制是","options":{"A":"抑制肠道碳水化合物的吸收","B":"促进外周组织摄取葡萄糖而不依赖胰岛素","C":"刺激胰岛β细胞释放胰岛素","D":"抑制胰高血糖素样肽-1的降解","E":"增加尿糖排泄"},"answer":["C"],"rationale":"磺酰脲类阻断β细胞ATP敏感性钾通道，促使细胞去极化、钙内流而释放胰岛素，故仅对胰岛功能尚存者有效，答案为 C。","expl":{"A":"错误，抑制肠道碳水化合物吸收的是α-葡萄糖苷酶抑制剂。","B":"错误，不依赖胰岛素而促进外周摄取葡萄糖的是二甲双胍等药物。","C":"正确，通过关闭钾通道促胰岛素释放，因此对1型糖尿病无效。","D":"错误，抑制GLP-1降解的是西格列汀等DPP-4抑制剂。","E":"错误，增加尿糖排泄的是SGLT2抑制剂。"},"id":"ph34_q03","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":3},{"type":"A","stem":"糖尿病患者夜间反复出现低血糖、清晨血糖却明显升高，此时正确的处理是","options":{"A":"增加晚餐前胰岛素剂量","B":"适当减少夜间胰岛素用量","C":"加用磺酰脲类降糖药","D":"睡前追加中效胰岛素","E":"立即停用胰岛素改为二甲双胍单药治疗"},"answer":["B"],"rationale":"夜间低血糖后清晨反跳性高血糖称为苏木杰效应，源于夜间胰岛素过量，处理应减少夜间胰岛素用量并酌情睡前加餐；若夜间血糖不低而清晨升高则属黎明现象，需增加剂量，故答案为 B。","expl":{"A":"错误，增加晚餐前胰岛素会加重夜间低血糖，使清晨高血糖更明显。","B":"正确，减少夜间胰岛素用量可消除低血糖，清晨血糖随之回落。","C":"错误，加用促胰岛素分泌药会进一步增加夜间低血糖的风险。","D":"错误，睡前追加中效胰岛素会加重夜间低血糖，方向相反。","E":"错误，苏木杰效应只需调整胰岛素剂量，不必停用胰岛素。"},"id":"ph34_q04","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":4}]},{"title":"第三十五章 调节骨代谢与形成药","questions":[{"type":"A","stem":"阿仑膦酸钠抗骨质疏松的主要机制是","options":{"A":"促进成骨细胞活性","B":"抑制破骨细胞介导的骨吸收","C":"促进肠道钙吸收","D":"抑制甲状旁腺激素分泌","E":"激动雌激素受体"},"answer":["B"],"rationale":"阿仑膦酸钠属双膦酸盐，与骨基质羟磷灰石结合后被破骨细胞摄取，抑制破骨细胞介导的骨吸收，故答案为 B。","expl":{"A":"错误，双膦酸盐主要抑制骨吸收，对成骨细胞无直接促进作用。","B":"正确，抑制破骨细胞功能使骨转换降低、骨量增加，为一线抗骨质疏松药。","C":"错误，促进肠道钙吸收的是维生素D及其活性代谢物。","D":"错误，它不抑制甲状旁腺激素分泌，用药初期反而可致低钙血症。","E":"错误，激动雌激素受体的是雌激素替代治疗。"},"id":"ph35_q01","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":1},{"type":"A","stem":"阿仑膦酸钠的正确服用方法是","options":{"A":"空腹用足量白水送服，服药后至少三十分钟内保持直立且不进食","B":"餐后立即用牛奶送服，以减少胃肠刺激","C":"与钙剂、铁剂同时服用，以增强疗效","D":"睡前嚼碎后吞服，服药后即可平卧","E":"与抗酸药同服，以减轻食管刺激"},"answer":["A"],"rationale":"双膦酸盐对食管黏膜有较强刺激性，且与多价阳离子结合后吸收显著减少，故须空腹用足量白水送服，服药后至少三十分钟内保持直立、不进食，以避免发生食管炎与食管溃疡，故答案为 A。","expl":{"A":"正确，空腹、足量白水、服后保持直立三十分钟是这类药物的标准用法。","B":"错误，牛奶中的钙与药物螯合会减少吸收，餐后服用也降低生物利用度。","C":"错误，钙剂、铁剂与双膦酸盐同服显著减少吸收，须间隔至少两小时。","D":"错误，嚼碎会加重食管刺激，服药后平卧易使药物滞留食管而致溃疡。","E":"错误，抗酸药同样减少吸收，且并不能减轻药物对食管的刺激。"},"id":"ph35_q02","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":2},{"type":"A","stem":"雷洛昔芬用于绝经后骨质疏松的药理学基础是","options":{"A":"在骨组织激动雌激素受体，而在乳腺和子宫内膜拮抗雌激素受体","B":"直接抑制破骨细胞的增殖并诱导其凋亡","C":"促进成骨细胞增殖，刺激新骨形成","D":"抑制肾小管对钙的重吸收，降低血钙","E":"在骨组织拮抗雌激素受体，减少骨吸收"},"answer":["A"],"rationale":"雷洛昔芬是选择性雌激素受体调节剂，在骨与心血管系统表现雌激素样激动作用，增加骨密度、降低椎体骨折风险；在乳腺与子宫内膜则拮抗雌激素受体，不增加乳腺癌与子宫内膜癌风险，这种组织选择性是其用于绝经后骨质疏松的药理学基础，故答案为 A。","expl":{"A":"正确，这种组织选择性正是它与他莫昔芬及雌激素替代治疗的重要区别。","B":"错误，直接抑制破骨细胞功能与存活的是双膦酸盐，它经受体途径起效。","C":"错误，促进成骨细胞增殖、刺激骨形成的是特立帕肽和氟化物。","D":"错误，它不抑制肾小管钙重吸收，减少肾小管钙重吸收的是降钙素。","E":"错误，它在骨组织是激动而非拮抗雌激素受体。"},"id":"ph35_q03","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":3},{"type":"X","stem":"关于维生素D及其活性代谢物，下列叙述正确的有","options":{"A":"维生素D须先后经肝、肾两次羟化生成1,25-二羟维生素D3才有活性","B":"骨化三醇即1,25-二羟维生素D3，无须经肝肾活化即可直接发挥作用","C":"可促进肠道钙吸收、骨矿化及肾小管对钙的重吸收","D":"过量应用可致高钙血症、肾结石与软组织钙化","E":"属骨吸收抑制剂，可替代双膦酸盐用于严重骨质疏松的治疗"},"answer":["A","B","C","D"],"rationale":"维生素D须经肝25-羟化、肾1-羟化生成骨化三醇后才有活性，骨化三醇为活性最强的形式，可直接作用于肠、骨与肾，促进钙吸收与骨矿化；过量则引起高钙血症、肾结石与软组织钙化。维生素D属骨矿化剂而非骨吸收抑制剂，故E错误。","expl":{"A":"正确，严重肝肾功能不全者因羟化障碍应直接选用活性制剂。","B":"正确，骨化三醇无须肝肾活化，适用于肾性骨营养不良与甲状旁腺功能减退。","C":"正确，这是它纠正负钙平衡、促进骨矿化的主要机制。","D":"正确，维生素D并非越多越好，过量可致高钙血症与肾损害。","E":"错误，维生素D是骨矿化剂和基础用药，不能替代双膦酸盐。"},"id":"ph35_q04","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":4}]},{"title":"第三十六章 抗病原微生物药概论","questions":[{"type":"A","stem":"化疗指数是评价抗菌药物安全性的常用指标，它是指","options":{"A":"半数致死量与半数有效量的比值","B":"最低抑菌浓度与最低杀菌浓度的比值","C":"血药峰浓度与最低抑菌浓度的比值","D":"最低杀菌浓度与最低抑菌浓度的比值","E":"抗菌后效应持续时间与给药间隔的比值"},"answer":["A"],"rationale":"化疗指数即半数致死量（LD50）与半数有效量（ED50）之比，是评价抗菌药安全性的常用指标，数值越大表示相对越安全；但化疗指数大并不等于绝对安全，如青霉素化疗指数极大仍可致过敏性休克，故答案为 A。","expl":{"A":"正确，以动物半数致死量与半数有效量之比表示，比值越大相对越安全。","B":"错误，这是两个浓度指标的比较，与化疗指数的定义无关。","C":"错误，峰浓度与最低抑菌浓度的比值是评价浓度依赖性杀菌的药效学参数。","D":"错误，最低杀菌浓度与最低抑菌浓度之比反映药物杀菌能力的强弱。","E":"错误，抗菌后效应与给药间隔的关系用于指导给药方案的设计。"},"id":"ph36_q01","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":1},{"type":"A","stem":"细菌对抗菌药产生获得性耐药的机制不包括","options":{"A":"产生灭活酶使药物失活","B":"改变靶位结构，降低药物与靶点的亲和力","C":"降低细胞膜通透性，减少药物进入菌体","D":"增强主动外排泵，将药物排出菌体","E":"增加药物转运载体，促进药物在菌体内蓄积"},"answer":["E"],"rationale":"细菌耐药的主要途径为产生灭活酶、改变靶位结构、降低胞膜通透性、增强外排泵以及改变代谢途径，其共同结果是菌体内有效药物浓度降低或药物与靶点结合减弱；“增加药物摄取并在菌体内蓄积”会提高敏感性，不属于耐药机制，故答案为 E。","expl":{"A":"正确，如产生β-内酰胺酶水解青霉素类、产生钝化酶灭活氨基糖苷类。","B":"正确，如改变青霉素结合蛋白或核糖体靶位而致耐药。","C":"正确，如革兰阴性菌外膜孔蛋白减少使药物难以进入菌体。","D":"正确，如主动外排泵可将四环素类、喹诺酮类排出菌体。","E":"错误，增强药物摄取与蓄积会提高敏感性，与耐药方向相反。"},"id":"ph36_q02","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":2},{"type":"A","stem":"下列抗菌药物中，通过影响细菌胞浆膜通透性发挥抗菌作用的是","options":{"A":"多黏菌素B","B":"万古霉素","C":"利福平","D":"磺胺甲噁唑","E":"四环素"},"answer":["A"],"rationale":"多黏菌素B与革兰阴性菌外膜脂多糖结合，使胞浆膜通透性增加、菌体内重要物质外漏而杀菌，属影响胞浆膜通透性这一类；万古霉素抑制细胞壁合成，利福平抑制核酸代谢，磺胺甲噁唑抑制叶酸代谢，四环素抑制蛋白质合成，故答案为 A。","expl":{"A":"正确，同属此类的还有两性霉素B，该机制药物多毒性较大。","B":"错误，万古霉素与细胞壁前体结合，抑制肽聚糖合成。","C":"错误，利福平抑制依赖DNA的RNA聚合酶，属抑制核酸代谢。","D":"错误，磺胺甲噁唑竞争性抑制二氢蝶酸合酶，属抑制叶酸代谢。","E":"错误，四环素与核糖体30S亚基结合，抑制蛋白质合成。"},"id":"ph36_q03","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":3},{"type":"X","stem":"关于抗菌药物的联合应用，下列叙述正确的有","options":{"A":"联合用药可产生协同、相加、无关和拮抗四种效果","B":"病原未明的严重感染是联合用药的明确指征","C":"繁殖期杀菌药与快速抑菌药合用可能出现拮抗","D":"长期单一用药易产生耐药者可考虑联合用药","E":"为避免耐药，所有细菌感染均应常规采用联合用药"},"answer":["A","B","C","D"],"rationale":"联合用药的目的是提高疗效、减少耐药与降低毒性，其结果可为协同、相加、无关或拮抗四种；指征包括病原未明的严重感染、单一药物不能控制的混合感染、易产生耐药的长期治疗以及需协同增效者；繁殖期杀菌药与快速抑菌药合用，可因抑菌药抑制细菌繁殖而削弱杀菌药作用，出现拮抗。无指征的普遍联合反而增加耐药与不良反应，故E错误。","expl":{"A":"正确，四种效果中以协同与相加为临床所求，拮抗应尽量避免。","B":"正确，此类患者应在采集标本后立即开始经验性联合治疗。","C":"正确，如青霉素类与四环素类合用是经典的拮抗例子。","D":"正确，如结核病与深部真菌感染的长期治疗均需联合用药。","E":"错误，无指征联合用药会增加不良反应、二重感染与耐药机会。"},"id":"ph36_q04","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":4}]},{"title":"第三十七章 人工合成抗菌药","questions":[{"type":"A","stem":"喹诺酮类药物的抗菌作用靶点是","options":{"A":"细菌细胞壁黏肽","B":"细菌核糖体50S亚基","C":"二氢蝶酸合酶","D":"DNA回旋酶和拓扑异构酶Ⅳ","E":"细菌细胞膜"},"answer":["D"],"rationale":"喹诺酮类抑制细菌DNA回旋酶和拓扑异构酶Ⅳ，阻碍DNA复制而杀菌，故答案为 D。","expl":{"A":"错误，作用于细胞壁的是β-内酰胺类和糖肽类。","B":"错误，作用于50S亚基的是大环内酯类和氯霉素。","C":"错误，作用于二氢蝶酸合酶的是磺胺类。","D":"正确，双重靶点使其抗菌谱广、不易产生耐药。","E":"错误，作用于细胞膜的是多黏菌素。"},"id":"ph37_q01","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":1},{"type":"A","stem":"磺胺类药物的抗菌作用机制是","options":{"A":"抑制二氢叶酸还原酶","B":"与对氨基苯甲酸竞争二氢蝶酸合酶，阻止二氢叶酸合成","C":"抑制DNA回旋酶","D":"抑制细菌细胞壁合成","E":"抑制细菌蛋白质合成"},"answer":["B"],"rationale":"磺胺类与对氨基苯甲酸竞争二氢蝶酸合酶，使细菌不能合成二氢叶酸，从而抑制核酸和蛋白质合成，故答案为 B。","expl":{"A":"错误，抑制二氢叶酸还原酶的是甲氧苄啶，与磺胺作用于前后两个环节。","B":"正确，竞争性抑制二氢蝶酸合酶，故脓液和普鲁卡因可减弱其疗效。","C":"错误，抑制DNA回旋酶的是喹诺酮类。","D":"错误，抑制细胞壁合成的是β-内酰胺类。","E":"错误，抑制蛋白质合成的是氨基糖苷类、大环内酯类等。"},"id":"ph37_q02","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":2},{"type":"A","stem":"氟喹诺酮类不宜用于十八岁以下患者，其主要原因是","options":{"A":"可致幼年动物关节软骨损害","B":"可引起不可逆的耳聋","C":"可致骨髓抑制与再生障碍性贫血","D":"可致灰婴综合征","E":"可致牙齿黄染与骨骼发育障碍"},"answer":["A"],"rationale":"氟喹诺酮类在幼年动物中可引起关节软骨损伤，并可能累及肌腱，故十八岁以下、孕妇及哺乳期妇女禁用；不可逆耳聋属氨基糖苷类，骨髓抑制属氯霉素类，牙齿黄染属四环素类，故答案为 A。","expl":{"A":"正确，软骨与肌腱损害是本类特有的安全性问题，用药期间出现肌腱疼痛应停药。","B":"错误，不可逆耳聋是氨基糖苷类的典型毒性。","C":"错误，骨髓抑制与再生障碍性贫血主要见于氯霉素。","D":"错误，灰婴综合征见于新生儿应用大剂量氯霉素。","E":"错误，牙齿黄染与骨骼发育障碍是四环素类的典型表现。"},"id":"ph37_q03","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":3},{"type":"A","stem":"甲氧苄啶与磺胺甲噁唑合用可显著增强抗菌作用的药理学依据是","options":{"A":"二者分别抑制二氢蝶酸合酶与二氢叶酸还原酶，双重阻断叶酸合成","B":"二者竞争同一靶点，从而延缓细菌产生耐药","C":"甲氧苄啶抑制肝药酶，使磺胺甲噁唑代谢减慢","D":"甲氧苄啶促进磺胺甲噁唑吸收并提高其血药浓度","E":"二者分别抑制细胞壁合成与蛋白质合成，作用于不同环节"},"answer":["A"],"rationale":"磺胺甲噁唑竞争性抑制二氢蝶酸合酶，甲氧苄啶抑制二氢叶酸还原酶，二者作用于细菌叶酸合成的两个连续环节，形成双重阻断，使抗菌作用增强数十倍，这也是复方制剂按五比一配比的依据，故答案为 A。","expl":{"A":"正确，双重阻断叶酸代谢是抗菌增效剂与磺胺类合用的经典范例。","B":"错误，二者靶点不同，并非竞争同一靶点的同类药物。","C":"错误，其增效来自对细菌叶酸代谢的协同阻断，与抑制肝药酶无关。","D":"错误，增效源于靶点协同，而不是改变吸收与血药浓度。","E":"错误，二者都作用于叶酸合成，不涉及细胞壁与蛋白质合成。"},"id":"ph37_q04","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":4}]},{"title":"第三十八章 β-内酰胺类抗生素","questions":[{"type":"A","stem":"青霉素G的抗菌作用机制是","options":{"A":"抑制细菌细胞壁黏肽合成","B":"抑制细菌蛋白质合成","C":"抑制细菌DNA回旋酶","D":"抑制二氢叶酸合成酶","E":"破坏细菌细胞膜通透性"},"answer":["A"],"rationale":"青霉素G与青霉素结合蛋白结合，抑制转肽酶活性，阻碍细胞壁黏肽交联，使细菌细胞壁缺损而死亡，故答案为 A。","expl":{"A":"正确，阻碍黏肽交联使细胞壁缺损，对繁殖期细菌杀菌作用强。","B":"错误，抑制蛋白质合成的是氨基糖苷类、大环内酯类和四环素类。","C":"错误，抑制DNA回旋酶的是喹诺酮类。","D":"错误，抑制二氢叶酸合成的是磺胺类。","E":"错误，破坏细胞膜通透性的是多黏菌素等药物。"},"id":"ph38_q01","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":1},{"type":"A","stem":"青霉素G最严重的不良反应是","options":{"A":"耳毒性","B":"肝损害","C":"过敏性休克","D":"骨髓抑制","E":"灰婴综合征"},"answer":["C"],"rationale":"青霉素G可致过敏性休克，多在注射后数分钟内发生，是本品最严重的不良反应，用药前必须做皮肤过敏试验，故答案为 C。","expl":{"A":"错误，耳毒性是氨基糖苷类抗生素的典型不良反应。","B":"错误，青霉素主要经肾排泄，肝损害不是其主要不良反应。","C":"正确，过敏性休克可致死，须询问过敏史、做皮试并备好抢救药品。","D":"错误，骨髓抑制多见于氯霉素等药物。","E":"错误，灰婴综合征见于新生儿应用大剂量氯霉素。"},"id":"ph38_q02","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":2},{"type":"A","stem":"关于头孢菌素类抗生素随代次升级的变化规律，下列叙述正确的是","options":{"A":"对革兰阴性菌作用增强，对β-内酰胺酶稳定性提高，肾毒性降低","B":"对革兰阳性菌作用增强，对革兰阴性菌作用减弱，肾毒性增加","C":"抗菌谱逐代变窄，对铜绿假单胞菌作用逐代减弱","D":"对β-内酰胺酶稳定性逐代下降，故耐药率逐代升高","E":"肾毒性逐代增强，以第三代头孢菌素最为明显"},"answer":["A"],"rationale":"头孢菌素类随代次升级，对革兰阴性菌的抗菌作用增强、对β-内酰胺酶的稳定性提高、肾毒性降低，而对革兰阳性菌的作用相对减弱；第三代头孢菌素对革兰阴性菌及铜绿假单胞菌作用强、易透过血脑屏障且基本无肾毒性，故答案为 A。","expl":{"A":"正确，这一规律是掌握四代头孢菌素抗菌特点与不良反应的主线。","B":"错误，革兰阳性菌作用相对减弱、肾毒性降低才是升级方向。","C":"错误，抗菌谱逐代扩展，第三代中部分品种对铜绿假单胞菌有效。","D":"错误，对β-内酰胺酶的稳定性逐代提高，第四代最为稳定。","E":"错误，第一代肾毒性相对明显，第三代基本无肾毒性。"},"id":"ph38_q03","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":3},{"type":"A","stem":"关于β-内酰胺酶抑制剂，下列叙述正确的是","options":{"A":"本身抗菌活性弱，能抑制β-内酰胺酶而保护配伍的β-内酰胺类","B":"本身抗菌作用强，可单独用于严重革兰阴性杆菌感染","C":"通过抑制细菌细胞壁合成而直接杀灭产酶菌","D":"属于氨基糖苷钝化酶抑制剂，可保护氨基糖苷类","E":"与青霉素类合用会加速青霉素被酶水解"},"answer":["A"],"rationale":"克拉维酸、舒巴坦、他唑巴坦等本身抗菌活性弱，但能与β-内酰胺酶结合使其失活，从而保护配伍的青霉素类或头孢菌素类不被水解，扩大抗菌谱并克服产酶耐药，故常与阿莫西林、哌拉西林等组成复方制剂，答案为 A。","expl":{"A":"正确，抑酶谱的差异决定其与不同β-内酰胺类配伍的适用范围。","B":"错误，其抗菌活性弱，不能单独用于治疗严重感染。","C":"错误，它抑制的是细菌产生的β-内酰胺酶，并不直接作用于细胞壁合成。","D":"错误，它抑制β-内酰胺酶，对氨基糖苷钝化酶无效。","E":"错误，合用是保护青霉素类免受水解，而非加速其水解。"},"id":"ph38_q04","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":4}]},{"title":"第三十九章 大环内酯类与林可霉素类抗生素","questions":[{"type":"A","stem":"大环内酯类抗生素的抗菌作用机制是","options":{"A":"与细菌核糖体30S亚基结合，抑制蛋白质合成","B":"抑制细菌细胞壁合成","C":"抑制细菌DNA合成","D":"抑制细菌叶酸代谢","E":"与细菌核糖体50S亚基结合，抑制蛋白质合成"},"answer":["E"],"rationale":"大环内酯类与细菌核糖体50S亚基结合，抑制转肽酶和移位酶，阻断蛋白质合成，故答案为 E。","expl":{"A":"错误，结合30S亚基的是氨基糖苷类和四环素类。","B":"错误，抑制细胞壁合成的是β-内酰胺类。","C":"错误，抑制DNA合成的是喹诺酮类等。","D":"错误，抑制叶酸代谢的是磺胺类和甲氧苄啶。","E":"正确，结合50S亚基抑制蛋白质合成，与林可霉素、氯霉素作用位点相近。"},"id":"ph39_q01","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":1},{"type":"A","stem":"与红霉素相比，阿奇霉素的主要药理学特点是","options":{"A":"半衰期长、组织与细胞内浓度高，可每日一次短程给药","B":"对革兰阳性球菌作用明显强于红霉素，属窄谱杀菌药","C":"主要经肾排泄，尿中浓度高，适用于泌尿系感染","D":"是强效肝药酶抑制剂，与多种药物易发生相互作用","E":"口服后被胃酸迅速破坏，必须静脉给药"},"answer":["A"],"rationale":"阿奇霉素为十五元环氮杂内酯类，半衰期长达数十小时，组织与细胞内浓度高且释放缓慢，故每日一次、短程给药即可维持有效浓度；它几乎不抑制肝药酶，是大环内酯类中药物相互作用风险最低的品种，故答案为 A。","expl":{"A":"正确，半衰期长与组织浓度高是其采用三日短程方案的基础。","B":"错误，其对革兰阳性球菌的作用并不强于红霉素，也不属窄谱杀菌药。","C":"错误，本类主要经胆汁排泄并有肝肠循环，尿中浓度不高。","D":"错误，强效抑制肝药酶的是红霉素、克拉霉素等十四元环品种。","E":"错误，阿奇霉素口服吸收好且耐酸，可供口服给药。"},"id":"ph39_q02","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":2},{"type":"A","stem":"克林霉素用于金黄色葡萄球菌所致骨髓炎的药理学依据是","options":{"A":"在骨组织与关节液中浓度高，且对金葡菌包括产酶株有效","B":"可透过血脑屏障，脑脊液中浓度高","C":"对革兰阴性需氧杆菌有强大杀菌作用","D":"能直接中和金葡菌产生的溶血素","E":"可促进成骨细胞增殖，加速死骨修复"},"answer":["A"],"rationale":"克林霉素的抗菌活性比林可霉素强，对金黄色葡萄球菌（包括产酶株）、链球菌及厌氧菌有效，且在骨组织与关节液中浓度高，故为金葡菌所致急慢性骨髓炎和化脓性关节炎的常用药物，答案为 A。","expl":{"A":"正确，骨组织高浓度与对产酶金葡菌有效是其治疗骨髓炎的基础。","B":"错误，林可霉素类不易透过血脑屏障，故不用于脑膜炎。","C":"错误，本类对革兰阴性需氧杆菌无效，仅覆盖阳性菌与厌氧菌。","D":"错误，其作用为抑制细菌蛋白质合成，并不中和毒素。","E":"错误，它没有促进骨形成的作用，骨修复依靠去除死骨与自身修复。"},"id":"ph39_q03","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":3},{"type":"X","stem":"关于大环内酯类抗生素，下列叙述正确的有","options":{"A":"胃肠道反应是最常见的不良反应，与激动促胃动素受体有关","B":"红霉素、克拉霉素抑制CYP3A4，可升高合用他汀类的血药浓度","C":"与氯霉素、林可霉素类合用可因竞争50S亚基结合位点而相互拮抗","D":"大剂量或长疗程可致耳鸣与听力下降，停药后多可恢复","E":"对支原体、衣原体、军团菌等无细胞壁的病原体无效"},"answer":["A","B","C","D"],"rationale":"大环内酯类最常见的不良反应是胃肠道反应，与激动胃肠道促胃动素受体、促进胃肠蠕动有关；红霉素与克拉霉素为强CYP3A4抑制剂，可使他汀类等合用药物浓度升高甚至引起横纹肌溶解；本类与氯霉素、林可霉素类结合50S亚基的位点相近，合用会竞争靶位而拮抗；大剂量可致可逆性耳毒性。本类对支原体、衣原体、军团菌等非典型病原体作用突出，故E错误。","expl":{"A":"正确，该反应多为剂量相关，餐后服用或减量可减轻。","B":"正确，故应避免与辛伐他汀、特非那定、麦角胺等合用。","C":"正确，结合位点相近的药物不宜联合应用。","D":"正确，其耳毒性多为双侧感音性耳聋，与氨基糖苷类的不可逆损害不同。","E":"错误，此类无细胞壁的非典型病原体恰是大环内酯类的主要适应证。"},"id":"ph39_q04","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":4}]},{"title":"第四十章 氨基糖苷类与多肽类抗生素","questions":[{"type":"A","stem":"氨基糖苷类抗生素的主要抗菌机制是","options":{"A":"抑制细菌细胞壁合成","B":"与细菌核糖体30S亚基结合，抑制蛋白质合成","C":"抑制DNA拓扑异构酶","D":"抑制二氢叶酸还原酶","E":"抑制RNA聚合酶"},"answer":["B"],"rationale":"氨基糖苷类与细菌核糖体30S亚基结合，抑制蛋白质合成的起始、延长和终止阶段，属静止期杀菌药，故答案为 B。","expl":{"A":"错误，抑制细胞壁合成的是β-内酰胺类和万古霉素。","B":"正确，结合30S亚基使蛋白质合成受阻，且具有抗生素后效应。","C":"错误，抑制拓扑异构酶的是喹诺酮类。","D":"错误，抑制二氢叶酸还原酶的是甲氧苄啶。","E":"错误，抑制RNA聚合酶的是利福平。"},"id":"ph40_q01","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":1},{"type":"A","stem":"氨基糖苷类抗生素最主要的不良反应是","options":{"A":"肝毒性和骨髓抑制","B":"胃肠反应","C":"过敏反应","D":"耳毒性和肾毒性","E":"二重感染"},"answer":["D"],"rationale":"氨基糖苷类在内耳和肾近曲小管蓄积，引起前庭及耳蜗损害和肾毒性，是最主要的不良反应，故答案为 D。","expl":{"A":"错误，肝毒性和骨髓抑制多见于抗结核药和氯霉素，不是氨基糖苷类的主要毒性。","B":"错误，胃肠反应可有，但远不如耳毒性和肾毒性重要。","C":"错误，过敏反应可发生，但发生率远低于耳、肾毒性。","D":"正确，还可引起神经肌肉阻滞，与剂量和用药时间相关。","E":"错误，二重感染多见于长期应用广谱抗生素如四环素类者。"},"id":"ph40_q02","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":2},{"type":"X","stem":"关于氨基糖苷类抗生素，下列叙述正确的有","options":{"A":"口服吸收差，主要经肾排泄","B":"具有较长的抗生素后效应","C":"可引起耳毒性和肾毒性","D":"可阻断神经肌肉传递","E":"对厌氧菌具有强大抗菌作用"},"answer":["A","B","C","D"],"rationale":"氨基糖苷类口服吸收差、主要经肾排泄，具有明显的抗生素后效应，可致耳毒性、肾毒性和神经肌肉阻滞；因其需氧转运进入菌体，对厌氧菌无效，故E错误。","expl":{"A":"正确，口服难吸收，须注射给药，主要以原形经肾小球滤过排出。","B":"正确，抗生素后效应明显，是支持每日一次给药的依据之一。","C":"正确，耳毒性和肾毒性是最主要的不良反应，与剂量和疗程相关。","D":"正确，可阻滞神经肌肉接头，静脉注射过快或合用肌松药时尤易发生。","E":"错误，其转运需依赖氧，故对厌氧菌无抗菌活性。"},"id":"ph40_q03","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":3},{"type":"A","stem":"万古霉素的抗菌作用机制是","options":{"A":"与细胞壁前体D-丙氨酰-D-丙氨酸结合，阻止肽聚糖延伸","B":"与核糖体30S亚基结合，抑制蛋白质合成","C":"抑制细菌DNA回旋酶，阻断DNA复制","D":"与细胞膜脂多糖结合，增加胞浆膜通透性","E":"抑制二氢叶酸还原酶，阻断叶酸合成"},"answer":["A"],"rationale":"万古霉素属糖肽类，与细胞壁肽聚糖前体末端的D-丙氨酰-D-丙氨酸结合，阻止转糖基与转肽反应，使肽聚糖不能延伸，对生长繁殖期细菌发挥杀菌作用，故答案为 A。","expl":{"A":"正确，其靶点与β-内酰胺类不同，故对耐甲氧西林金葡菌仍然有效。","B":"错误，与30S亚基结合的是氨基糖苷类与四环素类。","C":"错误，抑制DNA回旋酶的是喹诺酮类。","D":"错误，与脂多糖结合、增加胞浆膜通透性的是多黏菌素类。","E":"错误，抑制二氢叶酸还原酶的是甲氧苄啶。"},"id":"ph40_q04","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":4}]},{"title":"第四十一章 四环素类与氯霉素类抗生素","questions":[{"type":"A","stem":"四环素类抗生素抗菌的主要作用机制是","options":{"A":"与细菌核糖体30S亚基A位结合，阻止氨基酰tRNA进入A位","B":"与核糖体50S亚基肽酰转移酶结合，抑制肽键形成","C":"抑制细菌细胞壁肽聚糖的转肽反应","D":"抑制细菌DNA回旋酶，阻断DNA复制","E":"抑制细菌二氢叶酸还原酶，阻碍叶酸合成"},"answer":["A"],"rationale":"四环素类与细菌核糖体30S亚基的A位结合，阻止氨基酰tRNA进入A位，从而抑制肽链延长和蛋白质合成，属快速抑菌药，故答案为 A。","expl":{"A":"正确，作用环节在30S亚基A位，与氨基糖苷类结合30S亚基的部位不同。","B":"错误，与50S亚基肽酰转移酶结合的是氯霉素、大环内酯类和林可霉素类。","C":"错误，抑制肽聚糖转肽反应的是β-内酰胺类，如青霉素和头孢菌素。","D":"错误，抑制DNA回旋酶的是氟喹诺酮类。","E":"错误，抑制二氢叶酸还原酶的是甲氧苄啶和乙胺嘧啶。"},"id":"ph41_q01","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":1},{"type":"A","stem":"关于多西环素药理特点的叙述，正确的是","options":{"A":"脂溶性高，口服吸收好且不受食物影响，半衰期较长","B":"抗菌作用在四环素类中最弱，故仅用于肠道感染","C":"口服后几乎不吸收，临床必须静脉给药","D":"较易引起眩晕和共济失调等前庭反应","E":"与钙剂同服可络合而增强其抗菌活性"},"answer":["A"],"rationale":"多西环素为半合成四环素类，脂溶性高、口服吸收完全且不受食物影响，半衰期长可每日给药一至两次，抗菌作用强，是四环素类中的首选品种，故答案为 A。","expl":{"A":"正确，半合成品脂溶性高、吸收好、半衰期长，多西环素为四环素类首选药。","B":"错误，抗菌作用最弱的是土霉素，多西环素作用强。","C":"错误，多西环素口服吸收好，是可供口服的品种。","D":"错误，前庭反应主要见于米诺环素，多西环素以光敏反应较突出。","E":"错误，与钙、镁、铝、铁等金属离子络合会减少吸收，应间隔服用。"},"id":"ph41_q02","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":2},{"type":"A","stem":"关于氯霉素所致骨髓抑制的叙述，正确的是","options":{"A":"再生障碍性贫血与剂量和疗程无关，发生率低但病死率高","B":"可逆性骨髓抑制与剂量无关，停药后多不能恢复","C":"再生障碍性贫血多在用药后立即发生，与疗程长短密切相关","D":"两型骨髓抑制均与剂量呈明显的正相关","E":"骨髓抑制仅见于静脉给药，口服给药不会发生"},"answer":["A"],"rationale":"氯霉素的骨髓毒性分两型：与剂量和疗程相关的可逆性骨髓抑制，以及发生率低、与剂量无关、不可逆的再生障碍性贫血，后者病死率高，故答案为 A。","expl":{"A":"正确，再生障碍性贫血与剂量无关，多在停药后数周出现，病死率高。","B":"错误，可逆性骨髓抑制与剂量和疗程相关，停药后可以恢复。","C":"错误，再生障碍性贫血并非即刻发生，且与剂量疗程无关。","D":"错误，只有可逆性骨髓抑制与剂量相关，两型不能混为一谈。","E":"错误，口服吸收完全，口服给药同样可致骨髓抑制。"},"id":"ph41_q03","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":3},{"type":"X","stem":"关于四环素类药物不良反应及用药注意的叙述，正确的有","options":{"A":"可沉积于牙齿和骨骼，致牙齿黄染与骨生长抑制，8岁以下儿童禁用","B":"长期或大剂量静脉给药可致肝脂肪变性、转氨酶升高和黄疸","C":"米诺环素较易引起眩晕、共济失调等可逆性前庭反应","D":"多西环素等可致光敏反应，用药期间应避免日晒","E":"孕妇及8岁以下儿童可常规使用，因本类药物对胎儿和牙齿无明显影响"},"answer":["A","B","C","D"],"rationale":"四环素类可与钙络合沉积于牙齿和骨骼、大剂量静脉给药可致肝损害、米诺环素易致前庭反应、多西环素等可致光敏反应；孕妇与8岁以下儿童禁用是刚性禁忌，故E错误。","expl":{"A":"正确，与钙络合致牙齿黄染、釉质发育不全和骨生长抑制，孕妇与8岁以下儿童禁用。","B":"正确，肝损害多见于大剂量静脉给药、孕妇或原有肝病者。","C":"正确，前庭反应为米诺环素特有，多在用药后数日出现，停药可恢复。","D":"正确，多西环素和地美环素光敏反应较突出，用药期间应避免曝晒。","E":"错误，该类药可致牙齿黄染和骨生长抑制，孕妇与8岁以下儿童禁用。"},"id":"ph41_q04","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":4}]},{"title":"第四十二章 抗病毒药与抗真菌药","questions":[{"type":"A","stem":"阿昔洛韦抗病毒的作用机制是","options":{"A":"经病毒胸苷激酶磷酸化后抑制病毒DNA聚合酶","B":"抑制病毒逆转录酶","C":"抑制神经氨酸酶","D":"抑制病毒蛋白酶","E":"阻断病毒吸附于宿主细胞"},"answer":["A"],"rationale":"阿昔洛韦在感染细胞内经病毒胸苷激酶转化为三磷酸型，竞争性抑制病毒DNA聚合酶并终止DNA链延长，故答案为 A。","expl":{"A":"正确，对疱疹病毒选择性高，因正常细胞胸苷激酶对其磷酸化效率低。","B":"错误，抑制逆转录酶的是齐多夫定等抗HIV药物。","C":"错误，抑制神经氨酸酶的是奥司他韦、扎那米韦。","D":"错误，抑制病毒蛋白酶的是沙奎那韦等抗HIV药。","E":"错误，阻断病毒吸附融合的是恩夫韦肽。"},"id":"ph42_q01","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":1},{"type":"A","stem":"奥司他韦抗流感病毒的作用机制是","options":{"A":"抑制病毒神经氨酸酶，阻止病毒从感染细胞释放和扩散","B":"阻断甲型流感病毒M2离子通道，抑制病毒脱壳","C":"经病毒胸苷激酶活化后抑制病毒DNA聚合酶","D":"竞争性抑制病毒逆转录酶，终止DNA链合成","E":"抑制病毒蛋白酶，使前体蛋白不能裂解成熟"},"answer":["A"],"rationale":"奥司他韦为神经氨酸酶抑制剂，阻断流感病毒从感染细胞释放和扩散，对甲型与乙型流感均有效，应于症状出现48小时内开始用药，故答案为 A。","expl":{"A":"正确，抑制神经氨酸酶可阻止新形成的病毒颗粒释放，减少病毒扩散。","B":"错误，阻断M2离子通道、抑制脱壳的是金刚烷胺，仅对甲型流感有效。","C":"错误，经病毒胸苷激酶活化后抑制DNA聚合酶的是阿昔洛韦。","D":"错误，抑制逆转录酶的是齐多夫定等核苷类逆转录酶抑制剂。","E":"错误，抑制病毒蛋白酶的是利托那韦、洛匹那韦等抗HIV药物。"},"id":"ph42_q02","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":2},{"type":"A","stem":"关于两性霉素B的叙述，正确的是","options":{"A":"与真菌细胞膜麦角固醇结合形成孔道，使胞内重要物质外漏","B":"口服吸收完全，临床主要经口服治疗深部真菌感染","C":"剂量限制性毒性为骨髓抑制，表现为白细胞和血小板减少","D":"对细菌、病毒和真菌均有强大杀灭作用，属广谱抗微生物药","E":"用药期间血钾和肾功能稳定，无须监测"},"answer":["A"],"rationale":"两性霉素B属多烯类，与真菌细胞膜上的麦角固醇结合形成孔道，使胞内钾离子和小分子物质外漏而杀菌，是治疗重症深部真菌病的经典药物，故答案为 A。","expl":{"A":"正确，以麦角固醇为靶点形成膜孔道，对深部真菌作用强。","B":"错误，口服吸收少且刺激性强，须避光缓慢静脉滴注。","C":"错误，其剂量限制性毒性为肾损害，可致低钾、低镁和肾小管酸中毒。","D":"错误，两性霉素B仅抗真菌，对细菌和病毒无效。","E":"错误，用药期间必须监测血钾、血镁和肾功能。"},"id":"ph42_q03","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":3},{"type":"X","stem":"关于抗真菌药物作用机制与临床应用的叙述，正确的有","options":{"A":"唑类抑制真菌14α-去甲基化酶，减少细胞膜麦角固醇合成","B":"氟康唑脑脊液浓度高，是隐球菌脑膜炎的常用药物","C":"卡泊芬净抑制真菌细胞壁β-1,3-葡聚糖合成酶，对隐球菌无效","D":"氟胞嘧啶单用不易产生耐药，可作为隐球菌脑膜炎的首选单药","E":"灰黄霉素对念珠菌和深部真菌作用强大，是治疗隐球菌脑膜炎的首选药"},"answer":["A","B","C"],"rationale":"唑类抑制14α-去甲基化酶减少麦角固醇合成，氟康唑脑脊液穿透好用于隐球菌脑膜炎，卡泊芬净作用于细胞壁而对隐球菌无效；氟胞嘧啶单用极易耐药，灰黄霉素仅对皮肤癣菌有效，故D、E错误。","expl":{"A":"正确，咪唑类与三唑类均抑制该酶，使膜通透性增加而抑菌。","B":"正确，氟康唑口服吸收完全、脑脊液浓度高，但对曲霉作用差。","C":"正确，棘白菌素类作用于细胞壁，隐球菌无此靶点，故对隐球菌无效。","D":"错误，氟胞嘧啶单用极易耐药，常与两性霉素B联用以产生协同作用。","E":"错误，灰黄霉素仅对皮肤癣菌有效，对念珠菌和深部真菌无效。"},"id":"ph42_q04","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":4}]},{"title":"第四十三章 抗结核药与抗麻风药","questions":[{"type":"A","stem":"异烟肼引起周围神经炎的主要原因是","options":{"A":"维生素B1缺乏","B":"维生素C缺乏","C":"维生素B12缺乏","D":"叶酸缺乏","E":"维生素B6缺乏"},"answer":["E"],"rationale":"异烟肼结构与吡哆醇相似，竞争性干扰维生素B6的利用并使其排泄增多，导致周围神经炎，故答案为 E。","expl":{"A":"错误，维生素B1缺乏引起脚气病，与异烟肼的作用机制无关。","B":"错误，维生素C缺乏引起坏血病，与本品不良反应无关。","C":"错误，维生素B12缺乏引起巨幼细胞性贫血和神经损害，但不是本药机制。","D":"错误，叶酸缺乏主要引起巨幼细胞性贫血。","E":"正确，维生素B6缺乏导致周围神经炎，故长期用药需同服维生素B6预防。"},"id":"ph43_q01","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":1},{"type":"A","stem":"利福平抗结核作用的主要机制是","options":{"A":"抑制结核分枝杆菌细胞壁分枝菌酸合成","B":"抑制二氢叶酸合成","C":"抑制阿拉伯糖基转移酶","D":"抑制细菌DNA依赖性RNA聚合酶","E":"抑制细菌蛋白质合成"},"answer":["D"],"rationale":"利福平与细菌DNA依赖性RNA聚合酶的β亚基结合，抑制转录过程，对结核分枝杆菌有强大杀菌作用，故答案为 D。","expl":{"A":"错误，抑制分枝菌酸合成的是异烟肼。","B":"错误，抑制二氢叶酸合成的是对氨基水杨酸等，作用较弱。","C":"错误，抑制阿拉伯糖基转移酶的是乙胺丁醇。","D":"正确，抑制RNA聚合酶阻断转录，属杀菌药，且可致尿液橘红色。","E":"错误，抑制蛋白质合成的是链霉素、阿米卡星等氨基糖苷类。"},"id":"ph43_q02","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":2},{"type":"X","stem":"关于抗结核药的应用原则，正确的有","options":{"A":"早期用药","B":"联合用药","C":"适量","D":"规律和全程用药","E":"症状消失后即可停药"},"answer":["A","B","C","D"],"rationale":"抗结核化疗强调早期、联合、适量、规律和全程用药，以延缓耐药性产生并彻底杀灭病灶内残留菌；症状消失后仍须完成全疗程，故E错误。","expl":{"A":"正确，早期病灶内细菌繁殖旺盛、药物易渗入，疗效最好。","B":"正确，联合用药可发挥协同作用并延缓耐药菌产生。","C":"正确，剂量过小无效且易耐药，过大则毒性增加。","D":"正确，规律全程用药是防止复发和耐药的关键。","E":"错误，症状消失只是初步控制，须完成全疗程以免复发和产生耐药。"},"id":"ph43_q03","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":3},{"type":"A","stem":"关于氨苯砜抗麻风病作用的叙述，正确的是","options":{"A":"是抗麻风病首选药，抑制二氢蝶酸合酶而干扰叶酸合成","B":"对麻风分枝杆菌作用迅速，单用数周即可治愈麻风病","C":"主要不良反应为球后视神经炎和牙龈增生","D":"作用机制是抑制细菌DNA依赖性RNA聚合酶","E":"葡萄糖-6-磷酸脱氢酶缺乏者使用更安全，不会发生溶血"},"answer":["A"],"rationale":"氨苯砜是抗麻风病首选药，通过抑制二氢蝶酸合酶干扰叶酸合成，作用缓慢、单用易耐药，须与利福平、氯法齐明联合并长期用药，故答案为 A。","expl":{"A":"正确，机制与磺胺类相似，为叶酸合成抑制剂，是抗麻风病首选药。","B":"错误，氨苯砜作用缓慢，须长期联合化疗，单用易产生耐药。","C":"错误，球后视神经炎见于乙胺丁醇，牙龈增生见于环孢素、苯妥英钠。","D":"错误，抑制RNA聚合酶的是利福平，氨苯砜作用于叶酸合成环节。","E":"错误，G6PD缺乏者用氨苯砜易发生溶血性贫血和高铁血红蛋白血症。"},"id":"ph43_q04","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":4}]},{"title":"第四十四章 抗寄生虫药","questions":[{"type":"A","stem":"氯喹抗疟作用的主要环节是","options":{"A":"杀灭红细胞内期裂殖体，控制疟疾症状发作","B":"杀灭肝内休眠子，控制间日疟复发","C":"杀灭血中配子体，阻断疟疾传播","D":"杀灭肝内红外期裂殖体，用于病因性预防","E":"抑制疟原虫二氢叶酸还原酶，阻碍叶酸合成"},"answer":["A"],"rationale":"氯喹浓集于疟原虫食物泡，杀灭红细胞内期裂殖体，起效快而持久，是控制疟疾症状发作的首选药，但对红外期和配子体无效，故答案为 A。","expl":{"A":"正确，作用于红内期裂殖体，迅速控制寒战高热等临床症状。","B":"错误，杀灭肝内休眠子、控制复发的是伯氨喹。","C":"错误，杀灭血中配子体、阻断传播的是伯氨喹。","D":"错误，杀灭红外期裂殖体用于病因性预防的是乙胺嘧啶。","E":"错误，抑制二氢叶酸还原酶的是乙胺嘧啶，不是氯喹。"},"id":"ph44_q01","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":1},{"type":"A","stem":"吡喹酮治疗血吸虫病的作用机制是","options":{"A":"增加虫体表膜对钙离子的通透性，使虫体痉挛、麻痹并脱落","B":"抑制虫体微管聚合，阻碍葡萄糖摄取","C":"与虫体DNA结合，抑制核酸合成","D":"阻断虫体神经肌肉接头胆碱受体，产生松弛性麻痹","E":"使血中微丝蚴变性，被网状内皮系统吞噬"},"answer":["A"],"rationale":"吡喹酮增加血吸虫体表对钙离子的通透性，使虫体痉挛性收缩、麻痹并脱落，还可损伤虫体皮层，是治疗日本血吸虫病的首选药，故答案为 A。","expl":{"A":"正确，钙内流致虫体痉挛麻痹，高效低毒、疗程短、可口服。","B":"错误，抑制微管聚合的是阿苯达唑、甲苯咪唑等苯并咪唑类。","C":"错误，与DNA结合抑制核酸合成的是氯法齐明等吩嗪类。","D":"错误，阻断胆碱受体使虫体松弛性麻痹的是哌嗪。","E":"错误，使微丝蚴变性而被吞噬的是乙胺嗪，用于丝虫病。"},"id":"ph44_q02","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":2},{"type":"A","stem":"关于甲硝唑的叙述，正确的是","options":{"A":"在厌氧环境中还原生成活性代谢物损伤虫体DNA，是阿米巴病和滴虫病的首选药","B":"对需氧菌和真菌有强大杀灭作用，属广谱抗微生物药","C":"服药期间饮酒可增强疗效，且无不良反应","D":"妊娠早期可安全使用，是孕妇滴虫病的首选药","E":"仅对肠内阿米巴病有效，对肠外阿米巴病无效"},"answer":["A"],"rationale":"甲硝唑在厌氧环境中其硝基被还原生成活性代谢物，损伤虫体DNA，对肠内与肠外阿米巴病、阴道滴虫病及厌氧菌感染均有良效，故答案为 A。","expl":{"A":"正确，硝基还原产物破坏DNA，为阿米巴病与滴虫病的首选药。","B":"错误，甲硝唑对需氧菌和真菌无效，抗菌谱限于厌氧菌与原虫。","C":"错误，服药期间饮酒可致双硫仑样反应，应禁酒。","D":"错误，妊娠早期禁用甲硝唑。","E":"错误，对肠内与肠外阿米巴病均有效，是肠外阿米巴病的首选。"},"id":"ph44_q03","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":3},{"type":"X","stem":"关于抗疟药作用环节与临床应用的叙述，正确的有","options":{"A":"伯氨喹杀灭肝内休眠子和血中配子体，可控制复发并阻断传播","B":"乙胺嘧啶抑制二氢叶酸还原酶，主要杀灭红外期裂殖体，用于病因性预防","C":"青蒿素类对耐氯喹虫株有效，可用于脑型疟和重症疟疾","D":"奎宁不良反应轻微，是孕妇及视神经病变患者的首选抗疟药","E":"氯喹对肝内红外期和配子体均有强大杀灭作用，单用即可根治间日疟"},"answer":["A","B","C"],"rationale":"伯氨喹作用于休眠子与配子体、乙胺嘧啶作用于红外期、青蒿素类对耐氯喹虫株有效并用于脑型疟；奎宁可致金鸡纳反应和低血糖、孕妇慎用，氯喹对红外期与配子体无效，故D、E错误。","expl":{"A":"正确，伯氨喹是根治间日疟、阻断传播的关键药，G6PD缺乏者可致溶血。","B":"正确，抑制二氢叶酸还原酶阻碍叶酸合成，用于病因性预防。","C":"正确，含过氧桥的倍半萜内酯，能透过血脑屏障，为重症疟疾首选。","D":"错误，奎宁可致金鸡纳反应、低血糖和流产，孕妇应慎用。","E":"错误，氯喹仅杀红内期裂殖体，单用不能根治间日疟也不能阻断传播。"},"id":"ph44_q04","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":4}]},{"title":"第四十五章 抗肿瘤药","questions":[{"type":"A","stem":"环磷酰胺引起出血性膀胱炎的主要原因是","options":{"A":"代谢物丙烯醛经尿排出，刺激膀胱黏膜","B":"药物直接抑制膀胱平滑肌的收缩功能","C":"药物引起膀胱黏膜的过敏反应","D":"药物抑制骨髓使血小板减少而致出血","E":"药物在肾小管形成结晶阻塞管腔"},"answer":["A"],"rationale":"环磷酰胺经肝药酶活化后产生磷酰胺氮芥和丙烯醛，后者随尿排出并刺激膀胱黏膜，引起出血性膀胱炎，可用美司钠解救并充分补液，故答案为 A。","expl":{"A":"正确，丙烯醛是致膀胱毒性的代谢物，美司钠可与其结合而解毒。","B":"错误，出血性膀胱炎是化学性炎症，并非平滑肌收缩受抑。","C":"错误，其发生与药物代谢物直接刺激有关，属毒性反应而非过敏。","D":"错误，血小板减少可致全身出血倾向，但不是膀胱局部炎症的原因。","E":"错误，形成结晶阻塞肾小管见于大剂量甲氨蝶呤等，不是环磷酰胺的机制。"},"id":"ph45_q01","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":1},{"type":"A","stem":"大剂量甲氨蝶呤治疗后给予亚叶酸钙解救的药理学依据是","options":{"A":"亚叶酸钙绕过被抑制的二氢叶酸还原酶，补充四氢叶酸，减轻骨髓与黏膜毒性","B":"亚叶酸钙促进甲氨蝶呤经肾排泄，迅速降低其血药浓度","C":"亚叶酸钙直接抑制二氢叶酸还原酶，减少药物的活化","D":"亚叶酸钙与甲氨蝶呤结合成无活性复合物而解毒","E":"亚叶酸钙可增强甲氨蝶呤的抗肿瘤作用，故须与化疗同时给药"},"answer":["A"],"rationale":"甲氨蝶呤抑制二氢叶酸还原酶，阻碍四氢叶酸和胸苷酸生成；亚叶酸钙是四氢叶酸的甲酰衍生物，可绕过被阻断的酶补充四氢叶酸，选择性保护正常骨髓与黏膜细胞，故答案为 A。","expl":{"A":"正确，即“亚叶酸钙解救”，用以减轻骨髓抑制和口腔黏膜炎。","B":"错误，解救靠补充四氢叶酸，并非加速排泄。","C":"错误，亚叶酸钙不抑制二氢叶酸还原酶，不减少药物活化。","D":"错误，二者不形成无活性复合物，解救是代谢性补充。","E":"错误，解救的目的是保护正常组织，并非增强抗肿瘤作用。"},"id":"ph45_q02","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":2},{"type":"A","stem":"关于紫杉醇的叙述，正确的是","options":{"A":"促进微管蛋白聚合并稳定微管，使细胞停止于有丝分裂期","B":"抑制微管蛋白聚合，使有丝分裂停止于中期","C":"属细胞周期非特异性药物，主要不良反应为出血性膀胱炎","D":"用药前无须预处理，不会发生过敏反应","E":"主要用于消化道肿瘤，不良反应以腹泻最为突出"},"answer":["A"],"rationale":"紫杉醇促进微管蛋白聚合并稳定微管，使细胞不能形成正常纺锤体而停止于有丝分裂期，用于乳腺癌、卵巢癌和非小细胞肺癌，故答案为 A。","expl":{"A":"正确，作用方向与长春碱类相反，但同样使细胞停滞于M期。","B":"错误，抑制微管聚合的是长春碱和长春新碱。","C":"错误，紫杉醇作用于M期，属周期特异性药物；出血性膀胱炎见于环磷酰胺。","D":"错误，易致过敏反应，用药前需用糖皮质激素和抗组胺药预处理。","E":"错误，主要用于乳腺癌、卵巢癌和非小细胞肺癌，骨髓抑制与神经毒性较常见。"},"id":"ph45_q03","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":3},{"type":"X","stem":"下列属于细胞周期特异性抗肿瘤药的有","options":{"A":"甲氨蝶呤","B":"氟尿嘧啶","C":"长春新碱","D":"环磷酰胺","E":"顺铂"},"answer":["A","B","C"],"rationale":"甲氨蝶呤与氟尿嘧啶主要作用于S期，长春新碱作用于M期，均属细胞周期特异性药物；环磷酰胺与顺铂属细胞周期非特异性药物，对各期细胞均有杀伤作用，故D、E不选。","expl":{"A":"正确，抑制二氢叶酸还原酶，主要作用于S期，呈时间依赖性。","B":"正确，抑制胸苷酸合成酶，主要作用于S期，对消化道肿瘤疗效较好。","C":"正确，抑制微管聚合使有丝分裂停止于中期，作用于M期。","D":"错误，环磷酰胺为烷化剂，属细胞周期非特异性药物。","E":"错误，顺铂与DNA交联，属细胞周期非特异性药物。"},"id":"ph45_q04","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":4}]},{"title":"第四十六章 免疫功能调节剂","questions":[{"type":"A","stem":"环孢素A免疫抑制作用的主要机制是","options":{"A":"抑制钙调磷酸酶，选择性抑制T淋巴细胞活化","B":"抑制二氢叶酸还原酶","C":"抑制mTOR","D":"抑制DNA合成","E":"阻断IL-2受体"},"answer":["A"],"rationale":"环孢素A与亲环蛋白结合后抑制钙调磷酸酶，阻滞IL-2等细胞因子基因转录，选择性抑制T细胞活化，故答案为 A。","expl":{"A":"正确，主要抑制辅助性T细胞活化，对骨髓无明显抑制。","B":"错误，抑制二氢叶酸还原酶的是甲氨蝶呤。","C":"错误，抑制mTOR的是西罗莫司（雷帕霉素）。","D":"错误，抑制DNA合成的是硫唑嘌呤、环磷酰胺等。","E":"错误，阻断IL-2受体的是巴利昔单抗等抗体类药物。"},"id":"ph46_q01","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":1},{"type":"A","stem":"西罗莫司免疫抑制作用的主要机制是","options":{"A":"与FK结合蛋白结合后抑制mTOR，阻断T细胞由G1期进入S期","B":"与亲环蛋白结合后抑制钙调磷酸酶，减少白介素-2生成","C":"抑制次黄嘌呤核苷酸脱氢酶，阻断淋巴细胞嘌呤合成","D":"抑制二氢叶酸还原酶，阻碍四氢叶酸生成","E":"与DNA共价结合形成交联，抑制淋巴细胞增殖"},"answer":["A"],"rationale":"西罗莫司与FK结合蛋白结合后抑制mTOR，阻断T细胞由G1期进入S期的增殖信号，用于移植抗排斥及药物涂层支架预防再狭窄，故答案为 A。","expl":{"A":"正确，与钙调磷酸酶抑制药不同，其靶点是mTOR而非钙调磷酸酶。","B":"错误，与亲环蛋白结合并抑制钙调磷酸酶的是环孢素。","C":"错误，抑制次黄嘌呤核苷酸脱氢酶的是吗替麦考酚酯。","D":"错误，抑制二氢叶酸还原酶的是甲氨蝶呤。","E":"错误，与DNA交联的是烷化剂，如环磷酰胺。"},"id":"ph46_q02","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":2},{"type":"A","stem":"硫唑嘌呤与别嘌醇合用时须减少硫唑嘌呤剂量的原因是","options":{"A":"别嘌醇抑制黄嘌呤氧化酶，使硫唑嘌呤代谢减慢而蓄积，加重骨髓抑制","B":"别嘌醇诱导肝药酶，使硫唑嘌呤迅速活化为毒性产物","C":"两药竞争肾小管分泌，使硫唑嘌呤血药浓度明显下降","D":"别嘌醇中和硫唑嘌呤的活性代谢物，使其完全失效","E":"两药均抑制钙调磷酸酶，免疫抑制作用发生叠加"},"answer":["A"],"rationale":"硫唑嘌呤主要经黄嘌呤氧化酶代谢，别嘌醇抑制该酶后其代谢受阻、活性产物蓄积，可致严重骨髓抑制，故合用时须将硫唑嘌呤减至常用量的一部分或避免合用，答案为 A。","expl":{"A":"正确，黄嘌呤氧化酶被抑制致硫唑嘌呤蓄积，骨髓抑制明显加重。","B":"错误，别嘌醇是黄嘌呤氧化酶抑制剂，并非酶诱导剂。","C":"错误，相互影响在代谢环节而非肾小管分泌竞争，血药浓度是升高而非下降。","D":"错误，别嘌醇不影响其活性代谢物发挥作用，而是使其蓄积。","E":"错误，两药均不抑制钙调磷酸酶，钙调磷酸酶抑制药是环孢素和他克莫司。"},"id":"ph46_q03","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":3},{"type":"X","stem":"关于免疫增强药临床应用与特点的叙述，正确的有","options":{"A":"卡介苗膀胱内灌注可用于治疗表浅膀胱癌","B":"胸腺肽可促进T细胞分化成熟，用于免疫缺陷病的辅助治疗","C":"左旋咪唑在免疫功能正常者作用不明显，仅在免疫功能低下时显示增强作用","D":"免疫增强药作用可靠，可替代抗感染药物单独治疗严重细菌感染","E":"转移因子可传递供体的细胞免疫信息，但作用短暂需反复给药"},"answer":["A","B","C","E"],"rationale":"卡介苗灌注可诱发局部免疫反应治疗表浅膀胱癌，胸腺肽促进T细胞分化成熟，左旋咪唑仅在免疫功能低下时显效，转移因子传递细胞免疫信息但作用短暂；免疫增强药只能辅助治疗，不能替代抗感染药物，故D错误。","expl":{"A":"正确，机制为诱发局部非特异性炎症与免疫反应，活动性结核者禁用。","B":"正确，胸腺肽促进T细胞分化成熟，增强细胞免疫功能。","C":"正确，免疫增强与免疫抑制的划分是相对的，左旋咪唑即为典型例子。","D":"错误，免疫增强药多疗效有限，只能作为感染与肿瘤的辅助用药。","E":"正确，转移因子为致敏淋巴细胞提取物，作用短暂，需反复给药。"},"id":"ph46_q04","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":4}]},{"title":"第四十七章 生物技术药物","questions":[{"type":"A","stem":"关于干扰素α不良反应的叙述，正确的是","options":{"A":"治疗初期常见发热、乏力、肌肉酸痛等流感样症状，继续用药多可减轻","B":"主要毒性为肾损害，表现为血肌酐升高和低钾血症","C":"可使皮肤、角膜和分泌物呈红棕色","D":"剂量限制性毒性为心脏毒性，可致心肌病","E":"不会引起骨髓抑制和甲状腺功能异常"},"answer":["A"],"rationale":"干扰素α治疗初期常见发热、乏力、肌肉酸痛等流感样症状，继续用药多可减轻；还可致骨髓抑制、脱发和甲状腺功能异常，有严重抑郁史者慎用，故答案为 A。","expl":{"A":"正确，流感样症状是最常见的不良反应，多在用药初期出现。","B":"错误，肾损害与低钾血症是两性霉素B的典型毒性。","C":"错误，皮肤与分泌物红棕色是氯法齐明的特征性反应。","D":"错误，剂量限制性心脏毒性见于多柔比星等蒽环类。","E":"错误，干扰素可致骨髓抑制、脱发和甲状腺功能异常，需监测。"},"id":"ph47_q01","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":1},{"type":"A","stem":"关于重组人促红细胞生成素的叙述，正确的是","options":{"A":"作用于红系祖细胞促进其增殖分化，用于肾性贫血和化疗相关贫血","B":"起效迅速，给药后数小时即可使血红蛋白升至正常水平","C":"主要不良反应为骨髓抑制和出血性膀胱炎","D":"可口服给药，吸收完全且不受食物影响","E":"血红蛋白升得越高疗效越好，无须设定目标值"},"answer":["A"],"rationale":"促红细胞生成素作用于红系祖细胞，促进其增殖分化，用于肾性贫血、肿瘤化疗相关贫血及外科自体输血，起效需数周，故答案为 A。","expl":{"A":"正确，为肾皮质间质细胞分泌的糖蛋白，是肾性贫血的替代治疗药。","B":"错误，起效需数周，须监测血红蛋白逐步调整剂量。","C":"错误，其不良反应为高血压和血栓形成，骨髓抑制不是其主要毒性。","D":"错误，属蛋白质类药物，口服易被消化酶破坏，须注射给药。","E":"错误，血红蛋白过高会增加血栓与高血压风险，须设定目标值。"},"id":"ph47_q02","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":2},{"type":"A","stem":"关于重组人粒细胞集落刺激因子的叙述，正确的是","options":{"A":"刺激中性粒细胞前体增殖分化，用于化疗后中性粒细胞减少","B":"主要不良反应为剂量依赖性心脏毒性，可致心肌病","C":"应于化疗同时静脉推注，以直接杀灭肿瘤细胞","D":"主要作用是促进红系祖细胞分化，纠正贫血","E":"可口服给药，临床主要用于治疗血小板减少"},"answer":["A"],"rationale":"粒细胞集落刺激因子刺激中性粒细胞前体增殖分化并增强其吞噬功能，用于化疗后中性粒细胞减少，可缩短粒细胞缺乏期、减少感染，常见不良反应为骨痛和发热，故答案为 A。","expl":{"A":"正确，应在化疗后中性粒细胞降至低谷前使用，以缩短粒细胞缺乏期。","B":"错误，心脏毒性见于蒽环类，本药常见骨痛和发热。","C":"错误，本药不杀肿瘤细胞，一般在化疗结束后使用。","D":"错误，促进红系祖细胞分化的是促红细胞生成素。","E":"错误，属蛋白质类药物须注射给药，主要升高中性粒细胞而非血小板。"},"id":"ph47_q03","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":3},{"type":"X","stem":"关于疫苗、类毒素与抗毒素的叙述，正确的有","options":{"A":"减毒活疫苗接种后近似自然感染，免疫应答持久，常只需接种一次","B":"类毒素是细菌外毒素经甲醛处理失去毒性而保留免疫原性的制品","C":"抗毒素属人工被动免疫，使用前必须做皮肤过敏试验","D":"免疫缺陷者和孕妇禁用减毒活疫苗","E":"类毒素主要用于治疗已发生的外毒素中毒，起效迅速"},"answer":["A","B","C","D"],"rationale":"减毒活疫苗免疫持久但免疫缺陷者与孕妇禁用，类毒素为甲醛处理的脱毒外毒素用于人工主动免疫，抗毒素为异种血清抗体、属被动免疫且用前须皮试；治疗已发生的中毒应选抗毒素而非类毒素，故E错误。","expl":{"A":"正确，接种后近似自然感染，免疫应答持久，常只需一次接种。","B":"正确，如破伤风类毒素、白喉类毒素，用于人工主动免疫。","C":"正确，抗毒素为异种血清蛋白，须皮试并备好肾上腺素。","D":"正确，活疫苗对免疫缺陷者可致严重感染，孕妇亦禁用。","E":"错误，类毒素用于预防即人工主动免疫，治疗或紧急预防应选抗毒素。"},"id":"ph47_q04","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":4}]}]};
